function showSetPasswordOverlay() {
  if (document.getElementById('set-pw-overlay')) return;
  const ov = document.createElement('div');
  ov.id = 'set-pw-overlay';
  ov.style.cssText = 'position:fixed;inset:0;background:rgba(10,14,20,0.92);z-index:99999;display:flex;align-items:center;justify-content:center;padding:20px;';
  ov.innerHTML = `
    <div style="background:var(--surface-2,#151a23);border:1px solid var(--border,#2a2f3a);border-radius:12px;padding:28px;max-width:380px;width:100%;">
      <h3 style="margin:0 0 6px;">Welcome! Set your password</h3>
      <p style="font-size:13px;color:var(--muted,#8a93a3);margin:0 0 16px;">Choose the password you'll use to log in to the CRM.</p>
      <label>New password</label>
      <input type="password" id="set-pw-1" autocomplete="new-password" />
      <label>Confirm password</label>
      <input type="password" id="set-pw-2" autocomplete="new-password" />
      <div id="set-pw-msg" style="font-size:12px;color:#e2a33d;min-height:18px;margin-top:8px;"></div>
      <button class="btn btn-primary" style="width:100%;margin-top:6px;" onclick="submitSetPassword()">Save password &amp; enter the CRM</button>
    </div>`;
  document.body.appendChild(ov);
}

// Returns how many breaches the password appears in, 0 if none, or null if the
// service could not be reached -- in which case we let the save proceed rather
// than locking someone out of their own account over an outage.
async function passwordBreachCount_(pw) {
  try {
    const bytes = new TextEncoder().encode(pw);
    const digest = await crypto.subtle.digest('SHA-1', bytes);
    const hex = Array.from(new Uint8Array(digest))
      .map(b => b.toString(16).padStart(2, '0')).join('').toUpperCase();
    const prefix = hex.slice(0, 5), suffix = hex.slice(5);

    const res = await fetch('https://api.pwnedpasswords.com/range/' + prefix,
                            { headers: { 'Add-Padding': 'true' } });
    if (!res.ok) return null;
    const body = await res.text();
    for (const line of body.split('\n')) {
      const parts = line.trim().split(':');
      if (parts[0] === suffix) return parseInt(parts[1], 10) || 1;
    }
    return 0;
  } catch (e) {
    return null;   // offline, blocked, or no crypto.subtle -- do not block
  }
}

async function submitSetPassword() {
  const p1 = document.getElementById('set-pw-1').value;
  const p2 = document.getElementById('set-pw-2').value;
  const msg = document.getElementById('set-pw-msg');
  if (p1.length < 8) { msg.textContent = 'Password must be at least 8 characters.'; return; }
  if (p1 !== p2) { msg.textContent = 'Passwords do not match.'; return; }

  msg.textContent = 'Checking this password...';
  const breaches = await passwordBreachCount_(p1);
  if (breaches) {
    msg.textContent = 'That password has appeared in ' + breaches.toLocaleString()
      + ' known data breaches, so it is one attackers already try. Please choose a different one.';
    return;
  }

  msg.textContent = 'Saving...';
  const { error } = await supabaseClient.auth.updateUser({ password: p1 });
  if (error) { msg.textContent = 'Error: ' + error.message; return; }
  msg.textContent = '';
  window.location.replace(window.location.pathname);
}

// ============================================================
// TWO-FACTOR AUTHENTICATION (TOTP via Supabase Auth)
// Gate on arrival + enrollment management in Settings.
// ============================================================
async function mfaGateThenShowApp_() {
  try {
    var res = await supabaseClient.auth.mfa.getAuthenticatorAssuranceLevel();
    var aal = res && res.data ? res.data : null;
    if (aal && aal.nextLevel === 'aal2' && aal.currentLevel !== 'aal2') {
      showMfaChallengeOverlay_();
      return;
    }
  } catch (e) { /* if the check fails, fall through to the app */ }
  showApp();
}

function showMfaChallengeOverlay_() {
  if (document.getElementById('mfa-overlay')) return;
  var ov = document.createElement('div');
  ov.id = 'mfa-overlay';
  ov.style.cssText = 'position:fixed;inset:0;background:rgba(10,14,20,0.94);z-index:99999;display:flex;align-items:center;justify-content:center;padding:20px;';
  ov.innerHTML = '<div style="background:var(--surface-2,#151a23);border:1px solid var(--border,#2a2f3a);border-radius:12px;padding:28px;max-width:360px;width:100%;text-align:center;">' +
    '<div style="font-size:34px;margin-bottom:8px;">&#128274;</div>' +
    '<h3 style="margin:0 0 6px;">Two-factor check</h3>' +
    '<p style="font-size:13px;color:var(--muted,#8a93a3);margin:0 0 16px;">Enter the 6-digit code from your authenticator app.</p>' +
    '<input type="text" id="mfa-code" inputmode="numeric" autocomplete="one-time-code" maxlength="6" placeholder="123456" style="text-align:center;font-size:22px;letter-spacing:6px;" />' +
    '<div id="mfa-msg" style="font-size:12px;color:#e2a33d;min-height:18px;margin-top:8px;"></div>' +
    '<button class="btn btn-primary" style="width:100%;margin-top:6px;" onclick="submitMfaChallenge_()">Verify</button>' +
    '<button class="btn" style="width:100%;margin-top:8px;" onclick="signOut()">Cancel &amp; sign out</button>' +
    '</div>';
  document.body.appendChild(ov);
  var input = document.getElementById('mfa-code');
  input.focus();
  input.addEventListener('keydown', function(ev) { if (ev.key === 'Enter') submitMfaChallenge_(); });
}

async function submitMfaChallenge_() {
  var code = (document.getElementById('mfa-code').value || '').trim();
  var msg = document.getElementById('mfa-msg');
  if (code.length !== 6) { msg.textContent = 'Enter the 6-digit code.'; return; }
  msg.textContent = 'Checking...';
  try {
    var lf = await supabaseClient.auth.mfa.listFactors();
    var totp = lf.data && lf.data.totp && lf.data.totp.length ? lf.data.totp[0] : null;
    if (!totp) { msg.textContent = 'No authenticator found — contact Ken.'; return; }
    var r = await supabaseClient.auth.mfa.challengeAndVerify({ factorId: totp.id, code: code });
    if (r.error) { msg.textContent = 'That code did not match. Try the current code.'; return; }
    var ov = document.getElementById('mfa-overlay');
    if (ov) ov.remove();
    showApp();
  } catch (e) {
    msg.textContent = 'Error: ' + (e.message || e);
  }
}

async function loadMfaCard_() {
  var body = document.getElementById('mfa-card-body');
  if (!body) return;
  try {
    var lf = await supabaseClient.auth.mfa.listFactors();
    var totp = lf.data && lf.data.totp && lf.data.totp.length ? lf.data.totp[0] : null;
    if (totp) {
      body.innerHTML = '<div style="display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;">' +
        '<span style="font-size:13px;color:var(--success,#1a7f4e);font-weight:700;">&#10003; Two-factor is ON &mdash; your account requires an authenticator code at sign-in.</span>' +
        '<button class="btn btn-outline btn-sm" onclick="unenrollMfa_(\'' + totp.id + '\')">Turn off</button></div>';
    } else {
      body.innerHTML = '<div style="display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;">' +
        '<span style="font-size:13px;">Add two-factor sign-in so your account needs a code only you have. Works with <strong>any</strong> authenticator &mdash; including the one already built into your phone (iPhone: the <strong>Passwords</strong> app &middot; Android: Google password manager) or apps like Microsoft Authenticator, Authy, or 1Password. No Google account needed. <strong>Strongly recommended for all agents.</strong></span>' +
        '<button class="btn btn-primary btn-sm" onclick="startMfaEnroll_()">Enable two-factor</button></div>';
    }
  } catch (e) {
    body.textContent = 'Could not load two-factor status: ' + (e.message || e);
  }
}

async function startMfaEnroll_() {
  var body = document.getElementById('mfa-card-body');
  body.innerHTML = '<span style="font-size:13px;color:var(--text-muted);">Generating your secure QR code...</span>';
  var r = await supabaseClient.auth.mfa.enroll({ factorType: 'totp' });
  if (r.error) { body.textContent = 'Error: ' + r.error.message; return; }
  var f = r.data;
  body.innerHTML =
    '<div style="display:flex;gap:18px;align-items:flex-start;flex-wrap:wrap;">' +
    '<div style="background:#ffffff;padding:10px;border-radius:8px;">' + f.totp.qr_code + '</div>' +
    '<div style="flex:1;min-width:220px;">' +
    '<p style="font-size:13px;margin:0 0 8px;"><strong>iPhone:</strong> open the <strong>Passwords</strong> app &rarr; your login &rarr; Set Up Verification Code &rarr; scan this QR (or just point your camera at it).<br><strong>Android:</strong> open Google password manager or any authenticator app &rarr; add code &rarr; scan this QR.<br>Then enter the 6-digit code it shows to finish.</p>' +
    '<p style="font-size:11px;color:var(--text-muted);margin:0 0 10px;">Can\'t scan? Enter this key manually: <code style="font-size:11px;word-break:break-all;">' + f.totp.secret + '</code></p>' +
    '<input type="text" id="mfa-enroll-code" inputmode="numeric" maxlength="6" placeholder="123456" style="max-width:160px;text-align:center;font-size:18px;letter-spacing:4px;" /> ' +
    '<button class="btn btn-primary btn-sm" onclick="verifyMfaEnroll_(\'' + f.id + '\')">Verify &amp; turn on</button> ' +
    '<button class="btn btn-sm" onclick="cancelMfaEnroll_(\'' + f.id + '\')">Cancel</button>' +
    '<div id="mfa-enroll-msg" style="font-size:12px;color:#e2a33d;min-height:16px;margin-top:6px;"></div>' +
    '</div></div>';
}

async function verifyMfaEnroll_(factorId) {
  var code = (document.getElementById('mfa-enroll-code').value || '').trim();
  var msg = document.getElementById('mfa-enroll-msg');
  if (code.length !== 6) { msg.textContent = 'Enter the 6-digit code from your app.'; return; }
  msg.textContent = 'Verifying...';
  var r = await supabaseClient.auth.mfa.challengeAndVerify({ factorId: factorId, code: code });
  if (r.error) { msg.textContent = 'That code did not match — try the current code.'; return; }
  showToast('Two-factor authentication is ON.');
  loadMfaCard_();
}

async function cancelMfaEnroll_(factorId) {
  try { await supabaseClient.auth.mfa.unenroll({ factorId: factorId }); } catch (e) {}
  loadMfaCard_();
}

async function unenrollMfa_(factorId) {
  if (!confirm('Turn off two-factor authentication? Your account will be protected by password only.')) return;
  var r = await supabaseClient.auth.mfa.unenroll({ factorId: factorId });
  if (r.error) { showToast('Error: ' + r.error.message); return; }
  showToast('Two-factor authentication is OFF.');
  loadMfaCard_();
}

// Medicare access rule (Ken 2026-07-27):
// 1) must be on the Insured America side (agent brand 'ia' or 'both'), and
// 2) must hold a health insurance license (enough for Medigap/PDP-era launch).
// ahip_certified_year additionally marks who may sell MA/PDP (used for
// content gating later — AHIP is only required for Advantage + Part D).
// System owner always sees everything.
function medicareCertified_() {
  const role = activeRole();
  if (role === 'system_owner') return true;
  if (!currentAgent) return false;
  const iaSide = currentAgent.brand === 'ia' || currentAgent.brand === 'both';
  return iaSide && !!currentAgent.has_health_license;
}

// ============================================================
// SCOPE OF APPOINTMENT (Medicare compliance)
// Send a digital SOA for signature; show status on the deal panel.
// Records are retained permanently (10-year CMS rule).
// ============================================================
const SOA_PRODUCTS = [
  ['medigap', 'Medicare Supplement (Medigap)'],
  ['pdp', 'Stand-alone Prescription Drug Plan (Part D)'],
  ['ma', 'Medicare Advantage (Part C)'],
  ['dvh', 'Dental / Vision / Hearing products'],
];

async function loadSoaStatus_(deal) {
  const el = document.getElementById('soa-status-' + deal.id);
  if (!el || !deal.contact_id) { if (el) el.textContent = 'No contact linked.'; return; }
  const { data } = await supabaseClient.from('soa_records')
    .select('id,status,sent_at,signed_at,products_agreed')
    .eq('contact_id', deal.contact_id)
    .order('created_at', { ascending: false })
    .limit(1);
  const r = data && data[0];
  if (!r) { el.innerHTML = '<span style="color:#f59e0b;">&#9888; No SOA on file — required before a Medicare sales meeting.</span>'; return; }
  if (r.status === 'pending') {
    el.innerHTML = '&#9203; SOA sent ' + new Date(r.sent_at).toLocaleDateString() + ' — awaiting signature.';
  } else if (r.status === 'signed') {
    const okAt = new Date(new Date(r.signed_at).getTime() + 48 * 3600 * 1000);
    const now = new Date();
    const gate = now >= okAt
      ? '<span style="color:var(--success);">&#10003; 48-hour window satisfied — sales meeting permitted.</span>'
      : '<span style="color:#f59e0b;">&#9203; 48-hour rule: sales meeting permitted after ' + okAt.toLocaleString() + '.</span>';
    el.innerHTML = '<span style="color:var(--success);">&#10003; Signed ' + new Date(r.signed_at).toLocaleDateString() + '</span>'
      + ' — agreed: ' + ((r.products_agreed || []).join(', ') || 'none')
      + ' &nbsp;<a href="' + window.location.origin + '/soa.html?s=' + r.id + '&view=1" target="_blank" style="font-size:11px;">View / print record ↗</a>'
      + '<br>' + gate;
  } else {
    el.innerHTML = 'SOA ' + r.status + '.';
  }
}

function openSoaModal(dealId) {
  const deal = deals.find(d => d.id === dealId); if (!deal) return;
  const contact = contacts.find(c => c.id === deal.contact_id);
  if (!contact) { showToast('No contact linked to this deal.'); return; }
  if (!contact.email) { showToast('Contact has no email on file.'); return; }
  const boxes = SOA_PRODUCTS.map(p =>
    `<label style="display:flex;gap:8px;align-items:center;font-weight:400;margin-top:8px;"><input type="checkbox" id="soa-p-${p[0]}" style="width:auto;" ${p[0] !== 'ma' ? 'checked' : ''}/> ${p[1]}</label>`
  ).join('');
  showModal('Send Scope of Appointment — ' + (contact.name || ''), `
    <p style="font-size:13px;color:var(--text-muted);margin-bottom:10px;">
      The beneficiary signs before any Medicare sales meeting (48-hour rule).
      Select the products you propose to discuss — they can adjust before signing.
    </p>
    <label>Products to discuss</label>
    ${boxes}
    <p style="font-size:11px;color:var(--text-muted);margin-top:12px;">
      Sent to <strong>${contact.email}</strong>. The signed record is kept permanently (CMS 10-year rule).
    </p>
  `, async () => {
    const products = SOA_PRODUCTS.filter(p => document.getElementById('soa-p-' + p[0]).checked).map(p => p[1]);
    if (!products.length) { showToast('Select at least one product.'); return false; }
    const { data: rec, error } = await supabaseClient.from('soa_records').insert({
      contact_id: contact.id,
      agent_id: currentAgent ? currentAgent.id : null,
      agent_name: currentAgent ? (currentAgent.display_name || currentAgent.name) : null,
      beneficiary_name: contact.name || '',
      beneficiary_email: contact.email,
      products_offered: products,
    }).select().single();
    if (error) { showToast('Error: ' + error.message); return false; }
    try {
      fetch(APPS_SCRIPT_URL + '?action=send_soa&soa_id=' + rec.id
        + '&contact_id=' + contact.id
        + '&agent_id=' + (currentAgent ? currentAgent.id : ''), { mode: 'no-cors' });
    } catch (e) { /* email engine reports its own errors */ }
    showToast('SOA sent to ' + contact.email + ' for signature.');
    loadSoaStatus_(deal);
  }, { confirmLabel: 'Send SOA' });
}

// ============================================================
// CARRIERS — master reference (owners only, Admin page)
// ============================================================
// Federally standardized Medigap plans: the letter defines the benefits
// at EVERY carrier, so the product form fills itself from this list.
// The picker: one card per lettered plan they may actually buy, with the
// standardized benefits spelled out and a grid to compare them side by side.
window._qbMgSel = window._qbMgSel || {};

function openMedigapPicker_() {
  const prof = qbMgProfile_();
  if (!prof.state) { showToast('Enter their ZIP code first.'); return; }
  qbWorkbenchOpen_(false);           // the picker IS the screen now
  let el = document.getElementById('qb-mg-picker');
  if (!el) {
    el = document.createElement('div');
    el.id = 'qb-mg-picker';
    el.style.cssText = 'position:fixed;inset:0;z-index:99990;background:var(--surface-0);display:flex;flex-direction:column;';
    document.body.appendChild(el);
  }
  el.style.display = 'flex';
  window._qbMgShowGrid = false;
  renderMedigapPicker_();
  qbMgLoadRates_();
}

function closeMedigapPicker_() {
  const el = document.getElementById('qb-mg-picker');
  if (el) el.style.display = 'none';
  qbAutoCardPaint_();
  qbOptAutoFold_();
  qbGroupOptions_();
}

function mgToggleGrid_() { window._qbMgShowGrid = !window._qbMgShowGrid; renderMedigapPicker_(); }

function mgAddedSlot_(letter) {
  const sel = window._qbMgSel || {};
  for (let i = 0; i < QB_MAX_OPTIONS; i++) if (sel[i] && sel[i].letter === letter) return i;
  return -1;
}

// What the gap is actually worth this year. Blank until the plan year holds
// the figure \u2014 a stale amount would be worse than none.
const MG_ROW_AMOUNT = {
  'Part A hospital deductible': ['part_a_deductible', 'per benefit period'],
  'Part B deductible': ['part_b_deductible', 'a year'],
  'Skilled nursing facility coinsurance': ['part_a_snf_coins', 'a day, days 21\u2013100'],
  'Part A coinsurance & 365 extra hospital days': ['part_a_coins_61_90', 'a day, days 61\u201390'],
};

function mgAmountNote_(label) {
  const hit = MG_ROW_AMOUNT[label];
  if (!hit) return '';
  const amt = (window._planYearAmts || {})[hit[0]];
  if (amt == null) return '';
  return `<span style="display:block;font-size:10.5px;color:var(--text-muted);font-weight:400;">$${
    Number(amt).toLocaleString('en-US')} ${hit[1]}</span>`;
}

function mgGridHtml_(letters) {
  const th = 'position:sticky;left:0;background:var(--surface-0);z-index:2;text-align:left;font-size:11.5px;font-weight:700;color:var(--text-muted);padding:8px 12px;border-bottom:1px solid var(--border);min-width:230px;';
  const td = 'padding:8px 12px;border-bottom:1px solid var(--border);font-size:13px;text-align:center;min-width:74px;';
  return `<table style="border-collapse:collapse;width:100%;">
    <thead><tr><th style="${th}">What it pays</th>
      ${letters.map(L => `<td style="${td}font-weight:800;font-size:14px;border-bottom:1.5px solid var(--border);">${escWeb(L)}</td>`).join('')}
    </tr></thead>
    <tbody>
      ${MEDIGAP_GRID.rows.map(([label, byLetter]) => `<tr>
        <th style="${th}font-weight:500;color:var(--text-secondary);">${escWeb(label)}${mgAmountNote_(label)}</th>
        ${letters.map(L => `<td style="${td}">${MEDIGAP_MARK[byLetter[L] || 'none']}</td>`).join('')}
      </tr>`).join('')}
      <tr><th style="${th}font-weight:500;color:var(--text-secondary);">Yearly out-of-pocket limit</th>
        ${letters.map(L => {
          const amt = (window._planYearAmts || {})[L === 'K' ? 'medigap_k_oop' : 'medigap_l_oop'];
          return `<td style="${td}">${(L === 'K' || L === 'L')
            ? (amt != null
                ? '<span style="color:var(--text-success);font-weight:800;">$' + Number(amt).toLocaleString('en-US') + '</span>'
                : '<span style="color:var(--text-success);font-weight:800;">\u2713</span>')
            : MEDIGAP_MARK.none}</td>`;
        }).join('')}
      </tr>
    </tbody>
  </table>
  <div style="font-size:11px;color:var(--text-muted);margin-top:10px;line-height:1.5;">
    These benefits are set by federal law \u2014 Plan G from one carrier covers exactly what Plan G covers at any other.
    Only the premium, the rate increases and the service differ. Plan N also has copays of up to $20 for office visits
    and $50 for an emergency room visit that does not lead to admission.
  </div>`;
}

function mgCardHtml_(p) {
  const [letter, title, bullets] = p;
  const slot = mgAddedSlot_(letter);
  const qs = (window._qbMgQuotes || {})[letter] || [];
  const manualOpen = !qs.length || (window._qbMgManualOpen || {})[letter];
  const desc = title.split('\u2014')[1] ? title.split('\u2014')[1].trim() : title;

  return `<div class="pk-card ${slot >= 0 ? 'is-selected' : ''}"
      style="border-radius:12px;padding:12px 14px;display:flex;flex-direction:column;height:100%;cursor:pointer;"
      onclick="openMgDetail_('${escWeb(letter)}')">

      <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:7px;">
        <button type="button" class="btn btn-outline btn-sm" style="font-size:11px;padding:2px 9px;"
          onclick="event.stopPropagation();openMgDetail_('${escWeb(letter)}')">Plan details</button>
        <label style="margin-left:auto;display:flex;align-items:center;gap:5px;font-size:11px;color:var(--text-muted);cursor:pointer;" onclick="event.stopPropagation();">
          <input type="checkbox" ${(window._qbMgCmp || new Set()).has(letter) ? 'checked' : ''} onclick="event.stopPropagation();"
            onchange="mgCmpToggle_('${escWeb(letter)}', this)" style="width:13px;height:13px;" /> \u2696\ufe0f Compare</label>
      </div>

      ${slot >= 0 ? `<div class="pk-sel-badge">\u2713 OPTION ${qbOptionNo_(slot)}</div>` : ''}
      <div style="display:flex;align-items:baseline;gap:8px;flex-wrap:wrap;">
        <span style="font-size:11px;font-weight:800;letter-spacing:1px;text-transform:uppercase;color:var(--text-muted);">Plan</span>
        <span style="font-size:22px;font-weight:800;color:var(--accent,#c8a84b);line-height:1;">${escWeb(letter)}</span>
        <span style="font-size:13px;font-weight:700;">${escWeb(desc)}</span>
      </div>

      <ul style="list-style:none;margin:9px 0 0;padding:0;">
        ${bullets.map(b => `<li style="font-size:12px;line-height:1.5;color:var(--text-secondary);padding:2px 0 2px 16px;position:relative;">
          <span style="position:absolute;left:0;color:var(--text-success);font-weight:800;">\u00b7</span>${escWeb(b)}</li>`).join('')}
      </ul>

      <div style="margin-top:auto;padding-top:10px;">
        ${qs.length ? `<div style="font-size:10px;font-weight:800;letter-spacing:.5px;text-transform:uppercase;color:var(--text-muted);">
            ${qs.length} carrier${qs.length === 1 ? '' : 's'} \u00b7 cheapest first</div>
          ${qs.map(q => `<div style="display:flex;align-items:center;gap:8px;padding:5px 0;border-top:1px solid var(--border);">
            <div style="flex:1;min-width:0;">
              <div style="font-size:12.5px;font-weight:700;">${escWeb(q.carrier_name)}</div>
              <div style="font-size:10.5px;color:var(--text-muted);">${escWeb(q.chart.rating_method || 'rate chart')}${
                q.chart.effective_date ? ' \u00b7 eff. ' + escWeb(q.chart.effective_date) : ''}${
                q.chart.household_discount_pct ? ' \u00b7 household \u2212' + q.chart.household_discount_pct + '%' : ''}</div>
            </div>
            <div style="font-size:15px;font-weight:800;color:var(--accent,#1d3557);white-space:nowrap;">$${q.rate.toFixed(2)}</div>
            <button type="button" class="btn ${slot >= 0 ? 'btn-outline' : 'btn-primary'} btn-sm"
              onclick="event.stopPropagation();qbMgAddPlan_('${escWeb(letter)}','${escWeb(q.product_id)}')">Add</button>
          </div>`).join('')}` : ''}

        ${manualOpen ? mgManualRow_(letter, !!qs.length) : `<button type="button" class="btn btn-outline btn-sm"
            style="width:100%;font-size:11px;margin-top:8px;" onclick="event.stopPropagation();mgManualOpen_('${escWeb(letter)}')">
            + Another carrier / type a rate</button>`}

        ${slot >= 0
          ? `<button type="button" class="btn btn-outline btn-sm" style="width:100%;margin-top:8px;"
               onclick="event.stopPropagation();qbMgAddPlan_('${escWeb(letter)}')">\u2713 Added \u2014 remove</button>`
          : (qs.length ? '' : `<button type="button" class="btn btn-primary btn-sm" style="width:100%;margin-top:8px;"
               onclick="event.stopPropagation();qbMgAddManual_('${escWeb(letter)}')">+ Add to quote</button>`)}
      </div>
    </div>`;
}

window._qbMgCmp = window._qbMgCmp || new Set();

// A product's code carries the letter: "Plan G", "HD Plan G".
function mgLetterOf_(product) {
  const code = String(product.product_code || product.name || '');
  const m = code.match(/^(HD )?Plan\s+([A-N])$/i);
  if (!m) return null;
  return (m[1] ? 'HD' : '') + m[2].toUpperCase();
}

// For every lettered plan, which of YOUR carriers quote it in their state and
// at what price. One pass over the charts rather than a query per product.
// What Original Medicare costs this year. These are the same for everyone \u2014
// no plan changes them \u2014 so they are context for a quote, never part of it.
// Which ones matter depends on what is being shopped for.
const MED_FACT_LABEL = {
  part_a_deductible:     ['Hospital deductible', 'each benefit period'],
  part_a_coins_61_90:    ['Hospital days 61\u201390', 'a day'],
  part_a_coins_lifetime: ['Lifetime reserve days', 'a day'],
  part_a_snf_coins:      ['Nursing home days 21\u2013100', 'a day'],
  part_b_deductible:     ['Part B deductible', 'a year'],
  part_b_premium:        ['Part B premium', 'a month'],
  part_d_oop_cap:        ['Drug out-of-pocket limit', 'then $0 for covered drugs'],
  part_d_max_deductible: ['Most a drug plan may charge', 'deductible'],
};

const MED_FACTS_FOR = {
  'Medicare Supplement': ['part_a_deductible', 'part_a_coins_61_90', 'part_a_coins_lifetime',
                          'part_a_snf_coins', 'part_b_deductible', 'part_b_premium'],
  'Medicare Advantage':  ['part_b_premium', 'part_b_deductible', 'part_d_oop_cap'],
  'Part D (PDP)':        ['part_d_oop_cap', 'part_d_max_deductible', 'part_b_premium'],
};

const medFactMoney_ = v => '$' + Number(v).toLocaleString('en-US',
  { minimumFractionDigits: Number(v) % 1 ? 2 : 0, maximumFractionDigits: 2 });

// The year's amounts, fetched once. Held on window so the Medigap grid \u2014
// which is drawn synchronously \u2014 can read them. Keeps next year too: during
// annual enrolment both are live and the difference is the conversation.
async function planYearAmts_() {
  if (window._planYearAmts) return window._planYearAmts;
  window._planYearAmts = {};
  window._planYearNext = null;
  try {
    const thisYear = new Date().getFullYear();
    const { data } = await supabaseClient.from('plan_year_config')
      .select('*').order('plan_year', { ascending: false }).limit(4);
    const rows = data || [];
    window._planYearAmts = rows.find(r => r.plan_year <= thisYear) || rows[rows.length - 1] || {};
    const cur = window._planYearAmts.plan_year || thisYear;
    const nxt = rows.find(r => r.plan_year === cur + 1);
    // only worth showing once it actually holds figures
    window._planYearNext = (nxt && Object.keys(MED_FACT_LABEL).some(k => nxt[k] != null)) ? nxt : null;

    // the deductible ceiling comes from the plan data, not from CMS prose
    const { data: dm } = await supabaseClient.from('cms_plans')
      .select('drug_deductible').eq('plan_year', cur)
      .order('drug_deductible', { ascending: false }).limit(1);
    if (dm && dm[0]) window._planYearAmts.part_d_max_deductible = Number(dm[0].drug_deductible);
  } catch (e) {}
  return window._planYearAmts;
}

// The strip that goes above the cards in a plan picker.
function medFactsHtml_(line) {
  const keys = MED_FACTS_FOR[line];
  const cur = window._planYearAmts || {};
  if (!keys || !cur.plan_year) return '';
  const have = keys.filter(k => cur[k] != null);
  if (!have.length) return '';

  const next = window._planYearNext;
  const changed = next ? have.filter(k => next[k] != null && Number(next[k]) !== Number(cur[k])) : [];

  return `<div style="border:1px solid var(--border-info);background:var(--bg-info);border-radius:10px;padding:10px 13px;margin-bottom:12px;">
    <div style="font-size:10px;font-weight:800;letter-spacing:.5px;text-transform:uppercase;color:var(--text-info);margin-bottom:7px;">
      What Original Medicare costs in ${cur.plan_year} \u00b7 the same whichever plan they pick
    </div>
    <div style="display:flex;gap:8px 20px;flex-wrap:wrap;">
      ${have.map(k => `<div>
        <div style="font-size:14.5px;font-weight:800;color:var(--text-info);line-height:1.15;">${medFactMoney_(cur[k])}</div>
        <div style="font-size:10.5px;color:var(--text-info);opacity:.8;">${MED_FACT_LABEL[k][0]} \u00b7 ${MED_FACT_LABEL[k][1]}</div>
      </div>`).join('')}
    </div>
    ${changed.length ? `<div style="font-size:11px;color:var(--text-info);opacity:.9;margin-top:7px;padding-top:6px;border-top:1px solid var(--border-info);">
      In ${next.plan_year}: ${changed.map(k => MED_FACT_LABEL[k][0] + ' <strong>' + medFactMoney_(next[k]) + '</strong>').join(' \u00b7 ')}
    </div>` : ''}
  </div>`;
}

// What the quote was worked out from, whatever kind of quote it is. The ACA
// tool already records income and household; this adds the part that is true
// of every quote \u2014 where they live, and the doctors and drugs we checked.
function qbBasisSnapshot_() {
  const c = window._qbContact || {};
  const docs = (window._qbAcaDocs || []).filter(d => d.npi);
  const meds = (window._qbAcaMeds || []).filter(m => m.rxcui);
  if (!docs.length && !meds.length && !c.zip) return null;
  return {
    zip: c.zip || null,
    checked_at: new Date().toISOString(),
    doctors: docs.map(d => d.name),
    // the supply is worth showing: it is why the yearly figures say what they say
    medications_detail: meds.map(m => ({ name: m.name, days_supply: qbMedDays_(m) })),
    medications: meds.map(m => m.name),
  };
}

// Frozen into the quote so the client page draws the amounts that were true
// the day it was sent, not whatever is current when they open it.
function medFactsSnapshot_(lines) {
  const cur = window._planYearAmts || {};
  if (!cur.plan_year) return null;
  const keys = [...new Set(lines.flatMap(l => MED_FACTS_FOR[l] || []))];
  if (!keys.length) return null;
  const pick = row => keys.reduce((o, k) => { if (row[k] != null) o[k] = Number(row[k]); return o; }, {});
  const next = window._planYearNext;
  return {
    year: cur.plan_year,
    cur: pick(cur),
    next: next ? Object.assign({ year: next.plan_year }, pick(next)) : null,
  };
}

async function qbMgLoadRates_() {
  await planYearAmts_();
  const prof = qbMgProfile_();
  window._qbMgRates = {};
  window._qbMgQuotes = {};
  if (!prof.state || prof.age == null) { if (document.getElementById('qb-mg-picker')) renderMedigapPicker_(); return; }

  const { data: prods } = await supabaseClient.from('carrier_products')
    .select('id,name,product_code,carrier_id,is_active,line_of_business')
    .eq('line_of_business', 'Medicare Supplement').eq('is_active', true);
  const products = (prods || []).filter(p => mgLetterOf_(p));
  if (!products.length) { if (document.getElementById('qb-mg-picker')) renderMedigapPicker_(); return; }

  const { data: charts } = await supabaseClient.from('rate_charts')
    .select('*').in('product_id', products.map(p => p.id))
    .eq('is_active', true).eq('state', prof.state);
  if (!charts || !charts.length) { if (document.getElementById('qb-mg-picker')) renderMedigapPicker_(); return; }

  const { data: rows } = await supabaseClient.from('rate_rows')
    .select('*').in('chart_id', charts.map(c => c.id))
    .lte('age_min', prof.age).gte('age_max', prof.age);

  const carriers = window._qbCarriers || [];
  const zp = String(prof.zip || '').slice(0, 3);
  const g = prof.gender === 'F' ? 'F' : 'M';

  products.forEach(p => {
    const mine = (charts || []).filter(c => c.product_id === p.id);
    if (!mine.length) return;
    const chart = mine.find(c => c.zip_prefixes && zp && c.zip_prefixes.split(',').map(x => x.trim()).includes(zp))
      || mine.find(c => !c.zip_prefixes) || mine[0];
    const rr = (rows || []).filter(r => r.chart_id === chart.id);
    const pick = rr.find(r => r.gender === g && r.tobacco === prof.tobacco)
      || rr.find(r => r.gender === 'U' && r.tobacco === prof.tobacco)
      || rr.find(r => r.gender === g && !r.tobacco)
      || rr.find(r => r.gender === 'U' && !r.tobacco);
    if (!pick) return;
    const letter = mgLetterOf_(p);
    const carrier = carriers.find(c => c.id === p.carrier_id);
    (window._qbMgQuotes[letter] = window._qbMgQuotes[letter] || []).push({
      letter: letter, product_id: p.id, product_name: p.name,
      carrier_id: p.carrier_id, carrier_name: (carrier && carrier.name) || 'Carrier',
      rate: Number(pick.monthly_rate), chart: chart,
      appointed: !!carrier,
    });
  });

  Object.keys(window._qbMgQuotes).forEach(L => {
    window._qbMgQuotes[L].sort((a, b) => a.rate - b.rate);
    window._qbMgRates[L] = window._qbMgQuotes[L][0].rate;   // the cheapest, for the card
  });
  if (document.getElementById('qb-mg-picker')) renderMedigapPicker_();
}

function mgCmpToggle_(letter, cb) {
  if (cb.checked) {
    if (window._qbMgCmp.size >= 4) { cb.checked = false; showToast('Compare up to 4 plans at a time.'); return; }
    window._qbMgCmp.add(letter);
  } else window._qbMgCmp.delete(letter);
  renderMedigapPicker_();
}

function mgCmpClear_() { window._qbMgCmp.clear(); renderMedigapPicker_(); }

// Built to match the Medicare Advantage comparison, because an agent should
// not have to learn a different screen for every product line. High-deductible
// versions get their own column \u2014 they are a real choice, not a footnote.
async function openMgCompare_() {
  await planYearAmts_();
  const picked = [...window._qbMgCmp];
  if (picked.length < 2) { showToast('Tick \u2696\ufe0f Compare on at least 2 plans first.'); return; }
  const order = ['A','B','C','D','F','HDF','G','HDG','K','L','M','N'];
  const letters = order.filter(L => picked.includes(L)).concat(picked.filter(L => !order.includes(L)));

  let ov = document.getElementById('qb-mg-compare');
  if (!ov) {
    ov = document.createElement('div');
    ov.id = 'qb-mg-compare';
    ov.style.cssText = 'position:fixed;inset:0;z-index:99996;background:var(--surface-0);display:flex;flex-direction:column;';
    document.body.appendChild(ov);
  }

  const th = 'position:sticky;left:0;background:var(--surface-0);z-index:2;text-align:left;font-size:11.5px;font-weight:700;color:var(--text-muted);padding:9px 12px;border-bottom:1px solid var(--border);min-width:230px;';
  const td = 'padding:9px 12px;border-bottom:1px solid var(--border);font-size:12.5px;vertical-align:top;min-width:170px;text-align:center;';
  const row = (label, fn) => `<tr><th style="${th}">${label}</th>${letters.map(L => `<td style="${td}">${fn(L)}</td>`).join('')}</tr>`;
  const baseOf = L => String(L).replace(/^HD/, '');
  const cheapest = L => {
    const qs = (window._qbMgQuotes || {})[L] || [];
    return qs.length ? qs[0] : null;
  };

  ov.innerHTML = `
    <div style="padding:12px 18px;border-bottom:1px solid var(--border);display:flex;align-items:center;gap:12px;flex-wrap:wrap;">
      <div style="font-weight:800;font-size:15px;">\u2696\ufe0f Comparing ${letters.length} supplement plans</div>
      <div style="font-size:12px;color:var(--text-muted);">${escWeb(qbMgProfile_().state || '')}${qbMgProfile_().age ? ' \u00b7 age ' + qbMgProfile_().age : ''}</div>
      <button class="btn btn-outline btn-sm" style="margin-left:auto;" onclick="mgCmpClear_();document.getElementById('qb-mg-compare').style.display='none';">Clear picks</button>
      <button class="btn btn-outline btn-sm" onclick="document.getElementById('qb-mg-compare').style.display='none'">\u2715 Back</button>
    </div>

    <div style="flex:1;overflow:auto;padding:14px 18px;">
      <table style="border-collapse:collapse;width:100%;">
        <thead><tr><th style="${th}"></th>
          ${letters.map(L => {
            const q = cheapest(L);
            const slot = mgAddedSlot_(L);
            return `<td style="${td}border-bottom:1.5px solid var(--border);">
              <div style="font-size:10px;font-weight:800;letter-spacing:1px;text-transform:uppercase;color:var(--text-muted);">Plan</div>
              <div style="font-size:24px;font-weight:800;color:var(--accent,#c8a84b);line-height:1.1;">${escWeb(L)}</div>
              ${String(L).indexOf('HD') === 0 ? '<div style="font-size:10px;color:var(--text-warning);">high deductible</div>' : ''}
              ${q ? `<div style="font-size:10.5px;font-weight:800;text-transform:uppercase;letter-spacing:.4px;color:var(--text-muted);margin-top:6px;">${escWeb(q.carrier_name)}</div>
                     <div style="font-size:19px;font-weight:800;color:var(--accent,#1d3557);">$${q.rate.toFixed(2)}<span style="font-size:10px;font-weight:500;color:var(--text-muted);"> /mo</span></div>`
                  : '<div style="font-size:11px;color:var(--text-muted);margin-top:6px;">no rate chart</div>'}
              <button class="btn ${slot >= 0 ? 'btn-outline' : 'btn-primary'} btn-sm" style="width:100%;margin-top:8px;"
                onclick="qbMgAddPlan_('${escWeb(L)}'${q ? ",'" + escWeb(q.product_id) + "'" : ''});openMgCompare_();">
                ${slot >= 0 ? '\u2713 On the quote' : '+ Add to quote'}</button>
            </td>`;
          }).join('')}
        </tr></thead>
        <tbody>
          ${MEDIGAP_GRID.rows.map(([label, byLetter]) =>
            row(escWeb(label), L => MEDIGAP_MARK[byLetter[baseOf(L)] || 'none'])).join('')}
          ${row('Yearly out-of-pocket limit', L => (baseOf(L) === 'K' || baseOf(L) === 'L')
            ? '<span style="color:var(--text-success);font-weight:800;">\u2713</span>' : MEDIGAP_MARK.none)}
          ${letters.some(L => String(L).indexOf('HD') === 0)
            ? row('Yearly deductible first', L => String(L).indexOf('HD') === 0
              ? '<span style="color:var(--text-warning);font-weight:700;">Yes</span>' : MEDIGAP_MARK.none) : ''}
          ${letters.some(L => cheapest(L)) ? row('How the price changes', L => {
            const q = cheapest(L);
            const t = q && { 'attained-age': 'Rises with age', 'issue-age': 'Set at the age they buy', 'community': 'Same at every age' }[q.chart.rating_method];
            return t ? escWeb(t) : MEDIGAP_MARK.none;
          }) : ''}
        </tbody>
      </table>
      <div style="font-size:11px;color:var(--text-muted);margin-top:10px;line-height:1.5;">
        These benefits are set by federal law \u2014 the same letter covers the same things at every carrier. Plan N also
        has copays of up to $20 for office visits and $50 for an emergency room visit that does not lead to admission.
        A high-deductible plan behaves exactly like its letter once the yearly deductible is met.
      </div>
    </div>`;
  ov.style.display = 'flex';
}

// Everything about one lettered plan, in one place.
async function openMgDetail_(letter) {
  await planYearAmts_();
  const p = MEDIGAP_PLANS.find(x => x[0] === letter);
  if (!p) return;
  const base = letter.replace(/^HD/, '');
  let dr = document.getElementById('qb-mg-detail');
  if (!dr) {
    dr = document.createElement('div');
    dr.id = 'qb-mg-detail';
    dr.style.cssText = 'position:fixed;top:0;right:0;bottom:0;width:min(520px,92vw);z-index:99995;background:var(--surface-1);border-left:1px solid var(--border);box-shadow:-12px 0 40px rgba(15,23,42,.18);display:flex;flex-direction:column;';
    document.body.appendChild(dr);
  }
  const rate = (window._qbMgRates || {})[letter];
  const row = (label, val) => `<div style="display:flex;justify-content:space-between;gap:10px;padding:7px 0;border-bottom:1px solid var(--border);font-size:13px;">
      <span style="color:var(--text-muted);">${escWeb(label)}</span><span style="font-weight:600;text-align:right;">${val}</span></div>`;
  const covered = MEDIGAP_GRID.rows.filter(([, by]) => by[base] && by[base] !== 'none');
  const notCovered = MEDIGAP_GRID.rows.filter(([, by]) => !by[base] || by[base] === 'none');

  dr.style.display = 'flex';
  dr.innerHTML = `<div style="padding:16px 20px;border-bottom:1px solid var(--border);display:flex;align-items:center;gap:10px;">
      <div style="font-weight:800;font-size:16px;flex:1;min-width:0;">Plan ${escWeb(letter)}</div>
      <button class="btn btn-outline btn-sm" onclick="document.getElementById('qb-mg-detail').style.display='none'">\u2715 Close</button>
    </div>
    <div style="padding:16px 20px;overflow:auto;">
      <div style="font-size:13px;color:var(--text-secondary);line-height:1.55;">${escWeb(p[1])}</div>
      ${rate != null ? `<div style="font-size:24px;font-weight:800;color:var(--accent,#1d3557);margin-top:10px;">$${Number(rate).toFixed(2)}<span style="font-size:11px;font-weight:500;color:var(--text-muted);"> /mo</span></div>` : ''}
      ${letter.indexOf('HD') === 0 ? `<div class="pk-bar warn" style="border-radius:8px;border:1px solid;margin-top:10px;">
        High-deductible version: they pay everything themselves until the yearly deductible is met, then it behaves
        exactly like Plan ${escWeb(base)}.</div>` : ''}

      <div style="font-size:11px;font-weight:800;text-transform:uppercase;letter-spacing:.5px;color:var(--text-muted);margin:16px 0 4px;">What it pays</div>
      ${covered.map(([label, by]) => row(label, MEDIGAP_MARK[by[base]])).join('')}
      ${base === 'K' || base === 'L' ? row('Yearly out-of-pocket limit', '<span style="color:var(--text-success);font-weight:800;">\u2713</span>') : ''}

      ${notCovered.length ? `<div style="font-size:11px;font-weight:800;text-transform:uppercase;letter-spacing:.5px;color:var(--text-muted);margin:16px 0 4px;">What it does not pay</div>
      ${notCovered.map(([label]) => row(label, '<span style="color:var(--text-muted);">\u2014</span>')).join('')}` : ''}

      <div style="font-size:11px;color:var(--text-muted);margin-top:14px;line-height:1.5;">
        These benefits are fixed by federal law \u2014 Plan ${escWeb(base)} covers the same at every carrier. Only the
        premium, the rate increase history and the service differ.
      </div>
      <button class="btn ${mgAddedSlot_(letter) >= 0 ? 'btn-outline' : 'btn-primary'} btn-sm" style="width:100%;margin-top:14px;"
        onclick="qbMgAddPlan_('${escWeb(letter)}');openMgDetail_('${escWeb(letter)}');">
        ${mgAddedSlot_(letter) >= 0 ? '\u2713 On the quote \u2014 remove' : '+ Add Plan ' + escWeb(letter) + ' to the quote'}</button>
    </div>`;
}

// Everything needed to quote this letter, on the card itself: who is writing
// it and for how much. The carrier list is yours, but an agent can always type
// one we don't have \u2014 the system should never be the reason a quote can't be
// written.
function mgManualRow_(letter, secondary) {
  const carriers = (window._qbCarriers || []).slice()
    .sort((a, b) => String(a.name).localeCompare(String(b.name)));
  const st = window._qbMgManual = window._qbMgManual || {};
  const slot = mgAddedSlot_(letter);
  if (!st[letter] && slot >= 0) {
    const sel = (window._qbMgSel || {})[slot] || {};
    const byName = sel.carrier_name
      ? (window._qbCarriers || []).find(c => String(c.name).toLowerCase() === String(sel.carrier_name).toLowerCase())
      : null;
    if (byName && !sel.carrier_id) sel.carrier_id = byName.id;
    st[letter] = {
      carrier_id: sel.carrier_id || (byName ? byName.id : (sel.carrier_name ? '_other' : '')),
      carrier_name: sel.carrier_name || '',
      rate: sel.rate != null ? Number(sel.rate).toFixed(2)
        : (parseFloat((document.getElementById('qb-prem-' + slot) || {}).value) > 0
            ? Number((document.getElementById('qb-prem-' + slot) || {}).value).toFixed(2) : ''),
    };
  }
  const cur = st[letter] || {};
  const typing = cur.carrier_id === '_other';
  const onQuote = slot >= 0;
  return `<div style="margin-top:${secondary ? '8' : '9'}px;padding-top:${secondary ? '8' : '0'}px;${secondary ? 'border-top:1px dashed var(--border);' : ''}"
       onclick="event.stopPropagation();">
      ${secondary ? '<div style="font-size:10px;font-weight:800;letter-spacing:.5px;text-transform:uppercase;color:var(--text-muted);margin-bottom:5px;">Or another carrier</div>' : ''}
      <div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center;">
        <select onchange="mgManualSet_('${escWeb(letter)}','carrier_id',this.value)" style="flex:1;min-width:130px;width:auto;font-size:12px;">
          <option value="">&mdash; carrier &mdash;</option>
          ${carriers.map(c => `<option value="${escWeb(c.id)}" ${cur.carrier_id === c.id ? 'selected' : ''}>${escWeb(c.name)}</option>`).join('')}
          <option value="_other" ${typing ? 'selected' : ''}>+ type another carrier\u2026</option>
        </select>
        ${typing ? `<input type="text" placeholder="Carrier name" value="${escWeb(cur.carrier_name || '')}"
          oninput="mgManualSet_('${escWeb(letter)}','carrier_name',this.value,true)"
          style="flex:1;min-width:130px;width:auto;font-size:12px;" />` : ''}
        <span style="position:relative;display:inline-flex;align-items:center;">
          <span style="position:absolute;left:8px;font-size:12px;color:var(--text-muted);">$</span>
          <input type="text" inputmode="decimal" placeholder="0.00" value="${escWeb(cur.rate || '')}"
            oninput="mgManualSet_('${escWeb(letter)}','rate',this.value,true)"
            onblur="mgManualMoney_('${escWeb(letter)}',this)"
            style="width:96px;padding-left:18px;font-size:12px;text-align:right;" />
        </span>
        ${onQuote ? `<button type="button" class="btn btn-outline btn-sm" style="font-size:11px;"
          onclick="event.stopPropagation();qbMgAddManual_('${escWeb(letter)}')">Update</button>` : ''}
      </div>
    </div>`;
}

function mgManualOpen_(letter) {
  window._qbMgManualOpen = window._qbMgManualOpen || {};
  window._qbMgManualOpen[letter] = true;
  renderMedigapPicker_();
}

function mgManualSet_(letter, field, value, quiet) {
  const st = window._qbMgManual = window._qbMgManual || {};
  const cur = st[letter] = st[letter] || {};
  cur[field] = value;
  if (field === 'carrier_id' && value && value !== '_other') {
    const c = (window._qbCarriers || []).find(x => x.id === value);
    cur.carrier_name = c ? c.name : '';
    // if a chart already prices this carrier for this letter, use it
    const hit = ((window._qbMgQuotes || {})[letter] || []).find(q => q.carrier_id === value);
    if (hit) cur.rate = Number(hit.rate).toFixed(2);
  }
  if (!quiet) renderMedigapPicker_();
}

function mgManualMoney_(letter, el) {
  const n = parseFloat(String(el.value).replace(/[^0-9.]/g, ''));
  const st = window._qbMgManual = window._qbMgManual || {};
  st[letter] = st[letter] || {};
  if (isNaN(n)) { el.value = ''; st[letter].rate = ''; return; }
  el.value = n.toFixed(2);
  st[letter].rate = el.value;
}

function qbMgAddManual_(letter) {
  const cur = (window._qbMgManual || {})[letter] || {};
  const name = cur.carrier_id === '_other' ? String(cur.carrier_name || '').trim()
    : ((window._qbCarriers || []).find(c => c.id === cur.carrier_id) || {}).name;
  if (!name) { showToast('Choose a carrier, or type one in.'); return; }
  const rate = parseFloat(String(cur.rate || '').replace(/[^0-9.]/g, ''));
  const known = ((window._qbMgQuotes || {})[letter] || []).find(q => q.carrier_id === cur.carrier_id);
  qbMgAddPlan_(letter, known ? known.product_id : null, {
    carrier_id: cur.carrier_id === '_other' ? null : cur.carrier_id,
    carrier_name: name,
    rate: isNaN(rate) ? null : rate,
  });
}

function renderMedigapPicker_() {
  const el = document.getElementById('qb-mg-picker');
  if (!el) return;
  if (!window._qbListsFilled && !(window._qbAcaMeds || []).length) {
    qbAcaFillListsFromClient_().then(renderMedigapPicker_); return;
  }
  const prof = qbMgProfile_();
  const letters = medigapLetters_(prof);
  const w = medigapWindow_(prof);
  const gridLetters = ['A', 'B', 'C', 'D', 'F', 'G', 'K', 'L', 'M', 'N']
    .filter(L => letters.some(p => p[0] === L));
  const chosen = [];
  for (let i = 0; i < QB_MAX_OPTIONS; i++) if ((window._qbMgSel || {})[i]) chosen.push({ i: i, p: window._qbMgSel[i] });

  el.innerHTML = `
    <div style="padding:12px 18px;border-bottom:1px solid var(--border);display:flex;align-items:center;gap:12px;flex-wrap:wrap;">
      <div style="font-weight:800;font-size:15px;">\u{1F511} Medicare Supplement \u00b7 ${escWeb(prof.state || '')}</div>
      <div style="font-size:12px;color:var(--text-muted);">${letters.length} plans they can buy${prof.age ? ' \u00b7 age ' + prof.age : ''}</div>
      ${window._qbMgCmp.size ? `<button class="btn ${window._qbMgCmp.size >= 2 ? 'btn-primary' : 'btn-outline'} btn-sm"
        style="margin-left:auto;" ${window._qbMgCmp.size >= 2 ? '' : 'disabled'} onclick="openMgCompare_()">\u2696\ufe0f Compare (${window._qbMgCmp.size})</button>` : ''}
      <button class="btn ${window._qbMgShowGrid ? 'btn-primary' : 'btn-outline'} btn-sm" ${window._qbMgCmp.size ? '' : 'style="margin-left:auto;"'} onclick="mgToggleGrid_()">
        ${window._qbMgShowGrid ? '\u25A4 Show the plans' : '\u25A4 All benefits at once'}</button>
      <button class="btn btn-outline btn-sm" onclick="closeMedigapPicker_()">\u2715 Done</button>
    </div>

    <div style="padding:9px 18px;border-bottom:1px solid var(--border);">
      <div class="pk-bar ${w.tone === 'ok' ? 'ok' : (w.tone === 'warn' ? 'warn' : 'muted')}" style="border-radius:8px;border:1px solid;">${w.note}</div>
      ${w.extra.filter(x => x.tone !== 'muted').map(x => `<div class="pk-bar ${x.tone === 'ok' ? 'ok' : 'warn'}" style="border-radius:8px;border:1px solid;margin-top:5px;">${x.text}</div>`).join('')}
    </div>

    <div id="qb-med-basis" data-kind="MEDIGAP" style="background:var(--surface-1);border-bottom:1px solid var(--border);">${qbMedBasisHtml_('MEDIGAP')}</div>

    <div style="flex:1;overflow:auto;padding:14px 18px;">
      ${medFactsHtml_('Medicare Supplement')}
      ${window._qbMgShowGrid
        ? mgGridHtml_(gridLetters)
        : `<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:12px;">${letters.map(mgCardHtml_).join('')}</div>`}
    </div>

    ${chosen.length ? `<div class="pk-tray" style="padding:10px 20px;display:flex;gap:10px;align-items:center;flex-wrap:wrap;">
      <span class="pk-tray-label">On the quote \u00b7 ${chosen.length}</span>
      ${chosen.map(x => `<div class="pk-tray-item">
        <span class="num">${qbOptionNo_(x.i)}</span>
        <span class="who">
          ${x.p.carrier_name ? `<span class="carrier">${escWeb(x.p.carrier_name)}</span>` : ''}
          <span class="pname">Plan ${escWeb(x.p.letter)}${x.p.rate != null ? ' \u00b7 $' + Number(x.p.rate).toFixed(2) : ''}</span>
        </span>
        <button class="rm" onclick="qbMgRemoveSlot_(${x.i})" title="Take off the quote">\u2715</button>
      </div>`).join('')}
      <button class="btn btn-primary btn-sm" style="margin-left:auto;" onclick="closeMedigapPicker_()">Done \u2014 back to the quote</button>
    </div>` : ''}`;
}

// The same treatment the ACA and Medicare Advantage options get: a record,
// not a form. The letter is the coverage; the carrier is the choice.
function qbMgOptionView_(i) {
  const card = document.getElementById('qb-mg-card-' + i);
  const manual = document.getElementById('qb-manual-' + i);
  const carprod = document.getElementById('qb-carprod-' + i);
  const p = (window._qbMgSel || {})[i];
  if (!card) return;

  if (!p) {
    card.style.display = 'none'; card.innerHTML = '';
    if (manual) manual.style.display = '';
    if (carprod) carprod.style.display = '';
    return;
  }
  const needsTyping = p.rate == null;
  const carPicked = !!p.carrier_name || !!p.carrier_id || !!(document.getElementById('qb-car-' + i) || {}).value;
  if (manual) manual.style.display = needsTyping ? '' : 'none';
  if (carprod) carprod.style.display = carPicked ? 'none' : '';

  const base = String(p.letter).replace(/^HD/, '');
  const pays = MEDIGAP_GRID.rows.filter(([, by]) => by[base] && by[base] !== 'none');
  const gaps = MEDIGAP_GRID.rows.filter(([, by]) => !by[base] || by[base] === 'none');
  const method = { 'attained-age': 'Attained-age \u2014 the premium rises as they age',
                   'issue-age': 'Issue-age \u2014 priced at the age they buy',
                   'community': 'Community-rated \u2014 everyone pays the same' }[p.rating_method] || null;

  card.style.display = 'block';
  card.innerHTML = `
    <div class="pk-card is-selected" style="border-radius:12px;padding:12px 14px;">
      <div style="display:flex;gap:8px;align-items:baseline;flex-wrap:wrap;">
        <span style="font-size:10px;font-weight:800;letter-spacing:1px;text-transform:uppercase;color:var(--text-muted);">Plan</span>
        <span style="font-size:22px;font-weight:800;color:var(--accent,#c8a84b);line-height:1;">${escWeb(p.letter)}</span>
        ${p.letter.indexOf('HD') === 0 ? '<span style="font-size:10px;color:var(--text-warning);border:1px solid var(--border-warning);border-radius:6px;padding:2px 6px;">high deductible</span>' : ''}
        <span style="font-size:10px;color:var(--text-muted);border:1px solid var(--border);border-radius:6px;padding:2px 6px;">standardized by law</span>
      </div>
      ${p.carrier_name
        ? `<div style="font-size:10.5px;font-weight:800;text-transform:uppercase;letter-spacing:.5px;color:var(--text-muted);margin-top:7px;">${escWeb(p.carrier_name)}</div>`
        : `<div class="pk-bar warn" style="border-radius:8px;border:1px solid;margin-top:8px;font-size:11.5px;">
             &#9888;&#65039; <strong>Pick the carrier below</strong> \u2014 the letter says what it covers, the carrier says who writes it and what it costs.
           </div>`}
      <div style="font-size:14px;font-weight:700;margin:1px 0 8px;">Medicare Supplement Plan ${escWeb(p.letter)}</div>

      <div style="display:flex;align-items:flex-end;gap:14px;flex-wrap:wrap;">
        <div>
          <div style="font-size:22px;font-weight:800;color:var(--accent,#1d3557);line-height:1;">${p.rate != null ? '$' + Number(p.rate).toFixed(2) : '\u2014'}<span style="font-size:10.5px;font-weight:500;color:var(--text-muted);"> /mo</span></div>
          ${method ? `<div style="font-size:10.5px;color:var(--text-muted);margin-top:2px;">${escWeb(method)}</div>` : ''}
        </div>
        <div style="margin-left:auto;font-size:12px;color:var(--text-secondary);text-align:right;">
          <div style="font-size:10px;color:var(--text-muted);">Pays in full</div>
          <div style="font-weight:700;">${pays.length} of ${MEDIGAP_GRID.rows.length} gaps</div>
        </div>
      </div>

      <div style="margin-top:8px;border-top:1px solid var(--border);padding-top:6px;">
        <div style="display:flex;gap:5px;flex-wrap:wrap;">
          ${pays.slice(0, 5).map(([label, by]) => `<span class="pk-pill ${by[base] === 'full' || by[base] === 'copay' ? 'ok' : 'unk'}">${by[base] === 'full' ? '\u2713' : by[base] === 'copay' ? '\u2713' : by[base] + '%'} ${escWeb(label.replace(/ \(80%\)/, ''))}</span>`).join(' ')}
          ${pays.length > 5 ? `<span class="pk-pill unk">+${pays.length - 5} more</span>` : ''}
        </div>
        ${gaps.length ? `<div style="font-size:11px;color:var(--text-muted);margin-top:5px;">Not covered: ${gaps.map(([l]) => escWeb(l)).join(', ')}</div>` : ''}
      </div>

      <div style="display:flex;gap:8px;margin-top:10px;flex-wrap:wrap;">
        <button type="button" class="btn btn-outline btn-sm" onclick="openMgDetail_('${escWeb(p.letter)}')">Plan details</button>
        <button type="button" class="btn btn-outline btn-sm" onclick="openMedigapPicker_()">\u{1F5D6} Change plan or carrier</button>
        <button type="button" class="btn btn-outline btn-sm" style="color:var(--text-danger);border-color:var(--border-danger);margin-left:auto;" onclick="qbMgRemoveSlot_(${i})">\u{1F5D1} Remove</button>
      </div>
      <div style="font-size:10.5px;color:var(--text-muted);margin-top:8px;">Benefits are fixed by federal law \u2014 Plan ${escWeb(base)} covers the same at every carrier. ${p.rate != null ? 'The premium comes from your loaded rate chart.' : 'No rate chart loaded for this state \u2014 enter the premium in the box below, or load the chart under Admin \u2192 Carriers &amp; Products.'}</div>
    </div>`;
}

function qbMgRemoveSlot_(i) {
  if (!(window._qbMgSel || {})[i]) return;
  const letter = window._qbMgSel[i].letter;
  if (letter && window._qbMgManual) delete window._qbMgManual[letter];
  delete window._qbMgSel[i];
  ['qb-name-' + i, 'qb-prem-' + i, 'qb-bul-' + i].forEach(id => {
    const el = document.getElementById(id);
    if (el) { const ro = el.readOnly; el.readOnly = false; el.value = ''; el.readOnly = ro; }
  });
  qbMgOptionView_(i);
  qbTidyOptions_();
  if (document.getElementById('qb-mg-picker')) renderMedigapPicker_();
}

function qbMgAddPlan_(letter, productId, override) {
  const at = mgAddedSlot_(letter);
  if (at >= 0 && !productId && !override) { qbMgRemoveSlot_(at); return; }
  if (at >= 0) { qbMgRemoveSlot_(at); }   // swapping carrier or rate
  const p = MEDIGAP_PLANS.find(x => x[0] === letter);
  if (!p) return;

  let slot = -1;
  for (let i = 0; i < QB_MAX_OPTIONS; i++) {
    const w = document.getElementById('qb-opt-wrap-' + i);
    const nm = document.getElementById('qb-name-' + i);
    if (!w || !nm) continue;
    const empty = !nm.value.trim() && !(window._qbMgSel || {})[i]
      && !(window._qbCmsSel || {})[i] && !(window._qbAcaSel || {})[i];
    if (w.style.display !== 'none' && empty) { slot = i; break; }
  }
  if (slot < 0) {
    qbRevealOption_();
    for (let i = 0; i < QB_MAX_OPTIONS; i++) {
      const w = document.getElementById('qb-opt-wrap-' + i);
      const nm = document.getElementById('qb-name-' + i);
      if (w && w.style.display !== 'none' && nm && !nm.value.trim()) { slot = i; break; }
    }
  }
  if (slot < 0) { showToast('All ' + QB_MAX_OPTIONS + ' options are full \u2014 remove one first.'); return; }

  const _w = document.getElementById('qb-opt-wrap-' + slot);
  if (_w) _w.style.display = 'block';
  qbRenumberOptions_();
  const prof = qbMgProfile_();
  const quotes = (window._qbMgQuotes || {})[letter] || [];
  const q = productId ? quotes.find(x => x.product_id === productId) : (override ? null : quotes[0]);
  const rate = (override && override.rate != null) ? override.rate
    : (q ? q.rate : (window._qbMgRates || {})[letter]);
  window._qbMgSel = window._qbMgSel || {};
  window._qbMgSel[slot] = {
    letter: letter, title: p[1], bullets: p[2], state: prof.state,
    rate: rate != null ? rate : null,
    carrier_id: (override ? override.carrier_id : null) || (q ? q.carrier_id : null),
    carrier_name: (override ? override.carrier_name : null) || (q ? q.carrier_name : null),
    product_id: q ? q.product_id : null,
    rating_method: q ? q.chart.rating_method : null,
  };

  const ol = document.getElementById('qb-optline-' + slot);
  if (ol && ol.value !== 'Medicare Supplement') { ol.value = 'Medicare Supplement'; qbOptLineChanged_(slot); }

  // point the option at the real carrier and product so the quote records them
  const carId = (override && override.carrier_id) || (q && q.carrier_id);
  if (carId && !q) {
    const car = document.getElementById('qb-car-' + slot);
    if (car) { car.value = carId; qbFillProducts_(slot); }
  }
  if (q) {
    const car = document.getElementById('qb-car-' + slot);
    if (car) {
      car.value = q.carrier_id;
      qbFillProducts_(slot);
      setTimeout(() => {
        const pr = document.getElementById('qb-prod-' + slot);
        if (pr) { pr.value = q.product_id; qbApplyProduct_(slot); }
        const prem = document.getElementById('qb-prem-' + slot);
        if (prem && rate != null) prem.value = Number(rate).toFixed(2);
      }, 250);
    }
  }

  const nm = document.getElementById('qb-name-' + slot);
  const carrierLabel = (override && override.carrier_name) || (q && q.carrier_name) || '';
  if (nm) nm.value = (carrierLabel ? carrierLabel + ' \u2014 ' : '') + 'Medicare Supplement Plan ' + letter;
  if (rate != null) { const pr = document.getElementById('qb-prem-' + slot); if (pr) pr.value = Number(rate).toFixed(2); }
  const bul = document.getElementById('qb-bul-' + slot);
  if (bul) { const ro = bul.readOnly; bul.readOnly = false; bul.value = p[2].join('\n'); bul.readOnly = ro; }

  qbMgOptionView_(slot);
  renderMedigapPicker_();
  qbSectionSummary_();
  showToast('Added as option ' + qbOptionNo_(slot) + '.');
}

// "Medicare Supplement Plan G", "... High-Deductible Plan G" \u2014 the letter is
// right there in the name, so an option saved before we recorded a snapshot
// can still be recognized.
function mgLetterFromName_(name) {
  const t = String(name || '');
  let m = t.match(/High[- ]?Deductible Plan\s+([A-N])\b/i) || t.match(/\bHD Plan\s+([A-N])\b/i);
  if (m) return 'HD' + m[1].toUpperCase();
  m = t.match(/Medicare Supplement Plan\s+([A-N])\b/i) || t.match(/\bPlan\s+([A-N])\b/i);
  return m ? m[1].toUpperCase() : null;
}

function qbMgProfile_() {
  const c = window._qbContact || {};
  const zip = (document.getElementById('qb-mg-zip') || {}).value || c.zip || '';
  return {
    zip: zip,
    state: (zipToState_(zip) || c.state || '').toUpperCase(),
    age: parseInt((document.getElementById('qb-mg-age') || {}).value) || null,
    gender: (document.getElementById('qb-rt-gender') || {}).value || c.gender || '',
    tobacco: !!(document.getElementById('qb-rt-tob') || {}).checked,
    dob: c.date_of_birth || c.dob || window._qbMgDob || null,
    part_b_date: (document.getElementById('qb-mg-partb') || {}).value || null,
  };
}

function qbAgeFrom_(dob) {
  const d = new Date(dob);
  if (isNaN(d)) return null;
  const n = new Date();
  let a = n.getFullYear() - d.getFullYear();
  if (n < new Date(n.getFullYear(), d.getMonth(), d.getDate())) a--;
  return a;
}

// Turning 65 makes someone Medicare-eligible on the first of that month
// (or the month before, if they were born on the 1st). It is the usual Part B
// start date, so it is a reasonable assumption \u2014 clearly labelled as one.
function qbPartBGuess_(dob) {
  const d = new Date(dob);
  if (isNaN(d)) return null;
  const at65 = new Date(d.getFullYear() + 65, d.getMonth(), 1);
  if (d.getDate() === 1) at65.setMonth(at65.getMonth() - 1);
  return at65.toISOString().slice(0, 10);
}

async function qbMgInit_() {
  const c = window._qbContact;
  if (!c || !document.getElementById('qb-mg-zip')) return;
  const zip = document.getElementById('qb-mg-zip');
  if (!zip.value && c.zip) zip.value = c.zip;
  const age = document.getElementById('qb-mg-age');
  const pb = document.getElementById('qb-mg-partb');
  const tob = document.getElementById('qb-rt-tob');
  if (tob && c.tobacco_use) tob.checked = true;
  const gen = document.getElementById('qb-rt-gender');
  if (gen && !gen.value && c.gender) gen.value = c.gender;
  window._qbMgSource = { dob: null, partb: null };

  let dob = c.date_of_birth || c.dob || null;
  if (dob) window._qbMgSource.dob = 'their contact record';

  // The intake tied to THIS quote first, then their newest Medicare intake.
  let responses = null;
  try {
    if (window._qbIntakeSessionId) {
      const { data } = await supabaseClient.from('intake_sessions')
        .select('responses').eq('id', window._qbIntakeSessionId).maybeSingle();
      if (data) responses = data.responses || {};
    }
    if (!responses || (!responses.med_part_b_date && !responses.dob)) {
      const { data } = await supabaseClient.from('intake_sessions')
        .select('responses,form_type,created_at').eq('contact_id', c.id)
        .order('created_at', { ascending: false }).limit(6);
      const med = (data || []).find(x => x.form_type === 'medicare' && x.responses
        && (x.responses.med_part_b_date || x.responses.dob));
      if (med) responses = med.responses;
      else if (!responses) responses = ((data || [])[0] || {}).responses || {};
    }
  } catch (e) { responses = responses || {}; }
  responses = responses || {};

  if (!dob && responses.dob) { dob = responses.dob; window._qbMgSource.dob = 'their intake'; }
  window._qbMgDob = dob || null;
  if (!age.value && dob) age.value = qbAgeFrom_(dob) ?? '';

  if (!pb.value && c.part_b_effective) {
    pb.value = String(c.part_b_effective).slice(0, 10);
    window._qbMgSource.partb = 'their contact record';
  }
  if (!pb.value) {
    const fromIntake = String(responses.med_part_b_date || '').slice(0, 10);
    if (fromIntake) { pb.value = fromIntake; window._qbMgSource.partb = 'their intake'; }
    else if (dob) {
      const guess = qbPartBGuess_(dob);
      if (guess && new Date(guess) <= new Date()) {
        pb.value = guess;
        window._qbMgSource.partb = 'assumed \u2014 the month they turned 65';
      }
    }
  }
  qbMgRefresh_();
}

// The Part B date belongs to the client, not to this quote \u2014 it goes back on
// the contact record and into their Medicare intake, so every later quote and
// every other agent sees it.
async function qbMgPartBChanged_() {
  const c = window._qbContact;
  const val = String((document.getElementById('qb-mg-partb') || {}).value || '').slice(0, 10) || null;
  qbMgRefresh_();
  if (!c) return;
  try {
    const { error } = await supabaseClient.from('contacts')
      .update({ part_b_effective: val }).eq('id', c.id).select('id');
    if (error) throw error;
    c.part_b_effective = val;
    const cc = contacts.find(x => x.id === c.id); if (cc) cc.part_b_effective = val;
  } catch (e) { console.error('part b -> contact:', e); showToast('Could not save the Part B date.'); return; }

  // and into the Medicare intake it came from, so the two never disagree
  try {
    const { data } = await supabaseClient.from('intake_sessions')
      .select('id,responses').eq('contact_id', c.id).eq('form_type', 'medicare')
      .order('created_at', { ascending: false }).limit(1);
    const row = data && data[0];
    if (row) {
      const resp = Object.assign({}, row.responses || {}, { med_part_b_date: val });
      await supabaseClient.from('intake_sessions').update({ responses: resp }).eq('id', row.id).select('id');
    }
  } catch (e) { console.error('part b -> intake:', e); }
  window._qbMgSource = window._qbMgSource || {};
  window._qbMgSource.partb = 'their contact record';
  qbMgRefresh_();
}

function qbMgZipChanged_() {
  const c = window._qbContact;
  const zip = String((document.getElementById('qb-mg-zip') || {}).value || '').trim();
  if (/^\d{5}$/.test(zip) && c && zip !== c.zip) {
    const st = zipToState_(zip);
    const patch = st ? { zip: zip, state: st } : { zip: zip };
    supabaseClient.from('contacts').update(patch).eq('id', c.id).then(() => {
      Object.assign(c, patch);
      const cc = contacts.find(x => x.id === c.id); if (cc) Object.assign(cc, patch);
    });
  }
  qbMgRefresh_();
}

// Say plainly whether they can buy today without health questions.
function qbMgRefresh_() {
  const box = document.getElementById('qb-mg-window');
  if (!box) return;
  const prof = qbMgProfile_();
  const w = medigapWindow_(prof);
  const bars = [['<div class="pk-bar ' + (w.tone === 'ok' ? 'ok' : (w.tone === 'warn' ? 'warn' : 'muted'))
    + '" style="margin-bottom:5px;">' + w.note + '</div>']];
  w.extra.forEach(x => bars.push(['<div class="pk-bar ' + (x.tone === 'ok' ? 'ok' : (x.tone === 'warn' ? 'warn' : 'muted'))
    + '" style="margin-bottom:5px;">' + x.text + '</div>']));
  const pre = medigapEligibleBefore2020_(prof);
  if (pre === false) {
    bars.push(['<div class="pk-bar muted" style="margin-bottom:5px;">Plans <strong>C, F and high-deductible F</strong> '
      + 'are closed to them \u2014 they became eligible for Medicare after 1 January 2020. Those letters are hidden below.</div>']);
  } else if (pre === null) {
    bars.push(['<div class="pk-bar warn" style="margin-bottom:5px;">No date of birth or Part B date on file, so we '
      + 'cannot tell whether Plans C and F are open to them. Add one before quoting those.</div>']);
  }
  // Someone years away from 65 shouldn't be shown a Medigap window at all.
  const age65 = prof.age != null ? prof.age : (prof.dob ? qbAgeFrom_(prof.dob) : null);
  if (!prof.part_b_date && age65 != null && age65 < 64) {
    bars.length = 0;
    bars.push(['<div class="pk-bar warn" style="margin-bottom:5px;">They are <strong>' + age65
      + '</strong> — not Medicare-eligible yet. Medicare Supplement starts at 65, or earlier on disability. '
      + 'If they are eligible early, enter their Part B start date.</div>']);
  }

  const src = window._qbMgSource || {};
  const notes = [];
  if (prof.dob) notes.push('Age ' + (qbAgeFrom_(prof.dob) ?? '?') + ' from their date of birth'
    + (src.dob ? ' (' + src.dob + ')' : ''));
  else notes.push('<strong>No date of birth on file</strong> \u2014 add one to their contact record');
  if (prof.part_b_date && src.partb) notes.push('Part B date ' + (src.partb.indexOf('assumed') === 0
    ? '<strong>' + src.partb + '</strong> \u2014 confirm it with them' : 'from ' + src.partb));
  bars.push(['<div style="font-size:11px;color:var(--text-muted);margin-top:2px;">' + notes.join(' \u00b7 ') + '</div>']);

  box.innerHTML = bars.map(b => b[0]).join('');
  if (document.getElementById('qb-mg-picker')) qbMgLoadRates_();
}

// ============================================================
// MEDICARE SUPPLEMENT \u2014 what the law fixes, we can automate.
//
// Medigap letters are standardized by federal law: Plan G from one carrier
// covers exactly what Plan G from any other covers. Only price and service
// differ. So the benefit grid, who may buy which letter, and when they can
// buy without answering health questions are all knowable without a single
// carrier feed \u2014 which is just as well, because no public rate source exists.
// ============================================================

// Benefit \u00d7 plan letter, straight from the federal standardisation.
// full = paid in full, 50/75 = that share, none = not covered.
const MEDIGAP_GRID = {
  rows: [
    ['Part A coinsurance & 365 extra hospital days', { A:'full', B:'full', C:'full', D:'full', F:'full', G:'full', K:'full', L:'full', M:'full', N:'full' }],
    ['Part B coinsurance or copayment',              { A:'full', B:'full', C:'full', D:'full', F:'full', G:'full', K:'50',   L:'75',   M:'full', N:'copay' }],
    ['First 3 pints of blood',                       { A:'full', B:'full', C:'full', D:'full', F:'full', G:'full', K:'50',   L:'75',   M:'full', N:'full' }],
    ['Part A hospice coinsurance',                   { A:'full', B:'full', C:'full', D:'full', F:'full', G:'full', K:'50',   L:'75',   M:'full', N:'full' }],
    ['Skilled nursing facility coinsurance',         { A:'none', B:'none', C:'full', D:'full', F:'full', G:'full', K:'50',   L:'75',   M:'full', N:'full' }],
    ['Part A hospital deductible',                   { A:'none', B:'full', C:'full', D:'full', F:'full', G:'full', K:'50',   L:'75',   M:'50',   N:'full' }],
    ['Part B deductible',                            { A:'none', B:'none', C:'full', D:'none', F:'full', G:'none', K:'none', L:'none', M:'none', N:'none' }],
    ['Part B excess charges',                        { A:'none', B:'none', C:'none', D:'none', F:'full', G:'full', K:'none', L:'none', M:'none', N:'none' }],
    ['Foreign travel emergency (80%)',               { A:'none', B:'none', C:'full', D:'full', F:'full', G:'full', K:'none', L:'none', M:'full', N:'full' }],
  ],
};

const MEDIGAP_MARK = {
  full: '<span style="color:var(--text-success);font-weight:800;">\u2713</span>',
  '50': '<span style="color:var(--text-warning);font-weight:700;">50%</span>',
  '75': '<span style="color:var(--text-warning);font-weight:700;">75%</span>',
  copay: '<span style="color:var(--text-success);font-weight:800;">\u2713</span><span style="font-size:10px;color:var(--text-muted);"> less copays</span>',
  none: '<span style="color:var(--text-muted);">\u2014</span>',
};

// Massachusetts, Minnesota and Wisconsin standardize differently; the letter
// grid above does not describe their plans.
const MEDIGAP_WAIVER_STATES = { MA: 'Massachusetts', MN: 'Minnesota', WI: 'Wisconsin' };

// States with a "birthday rule" \u2014 an annual window to move to an equal or
// lesser plan with no health questions. Reviewed 2026-07-30; these change by
// legislature, so re-check each year.
const MEDIGAP_BIRTHDAY_RULES = {
  CA: 'Starts 30 days before their birthday and runs 60 days after \u2014 equal or lesser benefits.',
  OR: 'The 30 days starting on their birthday \u2014 equal or lesser benefits.',
  ID: 'The 63 days starting on their birthday \u2014 equal or lesser benefits.',
  IL: 'The 45 days starting on their birthday, ages 65\u201375 \u2014 same letter, any carrier.',
  NV: 'The 60 days starting the first day of their birth month \u2014 equal or lesser benefits.',
  LA: 'The 63 days starting on their birthday \u2014 same letter, any carrier.',
  OK: 'The 60 days starting on their birthday \u2014 equal or lesser benefits.',
  MD: 'A window around their birthday \u2014 equal or lesser benefits.',
  KY: 'The 60 days starting on their birthday \u2014 equal or lesser benefits.',
};

// States where an application can be made at any time without underwriting.
const MEDIGAP_YEAR_ROUND = {
  CT: 'Connecticut requires continuous open enrollment \u2014 no health questions at any time.',
  NY: 'New York requires continuous open enrollment \u2014 no health questions at any time.',
  ME: 'Maine has a designated annual open enrollment month and guaranteed-issue rules.',
  WA: 'Washington lets someone already on a Medigap plan switch at any time (except from Plan A upward).',
};

// Plans C, F and high-deductible F were closed to anyone who became eligible
// for Medicare on or after 1 January 2020. Quoting them to someone newly
// eligible is quoting something they cannot legally buy.
const MEDIGAP_MACRA_CLOSED = ['C', 'F', 'HDF'];

function medigapEligibleBefore2020_(profile) {
  const d = profile && (profile.medicare_eligible_on || profile.part_b_date);
  if (d) return new Date(d) < new Date('2020-01-01');
  // fall back on turning 65 \u2014 anyone 65 by the end of 2019 was eligible
  const dob = profile && profile.dob ? new Date(profile.dob) : null;
  if (!dob) return null;                    // unknown: warn rather than guess
  const sixtyFive = new Date(dob); sixtyFive.setFullYear(sixtyFive.getFullYear() + 65);
  return sixtyFive < new Date('2020-01-01');
}

function medigapLetters_(profile) {
  const preMacra = medigapEligibleBefore2020_(profile);
  return MEDIGAP_PLANS.filter(p => preMacra === false ? !MEDIGAP_MACRA_CLOSED.includes(p[0]) : true);
}

// When can they buy without answering a health question?
function medigapWindow_(profile) {
  const out = { open: false, note: '', tone: 'muted', extra: [] };
  const st = String((profile && profile.state) || '').toUpperCase();
  const pb = profile && profile.part_b_date ? new Date(profile.part_b_date) : null;

  if (pb && !isNaN(pb)) {
    const ends = new Date(pb); ends.setMonth(ends.getMonth() + 6); ends.setDate(ends.getDate() - 1);
    const today = new Date();
    const fmt = d => d.toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' });
    if (today <= ends) {
      const days = Math.ceil((ends - today) / 86400000);
      out.open = true; out.tone = 'ok';
      out.note = 'In their <strong>6-month Medigap open enrollment</strong> until <strong>' + fmt(ends)
        + '</strong> (' + days + ' day' + (days === 1 ? '' : 's') + ' left) \u2014 any plan, any carrier, no health questions.';
    } else {
      out.note = 'Their 6-month open enrollment ended <strong>' + fmt(ends)
        + '</strong>. Outside a guaranteed-issue situation, carriers may ask health questions.';
      out.tone = 'warn';
    }
  } else {
    out.note = 'Add their <strong>Part B start date</strong> to work out the open-enrollment window.';
    out.tone = 'muted';
  }

  if (MEDIGAP_YEAR_ROUND[st]) { out.extra.push({ tone: 'ok', text: MEDIGAP_YEAR_ROUND[st] }); out.open = true; }
  if (MEDIGAP_BIRTHDAY_RULES[st]) out.extra.push({ tone: 'ok', text: '\u{1F382} <strong>' + st + ' birthday rule:</strong> ' + MEDIGAP_BIRTHDAY_RULES[st] });
  if (MEDIGAP_WAIVER_STATES[st]) {
    out.extra.push({ tone: 'warn', text: '\u26a0\ufe0f <strong>' + MEDIGAP_WAIVER_STATES[st]
      + '</strong> standardizes Medigap differently \u2014 the lettered plans below do not apply there.' });
  }
  out.extra.push({ tone: 'muted', text: 'Guaranteed issue also applies when they lose employer coverage, when a Medicare Advantage plan leaves the area, or within the first 12 months of trying Medicare Advantage for the first time.' });
  return out;
}

