const CARRIER_LINES = ['Life','Health — Individual','Short-Term Medical','Private/Off-Market Medical',
  'Health Share','Health — Group','Medicare Advantage','Medicare Supplement','Part D (PDP)',
  'Hospital Indemnity','Accident','Cancer/Critical Illness','Dental/Vision/Hearing','Disability',
  'Auto/Home','Commercial','Other'];

// Retiring is the normal thing: the carrier stops being offered but every
// quote that used it still makes sense. Deleting is only for something added
// by mistake, and only while nothing points at it.
// Retiring a carrier retires everything they write \u2014 nothing can be sold
// through a carrier we no longer hold. Bringing them back is NOT the mirror
// image: a carrier returns with whatever line-up they have now, and some of
// those products were retired for their own reasons. So the products come back
// one at a time, chosen, with the reason each was retired in view.
async function carrierSetActive_(id, makeActive) {
  const cr = (window._allCarriers || []).find(c => c.id === id) || {};
  const today = new Date().toISOString().slice(0, 10);

  if (!makeActive) {
    const { error } = await supabaseClient.from('carriers')
      .update({ is_active: false }).eq('id', id).select('id');
    if (error) { showToast('Could not update: ' + error.message); return; }
    // Products already retired keep their own reason \u2014 it is the truer one.
    const { data: hit } = await supabaseClient.from('carrier_products').update({
      is_active: false, discontinued_on: today,
      discontinued_reason: 'Carrier retired ' + today,
    }).eq('carrier_id', id).is('discontinued_on', null).select('id');
    showToast('Carrier retired' + ((hit || []).length ? ' with ' + hit.length + ' product'
      + (hit.length === 1 ? '' : 's') : '') + ' \u2014 quotes and history are untouched.');
    renderAdmin();
    return;
  }

  const { data: prods } = await supabaseClient.from('carrier_products')
    .select('id,name,line_of_business,is_active,discontinued_on,discontinued_reason')
    .eq('carrier_id', id).order('name');
  const retired = (prods || []).filter(p => p.discontinued_on || !p.is_active);

  if (!retired.length) {
    const { error } = await supabaseClient.from('carriers')
      .update({ is_active: true }).eq('id', id).select('id');
    if (error) { showToast('Could not update: ' + error.message); return; }
    showToast('Carrier restored.');
    renderAdmin();
    return;
  }

  showModal('Bring back ' + escWeb(cr.name || 'this carrier'), `
    <p style="font-size:13px;line-height:1.6;margin-bottom:10px;">
      The carrier comes back either way. <strong>Choose which products come back with it</strong> \u2014
      a carrier usually returns with a different line-up, and some of these were retired for
      reasons of their own.</p>
    ${retired.map((p, i) => `
      <label style="display:flex;gap:9px;align-items:flex-start;padding:8px 11px;border:1px solid var(--border);border-radius:9px;margin-bottom:6px;font-weight:400;cursor:pointer;">
        <input type="checkbox" id="cr-un-${i}" style="width:auto;margin-top:3px;" />
        <span><strong>${escWeb(p.name)}</strong>
          <span style="font-size:11.5px;color:var(--text-muted);"> ${escWeb(p.line_of_business || '')}</span>
          ${p.discontinued_reason ? `<div style="font-size:11.5px;color:var(--text-warning);">retired: ${escWeb(p.discontinued_reason)}</div>` : ''}
        </span></label>`).join('')}
    <div style="font-size:11.5px;color:var(--text-muted);margin-top:8px;">
      Anything left unticked stays retired \u2014 you can bring it back later from the carrier's product list.</div>
  `, async () => {
    const { error } = await supabaseClient.from('carriers')
      .update({ is_active: true }).eq('id', id).select('id');
    if (error) { showToast('Could not update: ' + error.message); return false; }
    const back = retired.filter((_, i) => (document.getElementById('cr-un-' + i) || {}).checked);
    if (back.length) {
      const { error: e2 } = await supabaseClient.from('carrier_products')
        .update({ is_active: true, discontinued_on: null, discontinued_reason: null })
        .in('id', back.map(p => p.id));
      if (e2) { showToast('Carrier restored, but the products failed: ' + e2.message); return false; }
    }
    showToast('Carrier restored' + (back.length ? ' with ' + back.length + ' product'
      + (back.length === 1 ? '' : 's') : ', products left retired') + '.');
    renderAdmin();
  }, { confirmLabel: 'Restore' });
}

async function carrierDelete_(id) {
  const cr = (window._allCarriers || []).find(c => c.id === id) || {};
  const prods = (window._allCarrierProducts || []).filter(p => p.carrier_id === id);

  // anything pointing at this carrier means retire, not delete
  const [{ count: onQuotes }, { count: appts }] = await Promise.all([
    supabaseClient.from('quote_options').select('id', { count: 'exact', head: true }).eq('carrier_id', id),
    supabaseClient.from('carrier_appointments').select('id', { count: 'exact', head: true }).eq('carrier_id', id),
  ]);
  if (onQuotes || appts) {
    showToast('\u26a0\ufe0f ' + (cr.name || 'This carrier') + ' is used on ' + (onQuotes || 0) + ' quote option'
      + ((onQuotes || 0) === 1 ? '' : 's') + ' and ' + (appts || 0) + ' appointment'
      + ((appts || 0) === 1 ? '' : 's') + ' \u2014 retire it instead so that history still reads correctly.');
    return;
  }

  const names = prods.map(p => p.name).join(', ');
  if (!confirm('Delete ' + (cr.name || 'this carrier')
      + (prods.length ? ' and its ' + prods.length + ' product' + (prods.length === 1 ? '' : 's') + ' (' + names + ')' : '')
      + ' for good?\n\nNothing uses it, so nothing else changes. This cannot be undone.')) return;

  // rate charts hang off the products, so they go first
  if (prods.length) {
    const ids = prods.map(p => p.id);
    const { data: charts } = await supabaseClient.from('rate_charts').select('id').in('product_id', ids);
    if (charts && charts.length) {
      await supabaseClient.from('rate_rows').delete().in('chart_id', charts.map(c => c.id));
      await supabaseClient.from('rate_charts').delete().in('product_id', ids);
    }
    const { error: ep } = await supabaseClient.from('carrier_products').delete().in('id', ids).select('id');
    if (ep) { showToast('Could not delete the products: ' + ep.message); return; }
  }
  const { error } = await supabaseClient.from('carriers').delete().eq('id', id).select('id');
  if (error) { showToast('Could not delete: ' + error.message); return; }
  showToast('Deleted ' + (cr.name || 'the carrier') + (prods.length ? ' and its products.' : '.'));
  renderAdmin();
}

// Every dollar figure a plan year holds. `cms: true` means the Get button can
// read it off the CMS announcement; the rest are typed. `hurts` is what goes
// wrong while it is blank \u2014 said on the card so nobody has to guess.
const PLAN_YEAR_FIELDS = [
  { key: 'part_d_oop_cap',        label: 'Part D out-of-pocket limit', cms: true,
    hurts: 'drug cost estimates run high without it',
    help: 'Once a client has paid this much for covered drugs, they pay nothing more for the rest of the year.' },
  { key: 'part_b_premium',        label: 'Part B premium',        cms: true, per: '/mo' },
  { key: 'part_b_deductible',     label: 'Part B deductible',     cms: true },
  { key: 'part_a_deductible',     label: 'Part A hospital deductible', cms: true,
    note: 'what Medigap B, C, D, F, G and N pay in full',
    help: 'Charged per benefit period, not per year \u2014 someone admitted twice in a year can pay it twice.' },
  { key: 'part_a_coins_61_90',    label: 'Hospital days 61\u201390', cms: true, per: '/day' },
  { key: 'part_a_coins_lifetime', label: 'Lifetime reserve days',    cms: true, per: '/day' },
  { key: 'part_a_snf_coins',      label: 'Nursing home days 21\u2013100', cms: true, per: '/day',
    note: 'the gap Plan A leaves open' },
  { key: 'medigap_k_oop',         label: 'Medigap Plan K yearly limit', cms: false,
    help: 'Announced separately from the CMS fact sheet, so this one is typed.' },
  { key: 'medigap_l_oop',         label: 'Medigap Plan L yearly limit', cms: false },
];

function planYearEdit_(year) {
  const cfg = (window._planYears || []).find(x => x.plan_year === year) || {};
  const row = f => `
    <label style="margin-top:9px;">${f.label} ($)${f.cms ? '' : ' <span style="font-size:10.5px;font-weight:400;color:var(--text-muted);">\u00b7 typed by hand</span>'}</label>
    <input type="number" step="0.01" id="py-${f.key}" value="${cfg[f.key] != null ? cfg[f.key] : ''}" />
    ${f.help ? `<div style="font-size:11px;color:var(--text-muted);margin-top:3px;">${f.help}</div>` : ''}`;

  showModal('Plan year ' + year, `
    <div style="display:flex;gap:9px;align-items:center;flex-wrap:wrap;padding:9px 11px;border-radius:9px;background:var(--bg-info);border:1px solid var(--border-info);">
      <button class="btn btn-primary btn-sm" onclick="planYearFetch_(${year})">Get the CMS figures</button>
      <span style="font-size:11.5px;color:var(--text-info);flex:1;min-width:200px;">
        Reads them off the CMS announcement for ${year}. Check them, then save.
      </span>
    </div>
    <div id="py-fetch-note" style="font-size:11.5px;margin-top:7px;"></div>
    ${PLAN_YEAR_FIELDS.map(row).join('')}
  `, async () => {
    const patch = { plan_year: year, aep_start: year - 1 + '-10-15', aep_end: year - 1 + '-12-07',
                    updated_at: new Date().toISOString() };
    PLAN_YEAR_FIELDS.forEach(f => {
      const v = parseFloat((document.getElementById('py-' + f.key) || {}).value);
      patch[f.key] = isNaN(v) ? null : v;
    });
    const { error } = await supabaseClient.from('plan_year_config')
      .upsert(patch, { onConflict: 'plan_year' }).select('plan_year');
    if (error) { showToast('Could not save: ' + error.message); return false; }
    window._qbPartDCap = undefined;      // quoting picks the new figure up
    window._planYearAmts = null;         // and so does the Medigap grid
    showToast('Plan year ' + year + ' saved.');
    renderAdmin();
  }, { confirmLabel: 'Save' });
}

// Fills the boxes from the CMS announcement. It never saves on its own \u2014 a
// person looks at the numbers first, which is the whole point of the button.
async function planYearFetch_(year) {
  const note = document.getElementById('py-fetch-note');
  if (note) note.innerHTML = '<span style="color:var(--text-muted);">Reading the CMS announcement\u2026</span>';
  try {
    const { data, error } = await supabaseClient.functions.invoke('medicare-amounts?year=' + year);
    if (error) throw error;
    const found = (data && data.found) || {};
    const got = Object.keys(found);
    got.forEach(k => {
      const el = document.getElementById('py-' + k);
      if (el) { el.value = found[k]; el.style.borderColor = 'var(--border-info)'; }
    });

    // The Part D deductible is a cross-check, not a field we keep: if CMS and
    // our own plan data disagree, one of the two is stale and worth knowing.
    let cross = '';
    if (found.part_d_deductible != null && window._pyMaxDed != null) {
      cross = Number(found.part_d_deductible) === Number(window._pyMaxDed)
        ? ` Part D deductible $${found.part_d_deductible} matches our plan data.`
        : ` <strong>CMS says the Part D deductible is $${found.part_d_deductible}, our plan data says $${window._pyMaxDed}</strong> \u2014 worth a look.`;
    }

    const src = (data && data.sources && Object.values(data.sources)[0]) || 'https://www.cms.gov/newsroom/fact-sheets';
    if (note) note.innerHTML = got.length
      ? `<span style="color:var(--text-success);">Filled in ${got.filter(k => k !== 'part_d_deductible').length} figure(s)</span> from
         <a href="${src}" target="_blank" rel="noopener" style="color:var(--link);">the CMS announcement</a>.${cross}
         <br><span style="color:var(--text-muted);">${(data.notes || []).join(' ')}</span>`
      : `<span style="color:var(--text-warning);">Nothing found for ${year}.</span>
         <span style="color:var(--text-muted);">${(data.notes || []).join(' ')}</span>`;
  } catch (e) {
    if (note) note.innerHTML = `<span style="color:var(--text-warning);">Could not reach the CMS announcement (${e.message || e}).</span>
      <span style="color:var(--text-muted);">Type the figures in below.</span>`;
  }
}

// A new year starts from the last one's wording, with the CMS figures blank
// so nobody carries a stale dollar amount forward by accident.
async function planYearStart_(year) {
  const prev = (window._planYears || [])[0] || {};
  const { error } = await supabaseClient.from('plan_year_config').upsert({
    plan_year: year,
    aep_start: year - 1 + '-10-15',
    aep_end: year - 1 + '-12-07',
    oep_note: prev.oep_note || null,
    tpmo_disclaimer: prev.tpmo_disclaimer || null,
    not_gov_disclaimer: prev.not_gov_disclaimer || null,
    updated_at: new Date().toISOString(),
  }, { onConflict: 'plan_year' }).select('plan_year');
  if (error) { showToast('Could not start ' + year + ': ' + error.message); return; }
  showToast('Started plan year ' + year + ' \u2014 add the CMS figures when they publish.');
  planYearEdit_(year);
}

function openCarrierModal(id) {
  const cr = id ? (window._allCarriers || []).find(x => x.id === id) : null;
  const lines = new Set((cr && cr.lines_of_business) || []);
  const lineBoxes = CARRIER_LINES.map((l, i) =>
    `<label style="display:flex;gap:8px;align-items:center;font-weight:400;margin-top:6px;"><input type="checkbox" id="cr-line-${i}" style="width:auto;" onchange="toggleCarrierSoaFields_()" ${lines.has(l) ? 'checked' : ''}/> ${l}</label>`
  ).join('');
  showModal(cr ? 'Edit Carrier — ' + cr.name : 'Add Carrier', `
    <label>Carrier Name *</label><input type="text" id="cr-name" value="${cr ? escWeb(cr.name) : ''}" placeholder="e.g. Blue Cross Blue Shield of Montana" />
    <label>Brand</label>
    <select id="cr-brand">
      <option value="both" ${!cr || cr.brand==='both' ? 'selected' : ''}>Both brands</option>
      <option value="kfg" ${cr && cr.brand==='kfg' ? 'selected' : ''}>Kannon Financial</option>
      <option value="ia" ${cr && cr.brand==='ia' ? 'selected' : ''}>Insured America</option>
    </select>
    <label>Lines of business</label>
    ${lineBoxes}
    <label>Phone</label><input type="text" id="cr-phone" value="${cr ? escWeb(cr.phone || '') : ''}" />
    <label>Website</label><input type="text" id="cr-website" value="${cr ? escWeb(cr.website || '') : ''}" placeholder="https://..." />
    <label>Broker portal URL</label><input type="text" id="cr-portal" value="${cr ? escWeb(cr.broker_portal_url || '') : ''}" placeholder="https://..." />
    <div id="cr-soa-wrap" style="display:${lines.has('Medicare Advantage') || lines.has('Part D (PDP)') ? 'block' : 'none'};">
      <div style="font-size:11px;color:var(--text-muted);margin-top:12px;">Medicare Advantage / Part D selected &mdash; CMS requires a Scope of Appointment for these products.</div>
      <label style="display:flex;gap:8px;align-items:center;margin-top:6px;font-weight:400;"><input type="checkbox" id="cr-soa-req" style="width:auto;" ${cr && cr.soa_required ? 'checked' : ''}/> Requires Scope of Appointment</label>
      <label>SOA form accepted</label>
      <select id="cr-soa-type">
        <option value="ours" ${!cr || cr.soa_form_type==='ours' ? 'selected' : ''}>Our digital SOA is accepted</option>
        <option value="carrier" ${cr && cr.soa_form_type==='carrier' ? 'selected' : ''}>Carrier's proprietary form required</option>
        <option value="vendor" ${cr && cr.soa_form_type==='vendor' ? 'selected' : ''}>Approved vendor tool required</option>
      </select>
      <label>Carrier SOA form URL (if proprietary)</label><input type="text" id="cr-soa-url" value="${cr ? escWeb(cr.soa_form_url || '') : ''}" placeholder="https://..." />
    </div>
    <label>Notes</label><textarea id="cr-notes" rows="2">${cr ? escWeb(cr.notes || '') : ''}</textarea>
    <label style="display:flex;gap:8px;align-items:center;margin-top:12px;font-weight:400;"><input type="checkbox" id="cr-active" style="width:auto;" ${!cr || cr.is_active ? 'checked' : ''}/> Active</label>
  `, async () => {
    const name = document.getElementById('cr-name').value.trim();
    if (!name) { showToast('Carrier name is required'); return false; }
    const payload = {
      name,
      brand: document.getElementById('cr-brand').value,
      lines_of_business: CARRIER_LINES.filter((l, i) => document.getElementById('cr-line-' + i).checked),
      phone: document.getElementById('cr-phone').value.trim() || null,
      website: document.getElementById('cr-website').value.trim() || null,
      broker_portal_url: document.getElementById('cr-portal').value.trim() || null,
      soa_required: document.getElementById('cr-soa-wrap').style.display !== 'none'
        && document.getElementById('cr-soa-req').checked,
      soa_form_type: document.getElementById('cr-soa-type').value,
      soa_form_url: document.getElementById('cr-soa-url').value.trim() || null,
      notes: document.getElementById('cr-notes').value.trim() || null,
      is_active: document.getElementById('cr-active').checked,
    };
    const q = cr
      ? supabaseClient.from('carriers').update(payload).eq('id', cr.id)
      : supabaseClient.from('carriers').insert(payload);
    const { error } = await q;
    if (error) { showToast('Error: ' + error.message); return false; }
    showToast(cr ? 'Carrier updated.' : 'Carrier added.');
    renderAdmin();
  });
}

// SOA fields only apply to Medicare Advantage / Part D — CMS's
// Scope of Appointment rule doesn't cover other lines (Medigap included).
function toggleCarrierSoaFields_() {
  const w = document.getElementById('cr-soa-wrap');
  if (!w) return;
  const soaLines = ['Medicare Advantage', 'Part D (PDP)'];
  const on = CARRIER_LINES.some((l, i) =>
    soaLines.includes(l) && document.getElementById('cr-line-' + i)?.checked);
  const wasHidden = w.style.display === 'none';
  w.style.display = on ? 'block' : 'none';
  // First reveal: default "Requires SOA" to checked, since CMS mandates it
  if (on && wasHidden) document.getElementById('cr-soa-req').checked = true;
}

