function carrierApptsSummaryHtml_(appts) {
  const act = (appts || []).filter(a => a.is_active);
  if (!act.length) return '<div style="font-size:13px;color:var(--text-muted);font-style:italic;">No carrier appointments recorded yet.</div>';
  return act.map(a => `<div style="font-size:13px;padding:4px 0;">&#10003; <strong>${escWeb(a.carriers?.name || '')}</strong>${a.writing_number ? ` <span style="font-size:11px;color:var(--text-muted);">&middot; writing #${escWeb(a.writing_number)}</span>` : ''}</div>`).join('');
}

async function openCarrierProducts(crId) {
  const cr = (window._allCarriers || []).find(x => x.id === crId);
  if (!cr) return;
  const { data: prods } = await supabaseClient.from('carrier_products')
    .select('*').eq('carrier_id', crId).order('line_of_business').order('name');
  window._crProds = prods || [];
  const rows = window._crProds.length ? window._crProds.map(p => `
    <div style="display:flex;justify-content:space-between;align-items:center;gap:10px;padding:7px 0;border-bottom:0.5px solid var(--border);${p.is_active ? '' : 'opacity:.5;'}">
      <div style="flex:1;min-width:0;font-size:13px;"><strong>${escWeb(p.name)}</strong> <span style="font-size:11px;color:var(--text-muted);">&middot; ${escWeb(p.line_of_business)}${p.product_code ? ' &middot; ' + escWeb(p.product_code) : ''}${p.plan_year ? ' &middot; ' + p.plan_year : ''}${(p.states || []).length ? ' &middot; ' + escWeb((p.states || []).join(', ')) : ' &middot; <span style="color:var(--text-warning);">no states recorded</span>'}${
        p.discontinued_on ? ' &middot; <span style="color:var(--text-warning);">retired ' + escWeb(p.discontinued_on) + (p.discontinued_reason ? ', ' + escWeb(p.discontinued_reason) : '') + '</span>'
        : (p.is_active ? '' : ' &middot; inactive')}</span></div>
      <button class="btn btn-outline btn-sm" onclick="openRateCharts('${p.id}')">Rates</button>
      <button class="btn btn-outline btn-sm" onclick="openCarrierProductModal('${crId}','${p.id}')">Edit</button>
      ${p.discontinued_on
        ? `<button class="btn btn-outline btn-sm" onclick="productRetire_('${crId}','${p.id}',false)">Bring back</button>`
        : `<button class="btn btn-outline btn-sm" style="color:var(--text-warning);border-color:var(--border-warning);" onclick="productRetire_('${crId}','${p.id}',true)">Retire</button>`}
    </div>`).join('')
    : '<div style="font-size:13px;color:var(--text-muted);font-style:italic;">No products yet for this carrier.</div>';
  showModal('Products \u2014 ' + escWeb(cr.name), `
    <div style="display:flex;justify-content:flex-end;margin-bottom:8px;"><button class="btn btn-primary btn-sm" onclick="openCarrierProductModal('${crId}', null)">+ Add Product</button></div>
    ${rows}`, null, { hideConfirm: true });
}

// Retiring one product, without touching the carrier. Never a delete: quotes
// already sent point at this product and have to keep rendering.
function productRetire_(crId, prodId, retire) {
  const p = (window._crProds || []).find(x => x.id === prodId) || {};
  if (!retire) {
    showModal('Bring back ' + escWeb(p.name || 'this product'), `
      <p style="font-size:13px;line-height:1.6;">This will offer <strong>${escWeb(p.name || '')}</strong> again
      and clear the retirement note${p.discontinued_reason ? ' (\u201c' + escWeb(p.discontinued_reason) + '\u201d)' : ''}.</p>`,
      async () => {
        const { error } = await supabaseClient.from('carrier_products')
          .update({ is_active: true, discontinued_on: null, discontinued_reason: null }).eq('id', prodId);
        if (error) { showToast('Error: ' + error.message); return false; }
        showToast('Back in the list.');
        openCarrierProducts(crId);
      }, { confirmLabel: 'Bring it back' });
    return;
  }
  showModal('Retire ' + escWeb(p.name || 'this product'), `
    <p style="font-size:13px;line-height:1.6;margin-bottom:10px;">
      It stops being offered on new quotes. <strong>Nothing is deleted</strong> \u2014 quotes already sent
      still show it, and you can bring it back later.</p>
    <label>Why? (goes on the record)</label>
    <input type="text" id="pr-reason" placeholder="e.g. carrier withdrew it in MT from 1 January" />
    <label style="margin-top:10px;">From when?</label>
    <input type="date" id="pr-date" value="${new Date().toISOString().slice(0, 10)}" />
  `, async () => {
    const { error } = await supabaseClient.from('carrier_products').update({
      is_active: false,
      discontinued_on: (document.getElementById('pr-date') || {}).value || new Date().toISOString().slice(0, 10),
      discontinued_reason: (document.getElementById('pr-reason') || {}).value.trim() || null,
    }).eq('id', prodId);
    if (error) { showToast('Error: ' + error.message); return false; }
    showToast('Retired. Existing quotes are untouched.');
    openCarrierProducts(crId);
  }, { confirmLabel: 'Retire it' });
}

function openCarrierProductModal(crId, prodId) {
  const p = prodId ? (window._crProds || []).find(x => x.id === prodId) : null;
  const lineOpts = CARRIER_LINES.map(l => `<option value="${l}" ${p && p.line_of_business === l ? 'selected' : ''}>${l}</option>`).join('');
  showModal(p ? 'Edit Product \u2014 ' + escWeb(p.name) : 'Add Product', `
    <label>Product Name *</label><input type="text" id="cp-name" value="${p ? escWeb(p.name) : ''}" placeholder="e.g. Medicare Supplement Plan G" />
    <label>Line of business *</label><select id="cp-line" onchange="cpProductLineChanged_()">${lineOpts}</select>
    <div id="cp-mg-wrap" style="display:none;">
      <label>Standardized plan <span style="font-size:10px;color:var(--text-muted);">(picks name, code &amp; benefits for you — same at every carrier by law)</span></label>
      <select id="cp-mg" onchange="cpApplyMedigap_()">
        <option value="">&mdash; pick the plan letter &mdash;</option>
        ${MEDIGAP_PLANS.map(p => `<option value="${p[0]}">${p[1]}</option>`).join('')}
      </select>
    </div>
    <div id="cp-cms-hint" style="display:none;background:var(--bg-info);border:1px solid var(--border-info);border-radius:8px;padding:8px 12px;margin-top:8px;font-size:12px;color:var(--text-info);">
      Heads up: quoting for this line already uses the <strong>official CMS plan list</strong> automatically —
      you usually don't need to add products here at all.
    </div>
    <div id="cp-code-wrap"><label>Product code</label><input type="text" id="cp-code" value="${p ? escWeb(p.product_code || '') : ''}" placeholder="e.g. 20-Year Term, HMO-POS" /></div>
    <label>Plan year (Medicare products change yearly; blank = evergreen)</label><input type="number" id="cp-year" value="${p && p.plan_year ? p.plan_year : ''}" placeholder="e.g. 2026" />
    <label>Brand</label>
    <select id="cp-brand">
      <option value="both" ${!p || p.brand === 'both' ? 'selected' : ''}>Both brands</option>
      <option value="kfg" ${p && p.brand === 'kfg' ? 'selected' : ''}>Kannon Financial</option>
      <option value="ia" ${p && p.brand === 'ia' ? 'selected' : ''}>Insured America</option>
    </select>
    <label>Client-facing benefit bullets (one per line &mdash; shown on quotes)</label><textarea id="cp-bullets" rows="3" placeholder="Covers Part A &amp; B deductibles&#10;See any doctor who accepts Medicare&#10;No network restrictions">${p ? escWeb(((p.metadata || {}).bullets || []).join('\n')) : ''}</textarea>
    <label>Notes</label><textarea id="cp-notes" rows="2">${p ? escWeb(p.notes || '') : ''}</textarea>
    <label style="display:flex;gap:8px;align-items:center;margin-top:12px;font-weight:400;"><input type="checkbox" id="cp-active" style="width:auto;" ${!p || p.is_active ? 'checked' : ''}/> Active</label>
  `, async () => {
    const name = document.getElementById('cp-name').value.trim();
    if (!name) { showToast('Product name is required'); return false; }
    void 0;
    const yr = document.getElementById('cp-year').value.trim();
    const payload = {
      carrier_id: crId,
      name,
      line_of_business: document.getElementById('cp-line').value,
      product_code: document.getElementById('cp-code').value.trim() || null,
      plan_year: yr ? parseInt(yr, 10) : null,
      brand: document.getElementById('cp-brand').value,
      notes: document.getElementById('cp-notes').value.trim() || null,
      is_active: document.getElementById('cp-active').checked,
      metadata: Object.assign({}, (p && p.metadata) || {}, {
        bullets: document.getElementById('cp-bullets').value.split('\n').map(x => x.trim()).filter(Boolean)
      }),
    };
    const q = p
      ? supabaseClient.from('carrier_products').update(payload).eq('id', p.id)
      : supabaseClient.from('carrier_products').insert(payload);
    const { error } = await q;
    if (error) { showToast('Error: ' + error.message); return false; }
    showToast(p ? 'Product updated.' : 'Product added.');
    openCarrierProducts(crId); // back to the product list
    return false;              // keep the (replaced) modal open
  });
  setTimeout(cpProductLineChanged_, 0); // set picker/hint visibility for the pre-selected line
}

async function openMyCarriers() {
  const isOwner = activeRole() === 'system_owner' || activeRole() === 'broker_owner';
  const { data: master } = await supabaseClient.from('carriers')
    .select('*').eq('is_active', true).order('name');
  let allowed = master || [];
  if (!isOwner) {
    // Plain agents pick only from their agency leadership's active appointments
    let ownerIds = [];
    if (currentAgent.agency_id) {
      const { data: owners } = await supabaseClient.from('agents').select('id')
        .eq('agency_id', currentAgent.agency_id).in('role', ['broker_owner', 'system_owner']);
      ownerIds = (owners || []).map(o => o.id);
    }
    if (ownerIds.length) {
      const { data: oa } = await supabaseClient.from('carrier_appointments')
        .select('carrier_id').in('agent_id', ownerIds).eq('is_active', true);
      const okIds = new Set((oa || []).map(x => x.carrier_id));
      allowed = allowed.filter(c => okIds.has(c.id));
    } else {
      allowed = [];
    }
  }
  if (!allowed.length) {
    showModal('My Carrier Appointments', `<p style="font-size:13px;line-height:1.6;">${isOwner
      ? 'The master carrier list is empty (or inactive). Add carriers in the Admin page first.'
      : "Your agency's carrier list isn't set up yet. Your broker owner needs to record their carrier appointments first \u2014 then you can select yours from that list."}</p>`, null, { hideConfirm: true });
    return;
  }
  const { data: mine } = await supabaseClient.from('carrier_appointments')
    .select('*').eq('agent_id', currentAgent.id);
  const mineBy = {};
  (mine || []).forEach(m => { mineBy[m.carrier_id] = m; });
  const rows = allowed.map((c, i) => {
    const m = mineBy[c.id];
    return `
    <div style="display:flex;align-items:center;gap:10px;padding:7px 0;border-bottom:0.5px solid var(--border);">
      <input type="checkbox" id="appt-${i}" style="width:auto;flex-shrink:0;" ${m && m.is_active ? 'checked' : ''} />
      <label for="appt-${i}" style="flex:1;min-width:0;font-size:13px;font-weight:600;cursor:pointer;">${escWeb(c.name)} <span style="font-weight:400;font-size:11px;color:var(--text-muted);">${(c.lines_of_business || []).join(', ')}</span></label>
      <input type="text" id="appt-wn-${i}" value="${m ? escWeb(m.writing_number || '') : ''}" placeholder="writing #" style="width:110px;font-size:12px;flex-shrink:0;" />
      <input type="url" id="appt-url-${i}" value="${m ? escWeb(m.quoting_url || '') : ''}"
        placeholder="your quoting page at this carrier"
        title="Your own quoting link — it becomes a one-click button in the plan pickers"
        style="width:230px;font-size:12px;flex-shrink:0;" />
    </div>`;
  }).join('');
  showModal('My Carrier Appointments', `
    <p style="font-size:12.5px;color:var(--text-muted);margin-bottom:10px;">Check each carrier you're contracted (appointed) with${isOwner ? ' \u2014 your list also defines what agents in your agency can select' : ''}. Writing numbers are optional but useful.</p>
    ${rows}`, async () => {
    for (let i = 0; i < allowed.length; i++) {
      const c = allowed[i], m = mineBy[c.id];
      const on = document.getElementById('appt-' + i).checked;
      const wn = document.getElementById('appt-wn-' + i).value.trim() || null;
      const url = document.getElementById('appt-url-' + i).value.trim() || null;
      if (url && !/^https?:\/\//i.test(url)) {
        showToast('The quoting page for ' + c.name + ' needs to start with https://'); return false;
      }
      if (on && !m) {
        const { error } = await supabaseClient.from('carrier_appointments')
          .insert({ agent_id: currentAgent.id, carrier_id: c.id, writing_number: wn, quoting_url: url });
        if (error) { showToast('Error: ' + error.message); return false; }
      } else if (m && (on !== m.is_active || wn !== (m.writing_number || null) || url !== (m.quoting_url || null))) {
        const { error } = await supabaseClient.from('carrier_appointments')
          .update({ is_active: on, writing_number: wn, quoting_url: url }).eq('id', m.id);
        if (error) { showToast('Error: ' + error.message); return false; }
      }
    }
    showToast('Carrier appointments saved.');
    if (activeRole() === 'agent') renderSettings();
    else { renderAdmin(); renderSettings(); }
  });
}

// ============================================================
// PRODUCT WALKTHROUGH
//
// Three things a person actually wants to do — add, change, or withdraw — and
// the wizard asks which before anything else. On the add and change paths the
// reading does the work and, where a brochure is genuinely ambiguous, asks
// rather than guesses. Nothing reaches the live tables until the last step.
// ============================================================
let _pw = null;

const PW_MODES = [
  ['add', '➕ Add a new product', 'Upload a brochure — and a rate sheet if you have one. It reads them and creates what it finds.'],
  ['modify', '✏️ Change a product', 'Upload the new brochure. It compares against what is on file, shows what moved, and retires anything replaced.'],
  ['deactivate', '\u{1F6D1} Withdraw a product', 'No document needed. Pick what the carrier has pulled and say why.'],
];

function openProductWizard_() {
  _pw = { step: 0, mode: null, companies: [], carriers: [], products: [],
          companyIds: [], carrierId: null, newCarrier: '',
          files: [], hint: '', docs: [], run: null, answers: {},
          busy: false, error: null, chosen: {}, retire: {}, reason: '' };
  showModal('Products', '<div id="pw-body"></div>', null,
    { hideConfirm: true, cancelLabel: 'Close', wide: true });
  pwLoad_();
}

async function pwLoad_() {
  pwFindResumable_().then(r => { if (_pw) { _pw.resumable = r; if (_pw.step === 0) pwPaint_(); } });
  const [co, ca] = await Promise.all([
    supabaseClient.from('companies').select('id,name,slug').order('name'),
    supabaseClient.from('carriers').select('id,name,brand,is_active').eq('is_active', true).order('name'),
  ]);
  _pw.companies = co.data || [];
  _pw.carriers = ca.data || [];
  pwPaint_();
}

function pwStep_(n) { _pw.step = n; _pw.error = null; pwPaint_(); }

function pwPaint_() {
  const host = document.getElementById('pw-body');
  if (!host || !_pw) return;
  if (_pw.busy && _pw.step_note) {
    const note = document.getElementById('pw-progress');
    if (note) { note.textContent = _pw.step_note; return; }   // just update the line
  }
  const body =
    _pw.step === 0 ? pwStepMode_() :
    _pw.step === 1 ? pwStepCarrier_() :
    _pw.step === 2 ? (_pw.mode === 'deactivate' ? pwStepWithdraw_() : pwStepUpload_()) :
    _pw.step === 3 ? pwStepQuestions_() :
    _pw.step === 4 ? pwStepReview_() : pwStepSave_();

  const trail = _pw.mode
    ? `<div style="padding:11px 20px;border-bottom:1px solid var(--border);background:var(--surface-1);display:flex;gap:9px;align-items:center;flex-wrap:wrap;">
        <span style="font-size:12.5px;font-weight:800;">${escWeb((PW_MODES.find(m => m[0] === _pw.mode) || [])[1] || '')}</span>
        ${_pw.carrierId || _pw.newCarrier ? `<span style="font-size:12px;color:var(--text-muted);">· ${escWeb(pwCarrierName_())}</span>` : ''}
        <button class="btn btn-outline btn-sm" style="margin-left:auto;" onclick="openProductWizard_()">Start over</button>
      </div>` : '';

  host.innerHTML = trail + `<div style="padding:18px 20px;min-height:210px;">${body}</div>`;
}

function pwCarrierName_() {
  if (_pw.newCarrier) return _pw.newCarrier;
  const c = _pw.carriers.find(x => x.id === _pw.carrierId);
  return c ? c.name : '';
}

const pwErr_ = () => _pw.error
  ? `<div class="pk-bar warn" style="margin-top:12px;border-radius:8px;border:1px solid;">⚠️ ${escWeb(_pw.error)}</div>` : '';

// ------------------------------------------------------------------ 0. mode
function pwStepMode_() {
  const r = _pw.resumable;
  const waiting = r ? `
    <div style="border:1px solid var(--border-selected);background:var(--bg-selected-card);border-radius:11px;
      padding:13px 16px;margin-bottom:14px;">
      <div style="font-weight:800;font-size:14px;margin-bottom:3px;">Pick up where you left off</div>
      <div style="font-size:12.5px;color:var(--text-secondary);line-height:1.5;margin-bottom:9px;">
        ${escWeb(r.filename || 'A document')} was read ${pwWhenAgo_(r.created_at)} \u2014
        ${r.plans} plan${r.plans === 1 ? '' : 's'} found${r.questions ? ', ' + r.questions + ' question' + (r.questions === 1 ? '' : 's') + ' waiting for you' : ''}.
        Reading it again costs the same as the first time, so carry on with this one unless something changed.
      </div>
      <button class="btn btn-primary btn-sm" onclick="pwResume_('${r.id}')">Carry on with that reading</button>
    </div>` : '';
  return waiting + `<p style="font-size:13.5px;margin-bottom:14px;">${r ? 'Or start something new:' : 'What would you like to do?'}</p>
    ${PW_MODES.map(([key, title, blurb]) => `
      <button type="button" onclick="pwSetMode_('${key}')" style="display:block;width:100%;text-align:left;
        background:var(--surface-1);border:1px solid var(--border);border-radius:11px;padding:13px 16px;margin-bottom:9px;cursor:pointer;font:inherit;">
        <div style="font-weight:800;font-size:14px;color:var(--text-primary);margin-bottom:3px;">${title}</div>
        <div style="font-size:12.5px;color:var(--text-muted);line-height:1.5;">${escWeb(blurb)}</div>
      </button>`).join('')}`;
}

function pwSetMode_(m) { _pw.mode = m; pwStep_(1); }

function pwWhenAgo_(iso) {
  const mins = Math.round((Date.now() - new Date(iso).getTime()) / 60000);
  if (mins < 1) return 'just now';
  if (mins < 60) return mins + ' minute' + (mins === 1 ? '' : 's') + ' ago';
  const hrs = Math.round(mins / 60);
  if (hrs < 24) return hrs + ' hour' + (hrs === 1 ? '' : 's') + ' ago';
  return new Date(iso).toLocaleDateString();
}

// Anything read in the last two days that nobody has approved or thrown away yet.
async function pwFindResumable_() {
  try {
    const since = new Date(Date.now() - 2 * 86400000).toISOString();
    const { data } = await supabaseClient.from('extraction_runs')
      .select('id,status,created_at,proposal,findings,document_id')
      .in('status', ['needs_answers', 'needs_review'])
      .gte('created_at', since)
      .order('created_at', { ascending: false }).limit(1);
    const run = data && data[0];
    if (!run) return null;
    const plans = (((run.proposal || {}).products) || []).length;
    if (!plans) return null;
    let filename = '';
    if (run.document_id) {
      const { data: d } = await supabaseClient.from('product_documents')
        .select('filename').eq('id', run.document_id).maybeSingle();
      filename = (d || {}).filename || '';
    }
    return { id: run.id, created_at: run.created_at, filename, plans,
             questions: (((run.proposal || {}).questions) || []).length };
  } catch (e) { return null; }
}

async function pwResume_(runId) {
  _pw.busy = true; _pw.error = null; pwPaint_();
  try {
    const { data: run } = await supabaseClient.from('extraction_runs')
      .select('*').eq('id', runId).single();
    if (!run) throw new Error('That reading is no longer on file.');
    const f = run.findings || {};
    _pw.run = run;
    _pw.mode = f.mode || 'add';
    _pw.hint = f.hint || '';
    _pw.docs = f.document_ids || (run.document_id ? [run.document_id] : []);
    _pw.chosen = {};
    (((run.proposal || {}).products) || []).forEach((_, i) => { _pw.chosen[i] = true; });
    if (run.document_id) {
      const { data: d } = await supabaseClient.from('product_documents')
        .select('carrier_id').eq('id', run.document_id).maybeSingle();
      if (d && d.carrier_id) _pw.carrierId = d.carrier_id;
    }
    _pw.busy = false;
    pwStep_(run.status === 'needs_answers' ? 3 : 4);
  } catch (e) {
    _pw.busy = false; _pw.error = e.message || String(e); pwPaint_();
  }
}

// --------------------------------------------------------------- 1. carrier
function pwStepCarrier_() {
  const isAdd = _pw.mode === 'add';
  return `<p style="font-size:13px;color:var(--text-muted);margin-bottom:12px;">
      Which carrier?${isAdd ? ' Use the name on the brochure cover — if a different company underwrites it, the reading picks that up.' : ''}</p>
    <label>Carrier</label>
    <select id="pw-carrier" onchange="_pw.carrierId = this.value || null; if (this.value) _pw.newCarrier = '';">
      <option value="">${isAdd ? '— none / new carrier below —' : '— choose —'}</option>
      ${_pw.carriers.map(c => `<option value="${c.id}" ${_pw.carrierId === c.id ? 'selected' : ''}>${escWeb(c.name)}</option>`).join('')}
    </select>
    ${isAdd ? `
      <label style="margin-top:11px;">…or a new carrier's name</label>
      <input type="text" id="pw-newcarrier" value="${escWeb(_pw.newCarrier)}" placeholder="e.g. Allstate Health Solutions"
        oninput="_pw.newCarrier = this.value; _pw.carrierId = null;" />
      <label style="margin-top:13px;">Which of our companies can write it?</label>
      <div style="display:flex;gap:9px;flex-wrap:wrap;">
        ${_pw.companies.map(c => `
          <label style="display:flex;gap:7px;align-items:center;padding:8px 12px;border:1px solid var(--border);border-radius:9px;font-weight:400;margin:0;cursor:pointer;">
            <input type="checkbox" style="width:auto;" ${_pw.companyIds.includes(c.id) ? 'checked' : ''} onchange="pwToggleCompany_('${c.id}')" />
            ${escWeb(c.name)}</label>`).join('')}
      </div>` : ''}
    <div style="display:flex;justify-content:space-between;margin-top:16px;">
      <button class="btn btn-outline" onclick="pwStep_(0)">← Back</button>
      <button class="btn btn-primary" onclick="pwCarrierNext_()">Next →</button>
    </div>${pwErr_()}`;
}

function pwToggleCompany_(id) {
  const i = _pw.companyIds.indexOf(id);
  if (i >= 0) _pw.companyIds.splice(i, 1); else _pw.companyIds.push(id);
  pwPaint_();
}

async function pwCarrierNext_() {
  const sel = document.getElementById('pw-carrier');
  _pw.carrierId = (sel && sel.value) || null;
  const nc = document.getElementById('pw-newcarrier');
  _pw.newCarrier = nc ? nc.value.trim() : '';
  if (!_pw.carrierId && !_pw.newCarrier) { _pw.error = 'Pick a carrier or type a new one.'; pwPaint_(); return; }
  if (_pw.newCarrier && !_pw.companyIds.length) { _pw.error = 'Tick which of our companies can write this carrier.'; pwPaint_(); return; }
  if (_pw.carrierId) {
    const { data } = await supabaseClient.from('carrier_products')
      .select('id,name,line_of_business,is_active,states').eq('carrier_id', _pw.carrierId)
      .is('discontinued_on', null).order('name');
    _pw.products = data || [];
  }
  if (_pw.mode === 'deactivate' && !_pw.products.length) {
    _pw.error = 'That carrier has no active products on file.'; pwPaint_(); return;
  }
  pwStep_(2);
}

// -------------------------------------------------------------- 2a. upload
function pwStepUpload_() {
  return `<p style="font-size:13px;color:var(--text-muted);margin-bottom:12px;">
      ${_pw.mode === 'modify'
        ? 'Upload the new brochure. It will be compared against the ' + _pw.products.length + ' product' + (_pw.products.length === 1 ? '' : 's') + ' on file for this carrier.'
        : 'A brochure, a rate sheet, or both — you can pick more than one file. <strong>A brochure with no rates is still worth uploading</strong>: the benefits, exclusions and issue rules are most of what an agent needs.'}</p>
    <input type="file" id="pw-file" accept=".pdf,.png,.jpg,.jpeg" multiple onchange="pwPickFiles_(this)"
      style="padding:9px;border:1px dashed var(--border);border-radius:9px;width:100%;" />
    ${_pw.files.length ? `<div style="font-size:12.5px;color:var(--text-success);margin-top:7px;">
      ${_pw.files.map(f => '✓ ' + escWeb(f.name) + ' · ' + (f.size / 1048576).toFixed(1) + ' MB').join('<br>')}</div>` : ''}
    <label style="margin-top:12px;">Anything worth telling it? (optional)</label>
    <input type="text" id="pw-hint" value="${escWeb(_pw.hint)}" oninput="_pw.hint = this.value"
      placeholder="e.g. Montana only, ignore the association plans at the back" />
    <div style="display:flex;justify-content:space-between;margin-top:16px;">
      <button class="btn btn-outline" onclick="pwStep_(1)">← Back</button>
      <button class="btn btn-primary" ${_pw.files.length && !_pw.busy ? '' : 'disabled'} onclick="pwRun_()">
        ${_pw.busy ? 'Reading…' : 'Read it →'}</button>
    </div>
    ${_pw.busy ? `<div class="pk-bar muted" style="margin-top:12px;border-radius:8px;border:1px solid;">
      <div id="pw-progress">${escWeb(_pw.step_note || 'Reading the document…')}</div>
      <div style="font-size:11.5px;opacity:.75;margin-top:3px;">Each plan is read on its own, so a brochure with
      several plans takes a little longer — and gets read more carefully.</div></div>` : ''}${pwErr_()}`;
}

function pwPickFiles_(el) { _pw.files = Array.from(el.files || []); _pw.error = null; pwPaint_(); }

// ------------------------------------------------------------ 2b. withdraw
function pwStepWithdraw_() {
  return `<p style="font-size:13px;color:var(--text-muted);margin-bottom:12px;">
      Which products has the carrier pulled? They are retired, never deleted — quotes already sent still
      show them, they just stop being offered.</p>
    ${_pw.products.map(p => `
      <label style="display:flex;gap:9px;align-items:center;padding:8px 11px;border:1px solid var(--border);border-radius:9px;margin-bottom:6px;font-weight:400;cursor:pointer;">
        <input type="checkbox" style="width:auto;" ${_pw.retire[p.id] ? 'checked' : ''} onchange="pwToggleRetire_('${p.id}')" />
        <span><strong>${escWeb(p.name)}</strong> <span style="font-size:11.5px;color:var(--text-muted);">${escWeb(p.line_of_business || '')}</span></span>
      </label>`).join('')}
    <label style="margin-top:12px;">Why? (goes on the record)</label>
    <input type="text" id="pw-reason" value="${escWeb(_pw.reason)}" oninput="_pw.reason = this.value"
      placeholder="e.g. carrier withdrew it in MT from 1 January" />
    <div style="display:flex;justify-content:space-between;margin-top:16px;">
      <button class="btn btn-outline" onclick="pwStep_(1)">← Back</button>
      <button class="btn btn-primary" ${Object.values(_pw.retire).some(Boolean) && !_pw.busy ? '' : 'disabled'} onclick="pwWithdraw_()">
        ${_pw.busy ? 'Retiring…' : 'Retire the ticked products'}</button>
    </div>${pwErr_()}`;
}

function pwToggleRetire_(id) { _pw.retire[id] = !_pw.retire[id]; pwPaint_(); }

async function pwWithdraw_() {
  _pw.busy = true; _pw.error = null; pwPaint_();
  try {
    const ids = Object.keys(_pw.retire).filter(k => _pw.retire[k]);
    const { error } = await supabaseClient.from('carrier_products').update({
      is_active: false,
      discontinued_on: new Date().toISOString().slice(0, 10),
      discontinued_reason: _pw.reason.trim() || null,
    }).in('id', ids);
    if (error) throw new Error(error.message);
    showToast('Retired ' + ids.length + ' product' + (ids.length === 1 ? '' : 's') + '.');
    closeModal();
    renderAdmin();
  } catch (e) { _pw.busy = false; _pw.error = e.message || String(e); pwPaint_(); }
}

// ------------------------------------------------------------- the reading
// The wizard is told only "non-2xx". The reason, if there is one, is on the run
// row -- and a row still saying "running" with nothing in it means the worker was
// stopped mid-read rather than failing.
// Watch the run until it settles. Each pass is a fresh worker, so the only
// thing that can hang is a pass dying silently -- if nothing moves for four
// minutes, say so rather than spinning for ever.
// Find the run this kicked off, then watch it until it settles. The run row is
// written before any reading starts, so it appears within a second or two.
async function pwWaitForRun_(since, getCallError) {
  let runId = null, lastStep = '', still = 0, waitedForRow = 0;

  for (;;) {
    if (!runId) {
      const { data } = await supabaseClient.from('extraction_runs')
        .select('id').gte('created_at', since)
        .order('created_at', { ascending: false }).limit(1);
      if (data && data[0]) runId = data[0].id;
      else {
        waitedForRow++;
        // No row at all after ~25s means it never got started -- an expired
        // sign-in, or the documents are missing. Then the call's own error is
        // the truthful one.
        if (waitedForRow > 12) {
          const e = getCallError && getCallError();
          throw new Error((e && e.message) || 'The reading never started. Sign out and back in, then try again.');
        }
        await new Promise(r => setTimeout(r, 2000));
        continue;
      }
    }

    const { data: run } = await supabaseClient.from('extraction_runs')
      .select('*').eq('id', runId).single();
    if (!run) throw new Error('That reading is no longer on file.');
    if (run.status !== 'running') return run;

    const step = ((run.findings || {}).step) || 'Reading\u2026';
    if (step === lastStep) still++; else { still = 0; lastStep = step; }
    if (still > 90) {   // ~4.5 minutes with no movement at all
      const msg = 'A pass stopped without finishing. Nothing is wrong with the document \u2014 run it again.';
      await supabaseClient.from('extraction_runs')
        .update({ status: 'failed', error: msg }).eq('id', runId);
      throw new Error(msg);
    }
    if (_pw) { _pw.step_note = step; pwPaint_(); }
    await new Promise(r => setTimeout(r, 3000));
  }
}

async function pwWhyItFailed_(startedAt, error) {
  try {
    const { data } = await supabaseClient.from('extraction_runs')
      .select('status,error,proposal,created_at')
      .gte('created_at', startedAt)
      .order('created_at', { ascending: false }).limit(1);
    const run = data && data[0];
    if (run && run.error) return run.error;
    if (run && run.status === 'running' && !run.proposal) {
      // clear the stranded row so it does not sit in the list looking live
      await supabaseClient.from('extraction_runs')
        .update({ status: 'failed', error: 'Stopped at the server time limit before the reading came back.' })
        .eq('created_at', run.created_at);
      return 'The reading was stopped at the server\u2019s time limit before it finished. '
           + 'This document needs longer than one run allows \u2014 nothing is wrong with the file. '
           + 'Try uploading fewer pages at once, or tell Claude and the reading can be split.';
    }
  } catch (e) { /* fall through to the raw message */ }
  return (error && error.message) || 'The reading failed.';
}

async function pwRun_(answers) {
  _pw.busy = true; _pw.error = null; _pw.step_note = ''; pwPaint_();
  try {
    if (!_pw.carrierId) {
      const { data: nc, error } = await supabaseClient.from('carriers')
        .insert({ name: _pw.newCarrier, is_active: true }).select('id').single();
      if (error) throw new Error('Could not create the carrier: ' + error.message);
      _pw.carrierId = nc.id;
      if (_pw.companyIds.length) {
        await supabaseClient.from('carrier_companies')
          .insert(_pw.companyIds.map(cid => ({ carrier_id: _pw.carrierId, company_id: cid })));
      }
    }

    if (!_pw.docs.length) {
      for (const f of _pw.files) {
        const buf = await f.arrayBuffer();
        const sha = Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256', buf)))
          .map(b => b.toString(16).padStart(2, '0')).join('');
        const { data: seen } = await supabaseClient.from('product_documents')
          .select('id').eq('sha256', sha).maybeSingle();
        if (seen) { _pw.docs.push(seen.id); continue; }
        const path = _pw.carrierId + '/' + Date.now() + '-' + f.name.replace(/[^A-Za-z0-9._-]/g, '_');
        const { error: upErr } = await supabaseClient.storage.from('product-docs')
          .upload(path, f, { contentType: f.type || 'application/pdf', upsert: false });
        if (upErr) throw new Error('Upload failed: ' + upErr.message);
        const { data: doc, error: dErr } = await supabaseClient.from('product_documents').insert({
          carrier_id: _pw.carrierId, storage_path: path, filename: f.name,
          byte_size: f.size, sha256: sha, kind: _pw.files.length > 1 ? 'both' : 'brochure',
          uploaded_by: currentAgent.id,
        }).select('id').single();
        if (dErr) throw new Error('Could not record the document: ' + dErr.message);
        _pw.docs.push(doc.id);
      }
    }

    const payload = { document_ids: _pw.docs, mode: _pw.mode, hint: _pw.hint };
    if (answers) { payload.answers = answers; payload.prior_run_id = _pw.run.id; }

    // Start it, but do NOT wait for the reply -- the server finishes regardless,
    // and waiting is the only part that ever fails.
    const since = new Date(Date.now() - 120000).toISOString();  // slack for clock skew
    let callError = null;
    supabaseClient.functions.invoke('product-extract', { body: payload })
      .then(r => { if (r && r.error) callError = r.error; })
      .catch(e => { callError = e; });

    const run = await pwWaitForRun_(since, () => callError);
    if (run.status === 'failed') throw new Error(run.error || 'The reading failed.');
    const data = { status: run.status, run_id: run.id };
    _pw.run = run;
    _pw.chosen = {};
    (((run || {}).proposal || {}).products || []).forEach((_, i) => { _pw.chosen[i] = true; });
    _pw.busy = false;
    pwStep_(data.status === 'needs_answers' ? 3 : 4);
  } catch (e) {
    _pw.busy = false; _pw.error = e.message || String(e); pwPaint_();
  }
}

// ------------------------------------------------------- 3. it asks for help
function pwStepQuestions_() {
  const qs = ((_pw.run || {}).proposal || {}).questions || [];
  return `<p style="font-size:13px;margin-bottom:4px;"><strong>It read the document and needs a hand with ${qs.length} thing${qs.length === 1 ? '' : 's'}.</strong></p>
    <p style="font-size:12.5px;color:var(--text-muted);margin-bottom:14px;">
      These are the places a wrong guess would change what we quote, so it asked instead of guessing.</p>
    ${qs.map((q, i) => `
      <div style="border:1px solid var(--border-info);background:var(--bg-info);border-radius:10px;padding:12px 14px;margin-bottom:10px;">
        <div style="font-size:13.5px;font-weight:700;color:var(--text-info);">${escWeb(q.ask || '')}</div>
        ${q.why ? `<div style="font-size:11.5px;color:var(--text-info);opacity:.85;margin-top:3px;">Why it matters: ${escWeb(q.why)}${q.page ? ' · page ' + escWeb(String(q.page)) : ''}</div>` : ''}
        ${(q.options || []).map((o, j) => `
          <label style="display:flex;gap:8px;align-items:flex-start;margin-top:7px;font-weight:400;cursor:pointer;font-size:12.5px;">
            <input type="radio" name="pwq-${i}" style="width:auto;margin-top:3px;"
              ${_pw.answers[q.id || ('q' + i)] === o ? 'checked' : ''}
              onchange="pwAnswer_('${escWeb(q.id || ('q' + i))}', ${JSON.stringify(o).replace(/"/g, '&quot;')})" />
            <span>${escWeb(o)}</span></label>`).join('')}
        <input type="text" placeholder="…or answer in your own words"
          value="${(q.options || []).indexOf(_pw.answers[q.id || ('q' + i)]) >= 0 ? '' : escWeb(_pw.answers[q.id || ('q' + i)] || '')}"
          oninput="pwAnswer_('${escWeb(q.id || ('q' + i))}', this.value)"
          style="margin-top:8px;font-size:12.5px;" />
      </div>`).join('')}
    <div style="display:flex;justify-content:space-between;margin-top:14px;">
      <button class="btn btn-outline" onclick="pwStep_(4)">Skip — I'll check it myself</button>
      <button class="btn btn-primary" ${_pw.busy ? 'disabled' : ''} onclick="pwRun_(_pw.answers)">
        ${_pw.busy ? 'Re-reading…' : 'Send answers →'}</button>
    </div>${pwErr_()}`;
}

function pwAnswer_(id, value) { _pw.answers[id] = value; }

// ------------------------------------------------------------- 4. the review
// A choice is a list of COMBINATIONS, each one an object keyed by the parts that
// make it up -- a deductible on its own, or a deductible paired with the
// coinsurance that goes with it. Read them out as the buyer would choose them,
// so a pair never gets split into two unrelated lists.
function pwChoices_(d) {
  if (!d) return '';
  const combos = d.combos || [];
  if (!combos.length) return (d.values || []).join(' \u00b7 ');
  const parts = (d.parts && d.parts.length) ? d.parts : Object.keys(combos[0] || {});
  return combos.map(c => parts.map(p => c[p]).filter(v => v != null && v !== '').join(' / '))
    .filter(Boolean).join('  \u00b7  ');
}

function pwStepReview_() {
  const p = (_pw.run || {}).proposal || {};
  const f = (_pw.run || {}).findings || {};
  const prods = p.products || [];
  const carrier = p.carrier || {};
  const withdrawn = p.withdrawn || [];
  const charts = p.charts || [];
  const worries = [].concat(f.consistency || [], f.unsure || []);
  const chip = (t, tone) => `<span style="font-size:10.5px;font-weight:700;border-radius:6px;padding:2px 7px;
    background:var(--bg-${tone});color:var(--text-${tone});border:1px solid var(--border-info);">${t}</span>`;
  const tag = { new: ['NEW', 'success'], changed: ['CHANGED', 'warning'], unchanged: ['UNCHANGED', 'muted'] };

  return `
    <div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px;">
      ${chip(prods.length + ' product' + (prods.length === 1 ? '' : 's'), 'success')}
      ${chip(charts.length ? charts.length + ' rate chart' + (charts.length === 1 ? '' : 's') : 'no rates in this document', 'info')}
      ${carrier.underwriter ? chip('underwritten by ' + escWeb(carrier.underwriter), 'info') : ''}
      ${(carrier.states || []).length ? chip('for ' + carrier.states.join(', '), 'info') : ''}
      ${carrier.revision_label ? chip(escWeb(carrier.revision_label), 'info') : ''}
    </div>
    ${pwAgentOnlyHtml_(p)}
    ${worries.length ? `<div class="pk-bar warn" style="border-radius:9px;border:1px solid;margin-bottom:12px;">
      <strong>⚠️ Worth a look before saving</strong>
      <ul style="margin:6px 0 0 18px;padding:0;font-size:12px;line-height:1.6;">
        ${worries.map(w => `<li>${escWeb(String(w))}</li>`).join('')}</ul></div>` : ''}
    <div style="max-height:320px;overflow:auto;">
      ${prods.map((pr, i) => {
        const t = tag[pr.change] || null;
        return `<div style="border:1px solid var(--border);border-radius:10px;padding:12px 14px;margin-bottom:9px;">
          <label style="display:flex;gap:9px;align-items:flex-start;font-weight:400;margin:0;cursor:pointer;">
            <input type="checkbox" style="width:auto;margin-top:3px;" ${_pw.chosen[i] ? 'checked' : ''} onchange="pwToggleProduct_(${i})" />
            <span style="flex:1;min-width:0;">
              <span style="display:flex;gap:7px;align-items:center;flex-wrap:wrap;">
                ${t ? `<span style="font-size:9.5px;font-weight:800;letter-spacing:.5px;color:var(--text-${t[1]});">${t[0]}</span>` : ''}
                ${pr.matches_existing ? `<span style="font-size:10.5px;color:var(--text-muted);">replaces ${escWeb(pr.matches_existing)}</span>` : ''}
              </span>
              <input type="text" value="${escWeb(pr.name || '')}" onchange="pwEdit_(${i},'name',this.value)"
                style="font-weight:800;font-size:14px;width:100%;margin:3px 0 5px;" />
              <div style="font-size:11.5px;color:var(--text-muted);margin-bottom:6px;">${escWeb(pr.line_of_business || '')}${pr.product_code ? ' · ' + escWeb(pr.product_code) : ''}</div>
              ${(pr.what_changed || []).length ? `<div style="font-size:12px;color:var(--text-warning);margin-bottom:5px;">${(pr.what_changed || []).map(x => '• ' + escWeb(x)).join('<br>')}</div>` : ''}
              ${pr.summary ? `<div style="font-size:12.5px;color:var(--text-secondary);line-height:1.55;margin-bottom:6px;">${escWeb(pr.summary)}</div>` : ''}
              ${Object.entries(pr.dimensions || {}).map(([k, d]) =>
                `<div style="font-size:11.5px;line-height:1.6;"><strong>${escWeb((d && d.label) || k)}:</strong> ${escWeb(pwChoices_(d))}</div>`).join('')}
              ${Object.entries(pr.facts || {}).length ? `<div style="font-size:11.5px;color:var(--text-muted);line-height:1.6;margin-top:2px;">
                ${Object.entries(pr.facts).map(([k, v]) => escWeb(k.replace(/_/g, ' ')) + ': ' + escWeb(String(v))).join(' &nbsp;·&nbsp; ')}</div>` : ''}
            </span></label>
        </div>`;
      }).join('') || '<div style="font-size:13px;color:var(--text-muted);">Nothing was found to save.</div>'}
    </div>
    ${withdrawn.length ? `<div class="pk-bar warn" style="border-radius:9px;border:1px solid;margin-top:10px;font-size:12px;">
      <strong>No longer in this brochure:</strong> ${withdrawn.map(w => escWeb(w.name)).join(', ')} — ticked to retire on save.</div>` : ''}
    <div style="display:flex;justify-content:space-between;margin-top:16px;">
      <button class="btn btn-outline" onclick="pwStep_(2)">← Different document</button>
      <button class="btn btn-primary" ${prods.length ? '' : 'disabled'} onclick="pwStep_(5)">Next →</button>
    </div>`;
}

// Carrier policy documents are usually stamped "not for consumer use" and are
// often not state-specific either. What they say is gold for an agent and must
// never be handed to a client, so it is kept apart and labelled as such.
function pwAgentOnlyHtml_(p) {
  const a = p.agent_only || {};
  const docs = (p.documents || []).filter(d => d.internal_use_only);
  const counts = [
    (a.exclusions || []).length ? (a.exclusions || []).length + ' exclusions' : '',
    (a.benefit_detail || []).length ? (a.benefit_detail || []).length + ' benefit details' : '',
    (a.riders || []).length ? (a.riders || []).length + ' rider terms' : '',
  ].filter(Boolean);
  if (!docs.length && !counts.length) return '';
  return `<div style="border:1px solid var(--border-warning);background:var(--bg-warning);border-radius:9px;padding:10px 13px;margin-bottom:12px;">
    <div style="font-size:12.5px;font-weight:800;color:var(--text-warning);">&#128274; Agent reference only &mdash; never shown to a client</div>
    <div style="font-size:11.5px;color:var(--text-warning);opacity:.9;line-height:1.55;margin-top:4px;">
      ${docs.length ? escWeb(docs.map(d => d.filename).join(', ')) + ' ' + (docs.length === 1 ? 'is' : 'are') + ' marked not for consumer use. ' : ''}
      ${counts.length ? 'Kept on the product for you: ' + escWeb(counts.join(', ')) + '. ' : ''}
      ${(a.caveats || []).length ? escWeb((a.caveats || []).join(' ')) + ' ' : ''}
      Client-facing benefits come only from the consumer brochure.
    </div>
  </div>`;
}

function pwToggleProduct_(i) { _pw.chosen[i] = !_pw.chosen[i]; }
function pwEdit_(i, field, value) {
  const prods = ((_pw.run || {}).proposal || {}).products || [];
  if (prods[i]) prods[i][field] = value;
}

// ---------------------------------------------------------------- 5. save it
function pwStepSave_() {
  const p = (_pw.run || {}).proposal || {};
  const keep = (p.products || []).filter((_, i) => _pw.chosen[i]);
  const replacing = keep.filter(x => x.matches_existing).length;
  const withdrawn = (p.withdrawn || []).length;
  return `<p style="font-size:13px;margin-bottom:10px;">
      <strong>${keep.length} product${keep.length === 1 ? '' : 's'}</strong> will be created against ${escWeb(pwCarrierName_())}.
      ${replacing ? `<br>${replacing} of them replace${replacing === 1 ? 's' : ''} a product on file, which will be retired.` : ''}
      ${withdrawn ? `<br>${withdrawn} product${withdrawn === 1 ? '' : 's'} no longer in the brochure will be retired.` : ''}</p>
    <ul style="font-size:13px;line-height:1.8;margin:0 0 12px 18px;padding:0;">
      ${keep.map(x => `<li><strong>${escWeb(x.name)}</strong> <span style="color:var(--text-muted);">${escWeb(x.line_of_business || '')}</span></li>`).join('')}
    </ul>
    <div style="font-size:11.5px;color:var(--text-muted);line-height:1.6;">
      Retired products are never deleted — quotes already sent still show them.
      ${(p.charts || []).length ? '' : 'No rates were in this document, so none are created.'}
    </div>${pwErr_()}
    <div style="display:flex;justify-content:space-between;margin-top:16px;">
      <button class="btn btn-outline" onclick="pwStep_(4)">← Back</button>
      <button class="btn btn-primary" ${_pw.busy ? 'disabled' : ''} onclick="pwSave_()">
        ${_pw.busy ? 'Saving…' : 'Save'}</button>
    </div>`;
}

async function pwSave_() {
  _pw.busy = true; _pw.error = null; pwPaint_();
  try {
    const proposal = (_pw.run || {}).proposal || {};
    const shared = proposal.shared || {};
    const carrier = proposal.carrier || {};
    const keep = (proposal.products || []).filter((_, i) => _pw.chosen[i]);
    const today = new Date().toISOString().slice(0, 10);

    const rows = keep.map(p => ({
      carrier_id: _pw.carrierId,
      name: p.name,
      product_code: p.product_code || null,
      line_of_business: p.line_of_business || 'Other',
      states: (carrier.states && carrier.states.length) ? carrier.states : null,
      quoting_url: null,
      is_active: true,
      notes: p.summary || null,
      metadata: {
        // bullets and limitations are consumer-facing: they reach the quote card.
        bullets: p.key_benefits || [],
        limitations: [].concat(p.limitations || [], shared.limitations || []),
        // This half came out of documents the carrier says are not for consumers.
        // It is for the agent and must never be rendered to a client.
        agent_only: proposal.agent_only || null,
        documents: (proposal.documents || []).map(d => ({
          filename: d.filename, what_it_is: d.what_it_is,
          internal_use_only: !!d.internal_use_only, states: d.states_it_covers || null,
        })),
        eligibility: shared.eligibility || [],
        compliance_notes: shared.compliance_notes || [],
        dimensions: p.dimensions || {},
        facts: p.facts || {},
        benefits: p.benefits || null,
        network: p.network || null,
        prescription: p.prescription || null,
        oop_includes_deductible: (p.oop_includes_deductible === true || p.oop_includes_deductible === false)
          ? p.oop_includes_deductible : null,
        underwriter: carrier.underwriter || null,
        policy_form: carrier.policy_form || null,
        from_document: _pw.docs[0] || null,
      },
    }));

    const { data: made, error } = await supabaseClient.from('carrier_products').insert(rows).select('id');
    if (error) throw new Error(error.message);

    // Anything replaced or dropped is retired, never deleted
    const retireNames = [].concat(
      keep.map(p => p.matches_existing).filter(Boolean),
      (proposal.withdrawn || []).map(w => w.name).filter(Boolean));
    if (retireNames.length) {
      // A plan name is only unique WITHIN a state: carriers file the same name
      // separately in each one, with different benefits. Only retire rows whose
      // states this document actually covers, or a Texas brochure would quietly
      // replace the Montana version of the same plan.
      const docStates = (carrier.states || []).map(x => String(x).toUpperCase());
      const { data: cands } = await supabaseClient.from('carrier_products')
        .select('id,name,states').eq('carrier_id', _pw.carrierId).in('name', retireNames);
      const hit = (cands || []).filter(c => {
        const filed = (c.states || []).map(x => String(x).toUpperCase());
        if (!docStates.length || !filed.length) return true;   // nothing to tell them apart
        return filed.some(x => docStates.includes(x));
      });
      if (hit.length) {
        await supabaseClient.from('carrier_products').update({
          is_active: false, discontinued_on: today,
          discontinued_reason: 'Replaced from ' + (carrier.revision_label || 'a newer brochure')
            + (docStates.length ? ' (' + docStates.join(', ') + ')' : ''),
        }).in('id', hit.map(c => c.id));
      }
    }

    await supabaseClient.from('extraction_runs')
      .update({ status: 'approved', reviewed_by: currentAgent.id, approved_at: new Date().toISOString() })
      .eq('id', _pw.run.id);
    if (made && made.length && _pw.docs[0]) {
      await supabaseClient.from('product_documents').update({ product_id: made[0].id }).eq('id', _pw.docs[0]);
    }

    showToast('Saved ' + rows.length + ' product' + (rows.length === 1 ? '' : 's')
      + (retireNames.length ? ', retired ' + retireNames.length : '') + '.');
    closeModal();
    renderAdmin();
  } catch (e) { _pw.busy = false; _pw.error = e.message || String(e); pwPaint_(); }
}

// ============================================================
// PRODUCT PICKER — carrier products, side by side
//
// Built to the same shape as the ACA picker: a full-screen panel, a
// collapsible "what these are based on" bar the agent can edit in place, cards
// of equal height with their actions on the same line, and compare/detail as
// their own overlays ABOVE the picker rather than modals behind it.
//
// One picker, not one per line. What a product is priced by lives on the
// product (metadata.dimensions); how a rate becomes a premium lives on its
// chart (rate_basis). Short-term medical today, hospital indemnity, accident
// or critical illness the moment products exist for them.
// ============================================================

function ppState_() {
  window._qbPp = window._qbPp || { line: null, cmp: new Set(), sel: {}, choice: {}, prem: {}, basisOpen: false };
  return window._qbPp;
}

// What these products are being quoted against. Same facts the ACA tool uses,
// editable here so the agent never has to close the picker to fix a birth date.
function ppProfile_() {
  const c = window._qbContact || {};
  const zipEl = document.getElementById('qb-pp-zip');
  const dobEl = document.getElementById('qb-pp-dob');
  const zip = (zipEl && zipEl.value) || c.zip || '';
  const dob = (dobEl && dobEl.value) || c.date_of_birth || null;
  return {
    zip: zip,
    state: (zipToState_(zip) || c.state || '').toUpperCase(),
    dob: dob,
    age: dob ? qbAgeFrom_(dob) : null,
    household: window._qbPpHH || [],
  };
}

async function openProductPicker_(line) {
  const pp = ppState_();
  pp.line = line || (document.getElementById('qb-line') || {}).value || null;
  pp.cmp = new Set();
  qbWorkbenchOpen_(false);          // the picker IS the screen now

  // seed the household from whatever the ACA tool or the intake already knows
  if (!window._qbPpHH) {
    const c = window._qbContact || {};
    const rows = [...document.querySelectorAll('#qb-aca-members > div')];
    window._qbPpHH = rows.length
      ? rows.map(d => ({
          relationship: (d.querySelector('.aca-rel') || {}).value || 'Self',
          dob: (d.querySelector('.aca-dob') || {}).value || null,
          applying: !(d.querySelector('.aca-app')) || d.querySelector('.aca-app').checked,
        }))
      : (Array.isArray(c.household_members) && c.household_members.length
          ? c.household_members.map(m => ({ relationship: m.relationship || 'Member', dob: m.dob || null, applying: m.applying !== false }))
          : [{ relationship: 'Self', dob: c.date_of_birth || null, applying: true }]);
  }

  let el = document.getElementById('qb-pp-picker');
  if (!el) {
    el = document.createElement('div');
    el.id = 'qb-pp-picker';
    el.style.cssText = 'position:fixed;inset:0;z-index:99990;background:var(--surface-0);display:flex;flex-direction:column;';
    document.body.appendChild(el);
  }
  el.style.display = 'flex';
  el.innerHTML = '<div style="padding:24px;font-size:13px;color:var(--text-muted);">Loading products…</div>';

  const { data: allowed, error: allowErr } = await supabaseClient
    .from('my_offerable_products').select('product_id,office').eq('line_of_business', pp.line);
  const ids = [...new Set((allowed || []).map(x => x.product_id))];
  pp.offices = [...new Set((allowed || []).map(x => x.office).filter(Boolean))];

  // If that view cannot be read, fall back to the old rule rather than showing
  // an empty picker and leaving an agent unable to quote.
  let prods = [];
  if (allowErr) {
    const carriers = (window._qbCarriers || []).map(c => c.id);
    const { data } = carriers.length
      ? await supabaseClient.from('carrier_products').select('*')
          .eq('is_active', true).is('discontinued_on', null)
          .in('carrier_id', carriers).eq('line_of_business', pp.line)
      : { data: [] };
    prods = data || [];
    pp.gateFailed = true;
  } else if (ids.length) {
    const { data } = await supabaseClient.from('carrier_products').select('*').in('id', ids);
    prods = data || [];
  }
  const { data: charts } = prods.length
    ? await supabaseClient.from('rate_charts').select('*')
        .in('product_id', prods.map(p => p.id)).eq('is_active', true)
    : { data: [] };
  const st = ppProfile_().state;
  const all = prods || [];
  pp.hidden = 0;
  pp.products = !st ? all : all.filter(p => {
    const filed = (p.states || []).map(x => String(x).toUpperCase());
    const ok = !filed.length || filed.includes(st);
    if (!ok) pp.hidden++;
    return ok;
  });
  pp.charts = charts || [];
  const { data: docs } = carriers.length
    ? await supabaseClient.from('product_documents').select('product_id,carrier_id')
        .eq('internal_use_only', false).in('carrier_id', carriers)
    : { data: [] };
  pp.docFor = new Set();
  (docs || []).forEach(d => {
    if (d.product_id) pp.docFor.add(d.product_id);
    (prods || []).filter(x => x.carrier_id === d.carrier_id).forEach(x => pp.docFor.add(x.id));
  });
  renderProductPicker_();
}

function closeProductPicker_() {
  const el = document.getElementById('qb-pp-picker');
  if (el) el.style.display = 'none';
}

function ppDims_(p) { return ((p.metadata || {}).dimensions) || {}; }
function ppMeta_(p) { return p.metadata || {}; }
function ppChoice_(p) { const pp = ppState_(); return pp.choice[p.id] || (pp.choice[p.id] = {}); }

function ppChoose_(prodId, key, value) {
  const pp = ppState_();
  (pp.choice[prodId] = pp.choice[prodId] || {})[key] = value;
  renderProductPicker_();
}

function ppSetPrem_(prodId, value) {
  const pp = ppState_();
  const n = parseFloat(String(value).replace(/[^0-9.]/g, ''));
  pp.prem[prodId] = isNaN(n) ? null : n;
  const el = document.getElementById('pp-added-' + prodId);
  if (el) el.textContent = '';           // repaint on add, not on every keystroke
}

function ppRate_(p) {
  const pp = ppState_();
  const chart = (pp.charts || []).find(c => c.product_id === p.id);
  return chart ? { kind: 'chart', chart: chart, basis: chart.rate_basis || 'flat' } : { kind: 'none' };
}

// ------------------------------------------------------------- the basis bar
function ppBasisToggle_() { const pp = ppState_(); pp.basisOpen = !pp.basisOpen; renderProductPicker_(); }

function ppHHSet_(i, field, value) {
  const hh = window._qbPpHH || [];
  if (hh[i]) hh[i][field] = (field === 'applying') ? !!value : value;
}
function ppHHAdd_() { (window._qbPpHH = window._qbPpHH || []).push({ relationship: 'Dependent', dob: null, applying: true }); renderProductPicker_(); }
function ppHHDel_(i) { (window._qbPpHH || []).splice(i, 1); renderProductPicker_(); }
function ppProfileChanged_() { renderProductPicker_(); }

function ppBasisHtml_() {
  const pp = ppState_();
  const prof = ppProfile_();
  const hh = window._qbPpHH || [];
  const applying = hh.filter(m => m.applying !== false).length;
  const summary = [
    prof.zip ? prof.zip + (prof.state ? ' · ' + prof.state : '') : 'no ZIP',
    prof.age != null ? 'age ' + prof.age : 'no date of birth',
    hh.length ? applying + ' of ' + hh.length + ' applying' : '',
  ].filter(Boolean).join('  ·  ');

  const head = `<button type="button" onclick="ppBasisToggle_()" style="width:100%;text-align:left;background:none;border:none;cursor:pointer;padding:9px 20px;display:flex;align-items:center;gap:10px;font-size:12.5px;color:var(--text-secondary);">
      <span style="font-weight:800;color:var(--text-primary);">${pp.basisOpen ? '▾' : '▸'} What these plans are based on</span>
      <span style="color:var(--text-muted);">${escWeb(summary)}</span>
      <span style="margin-left:auto;color:var(--accent,#c8a84b);font-weight:700;">${pp.basisOpen ? 'Hide' : 'Edit'}</span>
    </button>`;
  if (!pp.basisOpen) return `<div style="background:var(--surface-1);border-bottom:1px solid var(--border);">${head}</div>`;

  return `<div style="background:var(--surface-1);border-bottom:1px solid var(--border);">
    ${head}
    <div style="padding:0 20px 14px;display:grid;grid-template-columns:minmax(230px,1fr) minmax(300px,1.5fr);gap:20px;align-items:start;">
      <div>
        <div style="display:flex;gap:10px;flex-wrap:wrap;">
          <div><label style="font-size:10px;margin:0 0 2px;">ZIP code</label>
            <input type="text" id="qb-pp-zip" maxlength="5" value="${escWeb(prof.zip || '')}" onchange="ppProfileChanged_()" style="width:90px;" /></div>
          <div><label style="font-size:10px;margin:0 0 2px;">Date of birth</label>
            <input type="date" id="qb-pp-dob" value="${escWeb(prof.dob || '')}" onchange="ppProfileChanged_()" style="width:150px;" /></div>
        </div>
        <div style="font-size:11.5px;color:var(--text-muted);margin-top:7px;line-height:1.5;">
          ${prof.state ? escWeb(prof.state) : 'No state yet'}${prof.age != null ? ' · age ' + prof.age : ' · no age yet'}
          — these decide which products are filed for them and what you can write.
        </div>
        <button type="button" class="btn btn-outline btn-sm" style="margin-top:8px;" onclick="ppSaveProfile_()">Save to their record</button>
      </div>
      <div>
        <div style="font-size:10px;font-weight:800;text-transform:uppercase;letter-spacing:.5px;color:var(--text-muted);margin-bottom:6px;">Who is being covered</div>
        ${hh.map((m, i) => `
          <div style="display:flex;gap:7px;align-items:center;margin-bottom:5px;flex-wrap:wrap;">
            <input type="text" value="${escWeb(m.relationship || '')}" onchange="ppHHSet_(${i},'relationship',this.value)" placeholder="Self / Spouse / Child" style="width:130px;font-size:12px;margin:0;" />
            <input type="date" value="${escWeb(m.dob || '')}" onchange="ppHHSet_(${i},'dob',this.value);ppProfileChanged_()" style="width:140px;font-size:12px;margin:0;" />
            <label style="display:flex;gap:4px;align-items:center;font-size:11.5px;color:var(--text-muted);font-weight:400;margin:0;">
              <input type="checkbox" ${m.applying !== false ? 'checked' : ''} onchange="ppHHSet_(${i},'applying',this.checked);ppProfileChanged_()" style="width:auto;" /> applying</label>
            <button type="button" class="btn btn-outline btn-sm" onclick="ppHHDel_(${i})" style="padding:1px 7px;">✕</button>
          </div>`).join('')}
        <button type="button" class="btn btn-outline btn-sm" style="margin-top:4px;" onclick="ppHHAdd_()">+ Add someone</button>
      </div>
    </div>
  </div>`;
}

async function ppSaveProfile_() {
  const c = window._qbContact;
  if (!c) return;
  const prof = ppProfile_();
  const patch = {};
  if (prof.zip && prof.zip !== c.zip) patch.zip = prof.zip;
  if (prof.dob && prof.dob !== c.date_of_birth) patch.date_of_birth = prof.dob;
  if ((window._qbPpHH || []).length) patch.household_members = window._qbPpHH;
  if (!Object.keys(patch).length) { showToast('Nothing changed.'); return; }
  const { error } = await supabaseClient.from('contacts').update(patch).eq('id', c.id);
  if (error) { showToast('Could not save: ' + error.message); return; }
  Object.assign(c, patch);
  showToast('Saved to their record.');
}

// ------------------------------------------------------------------ the card
// Some things always read better in the same place, whatever a carrier calls
// them. Pharmacy last, the coverage maximum just above it, everything else in
// the order the document gave. Used by the card, the details and the compare
// so all three agree.
function ppOrder_(key, label) {
  const t = ((label || '') + ' ' + (key || '')).toLowerCase().replace(/[_-]+/g, ' ');
  // The drug benefit and the coverage maximum each have their own place on the
  // card now, so nothing needs pinning to the end of a list any more. Detail
  // and compare still keep the maximum low, where it reads as a summary.
  if (/coverage period max|coverage max|policy max|maximum benefit|lifetime max/.test(t)) return 90;
  return 0;
}
function ppSorted_(entries) {
  return entries
    .map((e, i) => ({ e: e, i: i, w: ppOrder_(e[0], (e[1] || {}).label) }))
    .sort((a, b) => (a.w - b.w) || (a.i - b.i))
    .map(x => x.e);
}

// A dimension is either a plain list of values, or linked parts where choosing
// one narrows the next \u2014 a deductible that carries its own coinsurance. The
// linked kind is stored as combos so nothing has to be parsed back out of a label.
function ppCombos_(d) { return (d && Array.isArray(d.combos)) ? d.combos : null; }

// Keys on a combination that are NOT in "parts" are consequences of the choice
// rather than choices themselves — the out-of-pocket that comes with a
// particular deductible and coinsurance. Shown, never picked.
function ppShownKeys_(d) {
  const c = ppCombos_(d);
  if (!c || !c.length) return [];
  const parts = ppParts_(d);
  return Object.keys(c[0]).filter(k => parts.indexOf(k) < 0);
}

// What the choice has settled so far. Only shown once it IS settled — showing
// a range here would read as a promise the plan has not made.
function ppComboShown_(d, chosen) {
  const shown = ppShownKeys_(d);
  if (!shown.length) return '';
  const open = ppOpenCombos_(d, chosen);
  if (!open.length) return '';
  const settled = shown.filter(k => new Set(open.map(c => String(c[k]))).size === 1);
  if (!settled.length) return '';
  return `<div style="display:flex;gap:14px;flex-wrap:wrap;margin-top:6px;">
    ${settled.map(k => `<span style="font-size:11px;color:var(--text-muted);">${escWeb(k)}:
      <strong style="color:var(--text-secondary);">${escWeb(String(open[0][k]))}</strong></span>`).join('')}
  </div>`;
}

function ppParts_(d) {
  if (d && Array.isArray(d.parts) && d.parts.length) return d.parts;
  const c = ppCombos_(d);
  return c && c.length ? Object.keys(c[0]) : [];
}

// The combinations still open once the earlier parts have been chosen.
function ppOpenCombos_(d, chosen) {
  const combos = ppCombos_(d) || [];
  const parts = ppParts_(d);
  return combos.filter(c => parts.every(pt => {
    const want = (chosen || {})[pt];
    return !want || String(c[pt]) === String(want);
  }));
}

// One dropdown per part. Each is filled from what the parts before it allow, so
// a coinsurance list only ever offers levels the chosen deductible really has.
function ppComboPickers_(p, key, d) {
  const chosen = (ppChoice_(p)[key] || {});
  const parts = ppParts_(d);
  return `<div style="margin-top:8px;" onclick="event.stopPropagation();">
    <div style="font-size:10px;font-weight:800;text-transform:uppercase;letter-spacing:.4px;color:var(--text-muted);">${escWeb(d.label || key)}</div>
    <div style="display:flex;gap:7px;flex-wrap:wrap;margin-top:4px;">
      ${parts.map((pt, idx) => {
        const before = {};
        parts.slice(0, idx).forEach(k => { if (chosen[k]) before[k] = chosen[k]; });
        const open = [...new Set(ppOpenCombos_(d, before).map(c => String(c[pt])))];
        const val = chosen[pt] || '';
        const stale = val && !open.includes(String(val));
        return `<label style="display:flex;flex-direction:column;gap:2px;font-size:10.5px;color:var(--text-muted);font-weight:400;margin:0;">
          ${escWeb(pt)}
          <select onchange="ppComboSet_('${escWeb(p.id)}','${escWeb(key)}','${escWeb(pt)}',this.value)"
            style="width:auto;min-width:96px;font-size:12px;margin:0;${stale ? 'border-color:var(--border-warning);' : ''}">
            <option value="">\u2014 any \u2014</option>
            ${open.map(v => `<option value="${escWeb(v)}"${String(val) === String(v) ? ' selected' : ''}>${escWeb(v)}</option>`).join('')}
          </select></label>`;
      }).join('')}
    </div>
  </div>`;
}

// Everything a choice explains, gathered so it can sit at the foot of the card
// instead of in the middle. The eye then runs: choices, what they mean, price.
// The coverage period maximum is the number a plan is really judged on, so it
// sits with the other decisions at the foot of the card rather than lost in a
// strip of facts near the top.
function ppMaxHtml_(p) {
  const facts = (ppMeta_(p) || {}).facts || {};
  const key = Object.keys(facts).find(k => /coverage period max|coverage max|policy max/i.test(k.replace(/[_-]+/g, ' ')));
  if (!key) return '';
  return `<div style="display:flex;justify-content:space-between;gap:10px;font-size:11.5px;margin-top:7px;">
    <span style="color:var(--text-muted);">Coverage period maximum</span>
    <strong style="color:var(--text-secondary);">${escWeb(String(facts[key]))}</strong></div>`;
}

function ppComboSummary_(p) {
  return Object.entries(ppDims_(p)).map(([key, d]) => {
    if (!ppCombos_(d)) return '';
    const chosen = ppChoice_(p)[key] || {};
    return ppComboShown_(d, chosen) + ppExposure_(p, d, chosen) + ppComboNote_(d, chosen);
  }).join('');
}

// Every card gives its description the same room, sized to the longest one on
// screen, so everything below it starts at the same height across the row.
function ppNoteLines_() {
  const pp = ppState_();
  const longest = (pp.products || []).reduce((n, x) => Math.max(n, String(x.notes || '').length), 0);
  if (!longest) return 0;
  const perLine = 42;                     // roughly what fits at this card width
  return Math.max(2, Math.min(5, Math.ceil(longest / perLine)));   // never a wall of text
}
function ppNoteHeight_() { return ppNoteLines_() * 18; }

// Deductible plus the coinsurance cap is what a person actually faces on
// covered, in-network care before the plan starts paying everything. Worth
// showing, because neither number means much alone — but it is NOT a maximum
// out-of-pocket and must never be labelled as one. Copays sit on top,
// out-of-network doubles on these plans, the coverage-period maximum caps what
// the PLAN pays, and nothing excluded counts at all.
function ppMoney_(v) {
  const n = parseFloat(String(v == null ? '' : v).replace(/[^0-9.]/g, ''));
  return isNaN(n) ? null : n;
}

function ppExposure_(p, d, chosen) {
  // Carriers word this differently. Where the stated out-of-pocket already
  // includes the deductible, adding them would count it twice.
  if (p && (ppMeta_(p) || {}).oop_includes_deductible === true) return '';
  const open = ppOpenCombos_(d, chosen);
  if (open.length !== 1) return '';
  const c = open[0];
  const dedKey = Object.keys(c).find(k => /deductible/i.test(k));
  const oopKey = Object.keys(c).find(k => /out-?of-?pocket|oop/i.test(k));
  if (!dedKey || !oopKey) return '';
  const ded = ppMoney_(c[dedKey]), oop = ppMoney_(c[oopKey]);
  if (ded == null || oop == null) return '';
  const total = ded + oop;
  return `<div style="margin-top:7px;padding:7px 10px;border-radius:8px;background:var(--bg-info);border:1px solid var(--border-info);">
    <div style="font-size:13px;font-weight:800;color:var(--text-info);">$${total.toLocaleString('en-US')} in network,
      before the plan pays 100%</div>
    <div style="font-size:10.5px;color:var(--text-info);opacity:.85;line-height:1.5;margin-top:2px;">
      $${ded.toLocaleString('en-US')} deductible + $${oop.toLocaleString('en-US')} coinsurance cap.
      <strong>Not a maximum out-of-pocket</strong> — copays are on top, out-of-network is double on these plans,
      and anything the policy excludes does not count.</div>
  </div>`;
}

function ppComboNote_(d, chosen) {
  const parts = ppParts_(d);
  const open = ppOpenCombos_(d, chosen);
  const done = parts.every(pt => chosen[pt]);
  if (done) return '';
  return `<div style="font-size:10.5px;color:var(--text-muted);margin-top:4px;">${open.length} combination${open.length === 1 ? '' : 's'} this plan offers</div>`;
}

// Choosing an earlier part drops any later one it no longer allows, rather
// than leaving a pairing on screen the carrier does not sell.
function ppComboSet_(prodId, key, part, value) {
  const pp = ppState_();
  const p = (pp.products || []).find(x => x.id === prodId);
  if (!p) return;
  const d = ppDims_(p)[key] || {};
  const choice = (pp.choice[prodId] = pp.choice[prodId] || {});
  const sel = (choice[key] = choice[key] || {});
  if (value) sel[part] = value; else delete sel[part];

  const parts = ppParts_(d);
  const after = parts.slice(parts.indexOf(part) + 1);
  after.forEach(pt => {
    if (!sel[pt]) return;
    const before = {};
    parts.slice(0, parts.indexOf(pt)).forEach(k => { if (sel[k]) before[k] = sel[k]; });
    const open = ppOpenCombos_(d, before).map(c => String(c[pt]));
    if (!open.includes(String(sel[pt]))) delete sel[pt];
  });
  renderProductPicker_();
}

// How a chosen combination reads, wherever it is shown.
function ppChoiceLabel_(p, key, d) {
  const chosen = (ppChoice_(p)[key] || {});
  const parts = ppParts_(d);
  const said = parts.filter(pt => chosen[pt]).map(pt => pt + ' ' + chosen[pt]);
  if (!said.length) return null;
  // whatever the choice settles \u2014 the out-of-pocket that goes with it \u2014 rides along
  const open = ppOpenCombos_(d, chosen);
  ppShownKeys_(d).forEach(k => {
    const vals = new Set(open.map(c => String(c[k])));
    if (vals.size === 1) said.push(k + ' ' + [...vals][0]);
  });
  return said.join(' \u00b7 ');
}

// The benefit rows a medical plan is actually compared on. Carriers all word
// these differently, so the reading maps each brochure onto these names and
// keeps the carrier's own wording as the value. Without a shared vocabulary a
// comparison is just two lists side by side.
//
// The order is the order they matter in a conversation: what you use often
// first, what you dread further down, and the money questions last.
const PP_BENEFITS = [
  ['office_visit_primary', 'Primary care visit', '\u{1FA7A}'],
  ['office_visit_specialist', 'Specialist visit', '\u{1F52C}'],
  ['preventive_care', 'Preventive care', '\u{1F6E1}\uFE0F'],
  ['telehealth', 'Telehealth', '\u{1F4F1}'],
  ['urgent_care', 'Urgent care', '\u{1F3E5}'],
  ['emergency_room', 'Emergency room', '\u{1F691}'],
  ['ambulance', 'Ambulance', '\u{1F6A8}'],
  ['inpatient_hospital', 'Hospital stay', '\u{1F6CF}\uFE0F'],
  ['outpatient_surgery', 'Outpatient surgery', '\u2702\uFE0F'],
  ['diagnostic_lab', 'Diagnostic and lab', '\u{1F9EA}'],
  ['imaging', 'Imaging (X-ray, MRI, CT)', '\u{1FA7B}'],
  ['therapy_rehab', 'Physical therapy and rehab', '\u{1F9BE}'],
  ['mental_health', 'Mental health', '\u{1F9E0}'],
  ['substance_use', 'Substance use treatment', '\u{1F91D}'],
  ['maternity', 'Maternity', '\u{1F930}'],
  ['durable_medical_equipment', 'Equipment and supplies', '\u{1F9BD}'],
  ['organ_transplant', 'Transplant', '\u2764\uFE0F'],
  ['coverage_period_maximum', 'Coverage period maximum', '\u{1F4CF}'],
  // prescriptions last of the benefit rows, always
  ['prescription_drugs', 'Prescriptions', '\u{1F48A}'],
];

// How a single benefit reads. "not covered" is said plainly rather than left
// blank, because on a short-term plan the gaps are the point.
function ppBenefitCell_(p, key) {
  const b = ((ppMeta_(p) || {}).benefits || {})[key];
  if (!b) return null;
  if (typeof b === 'string') return escWeb(b);
  const covered = b.covered;
  const said = [b.value, b.limit].filter(Boolean).map(x => escWeb(String(x))).join(' \u00b7 ');
  if (covered === false || /^(no|none|not covered)$/i.test(String(b.value || ''))) {
    return `<span style="color:var(--text-warning);">Not covered</span>${said && !/not covered/i.test(said) ? ' \u00b7 ' + said : ''}`;
  }
  return said || (covered ? 'Covered' : null);
}

function ppBenefitRows_(p) {
  return PP_BENEFITS.filter(([k]) => k !== 'coverage_period_maximum')
    .map(([k, label, icon]) => [label, ppBenefitCell_(p, k), icon]).filter(r => r[1]);
}

function ppCardHtml_(p) {
  const pp = ppState_();
  const dims = ppDims_(p);
  const meta = ppMeta_(p);
  const choice = ppChoice_(p);
  const carrier = (window._qbCarriers || []).find(c => c.id === p.carrier_id) || {};
  const prof = ppProfile_();
  const fit = productFit_(p, prof.state, p.carrier_id);
  const rate = ppRate_(p);
  const slot = ppAddedSlot_(p.id);
  const typed = pp.prem[p.id];

  const dimRows = ppSorted_(Object.entries(dims)).map(([key, d]) => {
    if (ppCombos_(d)) return ppComboPickers_(p, key, d);
    const values = (d && d.values) || [];
    if (!values.length) return '';
    return `<div style="margin-top:8px;">
      <div style="font-size:10px;font-weight:800;text-transform:uppercase;letter-spacing:.4px;color:var(--text-muted);">${escWeb((d && d.label) || key)}</div>
      <div style="display:flex;gap:5px;flex-wrap:wrap;margin-top:4px;">
        ${values.map(v => `<button type="button" onclick="ppChoose_('${escWeb(p.id)}','${escWeb(key)}',${JSON.stringify(String(v)).replace(/"/g, '&quot;')})"
          class="fx-chip${String(choice[key]) === String(v) ? ' on' : ''}" style="font-size:11px;">${escWeb(ppFmt_(v, d))}</button>`).join('')}
      </div></div>`;
  }).join('');

  return `<div onclick="ppDetail_('${escWeb(p.id)}')" title="Open the full details"
    style="display:flex;flex-direction:column;cursor:pointer;border:1px solid ${slot >= 0 ? 'var(--border-selected)' : 'var(--border)'};border-radius:11px;padding:13px 15px;background:${slot >= 0 ? 'var(--bg-selected-card)' : 'var(--surface-1)'};">

    <div style="display:flex;justify-content:space-between;gap:9px;align-items:flex-start;min-height:52px;">
      <div style="flex:1;min-width:0;">
        <div style="font-size:10px;font-weight:800;text-transform:uppercase;letter-spacing:.5px;color:var(--text-muted);">${escWeb(carrier.name || '')}</div>
        <div style="font-size:14.5px;font-weight:800;margin:2px 0 2px;">${escWeb(p.name)}</div>
        ${meta.underwriter && meta.underwriter !== carrier.name
          ? `<div style="font-size:10.5px;color:var(--text-muted);">Underwritten by ${escWeb(meta.underwriter)}</div>` : ''}
      </div>
      <label onclick="event.stopPropagation();" style="display:flex;gap:5px;align-items:center;font-size:11px;color:var(--text-muted);cursor:pointer;white-space:nowrap;">
        <input type="checkbox" ${pp.cmp.has(p.id) ? 'checked' : ''} onchange="ppCmpToggle_('${escWeb(p.id)}')" style="width:13px;height:13px;" /> ⚖️ Compare</label>
    </div>

    ${slot >= 0 ? `<div style="margin:6px 0 2px;"><span class="pk-sel-badge">✓ Selected · Option ${qbOptionNo_(slot)}</span></div>` : ''}

    <div style="height:${ppNoteHeight_()}px;font-size:12px;color:var(--text-secondary);line-height:1.5;margin-top:5px;
      overflow:hidden;display:-webkit-box;-webkit-line-clamp:${ppNoteLines_()};-webkit-box-orient:vertical;"
      title="${p.notes ? escWeb(p.notes) : ''}">${p.notes ? escWeb(p.notes) : ''}</div>
    <div style="min-height:18px;" onclick="event.stopPropagation();">${ppNetworkHtml_(p)}</div>
    <div style="min-height:18px;" onclick="event.stopPropagation();">${(ppState_().docFor || new Set()).has(p.id)
      ? `<a href="#" onclick="event.preventDefault();productDocOpen_('${escWeb(p.id)}')" style="font-size:11px;color:var(--link);">&#128196; Brochure</a>
         <a href="#" onclick="event.preventDefault();productDocCopy_('${escWeb(p.id)}')" style="font-size:11px;color:var(--link);margin-left:10px;">copy link for the client</a>`
      : ''}</div>

    <div style="min-height:${ppBenefitHeight_()}px;margin-top:7px;">${ppBenefitList_(p)}</div>


    <div style="margin-top:auto;">
      <div style="min-height:26px;">
        ${fit.warnings.filter(w => w.scope !== 'agent').map(w =>
          `<div class="pk-bar warn" style="border-radius:8px;border:1px solid;margin-bottom:4px;font-size:11px;">⚠️ ${w.text}</div>`).join('')}
      </div>
      ${ppMaxHtml_(p)}
      ${dimRows}
      ${ppComboSummary_(p)}
    </div>

    <div style="padding-top:10px;border-top:1px solid var(--border);">
      ${rate.kind === 'none' ? `
        <div style="font-size:11px;color:var(--text-muted);line-height:1.45;">No rate chart on file — quote it at the carrier, then put the premium here.</div>
        <div style="display:flex;gap:7px;align-items:center;margin-top:6px;flex-wrap:wrap;" onclick="event.stopPropagation();">
          ${carrierQuotingBtn_(p.carrier_id, p.id, 'Quote at the carrier')}
          <span style="display:inline-flex;align-items:center;gap:4px;">
            <span style="font-size:12px;color:var(--text-muted);">$</span>
            <input type="text" inputmode="decimal" value="${typed != null ? typed : ''}" placeholder="premium"
              oninput="ppSetPrem_('${escWeb(p.id)}', this.value)" style="width:88px;font-size:12px;margin:0;" />
            <span style="font-size:11px;color:var(--text-muted);">/mo</span></span>
        </div>` : `
        <div style="font-size:18px;font-weight:800;color:var(--accent,#c8a84b);line-height:1.2;">${ppPriceLabel_(p, rate)}</div>`}
      <div style="display:flex;gap:7px;margin-top:9px;" onclick="event.stopPropagation();">
        <button class="btn ${slot >= 0 ? 'btn-outline' : 'btn-primary'} btn-sm" style="${slot >= 0 ? 'color:var(--success);border-color:var(--success);' : ''}" onclick="ppAdd_('${escWeb(p.id)}')">
          ${slot >= 0 ? '✓ Option ' + qbOptionNo_(slot) : '＋ Add'}</button>
        <button class="btn btn-outline btn-sm" onclick="ppDetail_('${escWeb(p.id)}')">Details</button>
        ${ppAcaOnQuote_().length ? `<button class="btn btn-outline btn-sm" title="Against the Marketplace plan already on this quote"
          onclick="ppVsAca_('${escWeb(p.id)}')">vs ACA</button>` : ''}
      </div>
    </div>
  </div>`;
}

// Which network the plan runs on, and the way to check whether their doctor is
// in it. We cannot query these directories the way we query the Marketplace,
// so the next best thing is one click to the carrier's own search.
function ppNetworkHtml_(p, big) {
  const n = (ppMeta_(p) || {}).network;
  if (!n || !(n.name || n.provided_by)) return '';
  const label = escWeb(n.name || (n.provided_by + ' network'));
  const url = n.provider_search_url;
  return `<div style="font-size:${big ? '13' : '11'}px;color:var(--text-muted);white-space:${big ? 'normal' : 'nowrap'};overflow:hidden;text-overflow:ellipsis;">
    &#127973; ${label}
    ${url ? `<a href="${escWeb(url)}" target="_blank" rel="noopener noreferrer" style="color:var(--link);margin-left:6px;">check a doctor &#8599;</a>` : ''}
    ${big && n.size ? `<div style="margin-top:2px;">${escWeb(n.size)}</div>` : ''}
  </div>`;
}

// Whether the plan pays anything toward prescriptions. Many short-term plans
// pay nothing, and a discount card is not a benefit: it does not pay a claim.
function ppRxHtml_(p, big) {
  const rx = (ppMeta_(p) || {}).prescription;
  const fact = ((ppMeta_(p) || {}).facts || {}).pharmacy;
  const size = big ? '13' : '11';
  if (!rx && !fact) return '';
  if (!rx) return `<div style="font-size:${size}px;color:var(--text-muted);">&#128138; ${escWeb(String(fact))}</div>`;
  if (rx.discount_card_only) return `<div style="font-size:${size}px;color:var(--text-warning);">&#128138; Discount card only &mdash; not a drug benefit</div>`;
  if (rx.has_benefit === false) return `<div style="font-size:${size}px;color:var(--text-muted);">&#128138; No prescription coverage</div>`;
  const bits = [rx.copay, rx.generics_only ? 'generics only' : null,
                rx.maximum_benefit ? 'max ' + rx.maximum_benefit : null].filter(Boolean).map(x => escWeb(String(x)));
  return `<div style="font-size:${size}px;color:var(--text-secondary);">&#128138;
    ${escWeb(rx.summary || 'Prescription coverage')}${bits.length && !rx.summary ? ' &middot; ' + bits.join(' &middot; ') : ''}
    ${rx.is_rider ? '<span style="color:var(--text-warning);"> (separate rider)</span>' : ''}</div>`;
}

// What the plan actually pays, on the card. Kept short: the full wording is in
// the details. Every card gets the same room so the rows below stay level.
function ppBenefitList_(p) {
  const ben = (ppMeta_(p) || {}).benefits || {};
  const rows = PP_BENEFITS.filter(([k]) => k !== 'coverage_period_maximum' && ben[k]);
  if (!rows.length) return '<span style="font-size:11px;color:var(--text-muted);">No benefit detail read from the brochure yet.</span>';
  return `<div style="display:grid;grid-template-columns:1fr 1fr;gap:1px 10px;">
    ${rows.map(([k, label]) => {
      const b = ben[k];
      const yes = !(b && (b.covered === false || /^(no|none|not covered|not applicable)$/i.test(String(b.value || ''))));
      return `<div style="font-size:11.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;
        color:${yes ? 'var(--text-secondary)' : 'var(--text-muted)'};">
        <span style="color:${yes ? 'var(--text-success)' : 'var(--text-muted)'};font-weight:800;">${yes ? '✓' : '✕'}</span>
        ${escWeb(label)}</div>`;
    }).join('')}
  </div>`;
}

function ppBenefitHeight_() {
  const pp = ppState_();
  const count = x => PP_BENEFITS.filter(([k]) =>
    k !== 'coverage_period_maximum' && (((ppMeta_(x) || {}).benefits) || {})[k]).length;
  const most = (pp.products || []).reduce((n, x) => Math.max(n, count(x)), 0);
  return most ? Math.ceil(most / 2) * 17 + 4 : 18;   // two columns of ticks
}

function ppFmt_(v, d) {
  if (d && d.unit === '$' && /^\d+(\.\d+)?$/.test(String(v))) return '$' + Number(v).toLocaleString('en-US');
  if (d && d.unit === '%' && /^\d+(\.\d+)?$/.test(String(v))) return v + '%';
  return String(v);
}

function ppPriceLabel_(p, rate) {
  const pp = ppState_();
  if (rate.basis !== 'flat') {
    const inp = (rate.chart && rate.chart.benefit_input) || {};
    return `<span style="font-size:12px;font-weight:400;color:var(--text-muted);">Priced per ${escWeb(
      rate.basis === 'per_1000_face' ? '$1,000 of cover'
      : rate.basis === 'per_100_benefit' ? '$100 of monthly benefit' : 'unit')} — enter ${escWeb(inp.label || 'the amount')} on the option</span>`;
  }
  const typed = pp.prem[p.id];
  return typed != null
    ? '$' + Number(typed).toFixed(2) + '<span style="font-size:11px;font-weight:500;color:var(--text-muted);">/mo</span>'
    : '<span style="font-size:12px;font-weight:400;color:var(--text-muted);">Rate chart on file — choose the options above</span>';
}

function ppCmpToggle_(id) {
  const pp = ppState_();
  if (pp.cmp.has(id)) pp.cmp.delete(id);
  else if (pp.cmp.size >= 4) { showToast('Four at a time is the most that reads well.'); return; }
  else pp.cmp.add(id);
  renderProductPicker_();
}

function ppAddedSlot_(prodId) {
  const pp = ppState_();
  for (let i = 0; i < QB_MAX_OPTIONS; i++) if (pp.sel[i] === prodId) return i;
  return -1;
}

function ppAdd_(prodId) {
  const pp = ppState_();
  const p = (pp.products || []).find(x => x.id === prodId);
  if (!p) return;

  const existing = ppAddedSlot_(prodId);
  if (existing >= 0) {
    delete pp.sel[existing];
    ['qb-name-', 'qb-prem-', 'qb-bul-', 'qb-note-'].forEach(pref => {
      const el = document.getElementById(pref + existing); if (el) el.value = '';
    });
    const pr0 = document.getElementById('qb-prod-' + existing); if (pr0) pr0.value = '';
    const rec = document.getElementById('qb-rec-' + existing); if (rec) rec.checked = false;
    qbTidyOptions_();
    renderProductPicker_();
    return;
  }

  let slot = -1;
  for (let i = 0; i < QB_MAX_OPTIONS; i++) if (!qbOptionFilled_(i)) { slot = i; break; }
  if (slot === -1) {
    showToast('All ' + QB_MAX_OPTIONS + ' options on this quote are used — take one off first.');
    return;
  }
  const wrap = document.getElementById('qb-opt-wrap-' + slot);
  if (wrap) wrap.style.display = 'block';
  pp.sel[slot] = prodId;

  const meta = ppMeta_(p);
  const choice = ppChoice_(p);
  const chosen = Object.entries(choice).map(([k, v]) => {
    const d = ppDims_(p)[k] || {};
    if (ppCombos_(d)) { const said = ppChoiceLabel_(p, k, d); return said ? said : null; }
    return ((d.label || k) + ': ' + ppFmt_(v, d));
  }).filter(Boolean);

  const ol = document.getElementById('qb-optline-' + slot);
  if (ol) { ol.value = p.line_of_business; qbOptLineChanged_(slot); }
  const car = document.getElementById('qb-car-' + slot);
  if (car) { car.value = p.carrier_id; qbFillProducts_(slot); }
  const pr = document.getElementById('qb-prod-' + slot);
  if (pr) pr.value = p.id;
  const nm = document.getElementById('qb-name-' + slot);
  if (nm) nm.value = p.name;
  const prem = document.getElementById('qb-prem-' + slot);
  if (prem && pp.prem[prodId] != null) prem.value = Number(pp.prem[prodId]).toFixed(2);
  const bul = document.getElementById('qb-bul-' + slot);
  if (bul) bul.value = [].concat(chosen, meta.bullets || []).join('\n');

  // The snapshot the client page reads. Without it a short-term option shows
  // only its bullets and the comparison has nothing on the short-term side.
  window._qbPpMeta = window._qbPpMeta || {};
  window._qbPpMeta[slot] = {
    src: 'stm', product_id: p.id, name: p.name,
    carrier_name: ((window._qbCarriers || []).find(c => c.id === p.carrier_id) || {}).name || null,
    underwriter: meta.underwriter || null,
    network: meta.network || null,
    benefits: meta.benefits || null,
    prescription: meta.prescription || null,
    facts: meta.facts || null,
    chosen: choice,
    limitations: meta.limitations || null,
    compliance_notes: meta.compliance_notes || null,
  };

  qbRenumberOptions_();
  qbSectionSummary_();
  if (typeof qbQuoteLinkPaint_ === 'function') qbQuoteLinkPaint_(slot);
  showToast('Added as Option ' + qbOptionNo_(slot) + '.');
  renderProductPicker_();
}

// ---------------------------------------- detail and compare, ABOVE the picker
function ppOverlay_(id, title, bodyHtml) {
  let ov = document.getElementById(id);
  if (!ov) {
    ov = document.createElement('div');
    ov.id = id;
    ov.style.cssText = 'position:fixed;inset:0;z-index:99996;background:var(--surface-0);display:flex;flex-direction:column;';
    document.body.appendChild(ov);
  }
  ov.style.display = 'flex';
  ov.innerHTML = `
    <div style="padding:12px 18px;border-bottom:1px solid var(--border);display:flex;align-items:center;gap:12px;">
      <div style="font-weight:800;font-size:15px;">${title}</div>
      <button class="btn btn-outline btn-sm" style="margin-left:auto;" onclick="document.getElementById('${id}').style.display='none'">✕ Close</button>
    </div>
    <div style="flex:1;overflow:auto;padding:16px 20px;">${bodyHtml}</div>`;
}

function ppDetail_(prodId) {
  const pp = ppState_();
  const p = (pp.products || []).find(x => x.id === prodId);
  if (!p) return;
  const meta = ppMeta_(p);
  const ao = meta.agent_only || {};
  const carrier = (window._qbCarriers || []).find(c => c.id === p.carrier_id) || {};
  const list = (title, arr, tone) => (arr || []).length ? `
    <div style="margin-top:14px;">
      <div style="font-size:10.5px;font-weight:800;text-transform:uppercase;letter-spacing:.5px;color:var(--text-${tone || 'muted'});">${title}</div>
      <ul style="margin:5px 0 0 18px;padding:0;font-size:13px;line-height:1.7;">${(arr || []).map(x => '<li>' + escWeb(String(x)) + '</li>').join('')}</ul>
    </div>` : '';

  ppOverlay_('qb-pp-detail', escWeb(p.name), `
    <div style="max-width:820px;">
      <div style="font-size:11px;font-weight:800;text-transform:uppercase;letter-spacing:.5px;color:var(--text-muted);">${escWeb(carrier.name || '')}</div>
      ${p.notes ? `<div style="font-size:13.5px;line-height:1.6;margin-top:6px;">${escWeb(p.notes)}</div>` : ''}
      ${ppNetworkHtml_(p, true)}
      ${meta.underwriter ? `<div style="font-size:12px;color:var(--text-muted);margin-top:7px;">Underwritten by <strong>${escWeb(meta.underwriter)}</strong>${meta.policy_form ? ' · form ' + escWeb(meta.policy_form) : ''}</div>` : ''}
      ${Object.keys(meta.facts || {}).length ? `<div style="margin-top:12px;display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:8px;">
        ${ppSorted_(Object.entries(meta.facts)).map(([k, v]) => `<div style="border:1px solid var(--border);border-radius:9px;padding:8px 11px;">
          <div style="font-size:10.5px;color:var(--text-muted);text-transform:uppercase;letter-spacing:.4px;">${escWeb(k.replace(/_/g, ' '))}</div>
          <div style="font-size:14px;font-weight:800;">${escWeb(String(v))}</div></div>`).join('')}
      </div>` : ''}
      ${ppBenefitRows_(p).length ? `<div style="margin-top:14px;">
        <div style="font-size:10.5px;font-weight:800;text-transform:uppercase;letter-spacing:.5px;color:var(--text-muted);">What it pays, item by item</div>
        <table style="border-collapse:collapse;margin-top:6px;width:100%;max-width:620px;">
          ${ppBenefitRows_(p).map(([label, cell, icon]) => `<tr>
            <td style="padding:5px 10px 5px 0;font-size:12.5px;color:var(--text-muted);vertical-align:top;width:230px;">${icon || ''} ${escWeb(label)}</td>
            <td style="padding:5px 0;font-size:12.5px;vertical-align:top;line-height:1.5;">${cell}</td></tr>`).join('')}
        </table></div>` : ''}
      ${list('What it covers', meta.bullets)}
      ${list('Limits and exclusions', meta.limitations, 'warning')}
      ${list('Eligibility', meta.eligibility)}
      ${list('Say this out loud', meta.compliance_notes, 'warning')}
      ${(ao.exclusions || []).length || (ao.riders || []).length || (ao.benefit_detail || []).length ? `
        <div style="margin-top:16px;border:1px solid var(--border-warning);background:var(--bg-warning);border-radius:10px;padding:12px 15px;">
          <div style="font-size:12px;font-weight:800;color:var(--text-warning);">🔒 Agent reference only — never shown to a client</div>
          ${list('Full policy exclusions', ao.exclusions, 'warning')}
          ${list('How the benefits are worded', ao.benefit_detail, 'warning')}
          ${list('Riders', ao.riders, 'warning')}
          ${(ao.caveats || []).length ? `<div style="font-size:11.5px;color:var(--text-warning);opacity:.9;margin-top:9px;">${escWeb((ao.caveats || []).join(' '))}</div>` : ''}
        </div>` : ''}
      <div style="margin-top:16px;display:flex;gap:14px;flex-wrap:wrap;">
        <a href="#" onclick="event.preventDefault();productDocOpen_('${escWeb(p.id)}')" style="font-size:13px;color:var(--link);">📄 Open the brochure</a>
        <a href="#" onclick="event.preventDefault();productDocCopy_('${escWeb(p.id)}')" style="font-size:13px;color:var(--link);">Copy a link for the client</a>
      </div>
    </div>`);
}

function openProductCompare_() {
  const pp = ppState_();
  const picked = (pp.products || []).filter(p => pp.cmp.has(p.id));
  if (picked.length < 2) { showToast('Tick ⚖️ Compare on at least 2 plans first.'); return; }
  const carrierOf = id => ((window._qbCarriers || []).find(c => c.id === id) || {}).name || '';
  const TH = 'position:sticky;left:0;background:var(--surface-0);text-align:left;font-size:11.5px;font-weight:700;color:var(--text-muted);padding:9px 12px;border-bottom:1px solid var(--border);min-width:180px;vertical-align:top;z-index:1;';
  const TD = 'padding:9px 12px;border-bottom:1px solid var(--border);font-size:12.5px;vertical-align:top;min-width:210px;line-height:1.6;';
  const dash = '<span style="color:var(--text-muted);">—</span>';

  // Every choice and every stated fact across the picked plans, so the rows
  // line up even when one carrier names something the others do not.
  const dimKeys = ppSorted_([...new Set(picked.flatMap(p => Object.keys(ppDims_(p))))]
    .map(k => [k, (picked.map(p => ppDims_(p)[k]).find(Boolean) || {})])).map(e => e[0]);
  const factKeys = ppSorted_([...new Set(picked.flatMap(p => Object.keys(ppMeta_(p).facts || {})))].map(k => [k, {}])).map(e => e[0]);
  const listRow = (label, key, tone) => {
    if (!picked.some(p => ((ppMeta_(p)[key]) || []).length)) return '';
    return `<tr><th style="${TH}">${label}</th>${picked.map(p => {
      const arr = ppMeta_(p)[key] || [];
      return `<td style="${TD}${tone ? 'color:var(--text-' + tone + ');' : ''}">${arr.length ? arr.map(x => '• ' + escWeb(String(x))).join('<br>') : dash}</td>`;
    }).join('')}</tr>`;
  };

  ppOverlay_('qb-pp-compare', '⚖️ Side by side · ' + escWeb(pp.line || ''), `
    <table style="border-collapse:collapse;width:100%;">
      <thead><tr><th style="${TH}"></th>${picked.map(p => `<td style="${TD}font-weight:800;font-size:14px;">
        <div style="font-size:10px;text-transform:uppercase;letter-spacing:.5px;color:var(--text-muted);font-weight:800;">${escWeb(carrierOf(p.carrier_id))}</div>
        ${escWeb(p.name)}</td>`).join('')}</tr></thead>
      <tbody>
        <tr><th style="${TH}">Premium</th>${picked.map(p => {
          const t = pp.prem[p.id];
          return `<td style="${TD}font-weight:800;font-size:15px;color:var(--accent,#c8a84b);">${t != null ? '$' + Number(t).toFixed(2) + '/mo' : dash}</td>`;
        }).join('')}</tr>
        ${dimKeys.map(k => {
          const label = ((picked.map(p => ppDims_(p)[k]).find(Boolean) || {}).label) || k;
          return `<tr><th style="${TH}">${escWeb(label)}</th>${picked.map(p => {
            const d = ppDims_(p)[k];
            if (!d) return `<td style="${TD}">${dash}</td>`;
            // linked parts: the agent's pick if they made one, otherwise every
            // combination the plan actually offers
            if (ppCombos_(d)) {
              const said = ppChoiceLabel_(p, k, d);
              if (said) return `<td style="${TD}"><strong style="color:var(--text-selected,var(--accent));">${escWeb(said)}</strong>
                <div style="font-size:11px;color:var(--text-muted);">chosen from ${(ppCombos_(d) || []).length} combinations</div></td>`;
              const parts = ppParts_(d), shown = ppShownKeys_(d);
              return `<td style="${TD}">${(ppCombos_(d) || []).map(c =>
                escWeb(parts.map(pt => c[pt]).join(' · '))
                + (shown.length ? ' <span style="color:var(--text-muted);">('
                    + escWeb(shown.map(k => c[k]).join(' · ')) + ')</span>' : '')).join('<br>')}</td>`;
            }
            const chosen = (pp.choice[p.id] || {})[k];
            if (!(d.values || []).length) return `<td style="${TD}">${dash}</td>`;
            return `<td style="${TD}">${(d.values || []).map(v =>
              String(v) === String(chosen)
                ? '<strong style="color:var(--text-selected,var(--accent));">' + escWeb(ppFmt_(v, d)) + ' ←</strong>'
                : escWeb(ppFmt_(v, d))).join('<br>')}</td>`;
          }).join('')}</tr>`;
        }).join('')}
        ${factKeys.map(k => `<tr><th style="${TH}">${escWeb(k.replace(/_/g, ' '))}</th>
          ${picked.map(p => `<td style="${TD}">${escWeb(String((ppMeta_(p).facts || {})[k] || '')) || dash}</td>`).join('')}</tr>`).join('')}
        ${listRow('What it covers', 'bullets')}
        ${listRow('Limits and exclusions', 'limitations', 'warning')}
        ${listRow('Eligibility', 'eligibility')}
        ${listRow('Say this out loud', 'compliance_notes', 'warning')}
        ${PP_BENEFITS.filter(([k]) => picked.some(p => ppBenefitCell_(p, k)))
          .map(([k, label]) => `<tr><th style="${TH}">${escWeb(label)}</th>${picked.map(p =>
            `<td style="${TD}">${ppBenefitCell_(p, k) || dash}</td>`).join('')}</tr>`).join('')}
        <tr><th style="${TH}">Network</th>${picked.map(p =>
          `<td style="${TD}">${ppNetworkHtml_(p, true) || dash}</td>`).join('')}</tr>
        <tr><th style="${TH}">Underwritten by</th>${picked.map(p =>
          `<td style="${TD}">${escWeb(ppMeta_(p).underwriter || carrierOf(p.carrier_id))}</td>`).join('')}</tr>
        <tr><th style="${TH}"></th>${picked.map(p => {
          const slot = ppAddedSlot_(p.id);
          return `<td style="${TD}"><button class="btn ${slot >= 0 ? 'btn-outline' : 'btn-primary'} btn-sm" onclick="ppAdd_('${escWeb(p.id)}');openProductCompare_();">
            ${slot >= 0 ? '✓ Option ' + qbOptionNo_(slot) : '＋ Add to quote'}</button></td>`;
        }).join('')}</tr>
      </tbody>
    </table>`);
}

// The one warning that is about the agent and the state rather than any single
// plan. Said once, above everything, instead of repeated on every card.
function ppAgentBar_(prof) {
  const bar = html => `<div class="pk-bar warn" style="border-radius:0;border:0;border-bottom:1px solid var(--border);">⚠️ ${html}</div>`;
  if (!prof.state) return bar('No ZIP code yet, so we cannot tell which products are filed for them. Add it below.');
  const me = (window.allAgents || []).find(a => a.id === (window.currentAgent || {}).id) || window.currentAgent || {};
  if (agentStates_(me).has(prof.state)) return '';
  return bar('You are not showing a license in <strong>' + escWeb(prof.state) + '</strong>. You can quote '
    + 'everything here, but you cannot write any of it until that is in place.');
}

// ---------------------------------------------------------------------------
// SHORT-TERM AGAINST A MARKETPLACE PLAN
//
// Only ever against a plan already on this quote, because that is the one the
// client is actually weighing. The structural rows sit at the top and are not
// collapsible: a copay table alone makes these look like two versions of the
// same thing, and they are not. The wording follows the federal notice these
// policies are required to carry.
// ---------------------------------------------------------------------------

// healthcare.gov names its benefits at length and inconsistently, so match on
// what the name contains rather than on an exact string.
const ACA_BENEFIT_MAP = [
  [/primary care/i, 'office_visit_primary'],
  [/specialist/i, 'office_visit_specialist'],
  [/preventive/i, 'preventive_care'],
  [/urgent care/i, 'urgent_care'],
  [/emergency room|emergency services/i, 'emergency_room'],
  [/ambulance|emergency transport/i, 'ambulance'],
  [/inpatient hospital|hospital stay/i, 'inpatient_hospital'],
  [/outpatient (facility|surgery)|ambulatory surgery/i, 'outpatient_surgery'],
  [/laborator/i, 'diagnostic_lab'],
  [/x-ray|imaging/i, 'imaging'],
  [/therapy|rehabilitat/i, 'therapy_rehab'],
  [/mental|behavioral/i, 'mental_health'],
  [/substance/i, 'substance_use'],
  [/maternity|prenatal|delivery/i, 'maternity'],
  [/durable medical/i, 'durable_medical_equipment'],
  [/transplant/i, 'organ_transplant'],
  [/drug/i, 'prescription_drugs'],
];

function acaBenefitRow_(plan, key) {
  const list = (plan && plan.benefits) || [];
  for (const b of list) {
    const hit = ACA_BENEFIT_MAP.find(([re]) => re.test(String(b.name || '')));
    if (hit && hit[1] === key) {
      if (b.covered === false) return '<span style="color:var(--text-warning);">Not covered</span>';
      return escWeb(b.cost || 'Covered');
    }
  }
  return null;
}

// The Marketplace plans on this quote, whichever way they were added.
function ppAcaOnQuote_() {
  const out = [];
  for (let i = 0; i < QB_MAX_OPTIONS; i++) {
    // A leftover selection is not a plan on the quote. The slot has to be
    // filled AND still be a Marketplace option, or the agent is offered a
    // comparison against something they already took off.
    if (typeof qbOptionFilled_ === 'function' && !qbOptionFilled_(i)) continue;
    const optLine = (document.getElementById('qb-optline-' + i) || {}).value || '';
    if (optLine && optLine !== 'Health — Individual') continue;

    const live = (window._qbAcaSel || {})[i];
    const saved = ((window._qbRequoteOpt || {})[i] || {}).plan_meta;
    const p = live || (saved && saved.src === 'aca' ? saved : null);
    if (!p) continue;
    const nm = (document.getElementById('qb-name-' + i) || {}).value;
    out.push({ slot: i, label: 'Option ' + qbOptionNo_(i) + ' \u00b7 ' + (nm || p.name || 'Marketplace plan'), plan: p });
  }
  return out;
}

// What a Marketplace plan must do that a short-term plan need not. These are
// the rows that explain the price gap, so they are never behind a toggle.
const PP_STRUCTURAL = [
  ['Pre-existing conditions', 'Not covered', 'Covered'],
  ['Can you be turned down for health?', 'Yes', 'No'],
  ['The ten essential health benefits', 'Not required', 'All of them, required'],
  ['A yearly limit on what you pay', 'May be none', 'Required'],
  ['Premium tax credit', 'Never', 'Often, depending on income'],
  ['Renewable', 'No \u2014 and ending it is not a qualifying life event', 'Yes, every year'],
];

function ppVsAca_(prodId) {
  const pp = ppState_();
  const p = (pp.products || []).find(x => x.id === prodId);
  const acaList = ppAcaOnQuote_();
  if (!p) return;
  if (!acaList.length) { showToast('No Marketplace plan on this quote to compare against.'); return; }
  pp.vsAca = pp.vsAca || acaList[0].slot;
  const pick = acaList.find(a => a.slot === pp.vsAca) || acaList[0];
  const a = pick.plan;
  pp.vsProd = prodId;

  const TH = 'text-align:left;font-size:12px;font-weight:700;color:var(--text-muted);padding:9px 12px;border-bottom:1px solid var(--border);vertical-align:top;min-width:200px;';
  const TD = 'padding:9px 12px;border-bottom:1px solid var(--border);font-size:12.5px;vertical-align:top;min-width:200px;line-height:1.55;';
  const dash = '<span style="color:var(--text-muted);">\u2014</span>';
  const money = v => (v == null || v === '') ? dash : ('$' + Number(v).toLocaleString('en-US'));

  const benefitRows = PP_BENEFITS.filter(([k]) => ppBenefitCell_(p, k) || acaBenefitRow_(a, k))
    .map(([k, label]) => `<tr><th style="${TH}">${escWeb(label)}</th>
      <td style="${TD}">${ppBenefitCell_(p, k) || dash}</td>
      <td style="${TD}">${acaBenefitRow_(a, k) || dash}</td></tr>`).join('');

  ppOverlay_('qb-pp-vsaca', '\u2696\ufe0f ' + escWeb(p.name) + ' against a Marketplace plan', `
    <div style="max-width:900px;">
      <label style="font-size:11px;margin:0 0 4px;">Compare against</label>
      <select onchange="ppState_().vsAca = Number(this.value); ppVsAca_('${escWeb(prodId)}')" style="width:auto;min-width:260px;">
        ${acaList.map(x => `<option value="${x.slot}"${x.slot === pick.slot ? ' selected' : ''}>${escWeb(x.label)}</option>`).join('')}
      </select>

      <div class="pk-bar warn" style="border-radius:9px;border:1px solid;margin:12px 0;">
        These are different kinds of coverage, not two versions of the same one. The rows below the line
        are what a Marketplace plan must do and a short-term plan need not \u2014 they are most of the reason
        for any difference in price.
      </div>

      <table style="border-collapse:collapse;width:100%;">
        <thead><tr><th style="${TH}"></th>
          <td style="${TD}font-weight:800;">${escWeb(p.name)}<div style="font-size:11px;color:var(--text-muted);font-weight:400;">short-term medical</div></td>
          <td style="${TD}font-weight:800;">${escWeb(a.name || 'Marketplace plan')}<div style="font-size:11px;color:var(--text-muted);font-weight:400;">${escWeb(a.metal || 'ACA')}${a.issuer ? ' \u00b7 ' + escWeb(a.issuer) : ''}</div></td>
        </tr></thead>
        <tbody>
          ${PP_STRUCTURAL.map(([label, stm, aca]) => `<tr>
            <th style="${TH}">${escWeb(label)}</th>
            <td style="${TD}color:var(--text-warning);">${escWeb(stm)}</td>
            <td style="${TD}color:var(--text-success);">${escWeb(aca)}</td></tr>`).join('')}

          <tr><th style="${TH}border-top:2px solid var(--border);">Monthly premium</th>
            <td style="${TD}border-top:2px solid var(--border);font-weight:800;font-size:15px;">${
              pp.prem[p.id] != null ? '$' + Number(pp.prem[p.id]).toFixed(2)
                : '<span style="font-size:12px;font-weight:400;color:var(--text-muted);">not quoted yet</span>'}</td>
            <td style="${TD}border-top:2px solid var(--border);font-weight:800;font-size:15px;">${
              a.net != null ? '$' + Number(a.net).toFixed(2)
                : (a.premium != null ? '$' + Number(a.premium).toFixed(2) : dash)}${
              a.net != null && a.premium != null && Number(a.premium) > Number(a.net)
                ? `<div style="font-size:11px;font-weight:400;color:var(--text-muted);">full $${Number(a.premium).toFixed(0)}, less the tax credit</div>` : ''}</td></tr>
          <tr><th style="${TH}">Deductible</th>
            <td style="${TD}border-top:2px solid var(--border);">${ppDeductibleSaid_(p)}</td>
            <td style="${TD}border-top:2px solid var(--border);">${money(a.deductible)}</td></tr>
          <tr><th style="${TH}">Yearly out-of-pocket limit</th>
            <td style="${TD}"><span style="color:var(--text-warning);">No true limit</span>
              <div style="font-size:11px;color:var(--text-muted);">coinsurance is capped; deductible, copays and anything excluded are on top</div></td>
            <td style="${TD}">${money(a.moop)}<div style="font-size:11px;color:var(--text-muted);">a real ceiling on covered care</div></td></tr>
          ${benefitRows}
        </tbody>
      </table>
      <div style="font-size:11.5px;color:var(--text-muted);margin-top:12px;line-height:1.55;">
        Marketplace figures come from the plan as quoted. Short-term figures come from the carrier's brochure.
        The issued policy governs in both cases.
      </div>
    </div>`);
}

// The deductible on a short-term plan depends on which combination is chosen,
// so say the chosen one, or the range when nothing is chosen yet.
function ppDeductibleSaid_(p) {
  const dims = ppDims_(p);
  for (const [k, d] of Object.entries(dims)) {
    if (!ppCombos_(d)) continue;
    const chosen = (ppChoice_(p)[k] || {});
    const dedPart = ppParts_(d).find(pt => /deduct/i.test(pt));
    if (!dedPart) continue;
    if (chosen[dedPart]) return escWeb(String(chosen[dedPart]));
    const all = [...new Set((ppCombos_(d) || []).map(c => String(c[dedPart])))];
    return escWeb(all.join(' / ')) + '<div style="font-size:11px;color:var(--text-muted);">choose one on the card</div>';
  }
  return '<span style="color:var(--text-muted);">\u2014</span>';
}

function renderProductPicker_() {
  const el = document.getElementById('qb-pp-picker');
  if (!el) return;
  const pp = ppState_();
  const list = pp.products || [];
  const prof = ppProfile_();
  const chosen = [];
  for (let i = 0; i < QB_MAX_OPTIONS; i++) {
    const p = (list).find(x => x.id === pp.sel[i]);
    if (p) chosen.push({ slot: i, p: p });
  }
  const withRates = list.filter(p => ppRate_(p).kind === 'chart').length;

  el.innerHTML = `
    <div style="padding:12px 18px;border-bottom:1px solid var(--border);display:flex;align-items:center;gap:12px;flex-wrap:wrap;">
      <div style="font-weight:800;font-size:15px;">📋 ${escWeb(pp.line || 'Products')}${prof.state ? ' · ' + escWeb(prof.state) : ''}</div>
      <div style="font-size:12px;color:var(--text-muted);">${list.length} product${list.length === 1 ? '' : 's'}${
        (pp.offices || []).length ? ' through ' + escWeb(pp.offices.join(' and ')) : ''}${
        prof.state ? ' filed in ' + escWeb(prof.state) : ''}${
        pp.hidden ? ' · ' + pp.hidden + ' not filed here' : ''}${
        withRates ? ' · ' + withRates + ' with rates on file' : ' · none with rates on file'}</div>
      ${pp.cmp.size ? `<button class="btn ${pp.cmp.size >= 2 ? 'btn-primary' : 'btn-outline'} btn-sm" style="margin-left:auto;"
        ${pp.cmp.size >= 2 ? '' : 'disabled'} onclick="openProductCompare_()">⚖️ Compare (${pp.cmp.size})</button>` : ''}
      <button class="btn btn-outline btn-sm" ${pp.cmp.size ? '' : 'style="margin-left:auto;"'} onclick="closeProductPicker_()">✕ Done</button>
    </div>

    ${ppAgentBar_(prof)}
    ${ppBasisHtml_()}

    <div style="flex:1;overflow:auto;padding:14px 18px;">
      ${list.length
        ? `<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(330px,1fr));gap:12px;align-items:stretch;">${list.map(ppCardHtml_).join('')}</div>`
        : `<div style="font-size:13px;color:var(--text-muted);line-height:1.6;">
             ${pp.hidden
               ? 'None of the ' + pp.hidden + ' ' + escWeb(pp.line || '') + ' product' + (pp.hidden === 1 ? ' is' : 's are')
                 + ' filed in <strong>' + escWeb(prof.state) + '</strong>. Carriers file a separate version of a plan in '
                 + 'each state, so the one you are thinking of may exist under the same name for somewhere else.<br>'
                 + 'Upload that state’s brochure from <strong>Admin → Carriers → Add products from a brochure</strong>.'
               : 'No ' + escWeb(pp.line || '') + ' products on file for the carriers you are appointed with.<br>'
                 + 'Add them from <strong>Admin → Carriers → Add products from a brochure</strong>.'}</div>`}
    </div>

    ${chosen.length ? `<div class="pk-tray" style="padding:10px 20px;display:flex;gap:10px;align-items:center;flex-wrap:wrap;">
      <span class="pk-tray-label">On the quote · ${chosen.length}</span>
      ${chosen.map(x => `<div class="pk-tray-item">
        <span class="num">${qbOptionNo_(x.slot)}</span>
        <span class="who">
          <span class="carrier">${escWeb(((window._qbCarriers || []).find(c => c.id === x.p.carrier_id) || {}).name || '')}</span>
          <span class="pname">${escWeb(x.p.name)}</span>
        </span>
        ${pp.prem[x.p.id] != null ? `<span class="price">$${Number(pp.prem[x.p.id]).toFixed(2)}</span>` : ''}
        <button class="rm" onclick="ppAdd_('${escWeb(x.p.id)}')" title="Take off the quote">✕</button>
      </div>`).join('')}
      <button class="btn btn-primary btn-sm" style="margin-left:auto;" onclick="closeProductPicker_()">Done — back to the quote</button>
    </div>` : ''}`;
}

// Licensed states have been written both as an array and as a loose string
// over the life of this system, so read either and hand back a clean set.
function agentStates_(agent) {
  const raw = (agent || {}).licensed_states;
  const parts = Array.isArray(raw) ? raw : String(raw || '').split(/[^A-Za-z]+/);
  return new Set(parts.map(x => String(x).trim().toUpperCase()).filter(x => x.length === 2));
}

// Can this agent sell this product to someone in this state? Three separate
// questions, and they fail differently:
//   - the product is not filed there    -> nobody can sell it, full stop
//   - the agent is not licensed there   -> they may quote it, not write it
//   - the appointment misses that state -> same, and usually a quick fix
//
// It warns, it never blocks. An agent seeing everything and being told what
// they cannot yet write beats a list that quietly hides options from them.
function productFit_(product, state, carrierId) {
  const out = { ok: true, filed: true, warnings: [] };
  const st = String(state || '').toUpperCase();
  if (!st || !/^[A-Z]{2}$/.test(st)) return out;      // no state known, nothing to judge

  const filed = (product && product.states) || [];
  if (filed.length && !filed.map(x => String(x).toUpperCase()).includes(st)) {
    out.ok = false; out.filed = false;
    out.warnings.push({ tone: 'warn', text: '<strong>' + escWeb(product.name || 'This product')
      + '</strong> is not filed in <strong>' + escWeb(st) + '</strong>' + (filed.length <= 8
        ? ' — only ' + filed.map(x => escWeb(String(x).toUpperCase())).join(', ') : '') + '.' });
  }

  const me = (window.allAgents || []).find(a => a.id === (window.currentAgent || {}).id) || window.currentAgent || {};
  if (!agentStates_(me).has(st)) {
    out.ok = false;
    out.warnings.push({ tone: 'warn', scope: 'agent', text: 'You are not showing a license in <strong>' + escWeb(st)
      + '</strong>. You can quote this, but you cannot write it until that is in place.' });
  }

  const appt = (window._qbAppts || []).find(a => a.carrier_id === carrierId);
  if (appt && (appt.states || []).length && !appt.states.map(x => String(x).toUpperCase()).includes(st)) {
    out.ok = false;
    out.warnings.push({ tone: 'warn', text: 'Your appointment with this carrier does not cover <strong>'
      + escWeb(st) + '</strong> yet.' });
  }
  return out;
}

// The uploaded documents stay in object storage, not in the database, so
// keeping every brochure costs the database nothing. A link is minted on
// demand and expires, rather than the file being made public.
//
// Documents a carrier stamped "not for consumer use" are never shareable. The
// storage rules enforce that too; this is the polite half.
async function productDocLink_(productId, opts) {
  const days = (opts && opts.days) || 7;
  const prod = (window._qbProds || []).concat((ppState_().products || []))
    .find(x => x.id === productId) || {};
  const { data: docs } = await supabaseClient.from('product_documents')
    .select('id,storage_path,filename,internal_use_only,kind,product_id,carrier_id')
    .or('product_id.eq.' + productId + (prod.carrier_id ? ',carrier_id.eq.' + prod.carrier_id : ''))
    .order('created_at', { ascending: false });
  const usable = (docs || []).filter(d => !d.internal_use_only);
  // the one stamped for this product wins; otherwise the carrier's brochure
  const share = usable.find(d => d.product_id === productId) || usable[0];
  if (!share) return null;
  const { data, error } = await supabaseClient.storage.from('product-docs')
    .createSignedUrl(share.storage_path, days * 86400);
  if (error || !data) return null;
  return { url: data.signedUrl, filename: share.filename, days: days };
}

async function productDocOpen_(productId) {
  const hit = await productDocLink_(productId);
  if (!hit) { showToast('No client-safe brochure on file for this product.'); return; }
  window.open(hit.url, '_blank', 'noopener');
}

async function productDocCopy_(productId) {
  const hit = await productDocLink_(productId);
  if (!hit) { showToast('No client-safe brochure on file for this product.'); return; }
  try {
    await navigator.clipboard.writeText(hit.url);
    showToast('Link copied \u2014 good for ' + hit.days + ' days.');
  } catch (e) { window.prompt('Copy this link (good for ' + hit.days + ' days):', hit.url); }
}

// Where this agent goes to quote this carrier. Their own link first, then the
// product's page, then the carrier's general broker portal.
function carrierQuotingUrl_(carrierId, productId) {
  const appt = (window._qbAppts || []).find(a => a.carrier_id === carrierId && a.is_active !== false);
  if (appt && appt.quoting_url) return { url: appt.quoting_url, whose: 'your page' };
  const prod = (window._qbProds || []).find(p => p.id === productId);
  if (prod && prod.quoting_url) return { url: prod.quoting_url, whose: 'the product page' };
  const car = (window._qbCarriers || []).find(c => c.id === carrierId);
  if (car && car.broker_portal_url) return { url: car.broker_portal_url, whose: 'the broker portal' };
  return null;
}

// For carriers whose rates we cannot hold — no sheet, no feed, quoted on their
// own site. Taking the agent there in one click is the honest answer; it beats
// pretending we can price it.
function carrierQuotingBtn_(carrierId, productId, label) {
  const hit = carrierQuotingUrl_(carrierId, productId);
  if (!hit) return '';
  return `<a href="${escWeb(hit.url)}" target="_blank" rel="noopener noreferrer"
      class="btn btn-outline btn-sm" style="text-decoration:none;"
      title="Opens ${escWeb(hit.whose)} in a new tab">↗ ${escWeb(label || 'Quote at the carrier')}</a>`;
}

// Shows the way out to the carrier's own site once a carrier is chosen. For
// short-term medical and most supplemental products this is how a real premium
// is actually obtained — there is no sheet to hold and no feed to read.
function qbQuoteLinkPaint_(i) {
  const host = document.getElementById('qb-quotelink-' + i);
  if (!host) return;
  const carId = (document.getElementById('qb-car-' + i) || {}).value || null;
  const prodId = (document.getElementById('qb-prod-' + i) || {}).value || null;
  if (!carId) { host.innerHTML = ''; return; }
  const btn = carrierQuotingBtn_(carId, prodId, 'Quote this at the carrier');
  const line = btn
    ? btn + `<span style="font-size:11px;color:var(--text-muted);margin-left:8px;">then bring the premium back to this option</span>`
    : `<span style="font-size:11px;color:var(--text-muted);">No quoting page saved for this carrier — add yours in My Profile → My Carrier Appointments.</span>`;

  const prod = (window._qbProds || []).find(p => p.id === prodId);
  const st = (typeof _acaClientState_ === 'function') ? _acaClientState_() : '';
  const fit = prod ? productFit_(prod, st, carId) : { warnings: [] };
  // Who actually pays the claim is often not the name on the brochure, and
  // clients ask. Say it wherever the product is in play.
  const meta = (prod && prod.metadata) || {};
  const uw = meta.underwriter && meta.underwriter !== (prod && prod.name)
    ? `<div style="font-size:11px;color:var(--text-muted);margin-top:4px;">Underwritten by <strong>${escWeb(meta.underwriter)}</strong>${meta.policy_form ? ' · form ' + escWeb(meta.policy_form) : ''}</div>` : '';
  const broch = prodId
    ? ` <a href="#" onclick="event.preventDefault();productDocOpen_('${escWeb(prodId)}')" style="font-size:11px;color:var(--link);margin-left:8px;">\u{1F4C4} Brochure</a>`
      + ` <a href="#" onclick="event.preventDefault();productDocCopy_('${escWeb(prodId)}')" style="font-size:11px;color:var(--link);margin-left:6px;">copy link for the client</a>`
    : '';
  host.innerHTML = line + broch + uw + fit.warnings.map(w =>
    `<div class="pk-bar warn" style="border-radius:8px;border:1px solid;margin-top:5px;font-size:11.5px;">⚠️ ${w.text}</div>`).join('');
}

// ============================================================
// QUOTING ENGINE — Phase 1 (Quick Quote)
// Agent assembles 1-4 options -> client gets a branded page at
// quote.html?q=<uuid> -> "I'm interested" advances the follow-up.
// ============================================================
// A multi-line proposal spends these fast: three Medicare options and a Part D
// plan leave only six for anything else. The slots are pre-rendered and hidden
// until used, so the cost of more is a little markup, not speed.
const QB_MAX_OPTIONS = 20;
// Group health is deliberately absent \u2014 it gets its own quoting engine.
const QUOTE_LINE_GROUPS = [
  ['Major medical', [
    ['Health — Individual', 'ACA Marketplace'],
    ['Short-Term Medical', 'Short-Term Medical'],
    ['Private/Off-Market Medical', 'Private / off-market medical'],
    ['Health Share', 'Health share (not insurance)'],
  ]],
  ['Medicare', [
    ['Medicare Advantage', 'Medicare Advantage'],
    ['Medicare Supplement', 'Medicare Supplement'],
    ['Part D (PDP)', 'Part D (PDP)'],
  ]],
  ['Supplemental', [
    ['Hospital Indemnity', 'Hospital indemnity'],
    ['Accident', 'Accident / excess accident'],
    ['Cancer/Critical Illness', 'Cancer / critical illness'],
    ['Dental/Vision/Hearing', 'Dental / vision / hearing'],
  ]],
  ['Life and income', [
    ['Life', 'Life'],
    ['Disability', 'Disability'],
  ]],
  ['Other', [['Other', 'Other']]],
];

// Flat list, still in the order above \u2014 anything that just needs the values.
const QUOTE_LINES = QUOTE_LINE_GROUPS.flatMap(g => g[1].map(x => x[0]));

// Major medical that is not ACA cannot be quoted from the Marketplace and does
// not carry its protections. Named here so the dialog can say so.
const NON_ACA_MAJOR_MEDICAL = ['Short-Term Medical', 'Private/Off-Market Medical', 'Health Share'];
const MEDICARE_QUOTE_LINES = ['Medicare Advantage','Medicare Supplement','Part D (PDP)'];

async function requoteFromQuote_(quoteId, dealId) {
  const { data: q } = await supabaseClient.from('quotes').select('*').eq('id', quoteId).single();
  const { data: opts } = await supabaseClient.from('quote_options')
    .select('*').eq('quote_id', quoteId).order('sort_order');
  if (!q) { showToast('Could not load the previous quote.'); return; }
  await openQuoteBuilder(dealId);
  setTimeout(() => {
    const lineSel = document.getElementById('qb-line');
    if (!lineSel) return;
    if ([...lineSel.options].some(o => o.value === q.line)) { lineSel.value = q.line; qbLineChanged_(); }
    const brandSel = document.getElementById('qb-brand');
    if (!brandSel.disabled) brandSel.value = q.brand;
    (opts || []).forEach((o, i) => {
      if (i >= QB_MAX_OPTIONS) return;
      if (i > 0) qbRevealOption_();
      const car = (window._qbCarriers || []).find(c => c.name === o.carrier_name);
      if (car) {
        document.getElementById('qb-car-' + i).value = car.id;
        qbFillProducts_(i);
        // If the carrier still has this exact product, pick it — bullets refresh
        // from the product record and Medigap auto-rating fetches CURRENT premiums
        const prod = (window._qbProds || []).find(p => p.carrier_id === car.id && p.name === o.display_name);
        if (prod) {
          document.getElementById('qb-prod-' + i).value = prod.id;
          qbApplyProduct_(i);
        }
      }
      if (!document.getElementById('qb-name-' + i).value) document.getElementById('qb-name-' + i).value = o.display_name;
      if (!document.getElementById('qb-prem-' + i).value) document.getElementById('qb-prem-' + i).value = o.monthly_premium;
      const bul = document.getElementById('qb-bul-' + i);
      if (!bul.value) {
        const ro = bul.readOnly; bul.readOnly = false;
        bul.value = (o.benefit_bullets || []).join('\n');
        bul.readOnly = ro;
      }
      if (o.agent_note) document.getElementById('qb-note-' + i).value = o.agent_note;
      if (o.is_recommended) { const r = document.getElementById('qb-rec-' + i); if (r) r.checked = true; }
      // Keep the official plan snapshot (facts + document links) alive across the re-quote
      if (o.plan_meta) window._qbRequoteOpt[i] = { plan_meta: o.plan_meta, display_name: o.display_name };
      // ...and put the coverage type back on the option, so Save doesn't ask again
      const olSel = document.getElementById('qb-optline-' + i);
      if (olSel && o.line && [...olSel.options].some(x => x.value === o.line)) {
        olSel.value = o.line; qbOptLineChanged_(i);
      }
      if (o.plan_meta && o.plan_meta.src === 'aca') qbAcaHydrateOption_(i, o);
      if (o.plan_meta && o.plan_meta.src === 'cms') qbCmsHydrateOption_(i, o);
      if ((!o.plan_meta || o.plan_meta.src !== 'medigap')
          && (o.line === 'Medicare Supplement' || /medicare supplement/i.test(o.display_name || ''))) {
        const L = mgLetterFromName_(o.display_name);
        if (L) {
          const known = MEDIGAP_PLANS.find(x => x[0] === L);
          window._qbMgSel = window._qbMgSel || {};
          window._qbMgSel[i] = {
            letter: L, title: (known || [, 'Medicare Supplement Plan ' + L])[1],
            bullets: (known || [, , []])[2] || [],
            state: (window._qbContact || {}).state || null,
            rate: o.monthly_premium != null ? Number(o.monthly_premium) : null,
            carrier_name: o.carrier_name || null, product_id: o.product_id || null,
            rating_method: null, _snapshot: true, _recovered: true,
          };
          const ol = document.getElementById('qb-optline-' + i);
          if (ol && ol.value !== 'Medicare Supplement') { ol.value = 'Medicare Supplement'; qbOptLineChanged_(i); }
          qbMgOptionView_(i);
        }
      }
      if (o.plan_meta && o.plan_meta.src === 'medigap') {
        const m = o.plan_meta;
        window._qbMgSel = window._qbMgSel || {};
        window._qbMgSel[i] = {
          letter: m.letter, title: 'Medicare Supplement Plan ' + m.letter,
          bullets: (MEDIGAP_PLANS.find(x => x[0] === m.letter) || [, , []])[2] || [],
          state: m.state, rate: m.premium != null ? m.premium : o.monthly_premium,
          carrier_name: m.carrier_name || o.carrier_name, product_id: m.product_id,
          rating_method: m.rating_method, _snapshot: true,
        };
        qbMgOptionView_(i);
      }
    });
    showToast('Pre-filled from the previous quote — check the premiums, then save & send.');
    qbAcaCoverSelected_();
    qbOptAutoFold_();
    qbGroupOptions_();
  }, 350);
}

// The agent shouldn't have to mentally join two lists. One tree: the intake
// they filled out, and underneath it the quotes that came from it.
async function loadDealTree_(deal) {
  const el = document.getElementById('deal-tree-' + deal.id);
  if (!el) return;
  const canQuote = !deal.pipeline || !deal.pipeline.startsWith('agent-');
  let sess = [], qs = [];
  try {
    const [a, b] = await Promise.all([
      deal.contact_id
        ? supabaseClient.from('intake_sessions').select('id,form_type,status,created_at')
            .eq('contact_id', deal.contact_id).order('created_at', { ascending: false }).limit(6)
        : Promise.resolve({ data: [] }),
      supabaseClient.from('quotes')
        .select('id,line,lines,status,created_at,client_email,intake_session_id')
        .eq('deal_id', deal.id).order('created_at', { ascending: false }),
    ]);
    sess = a.data || []; qs = b.data || [];
  } catch (e) { el.textContent = 'Could not load intakes and quotes.'; return; }

  const fmt = d => new Date(d).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
  const quoteLine = q => {
    let badge;
    if (q.status === 'interested') badge = '<span style="color:var(--text-success);font-weight:700;">\u2b50 INTERESTED \u2014 follow up!</span>';
    else if (q.status === 'viewed') badge = '<span style="color:#3b82f6;font-weight:600;">Viewed</span>';
    else if (q.status === 'sent') badge = 'Sent';
    else badge = '<span style="color:var(--text-warning);">Draft</span>';
    const send = (q.status === 'draft' && q.client_email)
      ? ` &middot; <a href="#" onclick="sendQuote_('${q.id}', this); return false;">Send now</a>` : '';
    const lines = Array.isArray(q.lines) && q.lines.length ? q.lines : [q.line];
    const label = lines.length > 1
      ? '\u{1F4E6} ' + lines.length + '-part proposal: ' + escWeb(lines.join(' + '))
      : '\u{1F4BC} ' + escWeb(lines[0] || q.line);
    return `<div style="padding:2px 0;font-size:12px;">${label} &middot; ${fmt(q.created_at)} &middot; ${badge}
      &middot; <a href="quote.html?q=${q.id}" target="_blank">view &#8599;</a>${send}
      &middot; <a href="#" onclick="requoteFromQuote_('${q.id}','${deal.id}'); return false;" title="Start a fresh quote pre-filled from this one">&#8635; re-quote</a></div>`;
  };

  const used = new Set();
  const branches = sess.map(x => {
    const kids = qs.filter(q => q.intake_session_id === x.id);
    kids.forEach(q => used.add(q.id));
    const lbl = INTAKE_TYPE_LABELS[x.form_type] || x.form_type;
    const done = x.status === 'completed';
    const badge = done
      ? '<span style="color:var(--text-success);font-weight:600;">completed</span>'
      : '<span style="color:var(--text-warning);">pending</span>';
    return `<div style="margin-bottom:8px;">
      <div style="display:flex;align-items:center;gap:6px;flex-wrap:wrap;font-size:12.5px;">
        <span>\u{1F91D} <strong>${escWeb(lbl)}</strong></span>
        <span style="color:var(--text-muted);">${fmt(x.created_at)} &middot; ${badge}</span>
        ${done ? `<a href="#" onclick="viewIntakeSession('${x.id}'); return false;">view</a>` : ''}
        <a href="#" style="color:var(--text-danger);" title="Delete this intake"
           onclick="deleteIntakeSession('${x.id}','${x.form_type}','${x.status}','${deal.contact_id}'); return false;">&#128465;</a>
        ${(canQuote && kids.length) ? `<button type="button" class="btn btn-outline btn-sm" style="margin-left:auto;font-size:11px;padding:2px 9px;"
            onclick="openQuoteBuilder('${deal.id}', { intakeSessionId: '${x.id}' })">\uff0b New Quote</button>` : ''}
      </div>
      <div style="margin-left:14px;padding-left:10px;border-left:2px solid var(--border-selected);margin-top:3px;">
        ${kids.length ? kids.map(quoteLine).join('')
          : `<div style="font-size:11.5px;color:var(--text-muted);padding:2px 0;">no quotes from this intake yet${canQuote ? ` &middot; <a href="#" onclick="openQuoteBuilder('${deal.id}', { intakeSessionId: '${x.id}' }); return false;">create one</a>` : ''}</div>`}
      </div>
    </div>`;
  }).join('');

  const orphans = qs.filter(q => !used.has(q.id));
  const orphanBlock = orphans.length ? `
    <div style="margin-top:${sess.length ? '10' : '0'}px;">
      ${sess.length ? '<div style="font-size:10.5px;font-weight:800;text-transform:uppercase;letter-spacing:.5px;color:var(--text-muted);margin-bottom:3px;">Quotes not tied to an intake</div>' : ''}
      ${orphans.map(quoteLine).join('')}
    </div>` : '';

  el.innerHTML = (branches || orphanBlock)
    ? branches + orphanBlock
    : '<div style="font-size:12px;color:var(--text-muted);">Nothing yet \u2014 start an intake, then quote from it.</div>';
}



// Pick the right Line of Business before the agent even looks:
// pipeline decides the family, the client's intake refines it.
async function qbSmartDefaultLine_(deal, contact) {
  try {
    if (deal.pipeline === 'medicare') {
      const { data: sess } = await supabaseClient.from('intake_sessions')
        .select('form_type,responses').eq('contact_id', contact.id)
        .eq('status', 'completed').order('created_at', { ascending: false }).limit(5);
      const med = (sess || []).find(x => x.form_type === 'medicare');
      const r = (med && med.responses) || {};
      if (r.mi_advantage) return 'Medicare Advantage';
      if (r.mi_supplement) return 'Medicare Supplement';
      if (r.mi_pdp) return 'Part D (PDP)';
      if (r.mi_dental) return 'Dental/Vision/Hearing';
      return 'Medicare Supplement'; // the confident Medicare fallback
    }
    if (deal.pipeline === 'group-employer') return 'Health — Group';
    if (deal.pipeline === 'individual-family') {
      const { data: sess } = await supabaseClient.from('intake_sessions')
        .select('form_type').eq('contact_id', contact.id)
        .eq('status', 'completed').order('created_at', { ascending: false }).limit(5);
      const types = (sess || []).map(x => x.form_type);
      if (types.includes('financial')) return 'Life';
      if (types.includes('health-individual')) return 'Health — Individual';
      if (contact.sequence_track === 'medicare') return 'Medicare Supplement';
      return 'Health — Individual'; // the confident I&F fallback
    }
  } catch (e) { console.error('qbSmartDefaultLine_:', e); }
  return 'Life';
}

async function openQuoteBuilder(dealId, opts) {
  opts = opts || {};
  const deal = deals.find(d => d.id === dealId); if (!deal) return;
  const contact = contacts.find(c => c.id === deal.contact_id);
  if (!contact) { showToast('No contact linked to this deal.'); return; }

  // Carriers the agent can quote: their active appointments; owners fall back to full master
  const { data: master } = await supabaseClient.from('carriers').select('*').eq('is_active', true).order('name');
  const { data: myAppts } = await supabaseClient.from('carrier_appointments')
    .select('carrier_id,quoting_url,is_active').eq('agent_id', currentAgent.id).eq('is_active', true);
  window._qbAppts = myAppts || [];        // the pickers read their quoting links from here
  const apptIds = new Set((myAppts || []).map(a => a.carrier_id));
  const isOwner = activeRole() === 'system_owner' || activeRole() === 'broker_owner';
  let myCarriers = (master || []).filter(c => apptIds.has(c.id));
  if (!myCarriers.length && isOwner) myCarriers = master || [];
  if (!myCarriers.length) {
    showToast('Set up your carrier appointments first (My Profile \u2192 My Carrier Appointments).');
    return;
  }
  const { data: prods } = await supabaseClient.from('carrier_products')
    .select('*').eq('is_active', true).is('discontinued_on', null)
    .in('carrier_id', myCarriers.map(c => c.id));
  window._qbCarriers = myCarriers;
  window._qbProds = prods || [];
  window._qbContact = contact;
  window._qbRequoteOpt = {};
  window._qbAcaSel = {};        // nothing from the last quote leaks into this one
  window._qbCmsSel = {};
  window._qbMgSel = {};
  window._qbMgCmp = new Set();
  window._qbMgQuotes = {};
  window._qbMgRates = {};
  window._qbAutoOpen = false;   // automation group starts collapsed
  window._qbCovGrpOpen = {};    // ...and so does each card's coverage detail
  // Phase 2: the quote is tied to an intake, and the agent can see/change which
  window._qbIntakeSessionId = opts.intakeSessionId || null;
  window._qbIntakeChoices = [];
  try {
    const { data: _si } = await supabaseClient.from('intake_sessions')
      .select('id,form_type,status,created_at').eq('contact_id', contact.id)
      .order('created_at', { ascending: false }).limit(8);
    window._qbIntakeChoices = _si || [];
    // default: what the caller asked for, else the newest completed one
    if (!window._qbIntakeSessionId) {
      const done = (_si || []).find(x => x.status === 'completed');
      if (done) window._qbIntakeSessionId = done.id;
    }
  } catch (e) { /* a quote without an intake is still perfectly valid */ }
  // Agency-level carrier list (owners' active appointments) — powers the ACA appointment warning
  window._qbAgencyCarrierNames = [];
  try {
    const { data: owners } = await supabaseClient.from('agents').select('id')
      .eq('agency_id', currentAgent.agency_id).in('role', ['broker_owner', 'system_owner']);
    const oIds = (owners || []).map(a => a.id);
    if (oIds.length) {
      const { data: agAppts } = await supabaseClient.from('carrier_appointments')
        .select('carrier_id').in('agent_id', oIds).eq('is_active', true);
      const agIds = new Set((agAppts || []).map(a => a.carrier_id));
      window._qbAgencyCarrierNames = (master || []).filter(c => agIds.has(c.id)).map(c => c.name);
    }
  } catch (e) {}

  const carOpts = '<option value="">— pick carrier —</option>'
    + myCarriers.map(c => `<option value="${c.id}">${escWeb(c.name)}</option>`).join('');
  const lineOpts = QUOTE_LINE_GROUPS.map(([group, items]) =>
    `<optgroup label="${escWeb(group)}">`
    + items.map(([value, label]) => `<option value="${escWeb(value)}">${escWeb(label)}</option>`).join('')
    + '</optgroup>').join('');
  const _forIntake = (window._qbIntakeChoices || []).find(x => x.id === window._qbIntakeSessionId);
  const intakeNote = _forIntake
    ? '\u{1F91D} Filed under their <strong>' + escWeb(INTAKE_TYPE_LABELS[_forIntake.form_type] || _forIntake.form_type)
      + '</strong> intake from ' + new Date(_forIntake.created_at).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
    : '\u{1F91D} Not tied to an intake \u2014 it will show under \u201cQuotes not tied to an intake\u201d.';
  const defValid = new Date(Date.now() + 30 * 86400000).toISOString().slice(0, 10);
  const optBlock = i => `
    <div id="qb-opt-wrap-${i}" style="border:1px solid var(--border);border-radius:12px;padding:14px 16px;margin-top:14px;${i > 0 ? 'display:none;' : ''}">
      <div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;cursor:pointer;" onclick="qbOptToggle_(${i})" title="Show or hide this option">
        <span id="qb-opt-chev-${i}" style="font-size:11px;color:var(--text-muted);width:10px;">&#9662;</span>
        <span id="qb-opt-no-${i}" style="display:inline-flex;align-items:center;justify-content:center;width:22px;height:22px;border-radius:50%;background:var(--accent,#1d3557);color:#fff;font-size:11px;font-weight:800;flex-shrink:0;">${i + 1}</span>
        <span id="qb-opt-label-${i}" style="font-weight:700;font-size:12px;color:var(--text-muted);text-transform:uppercase;letter-spacing:.5px;flex-shrink:0;">Option ${i + 1}</span>
        <span id="qb-opt-sum-${i}" style="flex:1;min-width:0;font-size:12.5px;color:var(--text-secondary);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;"></span>
        ${i > 0 ? `<button type="button" onclick="event.stopPropagation();qbHideOption_(${i})" style="background:none;border:none;color:var(--text-muted);cursor:pointer;font-size:13px;flex-shrink:0;" title="Remove this option">&#10005;</button>` : ''}
      </div>
      <div id="qb-opt-body-${i}">
      <label>Coverage type *</label>
      <select id="qb-optline-${i}" onchange="qbOptLineChanged_(${i})">
        <option value="">&mdash; choose coverage type &mdash;</option>${lineOpts}</select>
      <div id="qb-optline-hint-${i}" style="display:none;font-size:11px;color:var(--text-danger);margin-top:3px;">
        &#9888;&#65039; Required &mdash; what is this option quoting?</div>
      <div id="qb-optwarn-${i}" style="display:none;font-size:11px;color:var(--text-warning);background:var(--bg-warning);border:1px solid var(--border-warning);border-radius:7px;padding:6px 9px;margin-top:4px;line-height:1.5;"></div>
      <div id="qb-cms-wrap-${i}" style="display:none;">
        <label id="qb-cms-label-${i}">Medicare Advantage plan</label>
        <select id="qb-cms-${i}" onchange="qbApplyCmsPlan_(${i})"><option value="">&mdash; pick a plan &mdash;</option></select>
      </div>
      <div id="qb-aca-wrap-${i}" style="display:none;">
        <label>Official Marketplace plan</label>
        <select id="qb-aca-${i}" onchange="qbApplyAcaPlan_(${i})"><option value="">&mdash; get plans above first &mdash;</option></select>
      </div>
      <div id="qb-aca-warn-${i}" style="display:none;font-size:11.5px;line-height:1.5;border-radius:8px;padding:8px 10px;margin:6px 0;"></div>
      <div id="qb-carprod-${i}">
        <label>Carrier <span id="qb-car-opt-${i}" style="display:none;font-size:10px;color:var(--text-muted);">(optional when an official plan is picked)</span></label>
        <select id="qb-car-${i}" onchange="qbFillProducts_(${i});qbMgCarrierPicked_(${i});qbQuoteLinkPaint_(${i});">${carOpts}</select>
        <label>Product (from carrier's catalog — optional)</label>
        <select id="qb-prod-${i}" onchange="qbApplyProduct_(${i});qbQuoteLinkPaint_(${i});"><option value="">— none / type manually —</option></select>
        <div id="qb-quotelink-${i}" style="margin-top:6px;"></div>
      </div>
      <div id="qb-aca-card-${i}" style="display:none;"></div>
      <div id="qb-cms-card-${i}" style="display:none;"></div>
      <div id="qb-mg-card-${i}" style="display:none;"></div>
      <div id="qb-manual-${i}">
        <label>Plan name shown to client *</label><input type="text" id="qb-name-${i}" placeholder="e.g. Medicare Supplement Plan G" />
        <label>Monthly premium ($) *</label><input type="number" step="0.01" id="qb-prem-${i}" placeholder="e.g. 128.50" />
        <label>Benefit bullets (one per line)</label><textarea id="qb-bul-${i}" rows="3"></textarea>
      </div>
      <label>Short note to client (optional)</label><input type="text" id="qb-note-${i}" placeholder="e.g. Best value if you travel often" />
      <label style="display:flex;gap:8px;align-items:center;margin-top:8px;font-weight:400;"><input type="radio" name="qb-rec" id="qb-rec-${i}" style="width:auto;" /> Mark as my recommendation</label>
      </div>
    </div>`;

  showModal('Create Quote — ' + escWeb(contact.name || ''), `
    <select id="qb-line" onchange="qbLineChanged_()" style="display:none;">${lineOpts}</select>
    <div style="display:flex;gap:14px;flex-wrap:wrap;align-items:flex-end;">
      <div><label style="margin-top:0;">Brand on the client's page</label>
        <select id="qb-brand" style="width:auto;min-width:150px;">
          <option value="ia" selected>Insured America</option>
          <option value="kfg">Kannon Financial</option>
        </select></div>
      <div><label style="margin-top:0;">This Quote is Valid Until:</label>
        <input type="date" id="qb-valid" value="${defValid}" style="width:auto;" /></div>
    </div>
    <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:6px;">
      <div id="qb-intake-note" style="font-size:11.5px;color:var(--text-muted);">${intakeNote}</div>
      <button type="button" class="btn btn-outline btn-sm" style="font-size:11px;padding:2px 9px;"
        onclick="qbToggleIntakeDrawer_()">\u{1F4C4} Their answers</button>
    </div>
    <div id="qb-sections" style="font-size:11.5px;margin-top:4px;line-height:1.5;"></div>
    <div id="qb-auto-card" style="display:none;"></div>
    <div id="qb-strip-holder" style="display:none;"></div>
    <div id="qb-med-note" style="display:none;font-size:11px;color:#f59e0b;margin-top:4px;">Medicare line: benefit bullets are locked to the owner-curated product text (compliance). Pick a product for each option.</div>
    <div id="qb-pp-strip" style="display:none;"></div>
    <div id="qb-aca-strip" style="display:none;background:var(--surface-1);border:0.5px solid var(--border);border-radius:8px;padding:10px 12px;margin-top:10px;">
      <div style="font-size:11px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:.5px;margin-bottom:6px;">&#127963;&#65039; ACA Marketplace — household &amp; subsidy</div>
      <div style="display:flex;gap:12px;flex-wrap:wrap;align-items:flex-end;font-size:13px;">
        <div><label style="font-size:10px;margin:0 0 2px;">Yearly household income ($)</label>
          <input type="number" id="qb-aca-income" placeholder="e.g. 48000" style="width:120px;"
            oninput="window._qbAcaIncomeDirty = true;" /></div>
        <div><label style="font-size:10px;margin:0 0 2px;">ZIP code</label>
          <input type="text" id="qb-aca-zip" maxlength="5" placeholder="59718" style="width:90px;"
            onchange="qbAcaZipChanged_()" /></div>
        <div><label style="font-size:10px;margin:0 0 2px;">County</label>
          <select id="qb-aca-county" style="width:auto;"></select></div>
      </div>
      <div id="qb-aca-members" style="margin-top:8px;"></div>
      <button type="button" class="btn btn-outline btn-sm" style="margin-top:6px;" onclick="qbAcaAddMember_()">+ Add household member</button>
      <div style="display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-top:8px;font-size:13px;">
        <span>Employer ICHRA / HRA offer?
          <select id="qb-aca-ichra" style="width:auto;display:inline-block;">
            <option value="">No / unknown</option><option value="yes">Yes</option>
          </select></span>
        <span id="qb-aca-ichra-amt-wrap" style="display:none;">$<input type="number" id="qb-aca-ichra-amt" placeholder="mo. amount" style="width:90px;" />/mo</span>
      </div>
      <div style="display:flex;gap:12px;flex-wrap:wrap;align-items:flex-end;margin-top:10px;font-size:13px;">
        <div><label style="font-size:10px;margin:0 0 2px;">Coverage should start</label>
          <input type="date" id="qb-aca-start" style="width:auto;" onchange="qbAcaTimingChanged_()" /></div>
        <div><label style="font-size:10px;margin:0 0 2px;">Qualifying life event</label>
          <select id="qb-aca-qle" style="width:auto;max-width:230px;" onchange="qbAcaTimingChanged_()">${ACA_QLE_OPTIONS.map(o => `<option value="${escWeb(o)}">${escWeb(o)}</option>`).join('')}</select></div>
        <div id="qb-aca-qled-wrap"><label style="font-size:10px;margin:0 0 2px;">Date of that event</label>
          <input type="date" id="qb-aca-qle-date" style="width:auto;" onchange="qbAcaTimingChanged_()" /></div>
      </div>
      <div id="qb-aca-sep" style="font-size:12px;margin-top:8px;"></div>
      <div id="qb-aca-intake-note" style="display:none;font-size:12px;color:var(--text-warning);margin-top:6px;"></div>
      <div style="margin-top:10px;border-top:0.5px dashed var(--border);padding-top:8px;">
        <div style="font-size:10px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:.5px;">Their doctors &amp; medications (optional — plans get ✓/✗ coverage marks)</div>
        <div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:6px;align-items:center;">
          <span><input type="text" id="qb-aca-doc-q" placeholder="Doctor, clinic or hospital" style="width:180px;" /> <button type="button" class="btn btn-outline btn-sm" onclick="qbAcaSearch_('doc')">Find Provider/Facility</button></span>
          <span><input type="text" id="qb-aca-med-q" placeholder="Medication" style="width:150px;" /> <button type="button" class="btn btn-outline btn-sm" onclick="qbAcaSearch_('med')">Find Medication</button></span>
        </div>
        <div id="qb-aca-matches" style="font-size:12px;margin-top:5px;"></div>
        <div id="qb-aca-chips" style="margin-top:5px;display:flex;gap:6px;flex-wrap:wrap;"></div>
      </div>
      <div style="margin-top:12px;border-top:0.5px dashed var(--border);padding-top:10px;">
        <button type="button" class="btn btn-primary" style="width:100%;" onclick="qbAcaGetPlans_()">\u{1F5D6} Find plans &amp; subsidy</button>
      </div>
      <div id="qb-aca-result" style="font-size:12px;margin-top:8px;color:var(--text-muted);"></div>
      <div id="qb-aca-browser" style="display:none;margin-top:12px;"></div>
    </div>
    <div id="qb-cms-strip" style="display:none;background:var(--surface-1);border:0.5px solid var(--border);border-radius:8px;padding:10px 12px;margin-top:10px;">
      <div style="font-size:11px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:.5px;margin-bottom:8px;">&#127963;&#65039; Medicare Advantage Plans</div>

      <div style="display:flex;gap:12px;flex-wrap:wrap;align-items:flex-end;font-size:13px;">
        <div><label style="font-size:10px;margin:0 0 2px;">Their ZIP code</label>
          <input type="text" id="qb-cms-zip" maxlength="5" inputmode="numeric" placeholder="59718"
            style="width:90px;" onchange="qbCmsZipChanged_()" /></div>
        <div><label style="font-size:10px;margin:0 0 2px;">County</label>
          <select id="qb-cms-county" onchange="qbCmsCountyChanged_()" style="width:auto;min-width:170px;"></select></div>
        <div><label style="font-size:10px;margin:0 0 2px;">Plan year</label>
          <select id="qb-cms-year" style="width:auto;" onchange="qbCmsYearChanged_()"></select></div>
        <div><label style="font-size:10px;margin:0 0 2px;">Looking for</label>
          <select id="qb-cms-kind" style="width:auto;min-width:210px;">
            <option value="MAPD">Medicare Advantage with drugs (MA-PD)</option>
            <option value="MA">Medicare Advantage only (no drugs)</option>
            <option value="SNP">Special Needs Plans (SNP)</option>
            <option value="PDP">Part D drug plan only</option>
          </select></div>
      </div>

      <div id="qb-cms-elig" style="margin-top:8px;"></div>
      <div id="qb-cms-status" style="font-size:12px;color:var(--text-muted);margin-top:6px;"></div>

      <div style="margin-top:10px;">
        <button type="button" class="btn btn-primary" style="width:100%;" onclick="qbCmsGetPlans_()">&#128374; Find Medicare plans</button>
      </div>
      <div style="font-size:11px;color:var(--text-muted);margin-top:6px;">
        Plans, premiums, star ratings and out-of-pocket limits come straight from the official CMS landscape data
        for the county they live in.
      </div>
    </div>
    <div id="qb-rate-strip" style="display:none;background:var(--surface-1);border:0.5px solid var(--border);border-radius:8px;padding:10px 12px;margin-top:10px;">
      <div style="font-size:11px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:.5px;margin-bottom:8px;">&#128273; Medicare Supplement</div>

      <div style="display:flex;gap:12px;flex-wrap:wrap;align-items:flex-end;font-size:13px;">
        <div><label style="font-size:10px;margin:0 0 2px;">Their ZIP</label>
          <input type="text" id="qb-mg-zip" maxlength="5" inputmode="numeric" style="width:82px;" onchange="qbMgZipChanged_()" /></div>
        <div><label style="font-size:10px;margin:0 0 2px;">Age</label>
          <input type="number" id="qb-mg-age" style="width:70px;" onchange="qbMgRefresh_()" /></div>
        <div><label style="font-size:10px;margin:0 0 2px;">Gender</label>
          <select id="qb-rt-gender" onchange="qbReRate_();qbMgRefresh_();" style="width:auto;">
            <option value="">?</option><option value="M">M</option><option value="F">F</option>
          </select></div>
        <div><label style="font-size:10px;margin:0 0 2px;">Part B started</label>
          <input type="date" id="qb-mg-partb" style="width:auto;" onchange="qbMgPartBChanged_()" /></div>
        <label style="display:flex;gap:6px;align-items:center;font-weight:400;margin:0 0 6px;font-size:12.5px;">
          <input type="checkbox" id="qb-rt-tob" onchange="qbReRate_();qbMgRefresh_();" style="width:auto;" /> Tobacco</label>
      </div>

      <div id="qb-mg-window" style="margin-top:8px;"></div>
      <span id="qb-rt-age" style="display:none;"></span>
      <span id="qb-rt-loc" style="display:none;"></span>
      <div id="qb-rt-warn" style="font-size:11px;color:#f59e0b;margin-top:5px;"></div>

      <div style="margin-top:10px;">
        <button type="button" class="btn btn-primary" style="width:100%;" onclick="openMedigapPicker_()">&#128273; Show Medicare Supplement plans</button>
      </div>
      <div style="font-size:11px;color:var(--text-muted);margin-top:6px;">
        Every letter covers exactly the same benefits at every carrier &mdash; that is federal law. Premiums come from
        the rate charts you load under Admin.
      </div>
    </div>


    <div id="qb-opt-list">
      ${Array.from({ length: QB_MAX_OPTIONS }, (_, oi) => oi).map(optBlock).join('')}
    </div>
    <div id="qb-opt-parked" style="display:none;"></div>
    <button type="button" id="qb-add-opt" class="btn btn-outline btn-sm" style="margin-top:12px;" onclick="qbRevealOption_()">+ Add another option</button>
    <p style="font-size:11px;color:var(--text-muted);margin-top:12px;">Client: <strong>${escWeb(contact.name || '')}</strong>${contact.email ? ' &middot; ' + escWeb(contact.email) : ' &middot; <span style="color:#f59e0b;">no email on file — you can still copy the link</span>'}</p>
  `, async () => {
    const _optLines = [];
    for (let k = 0; k < QB_MAX_OPTIONS; k++) {
      const w = document.getElementById('qb-opt-wrap-' + k);
      const nm = document.getElementById('qb-name-' + k);
      if (!w || w.style.display === 'none' || !nm || !nm.value.trim()) continue;
      const ol = document.getElementById('qb-optline-' + k);
      if (!ol || !ol.value) {
        qbOptRequiredMark_(k);
        ol && ol.scrollIntoView({ behavior: 'smooth', block: 'center' });
        showToast('Option ' + qbOptionNo_(k) + ': choose a coverage type.');
        return false;
      }
      _optLines.push(ol.value);
    }
    const line = _optLines[0] || document.getElementById('qb-line').value;
    if (MEDICARE_QUOTE_LINES.includes(line) && typeof medicareCertified_ === 'function' && !medicareCertified_()) {
      showToast('Medicare quoting requires Insured America + health license.'); return false;
    }
    const options = [];
    for (let i = 0; i < QB_MAX_OPTIONS; i++) {
      const name = document.getElementById('qb-name-' + i).value.trim();
      const prem = parseFloat(document.getElementById('qb-prem-' + i).value);
      if (!name && !document.getElementById('qb-prem-' + i).value) continue;
      if (!name || isNaN(prem)) { showToast('Option ' + (i + 1) + ' needs a plan name and premium.'); return false; }
      const carId = document.getElementById('qb-car-' + i).value || null;
      const car = (window._qbCarriers || []).find(c => c.id === carId);
      const cmsSel = (window._qbCmsSel || {})[i];
      const acaSel = (window._qbAcaSel || {})[i];
      const mgHasCarrier = !!(((window._qbMgSel || {})[i] || {}).carrier_name);
      if (!car && !cmsSel && !acaSel && !mgHasCarrier) {
        showToast((window._qbMgSel || {})[i]
          ? 'Option ' + qbOptionNo_(i) + ': choose the carrier writing this supplement plan.'
          : 'Option ' + qbOptionNo_(i) + ': pick a carrier or an official plan.');
        return false;
      }
      const prodId = document.getElementById('qb-prod-' + i).value || null;
      let bullets = document.getElementById('qb-bul-' + i).value.split('\n').map(x => x.trim()).filter(Boolean);
      if (MEDICARE_QUOTE_LINES.includes(line)) {
        if (cmsSel) {
          // CMS-picked plan: keep the factual CMS-sourced bullets in the (locked) box
          bullets = document.getElementById('qb-bul-' + i).value.split('\n').map(x => x.trim()).filter(Boolean);
        } else {
          const prod = (window._qbProds || []).find(p => p.id === prodId);
          bullets = (prod && (prod.metadata || {}).bullets) || [];
        }
      }
      let planMeta = null;
      if (acaSel) {
        planMeta = {
          src: 'aca', plan_id: acaSel.id, year: window._qbAcaYear || acaSel._year || null,
          metal: acaSel.metal || null, plan_type: acaSel.type || null,
          full_premium: acaSel.premium, net_premium: acaSel.net,
          deductible: acaSel.deductible, deductible_family: acaSel.deductible_family,
          moop: acaSel.moop, moop_family: acaSel.moop_family,
          hsa: !!acaSel.hsa, rating: acaSel.rating || null,
          family_quote: !!window._qbAcaFamilyQuote, links: acaSel._links || null,
          csr: window._qbAcaCsr || null, csr_applies: acaCsrAppliesTo_(acaSel.metal),
          coverage: qbAcaCoverageSnapshot_(acaSel),
        };
      } else if ((window._qbMgSel || {})[i]
                 || ((document.getElementById('qb-optline-' + i) || {}).value === 'Medicare Supplement'
                     && mgLetterFromName_(name))) {
        const mg = (window._qbMgSel || {})[i] || {
          letter: mgLetterFromName_(name),
          carrier_name: (car && car.name) || null,
          rate: prem != null ? prem : null,
          state: (window._qbContact || {}).state || null,
        };
        const base = String(mg.letter).replace(/^HD/, '');
        planMeta = {
          src: 'medigap', letter: mg.letter, base_letter: base,
          carrier_name: mg.carrier_name || null, product_id: mg.product_id || null,
          rating_method: mg.rating_method || null, state: mg.state || null,
          premium: mg.rate != null ? mg.rate : null,
          pays: MEDIGAP_GRID.rows.filter(([, by]) => by[base] && by[base] !== 'none')
            .map(([label, by]) => ({ label: label, level: by[base] })),
          gaps: MEDIGAP_GRID.rows.filter(([, by]) => !by[base] || by[base] === 'none').map(([label]) => label),
        };
      } else if (cmsSel) {
        planMeta = {
          src: 'cms', year: cmsSel.plan_year || window._qbCmsYear || null,
          category: cmsSel.category || null, plan_type: cmsSel.plan_type || null,
          contract_id: cmsSel.contract_id, plan_id: cmsSel.plan_id, segment_id: String(cmsSel.segment_id || '0'),
          org_name: cmsSel.org_name || null, snp_type: cmsSel.snp_type || null,
          premium: cmsPremium_(cmsSel),
          part_c_premium: cmsSel.part_c_premium, part_d_premium: cmsSel.part_d_premium,
          moop: cmsSel.moop, drug_deductible: cmsSel.drug_deductible,
          rating: cmsSel.star_rating || null,
          state: cmsSel.state || null, county: cmsSel.county || null,
          formulary_id: cmsSel._formularyId || null,
          coverage: qbCmsCoverageSnapshot_(cmsSel),
        };
      } else if ((window._qbPpMeta || {})[i]) {
        // Added from the product picker
        planMeta = window._qbPpMeta[i];
      } else {
        // Re-quoted option left untouched: reuse the previous quote's snapshot
        const rq = (window._qbRequoteOpt || {})[i];
        if (rq && rq.plan_meta && rq.display_name === name) planMeta = rq.plan_meta;
      }
      options.push({
        carrier_id: carId, product_id: prodId,
        carrier_name: car ? car.name
          : (((window._qbMgSel || {})[i] || {}).carrier_name
             || (cmsSel ? (cmsSel.org_name || 'Medicare Plan')
                        : (acaSel ? (acaSel.issuer || 'Marketplace Plan') : 'Carrier'))),
        display_name: name, monthly_premium: prem, benefit_bullets: bullets,
        agent_note: document.getElementById('qb-note-' + i).value.trim() || null,
        is_recommended: document.getElementById('qb-rec-' + i).checked,
        sort_order: options.length, plan_meta: planMeta,
        line: (document.getElementById('qb-optline-' + i) || {}).value || line,
      });
    }
    if (!options.length) { showToast('Add at least one option.'); return false; }
    // Snapshot the official document links for ACA options. Best-effort: run
    // them together and give up after a few seconds — a slow relay must never
    // make "Save Quote" look like it did nothing.
    const needLinks = options.filter(o => o.plan_meta && o.plan_meta.src === 'aca' && !o.plan_meta.links);
    if (needLinks.length) {
      showToast('Saving quote\u2026');
      const grab = o => qbAcaDetail_(o.plan_meta.plan_id).then(d => {
        o.plan_meta.links = {
          sbc: d.benefits_url || null, brochure: d.brochure_url || null,
          formulary: d.formulary_url || null, network: d.network_url || null,
        };
        // and what the plan actually pays, so it can be compared against a
        // short-term plan later without going back to the Marketplace
        o.plan_meta.benefits = (d.benefits || []).filter(b => b && b.name).slice(0, 40).map(b => ({
          name: String(b.name), covered: b.covered !== false,
          cost: (b.cost_sharings || []).map(cs => cs.display_string).filter(Boolean).join('; ') || null,
        }));
      }).catch(() => {});
      await Promise.race([
        Promise.all(needLinks.map(grab)),
        new Promise(r => setTimeout(r, 8000)),
      ]);
    }
    // Remember rating inputs on the contact (silent, best-effort)
    try {
      const rg = document.getElementById('qb-rt-gender');
      if (document.getElementById('qb-line').value === 'Medicare Supplement' && rg && rg.value) {
        const cPatch = { gender: rg.value, tobacco_use: document.getElementById('qb-rt-tob').checked };
        await supabaseClient.from('contacts').update(cPatch).eq('id', contact.id);
        Object.assign(contact, cPatch);
      }
    } catch (e) {}
    const { data: q, error } = await supabaseClient.from('quotes').insert({
      contact_id: contact.id, deal_id: deal.id, agent_id: currentAgent.id,
      agent_name: currentAgent.display_name || currentAgent.name,
      agent_email: currentAgent.email, agent_phone: currentAgent.phone || null,
      agent_booking_url: (currentAgent.booking_types && currentAgent.booking_types.length
            ? window.location.origin + '/book.html?agent=' + currentAgent.id + '&context=client'
            : currentAgent.booking_link || null),
      client_name: contact.name || 'Client', client_email: contact.email || null,
      line: line, lines: [...new Set(options.map(o => o.line || line))],
      brand: document.getElementById('qb-brand').value,
      valid_until: document.getElementById('qb-valid').value || null,
      quote_inputs: (() => {
        const base = (line === 'Health — Individual' && window._qbAcaInputs) ? window._qbAcaInputs : null;
        const facts = medFactsSnapshot_([...new Set(options.map(o => o.line || line))]);
        const basis = qbBasisSnapshot_();
        if (!base && !facts && !basis) return null;
        // the ACA tool's own record wins where the two overlap
        const out = Object.assign({}, basis || {}, base || {});
        if (basis && basis.medications_detail) out.medications_detail = basis.medications_detail;
        if (basis && basis.checked_at) out.checked_at = basis.checked_at;
        if (facts) out.medicare_facts = facts;
        return out;
      })(),
      intake_session_id: window._qbIntakeSessionId || null,
    }).select().single();
    if (error) { showToast('Error: ' + error.message); return false; }
    const { error: e2 } = await supabaseClient.from('quote_options')
      .insert(options.map(o => Object.assign({ quote_id: q.id }, o)));
    if (e2) { showToast('Error saving options: ' + e2.message); return false; }
    closeModal();
    openQuoteReady_(q, contact);
    loadDealTree_(deal);
    return false;
  }, { confirmLabel: 'Save Quote' });
  let smartLine = await qbSmartDefaultLine_(deal, contact);
  // started from a specific intake? let its type pick the line
  const _chosen = (window._qbIntakeChoices || []).find(x => x.id === window._qbIntakeSessionId);
  if (opts.intakeSessionId && _chosen) {
    const byType = { 'health-individual': 'Health \u2014 Individual', 'medicare': 'Medicare Supplement',
                     'group-health': 'Health \u2014 Group', 'financial': 'Life' };
    if (byType[_chosen.form_type]) smartLine = byType[_chosen.form_type];
  }
  const lineSel = document.getElementById('qb-line');
  if (lineSel && [...lineSel.options].some(o => o.value === smartLine)) lineSel.value = smartLine;
  qbLineChanged_();
  // The agent tells us what each option is; we don't guess on their behalf.
  for (let i = 0; i < QB_MAX_OPTIONS; i++) qbOptFields_(i);
  qbGroupOptions_();
}

// The top-level line drives the automated data (ACA / CMS / rate charts).
// Each option can be a DIFFERENT coverage type, which is what turns a quote
// into a multi-section proposal.
// Lines whose official plan list we can actually load today. Medicare
// Supplement is deliberately absent: its official source is the carrier's
// product record and rate chart, which sit right below anyway.
const QB_CMS_PLAN_LINES = ['Medicare Advantage', 'Part D (PDP)'];

// The coverage type is the option's first decision and everything else keys
// off it, so an unanswered one is flagged rather than quietly defaulted.
function qbOptRequiredMark_(i) {
  const sel = document.getElementById('qb-optline-' + i);
  const hint = document.getElementById('qb-optline-hint-' + i);
  if (!sel) return;
  const missing = !sel.value;
  sel.style.borderColor = missing ? 'var(--border-danger)' : '';
  sel.style.background = missing ? 'var(--bg-danger)' : '';
  if (hint) hint.style.display = missing ? 'block' : 'none';
}

const NON_ACA_NOTE = {
  'Short-Term Medical': 'Short-term medical is <strong>not ACA-compliant</strong> — it can be declined for health, will not cover pre-existing conditions, and does not carry the Marketplace protections.',
  'Private/Off-Market Medical': 'An off-market plan carries <strong>no premium tax credit</strong> and may be medically underwritten.',
  'Health Share': 'A health share is <strong>not insurance</strong>. Sharing is not guaranteed and it is not regulated as an insurance product.',
};

// Only show a field when the option's own coverage type can use it.
function qbOptFields_(i) {
  const sel = document.getElementById('qb-optline-' + i);
  if (!sel) return;
  const warn = document.getElementById('qb-optwarn-' + i);
  if (warn) {
    const note = NON_ACA_NOTE[sel.value];
    warn.innerHTML = note || '';
    warn.style.display = note ? 'block' : 'none';
  }
  const acaWrap = document.getElementById('qb-aca-wrap-' + i);
  const cmsWrap = document.getElementById('qb-cms-wrap-' + i);
  const carOpt = document.getElementById('qb-car-opt-' + i);
  const isCms = QB_CMS_PLAN_LINES.includes(sel.value);
  // Marketplace plans are attached from the ACA tool, never from a bare
  // dropdown — the tool is what prices the subsidy and CSR.
  if (acaWrap) acaWrap.style.display = 'none';
  if (cmsWrap) cmsWrap.style.display = isCms ? 'block' : 'none';
  const cmsLbl = document.getElementById('qb-cms-label-' + i);
  if (cmsLbl && isCms) cmsLbl.textContent = sel.value === 'Part D (PDP)' ? 'Part D plan' : 'Medicare Advantage plan';
  if (carOpt) carOpt.style.display = isCms ? 'inline' : 'none';
  if (isCms) {
    const c = document.getElementById('qb-cms-' + i);
    const loaded = (window._qbCmsPlans || []).length;
    if (c && !loaded) {
      c.innerHTML = '<option value="">\u2014 open the Medicare tool above to load plans \u2014</option>';
    }
  }
  qbOptRequiredMark_(i);
}

function qbOptLineChanged_(i) {
  const sel = document.getElementById('qb-optline-' + i);
  const top = document.getElementById('qb-line');
  if (!sel || !top) return;
  // Medicare compliance rules follow the OPTION, not the dialog
  const optIsMed = MEDICARE_QUOTE_LINES.includes(sel.value);
  const bul = document.getElementById('qb-bul-' + i);
  if (bul) {
    bul.readOnly = optIsMed;
    bul.placeholder = optIsMed ? 'Locked \u2014 filled from the product record' : 'e.g. $0 deductible';
  }
  const anyMed = Array.from({ length: QB_MAX_OPTIONS }, (_, k) => document.getElementById('qb-optline-' + k))
    .some(el => el && MEDICARE_QUOTE_LINES.includes(el.value));
  const brand = document.getElementById('qb-brand');
  if (brand) { if (anyMed) { brand.value = 'ia'; brand.disabled = true; } else { brand.disabled = false; } }
  const medNote = document.getElementById('qb-med-note');
  if (medNote) medNote.style.display = anyMed ? 'block' : 'none';
  qbOptFields_(i);
  setTimeout(qbGroupOptions_, 0);
  // an option moved off its line can't keep the official plan it had
  if (sel.value !== 'Health \u2014 Individual') {
    const a = document.getElementById('qb-aca-' + i);
    if ((window._qbAcaSel || {})[i] || (a && a.value)) { if (a) a.value = ''; qbApplyAcaPlan_(i); }
  }
  if (!QB_CMS_PLAN_LINES.includes(sel.value)) {
    const c = document.getElementById('qb-cms-' + i);
    if (c && c.value) { c.value = ''; qbApplyCmsPlan_(i); }
  }
  qbSectionSummary_();
}

// Plain-English summary of what this proposal contains
function qbSectionSummary_() {
  const el = document.getElementById('qb-sections');
  if (!el) return;
  const counts = {};
  for (let i = 0; i < QB_MAX_OPTIONS; i++) {
    const w = document.getElementById('qb-opt-wrap-' + i);
    if (!w || w.style.display === 'none') continue;
    const nm = document.getElementById('qb-name-' + i);
    if (!nm || !nm.value.trim()) continue;
    const ln = (document.getElementById('qb-optline-' + i) || {}).value || '(unset)';
    counts[ln] = (counts[ln] || 0) + 1;
  }
  const keys = Object.keys(counts);
  if (!keys.length) { el.innerHTML = ''; return; }
  if (keys.length === 1) {
    el.innerHTML = '<span style="color:var(--text-muted);">One coverage type \u00b7 '
      + counts[keys[0]] + ' option' + (counts[keys[0]] === 1 ? '' : 's') + ' for the client to choose from.</span>';
    return;
  }
  el.innerHTML = '<strong style="color:var(--text-success);">\u{1F4E6} Proposal with ' + keys.length + ' sections:</strong> '
    + keys.map(k => escWeb(k) + ' (' + counts[k] + ')').join(' \u00b7 ')
    + '<span style="color:var(--text-muted);"> \u2014 the client picks one from each section.</span>';
}

// Automated lookups AVAILABLE to a line — never a definition of it.
// "Health — Individual" might be an ACA Marketplace plan, a short-term medical
// policy, a health share, or an off-exchange plan typed in by hand. Each entry
// here is one optional tool; add a source and it gets a workbench for free.
// Whether a tool suits THIS client. It never blocks \u2014 an agent may be
// quoting a spouse, or someone under 65 on disability \u2014 but it should not
// take a 55-year-old through a Medicare tool without saying something.
function qbClientAge_() {
  const c = window._qbContact || {};
  const dob = c.date_of_birth || c.dob || window._qbMgDob;
  return dob ? qbAgeFrom_(dob) : null;
}

function qbToolFit_(key) {
  const age = qbClientAge_();
  const medicareish = age != null && age >= 64;
  if (key === 'aca') {
    if (age != null && age >= 65) return { ok: false, why: 'They are ' + age + ' \u2014 most people this age are on Medicare, not a Marketplace plan.' };
    return { ok: true };
  }
  if (key === 'cms' || key === 'rate') {
    if (age == null) return { ok: true, why: 'No date of birth on file \u2014 add one and this will check whether Medicare fits them.' };
    if (!medicareish) return { ok: false, why: 'They are ' + age + ' \u2014 Medicare starts at 65, or earlier on disability.' };
    return { ok: true };
  }
  return { ok: true };
}

function qbAutoSources_() {
  return [
    { key: 'aca', el: 'qb-aca-strip', line: 'Health \u2014 Individual',
      title: '\u{1F3DB}\uFE0F ACA Marketplace',
      blurb: 'Live on-exchange plans with subsidy, CSR and doctor/drug checks.' },
    { key: 'cms', el: 'qb-cms-strip', line: 'Medicare Advantage',
      title: '\u{1F3DB}\uFE0F Medicare Advantage Plans',
      blurb: 'Official CMS plan data \u2014 Advantage and Part D plans where they live.' },
    { key: 'pdp', el: 'qb-cms-strip', line: 'Part D (PDP)',
      title: '\u{1F48A} Part D drug plans',
      blurb: 'Standalone drug plans where they live, checked against their prescriptions.' },
    { key: 'rate', el: 'qb-rate-strip', line: 'Medicare Supplement',
      title: '\u{1F4CA} Medigap rate lookup',
      blurb: 'Rates from the charts you\u2019ve loaded, by age, gender and tobacco.' },
    // One entry per line we hold products for. The picker itself is generic \u2014
    // it reads what each product is priced by \u2014 so adding a line here is the
    // whole job.
    { key: 'stm', el: 'qb-pp-strip', line: 'Short-Term Medical',
      title: '\u{1F4CB} Short-Term Medical plans',
      blurb: 'Products from your carriers side by side, with their benefits and exclusions.' },
    { key: 'hosp', el: 'qb-pp-strip', line: 'Hospital Indemnity',
      title: '\u{1F3E5} Hospital indemnity plans',
      blurb: 'Products from your carriers, compared on what they actually pay.' },
    { key: 'acc', el: 'qb-pp-strip', line: 'Accident',
      title: '\u{1FA79} Accident plans',
      blurb: 'Products from your carriers, compared side by side.' },
    { key: 'ci', el: 'qb-pp-strip', line: 'Cancer/Critical Illness',
      title: '\u{1F397}\ufe0f Cancer and critical illness',
      blurb: 'Products from your carriers, compared side by side.' },
  ];
}

function qbEnsureWorkbench_() {
  let wb = document.getElementById('qb-workbench');
  if (!wb) {
    wb = document.createElement('div');
    wb.id = 'qb-workbench';
    wb.style.cssText = 'position:fixed;top:0;left:0;bottom:0;width:min(560px,96vw);z-index:99988;display:none;'
      + 'flex-direction:column;background:var(--surface-0);border-right:1px solid var(--border);'
      + 'box-shadow:14px 0 44px rgba(0,0,0,.34);';
    wb.innerHTML = '<div style="padding:14px 18px;border-bottom:1px solid var(--border);display:flex;align-items:center;gap:10px;background:var(--surface-1);">'
      + '<div id="qb-wb-title" style="font-weight:800;font-size:14px;flex:1;"></div>'
      + '<button class="btn btn-primary btn-sm" onclick="qbWorkbenchOpen_(false)">\u2713 Done</button></div>'
      + '<div id="qb-wb-body" style="flex:1;overflow-y:auto;padding:14px 18px;"></div>';
    document.body.appendChild(wb);
  }
  return wb;
}

function qbWorkbenchOpen_(open, key) {
  const wb = qbEnsureWorkbench_();
  if (open && key === 'pdp') {
    const kind = document.getElementById('qb-cms-kind');
    if (kind) kind.value = 'PDP';
  }
  if (open && key) {
    window._qbWbActive = key;
    const src = qbAutoSources_().find(x => x.key === key);
    const ls = document.getElementById('qb-line');
    if (src && ls && ls.value !== src.line) { ls.value = src.line; qbLineChanged_(); }
  }
  if (open) qbMountSource_();
  wb.style.display = open ? 'flex' : 'none';
  if (!open) qbAutoCardPaint_();
}

function qbCloseWorkbench_() {
  const wb = document.getElementById('qb-workbench');
  if (wb) wb.remove();
}

// Move the chosen source's panel into the workbench; park every other one
// The product picker's own strip. It says what we hold for this line and opens
// the picker; everything else about the line lives on the products themselves.
async function qbPpStripPaint_(line) {
  const el = document.getElementById('qb-pp-strip');
  if (!el) return;
  el.innerHTML = `<div style="font-size:12.5px;color:var(--text-muted);">Counting products…</div>`;
  // the same gate the picker uses, so the count never promises more than opens
  const { data } = await supabaseClient.from('my_offerable_products')
    .select('product_id,carrier_id').eq('line_of_business', line);
  const n = new Set((data || []).map(x => x.product_id)).size;
  const carrierCount = new Set((data || []).map(x => x.carrier_id)).size;
  el.innerHTML = n
    ? `<div style="font-size:12.5px;color:var(--text-secondary);line-height:1.55;">
         <strong>${n}</strong> ${escWeb(line)} product${n === 1 ? '' : 's'} from
         <strong>${carrierCount}</strong> carrier${carrierCount === 1 ? '' : 's'} you can write.</div>
       <button type="button" class="btn btn-primary btn-sm" style="margin-top:8px;"
         onclick="openProductPicker_(${JSON.stringify(line).replace(/"/g, '&quot;')})">Open the plan picker</button>`
    : `<div style="font-size:12.5px;color:var(--text-muted);line-height:1.55;">
         No ${escWeb(line)} products on file for the carriers you are appointed with.<br>
         Load a carrier's brochure from <strong>Admin → Carriers → Add products from a brochure</strong>.</div>`;
}

function qbMountSource_() {
  const sources = qbAutoSources_();
  const active = sources.find(x => x.key === window._qbWbActive) || sources[0];
  const body = document.getElementById('qb-wb-body');
  const holder = document.getElementById('qb-strip-holder');
  if (!body || !holder) return;
  ['qb-aca-strip', 'qb-cms-strip', 'qb-rate-strip', 'qb-pp-strip'].forEach(id => {
    const el = document.getElementById(id);
    if (!el) return;
    if (active && active.el === id) {
      if (el.parentElement !== body) body.appendChild(el);
      el.style.display = 'block';
      el.style.border = 'none'; el.style.background = 'transparent';
      el.style.padding = '0'; el.style.margin = '0';
      if (id === 'qb-pp-strip') qbPpStripPaint_(active.line);
    } else {
      if (el.parentElement !== holder) holder.appendChild(el);
      el.style.display = 'none';
    }
  });
  const t = document.getElementById('qb-wb-title');
  if (t && active) t.innerHTML = active.title;
}

// Live summary of a source that's already been used
function qbSourceUsed_(key) {
  if (key === 'aca') return ((window._qbAcaPlans || []).length > 0);
  if (key === 'cms') return ((window._qbCmsPlans || []).length > 0 && window._qbCmsKind !== 'PDP');
  if (key === 'pdp') return ((window._qbCmsPlans || []).length > 0 && window._qbCmsKind === 'PDP');
  if (key === 'rate') return (window._qbRateAge != null);
  return false;
}

function qbSourceSummary_(key) {
  const bits = [];
  if (key === 'aca') {
    const inc = (document.getElementById('qb-aca-income') || {}).value;
    const zip = (document.getElementById('qb-aca-zip') || {}).value;
    const cs = document.getElementById('qb-aca-county');
    const county = (cs && cs.options[cs.selectedIndex]) ? cs.options[cs.selectedIndex].text : '';
    if (inc) bits.push('$' + Number(inc).toLocaleString() + '/yr');
    if (zip) bits.push(zip);
    if (county && !/loading|need a ZIP|unavailable/i.test(county)) bits.push(county);
    const n = (window._qbAcaPlans || []).length;
    if (n) bits.push('<strong style="color:var(--text-success);">' + n + ' plans loaded</strong>');
    if (window._qbAcaAptc) bits.push('credit $' + Number(window._qbAcaAptc).toFixed(0) + '/mo');
    const csr = (typeof acaCsrActive_ === 'function') ? acaCsrActive_() : null;
    if (csr && typeof acaCsrPct_ === 'function') bits.push('\u2728 ' + acaCsrPct_(csr) + '% CSR');
  } else if (key === 'cms') {
    const n = (window._qbCmsPlans || []).length;
    if (window._qbCmsCounty || window._qbCmsState) {
      bits.unshift(escWeb((window._qbCmsCounty ? window._qbCmsCounty + ' County, ' : '') + (window._qbCmsState || '')));
    }
    if (n) bits.push(n + ' CMS plans loaded');
  } else if (key === 'rate') {
    if (window._qbRateAge != null) bits.push('age ' + window._qbRateAge);
  }
  return bits;
}

// The dialog's compact card: what's AVAILABLE, plus what's been used
// The dialog's automated-quoting group: collapsed by default, with a
// one-line summary so a collapsed section still tells the agent something.
function qbAutoToggle_() {
  window._qbAutoOpen = !window._qbAutoOpen;
  qbAutoCardPaint_();
}

function qbAutoCardPaint_() {
  const card = document.getElementById('qb-auto-card');
  if (!card) return;
  const sources = qbAutoSources_();
  if (!sources.length) { card.style.display = 'none'; card.innerHTML = ''; return; }
  const open = !!window._qbAutoOpen;

  // collapsed headline: whatever has actually been run, else how many tools
  const runBits = [];
  sources.forEach(src => {
    if (qbSourceUsed_(src.key)) {
      const b = qbSourceSummary_(src.key);
      // the summaries carry markup for the expanded rows; a headline is plain text
      const plain = b.join(' \u00b7 ').replace(/<[^>]+>/g, '');
      runBits.push(src.title.replace(/^[^ ]+ /, '') + (plain ? ' \u00b7 ' + plain : ''));
    }
  });
  const headline = runBits.length
    ? runBits.join('  |  ')
    : sources.length + ' tool' + (sources.length === 1 ? '' : 's') + ' available \u2014 optional';

  card.style.display = 'block';
  card.innerHTML = `<div style="background:var(--surface-1);border:0.5px solid var(--border);border-radius:8px;margin-top:10px;overflow:hidden;">
      <button type="button" onclick="qbAutoToggle_()" style="width:100%;text-align:left;background:none;border:none;cursor:pointer;padding:10px 12px;display:flex;align-items:center;gap:10px;">
        <span style="font-size:10px;font-weight:800;text-transform:uppercase;letter-spacing:.5px;color:var(--text-muted);white-space:nowrap;">
          ${open ? '\u25BE' : '\u25B8'} \u2699\uFE0F Available Automated Quoting
        </span>
        <span style="flex:1;min-width:0;font-size:11.5px;color:${runBits.length ? 'var(--text-success)' : 'var(--text-muted)'};overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${escWeb(headline)}</span>
        <span style="font-size:11px;font-weight:700;color:var(--accent,#c8a84b);white-space:nowrap;">${open ? 'Hide' : 'Show'}</span>
      </button>
      ${open ? `<div style="padding:0 12px 10px;">
        ${sources.map(src => {
          const used = qbSourceUsed_(src.key);
          const bits = used ? qbSourceSummary_(src.key) : [];
          const fit = qbToolFit_(src.key);
          return `<div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:5px 0;border-top:1px solid var(--border);${fit.ok ? '' : 'opacity:.72;'}">
            <div style="flex:1;min-width:0;">
              <div style="font-size:12.5px;font-weight:700;">${src.title}${used ? ' <span style="font-size:10px;font-weight:800;color:var(--text-success);">\u2713 RUN</span>' : ''}${
                fit.ok ? '' : ' <span style="font-size:10px;font-weight:800;color:var(--text-warning);">DOESN\u2019T LOOK LIKE A FIT</span>'}</div>
              <div style="font-size:11.5px;color:${used ? 'var(--text-secondary)' : 'var(--text-muted)'};margin-top:2px;">
                ${used ? bits.join(' \u00b7 ') : escWeb(src.blurb)}</div>
              ${fit.why ? `<div style="font-size:11px;color:var(--text-warning);margin-top:2px;">${escWeb(fit.why)}</div>` : ''}
            </div>
            <button type="button" class="btn ${used ? 'btn-outline' : 'btn-primary'} btn-sm" onclick="qbWorkbenchOpen_(true, '${src.key}')">\u2699\uFE0F ${used ? 'Reopen' : 'Open'}</button>
          </div>`;
        }).join('')}
        <div style="font-size:11px;color:var(--text-muted);border-top:1px solid var(--border);margin-top:7px;padding-top:6px;">
          Quoting something else on this line \u2014 short-term medical, a health share, an off-exchange plan? Just type it into the options below.
        </div>
      </div>` : ''}
    </div>`;
}


// Keep panels parked correctly as the line changes; never open on its own
function qbSyncWorkbench_() {
  const sources = qbAutoSources_();
  qbEnsureWorkbench_();
  const holder = document.getElementById('qb-strip-holder');
  const wb0 = document.getElementById('qb-workbench');
  const wbOpen = !!(wb0 && wb0.style.display !== 'none');
  const activeEl = (sources.find(x => x.key === window._qbWbActive) || {}).el;
  window._qbPdpMode = window._qbWbActive === 'pdp';
  if (holder) {
    // Every tool is on offer now, so "offered" can't decide visibility:
    // a panel belongs on screen ONLY while it's the one open in the workbench.
    // Otherwise it parks, or it leaks back onto the dialog (qbLineChanged_
    // sets display:block on whichever strip matches the working line).
    ['qb-aca-strip', 'qb-cms-strip', 'qb-rate-strip', 'qb-pp-strip'].forEach(id => {
      const el = document.getElementById(id);
      if (!el) return;
      if (wbOpen && id === activeEl) return;
      if (el.parentElement !== holder) holder.appendChild(el);
      el.style.display = 'none';
    });
  }
  if (!sources.length) { window._qbWbActive = null; qbWorkbenchOpen_(false); }
  else if (!sources.some(x => x.key === window._qbWbActive)) window._qbWbActive = sources[0].key;
  const wb = document.getElementById('qb-workbench');
  if (wb && wb.style.display !== 'none') qbMountSource_();
  qbAutoCardPaint_();
}

function qbLineChanged_() {
  const line = document.getElementById('qb-line').value;
  const isMed = MEDICARE_QUOTE_LINES.includes(line);
  document.getElementById('qb-med-note').style.display = isMed ? 'block' : 'none';
  const strip = document.getElementById('qb-rate-strip');
  if (strip) {
    strip.style.display = line === 'Medicare Supplement' ? 'block' : 'none';
    if (line === 'Medicare Supplement') { qbInitRateStrip_(); qbMgInit_(); }
  }
  // qb-line now only says WHICH TOOL is loaded. It must never rewrite or
  // clear the options \u2014 each option owns its coverage type and its plan.
  const acaStrip = document.getElementById('qb-aca-strip');
  if (acaStrip) {
    const isAca = line === 'Health \u2014 Individual';
    acaStrip.style.display = isAca ? 'block' : 'none';
    if (isAca) qbAcaInit_();
  }
  const cmsStrip = document.getElementById('qb-cms-strip');
  if (cmsStrip) {
    const isCms = QB_CMS_PLAN_LINES.includes(line);
    cmsStrip.style.display = isCms ? 'block' : 'none';
    if (isCms) qbLoadCmsPlans_();
  }
  const brand = document.getElementById('qb-brand');
  if (isMed) { brand.value = 'ia'; brand.disabled = true; } else { brand.disabled = false; }
  for (let i = 0; i < QB_MAX_OPTIONS; i++) {
    qbFillProducts_(i);
    qbOptFields_(i);
  }
  qbSectionSummary_();
  qbSyncWorkbench_();
}

function qbMgCarrierPicked_(i) {
  const sel = (window._qbMgSel || {})[i];
  if (!sel) return;
  const carSel = document.getElementById('qb-car-' + i);
  const car = (window._qbCarriers || []).find(c => c.id === (carSel || {}).value);
  if (car) { sel.carrier_id = car.id; sel.carrier_name = car.name; }
  qbMgOptionView_(i);
}

function qbFillProducts_(i) {
  const carId = document.getElementById('qb-car-' + i).value;
  // This option's own coverage type decides which products fit it. The quote's
  // overall line is only a fallback for options that have not chosen one yet.
  const line = (document.getElementById('qb-optline-' + i) || {}).value
    || (document.getElementById('qb-line') || {}).value;
  const sel = document.getElementById('qb-prod-' + i);
  let list = (window._qbProds || []).filter(p => p.carrier_id === carId);
  const inLine = list.filter(p => p.line_of_business === line);
  if (inLine.length) list = inLine;
  // Products not filed in the client's state stay on the list, marked. Hiding
  // them would leave an agent wondering where a product they know exists went.
  const st = (typeof _acaClientState_ === 'function') ? _acaClientState_() : '';
  sel.innerHTML = '<option value="">— none / type manually —</option>'
    + list.map(p => {
        const filed = (p.states || []).map(x => String(x).toUpperCase());
        const off = st && filed.length && !filed.includes(st);
        return `<option value="${p.id}">${escWeb(p.name)}${p.plan_year ? ' (' + p.plan_year + ')' : ''}`
          + (off ? ' — not filed in ' + escWeb(st) : '') + '</option>';
      }).join('');
}

function qbApplyProduct_(i) {
  const prod = (window._qbProds || []).find(p => p.id === document.getElementById('qb-prod-' + i).value);
  if (!prod) return;
  document.getElementById('qb-name-' + i).value = prod.name;
  document.getElementById('qb-bul-' + i).value = ((prod.metadata || {}).bullets || []).join('\n');
  qbAutoRateOption_(i);
}

function qbInitRateStrip_() {
  const c = window._qbContact;
  if (!c) return;
  const ageEl = document.getElementById('qb-rt-age');
  const age = c.date_of_birth ? Math.floor((Date.now() - new Date(c.date_of_birth + 'T12:00:00')) / 31557600000) : null;
  window._qbRateAge = age;
  ageEl.innerHTML = age !== null
    ? 'Age: <strong>' + age + '</strong>'
    : '<span style="color:#f59e0b;">No DOB on contact &mdash; add it for auto-rating</span>';
  const g = document.getElementById('qb-rt-gender');
  if (!g.value) g.value = c.gender || '';
  const t = document.getElementById('qb-rt-tob');
  t.checked = !!c.tobacco_use;
  document.getElementById('qb-rt-loc').innerHTML = 'State: <strong>' + (c.state || '?') + '</strong>' + (c.zip ? ' &middot; Zip ' + escWeb(c.zip) : '');
  document.getElementById('qb-rt-warn').textContent = c.state ? '' : 'No state on the contact — auto-rating needs it.';
}

async function medigapRate_(productId) {
  const c = window._qbContact;
  const age = window._qbRateAge;
  const gender = document.getElementById('qb-rt-gender').value;
  const tobacco = document.getElementById('qb-rt-tob').checked;
  if (!c || age === null || age === undefined || !c.state) return null;
  const { data: charts } = await supabaseClient.from('rate_charts').select('*')
    .eq('product_id', productId).eq('is_active', true).eq('state', c.state.toUpperCase());
  if (!charts || !charts.length) return null;
  // Prefer a chart scoped to the client's zip area, else the statewide chart
  const zp = (c.zip || '').slice(0, 3);
  const chart = charts.find(ch => ch.zip_prefixes && zp && ch.zip_prefixes.split(',').map(x => x.trim()).includes(zp))
    || charts.find(ch => !ch.zip_prefixes)
    || charts[0];
  const { data: rows } = await supabaseClient.from('rate_rows').select('*')
    .eq('chart_id', chart.id).lte('age_min', age).gte('age_max', age);
  if (!rows || !rows.length) return null;
  const g = gender === 'F' ? 'F' : 'M';
  const pick = rows.find(r => r.gender === g && r.tobacco === tobacco)
    || rows.find(r => r.gender === 'U' && r.tobacco === tobacco)
    || rows.find(r => r.gender === g && !r.tobacco)
    || rows.find(r => r.gender === 'U' && !r.tobacco);
  return pick ? { rate: pick.monthly_rate, chart } : null;
}

async function qbAutoRateOption_(i) {
  if (document.getElementById('qb-line').value !== 'Medicare Supplement') return;
  const prodId = document.getElementById('qb-prod-' + i).value;
  if (!prodId) return;
  const hit = await medigapRate_(prodId);
  const premEl = document.getElementById('qb-prem-' + i);
  if (hit) {
    premEl.value = Number(hit.rate).toFixed(2);
    premEl.style.borderColor = '#16a34a';
    premEl.title = 'Auto-rated from the ' + hit.chart.state + ' rate chart ('
      + hit.chart.rating_method + (hit.chart.effective_date ? ', effective ' + hit.chart.effective_date : '') + ')'
      + (hit.chart.household_discount_pct ? ' — household discount available: ' + hit.chart.household_discount_pct + '%' : '');
  } else {
    premEl.style.borderColor = '';
    premEl.title = '';
  }
}

function qbReRate_() {
  for (let i = 0; i < QB_MAX_OPTIONS; i++) qbAutoRateOption_(i);
}

function openQuoteReady_(q, contact) {
  const link = 'https://crm.thekannongroup.com/quote.html?q=' + q.id;
  showModal('Quote ready to send', `
    <p style="font-size:13px;">The client's page is live at:</p>
    <input type="text" value="${link}" readonly onclick="this.select()" style="width:100%;font-size:12px;" />
    <div style="display:flex;gap:8px;margin-top:14px;flex-wrap:wrap;">
      ${contact.email ? `<button class="btn btn-primary" onclick="sendQuote_('${q.id}', this)">&#9993; Email it to ${escWeb(contact.email)}</button>` : ''}
      <button class="btn btn-outline" onclick="navigator.clipboard.writeText('${link}').then(()=>showToast('Link copied.'))">Copy link</button>
      <a class="btn btn-outline" href="${link}" target="_blank" style="text-decoration:none;">Preview &#8599;</a>
    </div>
    <p style="font-size:11px;color:var(--text-muted);margin-top:12px;">Emailing uses the branded template and marks the quote as Sent. Copying the link (for a text message) — click "Mark as sent" after you share it.</p>
    <button class="btn btn-outline btn-sm" style="margin-top:4px;" onclick="markQuoteSent_('${q.id}', this)">Mark as sent (shared another way)</button>
  `, null, { hideConfirm: true });
}

// Sending a quote moves the deal to its pipeline's "quoted" stage —
// forward only, never backward (an Enrolled client stays Enrolled).
const QUOTE_SENT_STAGE = {
  'individual-family': 'Quoted',
  'group-employer': 'Proposal',
  'medicare': 'Plan Comparison',
};

async function advanceDealOnQuoteSent_(quoteId) {
  try {
    const { data: q } = await supabaseClient.from('quotes').select('deal_id').eq('id', quoteId).single();
    if (!q || !q.deal_id) return;
    const deal = deals.find(d => d.id === q.deal_id);
    if (!deal) return;
    const target = QUOTE_SENT_STAGE[deal.pipeline];
    if (!target || deal.stage === target) return;
    const stages = (PIPELINES[deal.pipeline] || {}).stages || [];
    if (stages.indexOf(deal.stage) >= stages.indexOf(target)) return;
    const { error } = await supabaseClient.from('deals').update({ stage: target }).eq('id', deal.id);
    if (error) return;
    deal.stage = target;
    showToast((deal.title || 'Deal') + ' advanced to "' + target + '".');
    try { renderPipelines(); } catch (e) {}
  } catch (e) { console.error('advanceDealOnQuoteSent_:', e); }
}

async function sendQuote_(quoteId, btn) {
  if (btn) { btn.disabled = true; btn.textContent = 'Sending…'; }
  const { error } = await supabaseClient.from('quotes')
    .update({ status: 'sent', sent_at: new Date().toISOString() }).eq('id', quoteId);
  if (error) { showToast('Error: ' + error.message); if (btn) { btn.disabled = false; } return; }
  try { fetch(APPS_SCRIPT_URL + '?action=send_quote&quote_id=' + quoteId, { mode: 'no-cors' }); } catch (e) {}
  showToast('Quote email is on its way.');
  if (btn) btn.textContent = '\u2713 Sent';
  advanceDealOnQuoteSent_(quoteId);
}

async function markQuoteSent_(quoteId, btn) {
  const { error } = await supabaseClient.from('quotes')
    .update({ status: 'sent', sent_at: new Date().toISOString() }).eq('id', quoteId);
  if (error) { showToast('Error: ' + error.message); return; }
  showToast('Marked as sent.');
  if (btn) btn.textContent = '\u2713 Marked sent';
  advanceDealOnQuoteSent_(quoteId);
}

// ============================================================
// GROUP CENSUS — request -> employer completes company profile +
// census at census.html?c=<uuid> (template / smart upload / manual)
// ============================================================
async function loadBaaLine_(deal) {
  // Latest BAA for this deal's contact + whether it matches the active version
  const dealContactId = deal.contact_id;
  if (!dealContactId) return '';
  const { data: av } = await supabaseClient.from('baa_versions')
    .select('id,version').eq('is_active', true).order('version', { ascending: false }).limit(1);
  const activeVer = av && av[0];
  const { data: recs } = await supabaseClient.from('baa_records')
    .select('id,status,signed_at,signer_name,baa_version_id,baa_versions(version)')
    .eq('contact_id', dealContactId).order('created_at', { ascending: false }).limit(5);
  if (!recs || !recs.length) return '';
  const signed = recs.find(x => x.status === 'signed');
  const pending = recs.find(x => x.status === 'pending');
  let line = '<div style="margin-top:6px;padding-top:6px;border-top:0.5px dashed var(--border);">&#128274; HIPAA BAA: ';
  if (signed) {
    const sv = signed.baa_versions ? signed.baa_versions.version : '?';
    line += '<span style="color:var(--success);font-weight:600;">&#10003; signed v' + sv + '</span> '
      + new Date(signed.signed_at).toLocaleDateString() + ' by ' + escWeb(signed.signer_name || '')
      + ' &middot; <a href="baa.html?b=' + signed.id + '" target="_blank">view / print &#8599;</a>';
    if (activeVer && signed.baa_version_id !== activeVer.id) {
      line += '<br><span style="color:#f59e0b;font-weight:600;">&#9888; Master agreement updated to v' + activeVer.version + '</span>'
        + (pending ? ' &mdash; re-signature pending.' : ' &middot; <a href="#" onclick="requestBaaResign_(\'' + deal.id + '\'); return false;">request re-signature</a>');
    }
  } else if (pending) {
    line += '<span style="color:#f59e0b;">pending signature</span>'
      + ' &middot; <a href="baa.html?b=' + pending.id + '" target="_blank">open &#8599;</a>'
      + ' &middot; <a href="#" onclick="resendBaa_(\'' + pending.id + '\', this); return false;">resend email</a>';
  }
  return line + '</div>';
}

async function requestBaaResign_(dealId) {
  const deal = deals.find(d => d.id === dealId); if (!deal) return;
  const contact = contacts.find(c => c.id === deal.contact_id);
  if (!contact || !contact.email) { showToast('Contact needs an email on file.'); return; }
  const { data: av } = await supabaseClient.from('baa_versions')
    .select('id').eq('is_active', true).order('version', { ascending: false }).limit(1);
  if (!av || !av.length) { showToast('No active BAA version found.'); return; }
  const { data: b, error } = await supabaseClient.from('baa_records').insert({
    baa_version_id: av[0].id, contact_id: contact.id, deal_id: deal.id,
    agent_id: currentAgent.id,
    agent_name: currentAgent.display_name || currentAgent.name,
    agent_email: currentAgent.email,
    company_legal_name: contact.company || null,
  }).select().single();
  if (error) { showToast('Error: ' + error.message); return; }
  try { fetch(APPS_SCRIPT_URL + '?action=send_baa&baa_id=' + b.id, { mode: 'no-cors' }); } catch (e) {}
  showToast('Updated agreement sent to ' + contact.email + ' for signature.');
  loadCensusStatus_(deal);
}

async function resendBaa_(baaId, a) {
  try { fetch(APPS_SCRIPT_URL + '?action=send_baa&baa_id=' + baaId, { mode: 'no-cors' }); } catch (e) {}
  showToast('Agreement email re-sent.');
  if (a) a.textContent = 'sent again ✓';
}

async function loadCensusStatus_(deal) {
  const el = document.getElementById('census-status-' + deal.id);
  if (!el) return;
  const { data: reqs } = await supabaseClient.from('census_requests')
    .select('*').eq('deal_id', deal.id).order('created_at', { ascending: false }).limit(1);
  const r = reqs && reqs[0];
  const baaLine = await loadBaaLine_(deal);
  if (!r) { el.innerHTML = 'No census requested yet — group quotes need one first.' + baaLine; return; }
  const link = 'https://crm.thekannongroup.com/census.html?c=' + r.id;
  if (r.status === 'submitted') {
    const { data: emps } = await supabaseClient.from('census_employees')
      .select('row_type,date_of_birth').eq('request_id', r.id);
    const ee = (emps || []).filter(x => x.row_type === 'employee');
    const deps = (emps || []).length - ee.length;
    const ages = ee.map(x => x.date_of_birth ? Math.floor((Date.now() - new Date(x.date_of_birth)) / 31557600000) : null).filter(a => a !== null);
    const avg = ages.length ? Math.round(ages.reduce((a, b) => a + b, 0) / ages.length) : null;
    el.innerHTML = '<span style="color:var(--success);font-weight:700;">&#10003; Census received</span> '
      + new Date(r.submitted_at).toLocaleDateString()
      + '<br><strong>' + escWeb(r.company_legal_name || '') + '</strong>'
      + (r.company_dba ? ' (dba ' + escWeb(r.company_dba) + ')' : '')
      + (r.sic_code ? ' &middot; SIC ' + escWeb(r.sic_code) : '')
      + ' &middot; ' + escWeb((r.company_state || '') + ' ' + (r.company_zip || ''))
      + '<br>' + ee.length + ' employees + ' + deps + ' dependents'
      + (avg !== null ? ' &middot; avg employee age ' + avg : '')
      + '<br>Contact: ' + escWeb(r.contact_name || '') + (r.contact_phone ? ' &middot; ' + escWeb(r.contact_phone) : '')
      + ' &middot; <a href="#" onclick="openCensusEditor(\'' + r.id + '\'); return false;">view / edit census</a>'
      + ' &middot; <a href="#" onclick="downloadCensusCsv_(\'' + r.id + '\', \'' + escWeb((r.company_legal_name || 'census').replace(/[^a-z0-9 ]/gi, '')) + '\'); return false;">download CSV</a>'
      + baaLine;
  } else {
    el.innerHTML = 'Requested ' + new Date(r.created_at).toLocaleDateString()
      + ' &mdash; waiting on the employer.'
      + '<br><a href="' + link + '" target="_blank">open form &#8599;</a>'
      + ' &middot; <a href="#" onclick="resendCensus_(\'' + r.id + '\', this); return false;">resend email</a>'
      + ' &middot; <a href="#" onclick="navigator.clipboard.writeText(\'' + link + '\').then(()=>showToast(\'Link copied.\')); return false;">copy link</a>'
      + baaLine;
  }
}

function openCensusRequest(dealId) {
  const deal = deals.find(d => d.id === dealId); if (!deal) return;
  const contact = contacts.find(c => c.id === deal.contact_id);
  if (!contact) { showToast('No contact linked to this deal.'); return; }
  showModal('Request Employee Census — ' + escWeb(contact.company || contact.name || ''), `
    <p style="font-size:13px;color:var(--text-muted);margin-bottom:10px;">
      The employer gets a branded email with a secure link. They confirm company details
      (legal name, DBA, SIC, address &mdash; the rate-determinant info carriers need), then build
      the census: upload any spreadsheet (we auto-read their columns), use our template, or type it in.
      Pre-fill whatever you already know &mdash; they'll see it filled in and only fix what's wrong.
    </p>
    <label>Legal company name</label><input type="text" id="cx-legal" value="${escWeb(contact.company || '')}" />
    <label>Recipient name</label><input type="text" id="cx-name" value="${escWeb(contact.name || '')}" />
    <label>Recipient email *</label><input type="text" id="cx-email" value="${escWeb(contact.email || '')}" />
    <label>Recipient phone</label><input type="text" id="cx-phone" value="${escWeb(contact.phone || '')}" />
    <label>State</label><input type="text" id="cx-state" maxlength="2" value="${escWeb(contact.state || '')}" />
    <label>City</label><input type="text" id="cx-city" value="${escWeb(contact.city || '')}" />
  `, async () => {
    const email = document.getElementById('cx-email').value.trim();
    if (!email) { showToast('Recipient email is required.'); return false; }
    const { data: r, error } = await supabaseClient.from('census_requests').insert({
      deal_id: deal.id, contact_id: contact.id, agent_id: currentAgent.id,
      agent_name: currentAgent.display_name || currentAgent.name,
      agent_email: currentAgent.email, agent_phone: currentAgent.phone || null,
      company_legal_name: document.getElementById('cx-legal').value.trim() || null,
      company_city: document.getElementById('cx-city').value.trim() || null,
      company_state: document.getElementById('cx-state').value.trim().toUpperCase() || null,
      contact_name: document.getElementById('cx-name').value.trim() || null,
      contact_phone: document.getElementById('cx-phone').value.trim() || null,
      contact_email: email,
    }).select().single();
    if (error) { showToast('Error: ' + error.message); return false; }
    // HIPAA: attach a BAA unless one is already signed on the ACTIVE version
    try {
      const { data: av } = await supabaseClient.from('baa_versions')
        .select('id,version').eq('is_active', true).order('version', { ascending: false }).limit(1);
      const activeVer = av && av[0];
      if (activeVer) {
        const { data: signed } = await supabaseClient.from('baa_records').select('id')
          .eq('contact_id', contact.id).eq('baa_version_id', activeVer.id).eq('status', 'signed').limit(1);
        if (!signed || !signed.length) {
          const { data: b } = await supabaseClient.from('baa_records').insert({
            baa_version_id: activeVer.id, contact_id: contact.id, deal_id: deal.id,
            agent_id: currentAgent.id,
            agent_name: currentAgent.display_name || currentAgent.name,
            agent_email: currentAgent.email,
            company_legal_name: document.getElementById('cx-legal').value.trim() || contact.company || null,
          }).select().single();
          if (b) await supabaseClient.from('census_requests').update({ baa_record_id: b.id }).eq('id', r.id);
        }
      }
    } catch (e) { console.error('BAA attach:', e); }
    try { fetch(APPS_SCRIPT_URL + '?action=send_census&census_id=' + r.id, { mode: 'no-cors' }); } catch (e) {}
    showToast('Census request sent to ' + email + ' (HIPAA agreement included if needed).');
    loadCensusStatus_(deal);
  }, { confirmLabel: 'Send Request' });
}

async function resendCensus_(reqId, a) {
  try { fetch(APPS_SCRIPT_URL + '?action=send_census&census_id=' + reqId, { mode: 'no-cors' }); } catch (e) {}
  showToast('Census email re-sent.');
  if (a) a.textContent = 'sent again \u2713';
}

async function downloadCensusCsv_(reqId, company) {
  const { data: emps } = await supabaseClient.from('census_employees')
    .select('*').eq('request_id', reqId).order('sort_order');
  if (!emps || !emps.length) { showToast('No census rows found.'); return; }
  const head = 'Name,Employee #,Date of Birth,Gender,Zip,Relationship,Class,Hours per Week\n';
  const csv = head + emps.map(e => [e.full_name, e.employee_number, e.date_of_birth, e.gender, e.zip, e.relationship, e.employee_class, e.hours_per_week]
    .map(v => '"' + String(v == null ? '' : v).replace(/"/g, '""') + '"').join(',')).join('\n');
  const a = document.createElement('a');
  a.href = 'data:text/csv;charset=utf-8,' + encodeURIComponent(csv);
  a.download = (company || 'census') + '-census.csv';
  a.click();
}

// ============================================================
// CENSUS EDITOR — agents view/edit a submitted census in the CRM
// (employers often forget people or fields; agents fix before
// sending to carriers). Public page stays locked after submit.
// ============================================================
function _ceRowHtml_(rowType, d) {
  d = d || {};
  const rel = d.relationship || (rowType === 'dependent' ? 'spouse' : 'employee');
  return `
    <td style="${rowType === 'dependent' ? 'padding-left:20px;' : ''}"><input type="text" class="f-name" value="${escWeb(d.full_name || '')}" placeholder="${rowType === 'dependent' ? '\u21b3 dependent name' : 'Full name'}" style="min-width:140px;" /></td>
    <td><input type="text" class="f-num" value="${escWeb(d.employee_number || '')}" style="width:65px;" /></td>
    <td><input type="date" class="f-dob" value="${escWeb(d.date_of_birth || '')}" style="width:135px;" /></td>
    <td><select class="f-gen" style="width:55px;"><option value=""></option><option value="M"${d.gender === 'M' ? ' selected' : ''}>M</option><option value="F"${d.gender === 'F' ? ' selected' : ''}>F</option></select></td>
    <td><input type="text" class="f-zip" value="${escWeb(d.zip || '')}" style="width:70px;" /></td>
    <td><select class="f-rel">
      <option value="employee"${rel === 'employee' ? ' selected' : ''}>Employee</option>
      <option value="spouse"${rel === 'spouse' ? ' selected' : ''}>Spouse</option>
      <option value="child"${rel === 'child' ? ' selected' : ''}>Child</option>
    </select></td>
    <td><input type="text" class="f-class" value="${escWeb(d.employee_class || '')}" style="width:80px;" /></td>
    <td><input type="text" class="f-hrs" value="${d.hours_per_week != null ? d.hours_per_week : ''}" style="width:50px;" /></td>
    <td><button type="button" onclick="this.closest('tr').remove(); ceTally_();" style="background:none;border:none;color:var(--danger);cursor:pointer;font-size:14px;" title="Remove">&#10005;</button></td>`;
}

function ceAddRow_(rowType, d) {
  const tb = document.getElementById('ce-rows');
  if (!tb) return;
  const tr = document.createElement('tr');
  tr.dataset.rowType = rowType;
  if (rowType === 'dependent') tr.style.background = 'var(--surface-1)';
  tr.innerHTML = _ceRowHtml_(rowType, d);
  tr.querySelector('.f-rel').addEventListener('change', function() {
    const isEmp = this.value === 'employee';
    tr.dataset.rowType = isEmp ? 'employee' : 'dependent';
    tr.style.background = isEmp ? '' : 'var(--surface-1)';
    ceTally_();
  });
  tb.appendChild(tr);
  ceTally_();
}

function ceTally_() {
  const el = document.getElementById('ce-tally');
  if (!el) return;
  const trs = [...document.querySelectorAll('#ce-rows tr')];
  const ee = trs.filter(t => t.dataset.rowType === 'employee').length;
  el.textContent = ee + ' employees, ' + (trs.length - ee) + ' dependents';
}

async function openCensusEditor(reqId) {
  const { data: r } = await supabaseClient.from('census_requests').select('*').eq('id', reqId).single();
  if (!r) { showToast('Census not found.'); return; }
  const { data: emps } = await supabaseClient.from('census_employees')
    .select('*').eq('request_id', reqId).order('sort_order');

  const cf = (label, id, val, ph) =>
    `<div><label style="display:block;font-size:10px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:.5px;margin:8px 0 3px;">${label}</label>
     <input type="text" id="${id}" value="${escWeb(val || '')}" placeholder="${ph || ''}" style="width:100%;box-sizing:border-box;" /></div>`;

  showModal('Census — ' + escWeb(r.company_legal_name || 'Group'), `
    <div style="padding:18px 22px;">
      <div style="font-size:12px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:.5px;">Company Profile</div>
      <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:0 14px;">
        ${cf('Legal name', 'ce-legal', r.company_legal_name)}
        ${cf('DBA', 'ce-dba', r.company_dba)}
        ${cf('SIC code', 'ce-sic', r.sic_code)}
        ${cf('Street', 'ce-street', r.company_street)}
        ${cf('City', 'ce-city', r.company_city)}
        ${cf('State', 'ce-state', r.company_state)}
        ${cf('Zip', 'ce-zip', r.company_zip)}
        ${cf('Contact name', 'ce-cname', r.contact_name)}
        ${cf('Contact title', 'ce-ctitle', r.contact_title)}
        ${cf('Contact phone', 'ce-cphone', r.contact_phone)}
        ${cf('Contact email', 'ce-cemail', r.contact_email)}
      </div>
      <div style="display:flex;justify-content:space-between;align-items:center;margin-top:18px;">
        <div style="font-size:12px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:.5px;">Census <span id="ce-tally" style="font-weight:400;text-transform:none;letter-spacing:0;"></span></div>
        <div style="display:flex;gap:6px;">
          <button type="button" class="btn btn-outline btn-sm" onclick="ceAddRow_('employee')">+ Employee</button>
          <button type="button" class="btn btn-outline btn-sm" onclick="ceAddRow_('dependent')">+ Dependent</button>
        </div>
      </div>
      <div style="overflow-x:auto;margin-top:8px;">
        <table style="width:100%;border-collapse:collapse;font-size:12px;">
          <thead><tr style="text-align:left;color:var(--text-muted);font-size:10px;text-transform:uppercase;">
            <th>Name</th><th>Emp #</th><th>DOB</th><th>Gen</th><th>Zip</th><th>Relationship</th><th>Class</th><th>Hrs</th><th></th>
          </tr></thead>
          <tbody id="ce-rows"></tbody>
        </table>
      </div>
      <div style="font-size:11px;color:var(--text-muted);margin-top:10px;">Edits are saved to the CRM record only — the employer's page stays locked to what they submitted. Use "download CSV" on the deal for the carrier-ready file after saving.</div>
    </div>
  `, async () => {
    const trs = [...document.querySelectorAll('#ce-rows tr')];
    for (const t of trs) {
      if (!t.querySelector('.f-name').value.trim() || !t.querySelector('.f-dob').value) {
        showToast('Every row needs a name and date of birth.'); return false;
      }
    }
    const g = id => document.getElementById(id).value.trim() || null;
    const { error: e1 } = await supabaseClient.from('census_requests').update({
      company_legal_name: g('ce-legal'), company_dba: g('ce-dba'), sic_code: g('ce-sic'),
      company_street: g('ce-street'), company_city: g('ce-city'),
      company_state: (g('ce-state') || '').toUpperCase() || null, company_zip: g('ce-zip'),
      contact_name: g('ce-cname'), contact_title: g('ce-ctitle'),
      contact_phone: g('ce-cphone'), contact_email: g('ce-cemail'),
    }).eq('id', reqId);
    if (e1) { showToast('Error: ' + e1.message); return false; }
    let lastEmp = '';
    const rows = trs.map((t, i) => {
      const name = t.querySelector('.f-name').value.trim();
      if (t.dataset.rowType === 'employee') lastEmp = t.querySelector('.f-num').value.trim() || name;
      return {
        request_id: reqId, row_type: t.dataset.rowType, employee_ref: lastEmp,
        full_name: name,
        employee_number: t.querySelector('.f-num').value.trim() || null,
        date_of_birth: t.querySelector('.f-dob').value || null,
        gender: t.querySelector('.f-gen').value || null,
        zip: t.querySelector('.f-zip').value.trim() || null,
        relationship: t.querySelector('.f-rel').value,
        employee_class: t.querySelector('.f-class').value.trim() || null,
        hours_per_week: parseFloat(t.querySelector('.f-hrs').value) || null,
        sort_order: i,
      };
    });
    const { error: e2 } = await supabaseClient.from('census_employees').delete().eq('request_id', reqId);
    if (e2) { showToast('Error: ' + e2.message); return false; }
    if (rows.length) {
      const { error: e3 } = await supabaseClient.from('census_employees').insert(rows);
      if (e3) { showToast('Error: ' + e3.message); return false; }
    }
    showToast('Census updated.');
    const deal = r.deal_id ? deals.find(d => d.id === r.deal_id) : null;
    if (deal) loadCensusStatus_(deal);
  }, { confirmLabel: 'Save Census', wide: true });

  (emps || []).forEach(e => ceAddRow_(e.row_type, e));
  if (!emps || !emps.length) ceAddRow_('employee');
}

// ============================================================
// HIPAA BAA — master version management (system owner)
// ============================================================
function openBaaVersionModal() {
  const cur = window._activeBaaVersion;
  const nextVer = cur ? cur.version + 1 : 1;
  showModal('Publish BAA Version ' + nextVer, `
    <div style="padding:16px 20px;">
      <div style="background:var(--bg-warning);border:1px solid var(--border-warning);border-radius:8px;padding:10px 14px;font-size:12px;color:var(--text-warning);margin-bottom:12px;">
        &#9888; Publishing replaces the active agreement. Every company that signed an older version will show
        <strong>"master agreement updated — request re-signature"</strong> on their deals, and all new census
        requests will carry version ${nextVer}. Have your attorney review changes before publishing.
      </div>
      <label style="display:block;font-size:11px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:.5px;margin-bottom:4px;">Title</label>
      <input type="text" id="bv-title" value="${cur ? escWeb(cur.title) : 'HIPAA Business Associate Agreement'}" style="width:100%;box-sizing:border-box;" />
      <label style="display:block;font-size:11px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:.5px;margin:10px 0 4px;">Effective date</label>
      <input type="date" id="bv-date" value="${new Date().toISOString().slice(0, 10)}" />
      <label style="display:block;font-size:11px;font-weight:700;color:var(--text-muted);text-transform:uppercase;letter-spacing:.5px;margin:10px 0 4px;">Agreement text (HTML paragraphs)</label>
      <textarea id="bv-body" rows="18" style="width:100%;box-sizing:border-box;font-family:monospace;font-size:11.5px;">${cur ? escWeb(cur.body_html) : ''}</textarea>
    </div>
  `, async () => {
    const body = document.getElementById('bv-body').value.trim();
    if (body.length < 500) { showToast('Agreement text looks too short — paste the full agreement.'); return false; }
    if (cur) {
      const { error: e0 } = await supabaseClient.from('baa_versions').update({ is_active: false }).eq('id', cur.id);
      if (e0) { showToast('Error: ' + e0.message); return false; }
    }
    const { error } = await supabaseClient.from('baa_versions').insert({
      version: nextVer,
      title: document.getElementById('bv-title').value.trim() || 'HIPAA Business Associate Agreement',
      body_html: body,
      effective_date: document.getElementById('bv-date').value || new Date().toISOString().slice(0, 10),
      is_active: true,
    });
    if (error) { showToast('Error: ' + error.message); return false; }
    showToast('BAA version ' + nextVer + ' is now active.');
    renderAdmin();
  }, { confirmLabel: 'Publish v' + nextVer, wide: true });
}

