// ============================================================
// ACA MARKETPLACE — household panel + official plans with the
// government-calculated subsidy (via the Apps Script relay).
// ============================================================
// Slots are fixed (0..9) but the agent sees "Option 1, 2, 3..." — after a
// delete in the middle those must renumber, or Option 4 stays "Option 4"
// while sitting third.
function qbOptionFilled_(i) {
  const nm = document.getElementById('qb-name-' + i);
  return !!((nm && nm.value.trim())
    || (window._qbAcaSel || {})[i] || (window._qbCmsSel || {})[i] || (window._qbMgSel || {})[i]);
}

function qbOptionNo_(slot) {
  let n = 0;
  for (let i = 0; i <= slot; i++) {
    const w = document.getElementById('qb-opt-wrap-' + i);
    if ((w && w.style.display !== 'none') || qbOptionFilled_(i)) n++;
  }
  return n;
}

// Hide any option that has nothing in it, except the first \u2014 there is always
// somewhere to type. Called after anything removes a plan.
function qbTidyOptions_() {
  const addBtn = document.getElementById('qb-add-opt');
  for (let i = QB_MAX_OPTIONS - 1; i >= 1; i--) {
    const w = document.getElementById('qb-opt-wrap-' + i);
    if (!w || w.style.display === 'none') continue;
    if (qbOptionFilled_(i)) continue;
    const note = document.getElementById('qb-note-' + i);
    const bul = document.getElementById('qb-bul-' + i);
    if ((note && note.value.trim()) || (bul && bul.value.trim())) continue;   // agent typed something
    w.style.display = 'none';
    const ol = document.getElementById('qb-optline-' + i);
    if (ol) ol.value = '';
  }
  if (addBtn) addBtn.style.display = '';
  qbRenumberOptions_();
  qbOptAutoFold_();
  qbGroupOptions_();
  qbSectionSummary_();
}

// A quote with eight options should not be eight screens of scrolling. Each
// option folds down to one line that says what it is; the one being worked on
// stays open. An agent's own choice always wins over the automatic behavior.
function qbOptToggle_(i, force) {
  window._qbOptOpen = window._qbOptOpen || {};
  const body = document.getElementById('qb-opt-body-' + i);
  if (!body) return;
  const open = force === undefined ? !(body.style.display !== 'none') : force;
  body.style.display = open ? '' : 'none';
  const chev = document.getElementById('qb-opt-chev-' + i);
  if (chev) chev.innerHTML = open ? '&#9662;' : '&#9656;';
  if (force === undefined) window._qbOptOpen[i] = open;   // they chose
  qbOptHeaderPaint_(i);
}

// The one-line identity: what this option is quoting, and for how much.
function qbOptHeaderPaint_(i) {
  const sum = document.getElementById('qb-opt-sum-' + i);
  if (!sum) return;
  const nm = (document.getElementById('qb-name-' + i) || {}).value || '';
  const prem = (document.getElementById('qb-prem-' + i) || {}).value || '';
  const line = (document.getElementById('qb-optline-' + i) || {}).value || '';
  const rec = (document.getElementById('qb-rec-' + i) || {}).checked;
  if (!nm.trim()) {
    sum.innerHTML = line
      ? '<span style="color:var(--text-muted);">' + escWeb(line) + ' \u00b7 nothing chosen yet</span>'
      : '<span style="color:var(--text-muted);">empty</span>';
    return;
  }
  sum.innerHTML = (rec ? '<span style="color:#b3903a;">\u2b50 </span>' : '')
    + '<strong>' + escWeb(nm) + '</strong>'
    + (prem ? ' <span style="color:var(--text-success);font-weight:700;">$' + escWeb(prem) + '/mo</span>' : '')
    + (line ? ' <span style="color:var(--text-muted);">\u00b7 ' + escWeb(line) + '</span>' : '');
}

// Once an option holds a plan it folds itself away, unless the agent has
// opened it. The first option and any empty one stay open to be filled in.
function qbOptAutoFold_() {
  window._qbOptOpen = window._qbOptOpen || {};
  let openCount = 0;
  for (let i = 0; i < QB_MAX_OPTIONS; i++) {
    const w = document.getElementById('qb-opt-wrap-' + i);
    if (!w || w.style.display === 'none') continue;
    const filled = qbOptionFilled_(i);
    const chosen = window._qbOptOpen[i];
    const open = chosen !== undefined ? chosen : !filled;
    qbOptToggle_(i, open);
    if (open) openCount++;
  }
  return openCount;
}

// Group the options by coverage type ON SCREEN ONLY. Saving reads options by
// their slot number, never by where they sit in the page, so nothing about the
// quote or the client's proposal changes \u2014 and the client's page was already
// sectioned by coverage type, so the two now agree.
function qbGroupOptions_() {
  const list = document.getElementById('qb-opt-list');
  const parked = document.getElementById('qb-opt-parked');
  if (!list || !parked) return;
  window._qbGrpOpen = window._qbGrpOpen || {};

  // Take every option out of its group FIRST. Removing the group boxes while
  // the options are still inside them destroys the options with them.
  for (let i = 0; i < QB_MAX_OPTIONS; i++) {
    const w = document.getElementById('qb-opt-wrap-' + i);
    if (w) parked.appendChild(w);
  }
  list.querySelectorAll('.qb-optgrp').forEach(el => el.remove());

  const groups = [];
  for (let i = 0; i < QB_MAX_OPTIONS; i++) {
    const w = document.getElementById('qb-opt-wrap-' + i);
    if (!w) continue;
    if (w.style.display === 'none') continue;
    const line = (document.getElementById('qb-optline-' + i) || {}).value || '';
    let g = groups.find(x => x.line === line);
    if (!g) { g = { line: line, slots: [] }; groups.push(g); }
    g.slots.push(i);
  }

  // one header per coverage type, in the order the options appear
  groups.forEach(g => {
    const key = g.line || '_none';
    const open = window._qbGrpOpen[key] !== false;
    let total = 0, priced = 0;
    g.slots.forEach(i => {
      const v = parseFloat((document.getElementById('qb-prem-' + i) || {}).value);
      if (!isNaN(v)) { total += v; priced++; }
    });
    const box = document.createElement('div');
    box.className = 'qb-optgrp';
    box.style.cssText = 'border:1px solid var(--border);border-radius:12px;margin-top:14px;overflow:hidden;';
    box.innerHTML = `
      <div style="display:flex;align-items:center;gap:9px;padding:9px 13px;background:var(--surface-2);cursor:pointer;"
           onclick="qbGroupToggle_('${escWeb(key)}')">
        <span style="font-size:11px;color:var(--text-muted);width:10px;">${open ? '&#9662;' : '&#9656;'}</span>
        <span style="font-size:11.5px;font-weight:800;text-transform:uppercase;letter-spacing:.5px;">
          ${g.line ? escWeb(g.line) : 'Coverage type not chosen yet'}</span>
        <span style="font-size:11px;color:var(--text-muted);">${g.slots.length} option${g.slots.length === 1 ? '' : 's'}</span>
        ${priced ? `<span style="margin-left:auto;font-size:11.5px;color:var(--text-muted);">${priced === g.slots.length ? '' : 'so far '}<strong style="color:var(--text-success);">$${total.toFixed(2)}</strong>/mo if they take all ${g.slots.length === 1 ? 'of it' : g.slots.length}</span>` : ''}
      </div>
      <div class="qb-optgrp-body" style="padding:0 13px 13px;${open ? '' : 'display:none;'}"></div>`;
    list.appendChild(box);
    const body = box.querySelector('.qb-optgrp-body');
    g.slots.forEach(i => {
      const w = document.getElementById('qb-opt-wrap-' + i);
      w.style.border = 'none';
      w.style.borderRadius = '0';
      w.style.padding = '10px 0 0';
      w.style.borderTop = body.children.length ? '1px solid var(--border)' : 'none';
      body.appendChild(w);
    });
  });
}

function qbGroupToggle_(key) {
  window._qbGrpOpen = window._qbGrpOpen || {};
  window._qbGrpOpen[key] = window._qbGrpOpen[key] === false;
  qbGroupOptions_();
}

function qbRenumberOptions_() {
  let n = 0;
  for (let i = 0; i < QB_MAX_OPTIONS; i++) {
    const w = document.getElementById('qb-opt-wrap-' + i);
    if (!w) continue;
    if (w.style.display === 'none' && qbOptionFilled_(i)) w.style.display = 'block';   // never hide a filled option
    if (w.style.display === 'none') continue;
    n++;
    const chip = document.getElementById('qb-opt-no-' + i);
    const lbl = document.getElementById('qb-opt-label-' + i);
    if (chip) chip.textContent = n;
    if (lbl) lbl.textContent = 'Option ' + n;
    qbOptHeaderPaint_(i);
  }
}

function qbRevealOption_() {
  for (let i = 1; i < QB_MAX_OPTIONS; i++) {
    const w = document.getElementById('qb-opt-wrap-' + i);
    if (w && w.style.display === 'none') {
      w.style.display = 'block';
      if (i === QB_MAX_OPTIONS - 1) document.getElementById('qb-add-opt').style.display = 'none';
      qbRenumberOptions_();
      qbOptFields_(i);
      qbGroupOptions_();
      return;
    }
  }
}

function qbHideOption_(i) {
  const w = document.getElementById('qb-opt-wrap-' + i);
  if (!w) return;
  w.style.display = 'none';
  // clear its fields so a hidden option never sneaks into the quote
  ['qb-name-' + i, 'qb-prem-' + i, 'qb-bul-' + i, 'qb-note-' + i].forEach(id => {
    const el = document.getElementById(id); if (el) el.value = '';
  });
  const rec = document.getElementById('qb-rec-' + i); if (rec) rec.checked = false;
  delete (window._qbAcaSel || {})[i];
  delete (window._qbCmsSel || {})[i];
  delete (window._qbMgSel || {})[i];
  const addBtn = document.getElementById('qb-add-opt'); if (addBtn) addBtn.style.display = '';
  // a hidden slot must also drop its picker link, or the plan still reads as chosen
  const sel = document.getElementById('qb-aca-' + i); if (sel) sel.value = '';
  if (window._qbAcaSel) delete window._qbAcaSel[i];
  qbAcaOptionView_(i);
  qbRenumberOptions_();
  qbAcaRenderBrowser_();
  if (document.getElementById('qb-aca-picker')) renderPickerBody_();
}

// Shared shaper for finder results (NPPES uniform shape, legacy-tolerant).
// Client's zip area floats to the top, then A-Z.
function acaShapeProviders_(raw, clientZip) {
  const items = (Array.isArray(raw) ? raw : (raw.providers || raw.suggestions || [])).map(x => {
    const o = x.provider || x;
    if (o.ptype) {
      const where = [o.street, o.city, o.state].filter(Boolean).join(', ');
      const isFac = o.ptype === 'Facility';
      return { key: o.npi, zip: o.zip || '', cleanName: o.name, isFac: isFac,
        city: o.city || '', state: o.state || '', street: o.street || '', taxonomy: o.taxonomy || '',
        name: (isFac ? '\u{1F3E5} ' : '') + o.name + (o.taxonomy ? ' \u00b7 ' + o.taxonomy : '') + (where ? ' \u00b7 ' + where : '') };
    }
    const nm = typeof o.name === 'object' && o.name ? [o.name.first, o.name.last].filter(Boolean).join(' ') : (o.name || '');
    return { key: o.npi, zip: '', cleanName: nm, isFac: false, city: '', state: '', street: '', taxonomy: o.taxonomy || '',
      name: nm + (o.taxonomy ? ' \u00b7 ' + o.taxonomy : '') };
  }).filter(x => x.key && x.cleanName);
  const z3 = String(clientZip || '').slice(0, 3);
  items.sort((a, b) =>
    ((z3 && a.zip.slice(0, 3) === z3 ? 0 : 1) - (z3 && b.zip.slice(0, 3) === z3 ? 0 : 1))
    || String(a.cleanName).localeCompare(String(b.cleanName)));
  return items;
}

async function acaProxy_(action, params) {
  const qs = Object.keys(params).map(k => k + '=' + encodeURIComponent(params[k])).join('&');
  const res = await fetch(APPS_SCRIPT_URL + '?action=' + action + '&' + qs);
  return res.json();
}

function qbAcaMemberRow_(m) {
  const wrap = document.getElementById('qb-aca-members');
  const n = wrap.children.length;
  const div = document.createElement('div');
  div.style.cssText = 'display:flex;gap:10px;align-items:center;margin-top:4px;font-size:12.5px;flex-wrap:wrap;';
  div.innerHTML = `
    <select class="aca-rel" style="width:auto;" ${n === 0 ? 'disabled' : ''}>
      <option value="Self" ${(m.relationship || 'Self') === 'Self' ? 'selected' : ''}>Client</option>
      <option value="Spouse" ${m.relationship === 'Spouse' ? 'selected' : ''}>Spouse</option>
      <option value="Child" ${m.relationship === 'Child' ? 'selected' : ''}>Child</option>
    </select>
    <span>Age <input type="number" class="aca-age" value="${m.age != null ? m.age : ''}" style="width:60px;" /></span>
    <select class="aca-gen" style="width:auto;">
      <option value="M" ${m.gender !== 'F' ? 'selected' : ''}>M</option>
      <option value="F" ${m.gender === 'F' ? 'selected' : ''}>F</option>
    </select>
    <label style="display:flex;gap:5px;align-items:center;font-weight:400;margin:0;"><input type="checkbox" class="aca-tob" style="width:auto;" ${m.uses_tobacco ? 'checked' : ''}/> Tobacco</label>
    <label style="display:flex;gap:5px;align-items:center;font-weight:400;margin:0;" title="Uncheck if this person is NOT applying for this coverage (they still count for the subsidy math)"><input type="checkbox" class="aca-app" style="width:auto;" ${m.applying === false ? '' : 'checked'}/> Applying</label>
    <label style="display:flex;gap:5px;align-items:center;font-weight:400;margin:0;" title="Check if this person has other coverage (job plan, Medicare, Medicaid) — it affects the household's tax credit"><input type="checkbox" class="aca-mec" style="width:auto;" ${m.has_mec ? 'checked' : ''}/> Other cov.</label>
    ${n > 0 ? '<button type="button" onclick="this.parentElement.remove()" style="background:none;border:none;color:var(--danger);cursor:pointer;">&#10005;</button>' : ''}`;
  wrap.appendChild(div);
}

function qbAcaAddMember_() { qbAcaMemberRow_({ relationship: 'Spouse' }); }

document.addEventListener('change', function(e) {
  if (e.target && e.target.id === 'qb-aca-ichra') {
    const w = document.getElementById('qb-aca-ichra-amt-wrap');
    if (w) w.style.display = e.target.value === 'yes' ? 'inline' : 'none';
  }
});

async function qbAcaInit_() {
  window._qbAcaIncomeDirty = false;   // fresh strip — prefills may fill it again
  const c = window._qbContact;
  document.getElementById('qb-aca-members').innerHTML = '';
  const age = c && c.date_of_birth ? Math.floor((Date.now() - new Date(c.date_of_birth + 'T12:00:00')) / 31557600000) : null;
  qbAcaMemberRow_({ relationship: 'Self', age: age, gender: c && c.gender, uses_tobacco: c && c.tobacco_use });
  const zipEl = document.getElementById('qb-aca-zip');
  if (zipEl) zipEl.value = (c && c.zip) || '';
  if (!(await qbAcaLoadCounties_())) return;
  window._qbAcaDocs = []; window._qbAcaMeds = []; window._qbListsFilled = false;
  qbAcaRenderChips_();
  qbAcaSepStatus_(null, null);
  qbAcaPrefillFromIntake_();
}

async function qbAcaLoadCounties_() {
  const c = window._qbContact;
  const countySel = document.getElementById('qb-aca-county');
  const res = document.getElementById('qb-aca-result');
  if (!countySel) return false;
  countySel.innerHTML = '<option value="">loading\u2026</option>';
  if (!c || !c.zip) {
    countySel.innerHTML = '<option value="">need a ZIP</option>';
    if (res) res.innerHTML = '<span style="color:#f59e0b;">Enter a ZIP code above for marketplace lookups.</span>';
    return false;
  }
  try {
    const data = await acaProxy_('aca_counties', { zip: c.zip });
    if (data.status !== 'ok') {
      countySel.innerHTML = '<option value="">unavailable</option>';
      if (res) res.innerHTML = '<span style="color:#f59e0b;">' + escWeb(data.message || 'Marketplace lookup failed.') + '</span>';
      return false;
    }
    countySel.innerHTML = data.counties.map(x =>
      `<option value="${escWeb(x.fips)}|${escWeb(x.state)}">${escWeb(x.name)}, ${escWeb(x.state)}</option>`).join('');
    if (res) res.textContent = '';
    return true;
  } catch (e) {
    countySel.innerHTML = '<option value="">unavailable</option>';
    if (res) res.innerHTML = '<span style="color:#f59e0b;">Marketplace relay unreachable \u2014 is the API key set up?</span>';
    return false;
  }
}

// ZIP is the agent's real handle on a client: it decides state, county and
// pricing. Editing it here updates the contact card and the intake too.
async function qbAcaZipChanged_() {
  const el = document.getElementById('qb-aca-zip');
  const c = window._qbContact;
  const zip = String((el && el.value) || '').trim();
  if (!c) return;
  if (!/^\d{5}$/.test(zip)) { showToast('Enter a 5-digit ZIP code.'); if (el) el.value = c.zip || ''; return; }
  if (zip === c.zip) return;
  const st = zipToState_(zip);
  c.zip = zip; if (st) c.state = st;
  const patch = st ? { zip: zip, state: st } : { zip: zip };
  try {
    await supabaseClient.from('contacts').update(patch).eq('id', c.id);
    const cc = contacts.find(x => x.id === c.id); if (cc) Object.assign(cc, patch);
  } catch (e) { console.error('zip->contact:', e); }
  try {
    const row = await qbAcaIntakeRow_(['zip']);
    if (row) {
      const resp = Object.assign({}, row.responses, { zip: zip });
      await supabaseClient.from('intake_sessions').update({ responses: resp }).eq('id', row.id).select('id');
    }
  } catch (e) { console.error('zip->intake:', e); }
  await qbAcaLoadCounties_();
  const note = document.getElementById('qb-aca-intake-note');
  if (note) {
    note.style.display = 'block'; note.style.color = '#0d9488';
    note.innerHTML = '\u2713 ZIP set to ' + escWeb(zip) + (st ? ' (' + escWeb(st) + ')' : '')
      + ' \u2014 saved to their contact card and intake. Re-price to refresh the plans.';
  }
}


const ACA_INCOME_MIDPOINTS = {
  'Under $25,000': 20000, '$25,000\u2013$50,000': 37500, '$50,000\u2013$75,000': 62500,
  '$75,000\u2013$100,000': 87500, 'Over $100,000': 110000,
  'Under $20k': 15000, '$20k\u2013$40k': 30000, '$40k\u2013$60k': 50000,
  '$60k\u2013$80k': 70000, '$80k\u2013$100k': 90000, '$100k+': 110000,
};

// Federal ACA enrollment windows: OEP Nov 1 \u2013 Jan 15; otherwise a
// Qualifying Life Event opens a 60-day Special Enrollment Period.
const ACA_QLE_OPTIONS = ['No \u2014 none of these', 'Lost other health coverage', 'Moved to a new area',
  'Got married', 'Had or adopted a baby', 'Divorce or legal separation (lost coverage)',
  'Lost Medicaid/CHIP eligibility', 'Left incarceration', 'Gained citizenship or lawful presence',
  'Other qualifying life change'];

// The agent can correct enrollment timing here instead of digging back into
// the intake; edits flow back to the intake record that supplied them.
async function qbAcaTimingChanged_() {
  const start = (document.getElementById('qb-aca-start') || {}).value || '';
  const qle = (document.getElementById('qb-aca-qle') || {}).value || '';
  const qleDate = (document.getElementById('qb-aca-qle-date') || {}).value || '';
  qbAcaSepStatus_(qle, qleDate, start);
  try {
    const row = await qbAcaIntakeRow_(['coverage_start_date', 'aca_qle', 'aca_qle_date']);
    if (!row) return;
    const resp = Object.assign({}, row.responses, {
      coverage_start_date: start || null, aca_qle: qle || null, aca_qle_date: qleDate || null,
    });
    const { data: ok } = await supabaseClient.from('intake_sessions')
      .update({ responses: resp }).eq('id', row.id).select('id');
    const note = document.getElementById('qb-aca-intake-note');
    if (ok && ok.length && note) {
      note.style.display = 'block'; note.style.color = 'var(--text-success)';
      note.textContent = '\u2713 Coverage timing saved back to their intake record.';
    }
  } catch (e) { console.error('qbAcaTimingChanged_:', e); }
}

function qbAcaSepStatus_(qle, qleDate, startDate) {
  const el = document.getElementById('qb-aca-sep');
  if (!el) return;
  // keep the editable fields in step with whatever was passed in
  const sEl = document.getElementById('qb-aca-start');
  const qEl = document.getElementById('qb-aca-qle');
  const qdEl = document.getElementById('qb-aca-qle-date');
  if (sEl && startDate && !sEl.value) sEl.value = startDate;
  if (qEl && qle && [...qEl.options].some(o => o.value === qle)) qEl.value = qle;
  if (qdEl && qleDate && !qdEl.value) qdEl.value = qleDate;
  startDate = (sEl && sEl.value) || startDate;
  qle = (qEl && qEl.value) || qle;
  qleDate = (qdEl && qdEl.value) || qleDate;

  const hasEvent = qle && !/^no\b/i.test(qle);
  const wrap = document.getElementById('qb-aca-qled-wrap');
  if (wrap) wrap.style.display = hasEvent ? '' : 'none';

  const now = new Date();
  const y = now.getFullYear();
  const inOEP = (now >= new Date(y, 10, 1)) || (now <= new Date(y, 0, 15, 23, 59, 59));
  const ok = t => '<span style="color:var(--text-success);font-weight:700;">' + t + '</span>';
  const warn = t => '<span style="color:var(--text-warning);font-weight:700;">' + t + '</span>';

  if (!inOEP && startDate) {
    const nextJan1 = new Date(now < new Date(y, 0, 16) ? y : y + 1, 0, 1);
    if (new Date(startDate + 'T12:00:00') >= nextJan1) {
      el.innerHTML = ok('\u{1F7E2} Coverage starting ' + new Date(startDate + 'T12:00:00').toLocaleDateString()
        + ' \u2014 Open Enrollment (opens Nov 1) covers that. No life event needed.');
      return;
    }
  }
  if (inOEP) {
    el.innerHTML = ok('\u{1F7E2} Open Enrollment is ON (Nov 1 \u2013 Jan 15) \u2014 anyone can enroll.');
    return;
  }
  let html = warn('\u{1F7E0} Outside Open Enrollment \u2014 enrolling requires a Qualifying Life Event (Special Enrollment Period).');
  if (hasEvent) {
    if (qleDate) {
      const d = new Date(qleDate + 'T12:00:00');
      const end = new Date(d.getTime() + 60 * 86400000);
      html += now <= end
        ? '<br><span style="color:var(--text-success);font-weight:600;">\u2713 SEP on file: ' + escWeb(qle) + ' (' + d.toLocaleDateString() + ') \u2014 their 60-day enrollment window runs through <strong>' + end.toLocaleDateString() + '</strong>.</span>'
        : '<br><span style="color:var(--text-danger);font-weight:600;">\u2717 Reported event: ' + escWeb(qle) + ' (' + d.toLocaleDateString() + ') \u2014 the 60-day window CLOSED ' + end.toLocaleDateString() + '. A new event (or Open Enrollment) is needed.</span>';
    } else {
      html += '<br>' + warn('Reported event: ' + escWeb(qle) + ' \u2014 add the event DATE to confirm the 60-day window.');
    }
  } else {
    html += '<br><span style="color:var(--text-muted);">No qualifying event on file \u2014 ask about: lost coverage, a move, marriage, a new baby, loss of Medicaid, and similar life changes.</span>';
  }
  el.innerHTML = html;
}

// The intake is the client's original answers; the last quote is what the agent
// actually priced. For a re-quote the latter is the truth worth restoring.
async function qbAcaPrefillFromLastQuote_() {
  const c = window._qbContact; if (!c) return;
  try {
    const { data } = await supabaseClient.from('quotes')
      .select('quote_inputs,created_at').eq('contact_id', c.id)
      .not('quote_inputs', 'is', null)
      .order('created_at', { ascending: false }).limit(1);
    const qi = data && data[0] && data[0].quote_inputs;
    if (!qi) return;
    // Income deliberately NOT restored here: qbAcaSyncIncomeToIntake_ keeps the
    // intake current on every re-price, so the intake prefill is the fresher
    // source. Restoring an older quote's figure re-introduced stale income.
    const inc = document.getElementById('qb-aca-income');
    if (window._qbAcaIncomeDirty || !inc || inc.value) return;
    if (qi.income != null) inc.value = qi.income;
  } catch (e) { console.error('qbAcaPrefillFromLastQuote_:', e); }
}

// ── Client profile ────────────────────────────────────────────────────────
// Income, household, doctors and medications are facts about the CLIENT, so
// they live on the contact row. The intake stays a point-in-time record of
// what they answered; we read the contact first and only fall back to intake
// answers for clients whose profile hasn't been filled in yet.
function _cpArr_(v) {
  if (Array.isArray(v)) return v;
  if (typeof v === 'string' && v.trim().startsWith('[')) { try { return JSON.parse(v); } catch (e) {} }
  return [];
}

async function qbSaveClientProfile_(patch) {
  const c = window._qbContact;
  if (!c || !patch || !Object.keys(patch).length) return false;
  patch.profile_updated_at = new Date().toISOString();
  try {
    const { data, error } = await supabaseClient.from('contacts')
      .update(patch).eq('id', c.id).select('id');
    if (error || !data || !data.length) { console.error('profile save:', error); return false; }
    Object.assign(c, patch);
    const cached = contacts.find(x => x.id === c.id);
    if (cached) Object.assign(cached, patch);
    return true;
  } catch (e) { console.error('profile save:', e); return false; }
}

// Load the client's doctors and medications from their own tables. Cached on
// the contact object for the life of the dialog.
async function qbLoadClientLists_() {
  const c = window._qbContact;
  if (!c) return { providers: [], medications: [] };
  try {
    const [pv, md] = await Promise.all([
      supabaseClient.from('client_providers').select('npi,name').eq('contact_id', c.id)
        .eq('is_active', true).order('created_at'),
      supabaseClient.from('client_medications').select('rxcui,name,quantity,doses_per_day,days_supply')
        .eq('contact_id', c.id).eq('is_active', true).order('created_at'),
    ]);
    c._providers = pv.data || [];
    c._medications = md.data || [];
  } catch (e) { console.error('client lists:', e); c._providers = c._providers || []; c._medications = c._medications || []; }
  return { providers: c._providers, medications: c._medications };
}

// Replace the client's saved set with what's on screen (add/remove in one go)
async function qbSaveClientLists_() {
  const c = window._qbContact;
  if (!c) return;
  const docs = (window._qbAcaDocs || []).filter(d => d.npi);
  const meds = (window._qbAcaMeds || []).filter(m => m.rxcui);
  try {
    await supabaseClient.from('client_providers').delete().eq('contact_id', c.id);
    if (docs.length) {
      await supabaseClient.from('client_providers').insert(docs.map(d => ({
        contact_id: c.id, npi: String(d.npi), name: d.name || '(unnamed)', source: 'quote',
      })));
    }
    await supabaseClient.from('client_medications').delete().eq('contact_id', c.id);
    if (meds.length) {
      await supabaseClient.from('client_medications').insert(meds.map(m => ({
        contact_id: c.id, rxcui: String(m.rxcui), name: m.name || '(unnamed)', source: 'quote',
        days_supply: qbMedDays_(m),
        quantity: m.quantity == null ? null : Number(m.quantity),
        doses_per_day: m.doses_per_day == null ? null : Number(m.doses_per_day),
      })));
    }
    c._providers = docs.map(d => ({ npi: String(d.npi), name: d.name }));
    c._medications = meds.map(m => ({ rxcui: String(m.rxcui), name: m.name,
      days_supply: qbMedDays_(m), quantity: m.quantity == null ? null : Number(m.quantity),
      doses_per_day: m.doses_per_day == null ? null : Number(m.doses_per_day) }));
    return true;
  } catch (e) { console.error('save client lists:', e); return false; }
}

// Everything the ACA strip needs, read from the client record
function qbClientProfile_() {
  const c = window._qbContact || {};
  return {
    income: (c.household_income != null && c.household_income !== '') ? Number(c.household_income) : null,
    household: _cpArr_(c.household_members),
    providers: c._providers || [],
    medications: c._medications || [],
  };
}

// Read the client profile into the strip. Returns what it managed to fill so
// qbAcaPrefillFromIntake_ knows which gaps are left for the intake to cover.
function qbApplyClientProfile_() {
  const prof = qbClientProfile_();
  const filled = { income: false, household: false, providers: false, medications: false };

  const incEl = document.getElementById('qb-aca-income');
  if (incEl && !incEl.value && !window._qbAcaIncomeDirty && prof.income != null) {
    incEl.value = prof.income; filled.income = true;
  }
  if (prof.household.length) {
    const wrap = document.getElementById('qb-aca-members');
    if (wrap) {
      const c = window._qbContact || {};
      wrap.innerHTML = '';
      prof.household.forEach((m, i) => qbAcaMemberRow_({
        relationship: i === 0 ? 'Self' : (m.relationship === 'Spouse' ? 'Spouse' : (m.relationship || 'Child')),
        age: m.age,
        gender: m.gender === 'F' ? 'F' : (m.gender === 'M' ? 'M' : (c.gender || '')),
        uses_tobacco: !!m.tobacco,
        applying: m.covered !== false,
        has_mec: !!m.has_mec,
      }));
      filled.household = true;
    }
  }
  if (prof.providers.length) {
    window._qbAcaDocs = prof.providers.filter(d => d.npi).map(d => ({ npi: d.npi, name: d.name }));
    filled.providers = !!window._qbAcaDocs.length;
  }
  if (prof.medications.length) {
    window._qbAcaMeds = prof.medications.filter(m => m.rxcui)
      .map(m => ({ rxcui: m.rxcui, name: m.name, days_supply: qbMedDays_(m), quantity: m.quantity, doses_per_day: m.doses_per_day }));
    filled.medications = !!window._qbAcaMeds.length;
  }
  if (filled.providers || filled.medications) qbAcaRenderChips_();
  return filled;
}

// Read the household rows back out of the strip in profile shape
function qbReadHouseholdRows_() {
  return [...document.querySelectorAll('#qb-aca-members > div')].map(d => ({
    relationship: d.querySelector('.aca-rel') ? d.querySelector('.aca-rel').value : null,
    age: d.querySelector('.aca-age') ? parseInt(d.querySelector('.aca-age').value) : null,
    gender: d.querySelector('.aca-gen') ? d.querySelector('.aca-gen').value : null,
    tobacco: d.querySelector('.aca-tob') ? d.querySelector('.aca-tob').checked : false,
    covered: d.querySelector('.aca-app') ? d.querySelector('.aca-app').checked : true,
    has_mec: d.querySelector('.aca-mec') ? d.querySelector('.aca-mec').checked : false,
  })).filter(m => !isNaN(m.age) && m.age != null);
}

async function qbAcaPrefillFromIntake_() {
  const c = window._qbContact;
  if (!c) return;
  await qbLoadClientLists_();                    // doctors/meds from their tables
  const fromProfile = qbApplyClientProfile_();   // client record wins
  try {
    const { data: sess } = await supabaseClient.from('intake_sessions')
      .select('form_type,responses').eq('contact_id', c.id)
      .eq('status', 'completed').order('created_at', { ascending: false }).limit(5);
    const best = (sess || []).find(x => x.form_type === 'health-individual')
      || (sess || []).find(x => x.form_type === 'medicare');
    if (!best || !best.responses) return;
    const r = best.responses;
    const pulled = [];

    // Income (range midpoint — an estimate the agent can refine)
    const incEl = document.getElementById('qb-aca-income');
    if (incEl && !incEl.value && !fromProfile.income && r.aca_income) {
      const exact = parseFloat(String(r.aca_income).replace(/[^0-9.]/g, ''));
      if (!isNaN(exact) && exact >= 1000) {
        incEl.value = Math.round(exact);
        pulled.push('income ($' + Math.round(exact).toLocaleString() + ' from their intake)');
      } else if (ACA_INCOME_MIDPOINTS[r.aca_income]) {
        incEl.value = ACA_INCOME_MIDPOINTS[r.aca_income];
        pulled.push('income (midpoint of \u201c' + r.aca_income + '\u201d \u2014 refine if you know the exact figure)');
      }
    }

    // Household members: structured table wins outright
    let hhStruct = null;
    try { if (r.household_struct) hhStruct = JSON.parse(r.household_struct); } catch (e) {}
    if (hhStruct && hhStruct.length && !fromProfile.household) {
      const wrap = document.getElementById('qb-aca-members');
      wrap.innerHTML = '';
      hhStruct.forEach((m, i) => qbAcaMemberRow_({
        relationship: i === 0 ? 'Self' : (m.relationship === 'Spouse' ? 'Spouse' : 'Child'),
        age: m.age, gender: m.gender === 'F' ? 'F' : (m.gender === 'M' ? 'M' : (c.gender || '')),
        uses_tobacco: !!m.tobacco, applying: m.covered !== false,
        has_mec: false,
      }));
      const covered = hhStruct.filter(m => m.covered !== false).length;
      pulled.push('household (' + hhStruct.length + ' members, ' + covered + ' applying \u2014 from their table)');
    }
    // Household members from the ages list (legacy fallback)
    if (!(hhStruct && hhStruct.length) && r.member_ages) {
      const ages = String(r.member_ages).split(/[^0-9]+/).map(x => parseInt(x)).filter(n => n > 0 && n < 120);
      if (ages.length > 1) {
        const wrap = document.getElementById('qb-aca-members');
        const firstAge = wrap.querySelector('.aca-age') ? wrap.querySelector('.aca-age').value : '';
        wrap.innerHTML = '';
        qbAcaMemberRow_({ relationship: 'Self', age: firstAge || ages[0], gender: c.gender, uses_tobacco: c.tobacco_use });
        ages.slice(1).forEach((a, i) => qbAcaMemberRow_({ relationship: a >= 18 && i === 0 ? 'Spouse' : 'Child', age: a }));
        pulled.push('household (' + ages.length + ' members \u2014 check relationships)');
      }
    }

    // Medications: structured picks from the gold-plated intake win outright
    let structMeds = null, structDocs = null;
    try { if (r.med_medications_struct) structMeds = JSON.parse(r.med_medications_struct); } catch (e) {}
    try { if (r.med_doctors_struct) structDocs = JSON.parse(r.med_doctors_struct); } catch (e) {}
    if (structMeds && structMeds.length && !fromProfile.medications) {
      window._qbAcaMeds = structMeds.filter(m => m.rxcui)
        .map(m => ({ rxcui: m.rxcui, name: m.name, days_supply: qbMedDays_(m), quantity: m.quantity, doses_per_day: m.doses_per_day }));
      if (window._qbAcaMeds.length) pulled.push('medications (' + window._qbAcaMeds.length + ', exact picks from intake)');
    }
    if (structDocs && structDocs.length && !fromProfile.providers) {
      window._qbAcaDocs = structDocs.filter(d => d.npi).map(d => ({ npi: d.npi, name: d.name }));
      if (window._qbAcaDocs.length) pulled.push('doctors (' + window._qbAcaDocs.length + ', exact picks from intake)');
    }

    // Medications -> resolved chips (free-text fallback)
    if (!(structMeds && structMeds.length) && r.med_medications) {
      const terms = String(r.med_medications).split(/[\n,;]+/).map(x => x.trim()).filter(x => x.length > 2).slice(0, 4);
      for (const t of terms) {
        try {
          const resp = await acaProxy_('aca_drug_search', { q: t.split(' ')[0] });
          const raw = resp.data || [];
          const items = Array.isArray(raw) ? raw : (raw.drugs || raw.suggestions || []);
          const hit = items[0];
          if (hit && hit.rxcui) {
            window._qbAcaMeds = window._qbAcaMeds || [];
            const nm = (hit.name || hit.full_name || t) + (hit.strength ? ' ' + hit.strength : '');
            if (!window._qbAcaMeds.some(m => String(m.rxcui) === String(hit.rxcui)))
              window._qbAcaMeds.push({ rxcui: hit.rxcui, name: nm });
          }
        } catch (e) {}
      }
      if ((window._qbAcaMeds || []).length) pulled.push('medications (' + window._qbAcaMeds.length + ')');
    }

    // Doctors -> resolved chips (free-text fallback, matched near their zip)
    if (!(structDocs && structDocs.length) && r.med_doctors) {
      const terms = String(r.med_doctors).split(/[\n,;]+|\band\b/i).map(x => x.replace(/^dr\.?\s*/i, '').trim()).filter(x => x.length > 2).slice(0, 3);
      for (const t of terms) {
        try {
          const resp = await acaProxy_('aca_provider_search', { q: t, zip: c.zip || '' });
          const raw = resp.data || [];
          const items = Array.isArray(raw) ? raw : (raw.providers || raw.suggestions || []);
          const o = items[0] && (items[0].provider || items[0]);
          if (o && o.npi) {
            window._qbAcaDocs = window._qbAcaDocs || [];
            const nm = typeof o.name === 'object' && o.name ? [o.name.first, o.name.last].filter(Boolean).join(' ') : (o.name || t);
            if (!window._qbAcaDocs.some(d => String(d.npi) === String(o.npi)))
              window._qbAcaDocs.push({ npi: o.npi, name: nm });
          }
        } catch (e) {}
      }
      if ((window._qbAcaDocs || []).length) pulled.push('doctors (' + window._qbAcaDocs.length + ' \u2014 verify the match)');
    }

    if (r.aca_ichra_offer === 'Yes') {
      const sel = document.getElementById('qb-aca-ichra');
      if (sel) { sel.value = 'yes'; sel.dispatchEvent(new Event('change')); }
      const amt = document.getElementById('qb-aca-ichra-amt');
      if (amt && r.aca_ichra_amount) amt.value = r.aca_ichra_amount;
      pulled.push('ICHRA offer flagged');
    }
    if (r.aca_qle || r.coverage_start_date) {
      const sEl = document.getElementById('qb-aca-start');
      if (sEl && r.coverage_start_date) sEl.value = r.coverage_start_date;
      const qdEl = document.getElementById('qb-aca-qle-date');
      if (qdEl && r.aca_qle_date) qdEl.value = r.aca_qle_date;
      qbAcaSepStatus_(r.aca_qle || null, r.aca_qle_date || null, r.coverage_start_date || null);
      if (r.aca_qle && !/^no\b/i.test(r.aca_qle)) pulled.push('SEP life event');
    }
    if (r.aca_not_applying) {
      const note = document.getElementById('qb-aca-intake-note');
      if (note) { note.style.display = 'block';
        note.innerHTML = '&#9888; Intake note \u2014 not everyone is applying: \u201c' + escWeb(r.aca_not_applying) + '\u201d \u2014 uncheck \u201cApplying\u201d on those members.'; }
      pulled.push('who\u2019s-applying note');
    }
    if (pulled.length) {
      qbAcaRenderChips_();
      document.getElementById('qb-aca-matches').innerHTML =
        '<span style="color:#0d9488;">\u26a1 Pulled from their intake: ' + pulled.join(' \u00b7 ') + '. Remove anything that doesn\u2019t fit.</span>';
    }
    await qbAcaPrefillFromLastQuote_();
  } catch (e) { console.error('qbAcaPrefillFromIntake_:', e); }
}

// The finder lives in two places (quote strip + plan picker). One set of
// functions drives both: picker fields win whenever the picker is open.
function _acaFld_(base) {
  return document.getElementById('qbpk-' + base) || document.getElementById('qb-' + base);
}

function pkBasisToggle_() {
  window._qbPkBasisOpen = !window._qbPkBasisOpen;
  renderPickerBody_();
}

async function pkReprice_() {
  const pk = document.getElementById('qbpk-aca-income');
  const strip = document.getElementById('qb-aca-income');
  if (pk && strip && pk.value) strip.value = pk.value;
  window._qbPkBasisOpen = true;
  await qbAcaGetPlans_();
}

function pkBasisPanel_() {
  const open = !!window._qbPkBasisOpen;
  const docs = window._qbAcaDocs || [], meds = window._qbAcaMeds || [];
  const incEl = document.getElementById('qb-aca-income');
  const income = incEl ? incEl.value : '';
  const cSel = document.getElementById('qb-aca-county');
  const county = (cSel && cSel.options[cSel.selectedIndex]) ? cSel.options[cSel.selectedIndex].text : '';
  const rows = [...document.querySelectorAll('#qb-aca-members > div')];
  const applying = rows.filter(d => { const a = d.querySelector('.aca-app'); return !a || a.checked; }).length;
  const summary = [
    income ? '$' + Number(income).toLocaleString() + '/yr' : 'no income set',
    county,
    rows.length ? applying + ' of ' + rows.length + ' applying' : '',
    docs.length ? docs.length + ' doctor' + (docs.length > 1 ? 's' : '') : '',
    meds.length ? meds.length + ' medication' + (meds.length > 1 ? 's' : '') : '',
  ].filter(Boolean).join('  \u00b7  ');

  const head = `<button type="button" onclick="pkBasisToggle_()" style="width:100%;text-align:left;background:none;border:none;cursor:pointer;padding:9px 20px;display:flex;align-items:center;gap:10px;font-size:12.5px;color:var(--text-secondary);">
      <span style="font-weight:800;color:var(--text-primary);">${open ? '\u25BE' : '\u25B8'} What these plans are based on</span>
      <span style="color:var(--text-muted);">${escWeb(summary)}</span>
      <span style="margin-left:auto;color:var(--accent,#1d3557);font-weight:700;">${open ? 'Hide' : 'Edit'}</span>
    </button>`;
  if (!open) return `<div style="background:var(--surface-1);border-bottom:0.5px solid var(--border);">${head}</div>`;
  setTimeout(qbAcaRenderChips_, 0);   // paint chips once this HTML lands in the DOM

  return `<div style="background:var(--surface-1);border-bottom:0.5px solid var(--border);">
    ${head}
    <div style="padding:0 20px 14px;display:grid;grid-template-columns:minmax(220px,1fr) minmax(280px,1.4fr);gap:18px;align-items:start;">
      <div>
        <label style="font-size:10px;margin:0 0 3px;display:block;">Yearly household income ($)</label>
        <input type="number" id="qbpk-aca-income" value="${escWeb(income)}" style="width:150px;" />
        <div style="font-size:11.5px;color:var(--text-muted);margin-top:6px;line-height:1.5;">
          ${escWeb(county || 'County not set')}${rows.length ? ' \u00b7 ' + applying + ' of ' + rows.length + ' household members applying' : ''}
        </div>
        <button type="button" class="btn btn-primary btn-sm" style="margin-top:8px;" onclick="pkReprice_()">\u21bb Update plans list</button>
        <div style="font-size:11px;color:var(--text-muted);margin-top:6px;">Household members, ICHRA and life-event answers live in the quote dialog \u2014 close the picker to change those.</div>
      </div>
      <div>
        <div style="font-size:10px;font-weight:800;text-transform:uppercase;letter-spacing:.5px;color:var(--text-muted);margin-bottom:6px;">Doctors &amp; medications \u2014 add or remove, plans re-check instantly</div>
        <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;">
          <span><input type="text" id="qbpk-aca-doc-q" placeholder="Doctor, clinic or hospital" style="width:170px;" />
            <button type="button" class="btn btn-outline btn-sm" onclick="qbAcaSearch_('doc')">Find Provider/Facility</button></span>
          <span><input type="text" id="qbpk-aca-med-q" placeholder="Medication" style="width:140px;" />
            <button type="button" class="btn btn-outline btn-sm" onclick="qbAcaSearch_('med')">Find Medication</button></span>
        </div>
        <div id="qbpk-aca-matches" style="font-size:12px;margin-top:6px;"></div>
        <div id="qbpk-aca-chips" style="margin-top:6px;display:flex;gap:6px;flex-wrap:wrap;"></div>
        <div id="qbpk-sync-note" style="font-size:11px;color:#0d9488;margin-top:6px;"></div>
      </div>
    </div>
  </div>`;
}

// Latest completed intake carrying any of these answer keys
async function qbAcaIntakeRow_(keys) {
  const c = window._qbContact; if (!c) return null;
  const { data } = await supabaseClient.from('intake_sessions')
    .select('id,responses,form_type').eq('contact_id', c.id).eq('status', 'completed')
    .order('created_at', { ascending: false }).limit(5);
  const rows = data || [];
  return rows.find(r => r.responses && keys.some(k => k in r.responses))
      || rows.find(r => r.form_type === 'health-individual')
      || null;
}

// Doctor/med edits made anywhere flow back to the client's intake record
async function qbAcaSyncPicksToIntake_() {
  await qbSaveClientLists_();
  try {
    const row = await qbAcaIntakeRow_(['med_doctors', 'med_medications', 'med_doctors_struct', 'med_medications_struct']);
    if (!row) return;
    const docs = window._qbAcaDocs || [], meds = window._qbAcaMeds || [];
    const resp = Object.assign({}, row.responses, {
      med_doctors_struct: JSON.stringify(docs.map(d => ({ npi: d.npi, name: d.name }))),
      med_doctors: docs.map(d => d.name).join(', '),
      med_medications_struct: JSON.stringify(meds.map(m => ({
        rxcui: m.rxcui, name: m.name, days_supply: qbMedDays_(m),
        quantity: m.quantity || null, doses_per_day: m.doses_per_day || null }))),
      med_medications: meds.map(m => m.name).join(', '),
    });
    const { data: ok } = await supabaseClient.from('intake_sessions')
      .update({ responses: resp }).eq('id', row.id).select('id');
    const note = document.getElementById('qbpk-sync-note');
    if (note) note.textContent = '\u2713 Saved to this client\u2019s record: ' + docs.length + ' doctor' + (docs.length === 1 ? '' : 's') + ', ' + meds.length + ' medication' + (meds.length === 1 ? '' : 's') + '.';
  } catch (e) { console.error('qbAcaSyncPicksToIntake_:', e); }
}

function qbAcaRenderChips_() {
  const wraps = [document.getElementById('qb-aca-chips'), document.getElementById('qbpk-aca-chips')].filter(Boolean);
  if (!wraps.length) return;
  const chip = (label, kind, key, extra) =>
    `<span style="display:inline-flex;align-items:center;gap:5px;background:var(--surface-2);border:0.5px solid var(--border);border-radius:999px;padding:3px 10px;font-size:12px;">${kind === 'doc' ? '\u{1FA7A}' : '\u{1F48A}'} ${escWeb(label)}${extra || ''}
      <button type="button" onclick="qbAcaRemoveChip_('${kind}','${escWeb(String(key))}')" style="background:none;border:none;color:var(--text-muted);cursor:pointer;font-size:12px;">&#10005;</button></span>`;
  // Two things off the bottle. The supply falls out of them, and how much they
  // pick up at a time is most of what a drug plan costs them.
  const box = (m, field, ph, w) => `<input type="number" min="0" step="any" value="${m[field] == null ? '' : m[field]}"
      placeholder="${ph}" title="${field === 'doses_per_day' ? 'Doses a day' : 'How many in one fill'}"
      onchange="qbMedSet_('${escWeb(String(m.rxcui))}','${field}',this.value)"
      style="width:${w};padding:0 3px;margin:0;font-size:11px;height:19px;text-align:center;background:var(--surface-1);border:0.5px solid var(--border);border-radius:5px;color:var(--text-primary);" />`;
  const supply = m => {
    const note = medSupplyNote_(m);
    return `<span style="display:inline-flex;align-items:center;gap:3px;font-size:11px;color:var(--text-muted);">
      ${box(m, 'doses_per_day', '2', '30px')}/day
      ${box(m, 'quantity', 'qty', '42px')}
      ${note ? `<span style="color:${medDaysFrom_(m.quantity, m.doses_per_day) ? 'var(--text-info)' : 'var(--text-muted)'};font-weight:600;">${note}</span>` : ''}
    </span>`;
  };
  const html = (window._qbAcaDocs || []).map(d => chip(d.name, 'doc', d.npi)).join('')
    + (window._qbAcaMeds || []).map(m => chip(m.name, 'med', m.rxcui, supply(m))).join('');
  wraps.forEach(w => w.innerHTML = html);
}

// Nobody says "ninety day supply" \u2014 they say "two a day" and the bottle says
// how many they got. That division is the supply, snapped to the three sizes
// CMS actually prices. Anything we cannot work out is a monthly fill, which is
// what the CMS prices are quoted against.
function medDaysFrom_(quantity, dosesPerDay) {
  const q = Number(quantity), d = Number(dosesPerDay);
  if (!(q > 0) || !(d > 0)) return null;
  const days = q / d;
  return [30, 60, 90].reduce((best, n) =>
    Math.abs(n - days) < Math.abs(best - days) ? n : best, 30);
}

function qbMedDays_(m) {
  const worked = medDaysFrom_(m && m.quantity, m && m.doses_per_day);
  if (worked) return worked;
  const d = Number(m && m.days_supply);
  return (d === 60 || d === 90) ? d : 30;
}

// What the client would recognize on the label
function medSupplyNote_(m) {
  const worked = medDaysFrom_(m && m.quantity, m && m.doses_per_day);
  if (worked) return worked + '-day supply';
  if (Number(m && m.doses_per_day) > 0) return 'how many did they get?';
  return null;
}

function qbMedSet_(rxcui, field, value) {
  const m = (window._qbAcaMeds || []).find(x => String(x.rxcui) === String(rxcui));
  if (!m) return;
  const n = parseFloat(value);
  m[field] = isNaN(n) || n <= 0 ? null : n;
  m.days_supply = qbMedDays_(m);
  qbPkListsChanged_();
}

function qbAcaRemoveChip_(kind, key) {
  if (kind === 'doc') window._qbAcaDocs = (window._qbAcaDocs || []).filter(d => String(d.npi) !== key);
  else window._qbAcaMeds = (window._qbAcaMeds || []).filter(m => String(m.rxcui) !== key);
  qbPkListsChanged_();
}

async function qbAcaSearch_(kind) {
  const inp = _acaFld_(kind === 'doc' ? 'aca-doc-q' : 'aca-med-q');
  const q = inp.value.trim();
  const out = _acaFld_('aca-matches');
  if (q.length < 3) { out.textContent = 'Type at least 3 letters first.'; return; }
  out.textContent = 'Searching\u2026';
  try {
    const c = window._qbContact || {};
    const resp = kind === 'doc'
      ? await acaProxy_('aca_provider_search', { q: q, zip: c.zip || '', state: _acaClientState_() })
      : await acaProxy_('aca_drug_search', { q: q });
    if (resp.status !== 'ok') { out.innerHTML = '<span style="color:var(--danger);">' + escWeb(resp.message || 'Search failed') + '</span>'; return; }
    const raw = resp.data || {};
    let items;
    if (kind === 'doc') {
      items = acaShapeProviders_(raw, c.zip);
    } else {
      items = (Array.isArray(raw) ? raw : (raw.drugs || raw.suggestions || [])).map(o => {
        const medNm = (o.name || o.full_name || '') + (o.strength ? ' ' + o.strength : '');
        return { key: o.rxcui || o.id, name: medNm + (o.route ? ' \u00b7 ' + o.route : ''), cleanName: medNm };
      }).filter(x => x.key && x.name);
    }
    window._qbAcaMatches = items.slice(0, 60);
    window._qbAcaMatchKind = kind;
    window._qbAcaShowFar = false;
    qbAcaRenderMatches_();
  } catch (e) { out.innerHTML = '<span style="color:var(--danger);">Search unreachable.</span>'; }
}


// ZIP prefix -> state. A ZIP on file is enough to scope a search; we should
// never make an agent wait on a county dropdown to stop seeing other states.
const ZIP3_STATE = [
  [5,9,'PR'],[10,27,'MA'],[28,29,'RI'],[30,38,'NH'],[39,49,'ME'],[50,59,'VT'],
  [60,69,'CT'],[70,89,'NJ'],[100,149,'NY'],[150,196,'PA'],[197,199,'DE'],
  [200,205,'DC'],[206,219,'MD'],[220,246,'VA'],[247,268,'WV'],[270,289,'NC'],
  [290,299,'SC'],[300,319,'GA'],[320,349,'FL'],[350,369,'AL'],[370,385,'TN'],
  [386,397,'MS'],[400,427,'KY'],[430,459,'OH'],[460,479,'IN'],[480,499,'MI'],
  [500,528,'IA'],[530,549,'WI'],[550,567,'MN'],[570,577,'SD'],[580,588,'ND'],
  [590,599,'MT'],[600,629,'IL'],[630,658,'MO'],[660,679,'KS'],[680,693,'NE'],
  [700,714,'LA'],[716,729,'AR'],[730,749,'OK'],[750,799,'TX'],[800,816,'CO'],
  [820,831,'WY'],[832,838,'ID'],[840,847,'UT'],[850,865,'AZ'],[870,884,'NM'],
  [885,885,'TX'],[889,898,'NV'],[900,961,'CA'],[967,968,'HI'],[970,979,'OR'],
  [980,994,'WA'],[995,999,'AK'],
];
function zipToState_(zip) {
  const n = parseInt(String(zip || '').slice(0, 3), 10);
  if (isNaN(n)) return '';
  const hit = ZIP3_STATE.find(r => n >= r[0] && n <= r[1]);
  return hit ? hit[2] : '';
}

function _acaClientState_() {
  const c = window._qbContact || {};
  if (c.state) return String(c.state).toUpperCase();
  const cs = document.getElementById('qb-aca-county');
  if (cs && cs.value && cs.value.indexOf('|') > -1) return cs.value.split('|')[1].toUpperCase();
  return zipToState_(c.zip);        // their ZIP alone tells us the state
}

// Shared by every provider list in the CRM so they can't drift apart.
// pickJs is a JS snippet with {i} standing in for the item index.
function acaProviderGroupsHtml_(items, zip, state, pickJs, showFar, toggleJs) {
  const z3 = String(zip || '').slice(0, 3);
  const st = String(state || '').toUpperCase();
  const near = [], inState = [], far = [];
  items.forEach((x, i) => {
    const xs = String(x.state || '').toUpperCase();
    if (z3 && String(x.zip || '').slice(0, 3) === z3) near.push({ x, i });
    else if (st && xs === st) inState.push({ x, i });
    else far.push({ x, i });
  });
  const row = (x, i) => `<a href="#" onclick="${pickJs.replace('{i}', i)}; return false;"
      style="display:block;padding:7px 9px;border-radius:8px;text-decoration:none;color:inherit;border-bottom:0.5px solid var(--border);"
      onmouseover="this.style.background='var(--surface-2)'" onmouseout="this.style.background='transparent'">
      <div style="font-size:12.5px;font-weight:700;color:var(--text-primary);">${x.isFac ? '\u{1F3E5} ' : ''}${escWeb(x.cleanName)}</div>
      ${x.taxonomy ? `<div style="font-size:11px;color:var(--accent,#1d3557);">${escWeb(x.taxonomy)}</div>` : ''}
      ${(x.street || x.city) ? `<div style="font-size:11px;color:var(--text-muted);">${escWeb([x.street, x.city, x.state].filter(Boolean).join(', '))} ${escWeb(x.zip || '')}</div>` : ''}
    </a>`;
  const group = (label, list, tone) => list.length ? `
    <div style="font-size:10px;font-weight:800;text-transform:uppercase;letter-spacing:.5px;color:${tone};padding:7px 2px 3px;">${label} (${list.length})</div>
    ${list.map(e => row(e.x, e.i)).join('')}` : '';
  return group(z3 ? 'Near ' + escWeb(zip) : 'Nearby', near, '#15803d')
    + group(st ? 'Elsewhere in ' + escWeb(st) : 'Same state', inState, 'var(--accent,#1d3557)')
    + (showFar ? group('Other states', far, 'var(--text-muted)') : '')
    + (!near.length && !inState.length && !showFar && far.length
        ? `<div style="font-size:12px;color:var(--text-warning);padding:8px 2px;">No matches in ${escWeb(st || 'their state')} \u2014 ${far.length} found elsewhere.</div>` : '')
    + (far.length ? `<div style="padding:7px 2px;"><a href="#" onclick="${toggleJs}; return false;" style="font-size:11.5px;font-weight:700;color:var(--accent,#1d3557);text-decoration:none;">${showFar ? '\u2191 Hide the ' + far.length + ' out-of-state matches' : '\u2193 Show ' + far.length + ' match' + (far.length === 1 ? '' : 'es') + ' in other states'}</a></div>` : '');
}

function qbAcaToggleFar_() {
  window._qbAcaShowFar = !window._qbAcaShowFar;
  qbAcaRenderMatches_();
}

// Providers come back name-matched nationwide. An agent only ever wants the
// ones near THIS client, so group by distance-from-home and hide the rest.
function qbAcaRenderMatches_() {
  const out = _acaFld_('aca-matches');
  if (!out) return;
  const items = window._qbAcaMatches || [];
  const kind = window._qbAcaMatchKind;
  if (!items.length) { out.textContent = 'No matches \u2014 try a different spelling.'; return; }

  const row = (x, i) => `<a href="#" onclick="qbAcaPick_('${kind}', ${i}); return false;"
      style="display:block;padding:7px 9px;border-radius:8px;text-decoration:none;color:inherit;border-bottom:0.5px solid var(--border);"
      onmouseover="this.style.background='var(--surface-2)'" onmouseout="this.style.background='transparent'">
      <div style="font-size:12.5px;font-weight:700;color:var(--text-primary);">${x.isFac ? '\u{1F3E5} ' : ''}${escWeb(x.cleanName)}</div>
      ${x.taxonomy ? `<div style="font-size:11px;color:var(--accent,#1d3557);">${escWeb(x.taxonomy)}</div>` : ''}
      ${(x.street || x.city) ? `<div style="font-size:11px;color:var(--text-muted);">${escWeb([x.street, x.city, x.state].filter(Boolean).join(', '))} ${escWeb(x.zip || '')}</div>` : ''}
    </a>`;

  if (kind !== 'doc') {
    out.style.maxHeight = '230px'; out.style.overflowY = 'auto';
    out.innerHTML = items.map((x, i) =>
      `<a href="#" onclick="qbAcaPick_('med', ${i}); return false;" style="display:block;padding:6px 9px;border-radius:8px;text-decoration:none;color:var(--text-primary);font-size:12.5px;border-bottom:0.5px solid var(--border);"
        onmouseover="this.style.background='var(--surface-2)'" onmouseout="this.style.background='transparent'">${escWeb(x.name)}</a>`).join('');
    return;
  }

  const c = window._qbContact || {};
  out.style.maxHeight = '300px'; out.style.overflowY = 'auto';
  out.innerHTML = acaProviderGroupsHtml_(items, c.zip, _acaClientState_(),
    "qbAcaPick_('doc', {i})", !!window._qbAcaShowFar, 'qbAcaToggleFar_()');
}

// Whatever changed, this puts it everywhere it belongs: on screen, on the
// client's record, back into their intake, and through whichever coverage
// check the plans on screen can actually answer.
function qbPkListsChanged_() {
  qbAcaRenderChips_();
  qbSaveClientLists_();
  qbAcaSyncPicksToIntake_();
  if ((window._qbAcaPlans || []).length) qbAcaCheckCoverage_();
  if ((window._qbCmsPlans || []).length) {
    window._qbCmsMeds = (window._qbAcaMeds || []).filter(m => m.rxcui).map(m => ({
      rxcui: String(m.rxcui), name: m.name, quantity: m.quantity,
      doses_per_day: m.doses_per_day, days_supply: qbMedDays_(m),
    }));
    qbCmsDrugCheck_();
  }
  if (document.getElementById('qb-med-basis')) qbMedBasisPaint_();
}

// The finder, on a Medicare picker. Clients are vague on intake forms and
// thorough on the phone, so the agent needs to fix the list where they are
// rather than close everything and start again.
// The Medicare pickers can be reached without the ACA strip ever running, so
// the client's own lists have to be fetched before the finder can show them.
async function qbAcaFillListsFromClient_() {
  window._qbListsFilled = true;
  const lists = await qbLoadClientLists_();
  window._qbAcaDocs = (lists.providers || []).filter(d => d.npi).map(d => ({ npi: d.npi, name: d.name }));
  window._qbAcaMeds = (lists.medications || []).filter(m => m.rxcui).map(m => ({
    rxcui: m.rxcui, name: m.name, quantity: m.quantity,
    doses_per_day: m.doses_per_day, days_supply: m.days_supply,
  }));
}

function qbMedBasisToggle_() {
  window._qbMedBasisOpen = !window._qbMedBasisOpen;
  qbMedBasisPaint_();
}

const QB_BASIS_TITLE = {
  MAPD: 'What these plans are checked against',
  PDP: 'What these plans are checked against',
  MEDIGAP: 'Their medications — nothing here changes these plans',
};

const QB_BASIS_NOTE = {
  MAPD: 'Drugs are re-checked against every plan\u2019s formulary as you add them, and the yearly figures move with them. '
      + 'Doctors are saved to their record \u2014 Medicare Advantage networks are not published to us, so those cannot be checked here.',
  PDP: 'Drugs are re-checked against every plan\u2019s drug list as you add them, and the yearly figures move with them.',
  MEDIGAP: 'A Medicare Supplement has no network and no drug list, so nothing here changes these plans. '
         + 'It is here so their record is right while you have them \u2014 and a Part D quote is ready when you need one.',
};

function qbMedBasisHtml_(kind) {
  const docs = window._qbAcaDocs || [], meds = window._qbAcaMeds || [];
  const open = !!window._qbMedBasisOpen;
  const withDocs = kind === 'MAPD';
  const summary = [
    meds.length ? meds.length + ' medication' + (meds.length === 1 ? '' : 's') : 'no medications on file',
    withDocs && docs.length ? docs.length + ' doctor' + (docs.length === 1 ? '' : 's') : '',
  ].filter(Boolean).join('  \u00b7  ');

  const head = `<button type="button" onclick="qbMedBasisToggle_()" style="width:100%;text-align:left;background:none;border:none;cursor:pointer;padding:8px 18px;display:flex;align-items:center;gap:10px;font-size:12.5px;color:var(--text-secondary);">
      <span style="font-weight:800;color:var(--text-primary);">${open ? '\u25BE' : '\u25B8'} \u{1F48A} ${QB_BASIS_TITLE[kind] || QB_BASIS_TITLE.MAPD}</span>
      <span style="color:var(--text-muted);">${escWeb(summary)}</span>
      <span style="margin-left:auto;color:var(--accent,#1d3557);font-weight:700;">${open ? 'Hide' : 'Add or edit'}</span>
    </button>`;
  if (!open) return head;
  setTimeout(qbAcaRenderChips_, 0);

  return `${head}
    <div style="padding:0 18px 12px;">
      <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;">
        <span><input type="text" id="qbpk-aca-med-q" placeholder="Medication" style="width:150px;"
          onkeydown="if(event.key==='Enter'){event.preventDefault();qbAcaSearch_('med');}" />
          <button type="button" class="btn btn-outline btn-sm" onclick="qbAcaSearch_('med')">Find Medication</button></span>
        ${withDocs ? `<span><input type="text" id="qbpk-aca-doc-q" placeholder="Doctor, clinic or hospital" style="width:180px;"
          onkeydown="if(event.key==='Enter'){event.preventDefault();qbAcaSearch_('doc');}" />
          <button type="button" class="btn btn-outline btn-sm" onclick="qbAcaSearch_('doc')">Find Provider/Facility</button></span>` : ''}
      </div>
      <div id="qbpk-aca-matches" style="font-size:12px;margin-top:6px;"></div>
      <div id="qbpk-aca-chips" style="margin-top:7px;display:flex;gap:6px;flex-wrap:wrap;"></div>
      <div style="font-size:11px;color:var(--text-muted);margin-top:7px;line-height:1.5;">${QB_BASIS_NOTE[kind] || ''}</div>
    </div>`;
}

function qbMedBasisPaint_() {
  const el = document.getElementById('qb-med-basis');
  if (el) el.innerHTML = qbMedBasisHtml_(el.dataset.kind || 'MAPD');
}

function qbAcaPick_(kind, i) {
  const x = (window._qbAcaMatches || [])[i];
  if (!x) return;
  if (kind === 'doc') {
    window._qbAcaDocs = window._qbAcaDocs || [];
    if (!window._qbAcaDocs.some(d => String(d.npi) === String(x.key))) window._qbAcaDocs.push({ npi: x.key, name: x.cleanName });
    const dq = _acaFld_('aca-doc-q'); if (dq) dq.value = '';
  } else {
    window._qbAcaMeds = window._qbAcaMeds || [];
    if (!window._qbAcaMeds.some(m => String(m.rxcui) === String(x.key))) window._qbAcaMeds.push({ rxcui: x.key, name: x.cleanName });
    const mq = _acaFld_('aca-med-q'); if (mq) mq.value = '';
  }
  const mt = _acaFld_('aca-matches'); if (mt) mt.innerHTML = '';
  qbPkListsChanged_();
}

function _covIsYes_(v) {
  if (v === true) return true;
  const s = String(v || '').toLowerCase();
  return s === 'covered' || s === 'true' || s === 'yes' || s === 'in network' || s === 'innetwork';
}

// A re-quoted option has a plan id and the client has doctors and drugs on
// file, so we can answer "is my doctor in network" the moment the dialog
// opens \u2014 no tool run required. One or two calls, capped at 10 plan ids.
async function qbAcaCoverSelected_() {
  const sel = window._qbAcaSel || {};
  const plans = Object.keys(sel).map(k => sel[k]).filter(p => p && p.id);
  const ids = [...new Set(plans.map(p => p.id))].slice(0, 10);
  if (!ids.length) return;
  if (!(window._qbAcaDocs || []).length && !(window._qbAcaMeds || []).length) {
    const lists = await qbLoadClientLists_();
    window._qbAcaDocs = (lists.providers || []).filter(d => d.npi).map(d => ({ npi: d.npi, name: d.name }));
    window._qbAcaMeds = (lists.medications || []).filter(m => m.rxcui)
      .map(m => ({ rxcui: m.rxcui, name: m.name, days_supply: qbMedDays_(m), quantity: m.quantity, doses_per_day: m.doses_per_day }));
  }
  const docs = window._qbAcaDocs || [], meds = window._qbAcaMeds || [];
  if (!docs.length && !meds.length) return;
  const year = plans[0]._year || window._qbAcaYear || new Date().getFullYear();
  const byId = {}; plans.forEach(p => { p._docCov = p._docCov || {}; p._medCov = p._medCov || {}; byId[p.id] = p; });
  window._qbAcaCovBusy = true;
  qbAcaOptionCardsPaint_();
  const jobs = [];
  if (docs.length) {
    jobs.push(acaProxy_('aca_provider_coverage', { planids: ids.join(','), providers: docs.map(d => d.npi).join(','), year: year })
      .then(r => {
        const rows = (r.data && (r.data.coverage || r.data.plans || r.data)) || [];
        (Array.isArray(rows) ? rows : []).forEach(row => {
          const p = byId[row.plan_id || row.planid || row.id];
          if (p) p._docCov[row.npi || row.provider_npi] = _covIsYes_(row.coverage != null ? row.coverage : row.covered);
        });
        qbAcaOptionCardsPaint_();
      }).catch(e => console.error('provider coverage (saved plans):', e)));
  }
  if (meds.length) {
    jobs.push(acaProxy_('aca_drug_coverage', { planids: ids.join(','), drugs: meds.map(m => m.rxcui).join(','), year: year })
      .then(r => {
        const rows = (r.data && (r.data.coverage || r.data)) || [];
        (Array.isArray(rows) ? rows : []).forEach(row => {
          const p = byId[row.plan_id || row.planid || row.id];
          if (p) p._medCov[row.rxcui] = _covIsYes_(row.coverage != null ? row.coverage : row.covered);
        });
        qbAcaOptionCardsPaint_();
      }).catch(e => console.error('drug coverage (saved plans):', e)));
  }
  try { await qbCovDeadline_(jobs); } catch (e) { console.error('saved-plan coverage:', e); }
  window._qbAcaCovBusy = false;
  qbAcaOptionCardsPaint_();
}

// 45s and we stop saying "checking". An answer that never comes must not
// look the same as one still on its way.
function qbCovDeadline_(jobs, ms) {
  return Promise.race([
    Promise.all(jobs),
    new Promise(r => setTimeout(r, ms || 45000)),
  ]);
}

async function qbAcaCheckCoverage_() {
  const plans = window._qbAcaPlans || [];
  const docs = window._qbAcaDocs || [], meds = window._qbAcaMeds || [];
  if (!plans.length || (!docs.length && !meds.length)) { window._qbAcaCovBusy = false; qbAcaRefreshOptionLabels_(); return; }
  const res = document.getElementById('qb-aca-result');
  const prev = res ? res.innerHTML : '';
  if (res) res.innerHTML = prev + ' <em style="color:var(--text-muted);">checking coverage\u2026</em>';
  const year = window._qbAcaYear || new Date().getFullYear();
  plans.forEach(p => { p._docCov = {}; p._medCov = {}; });
  const byId = {}; plans.forEach(p => byId[p.id] = p);

  // Cards say "checking" (not "not reported") until the answers land
  window._qbAcaCovBusy = true;
  qbAcaRenderBrowser_();

  // Batches run in PARALLEL — sequential runs took ~19s for 37 plans, which
  // read as "broken" long before it read as "loading".
  let lastPaint = 0;
  const paint = (force) => {
    const now = Date.now();
    if (!force && (now - lastPaint < 1200 || window._qbPkBasisOpen)) return;
    lastPaint = now;
    qbAcaRenderBrowser_();
    qbAcaOptionCardsPaint_();
  };
  // The plans already on the quote are the ones the agent is looking at, so
  // they go in the first batch instead of wherever the list happens to put
  // them \u2014 their cards then answer on the first round-trip.
  const chosen = new Set(Object.keys(window._qbAcaSel || {}).map(k => (window._qbAcaSel[k] || {}).id).filter(Boolean));
  const queue = chosen.size ? plans.filter(p => chosen.has(p.id)).concat(plans.filter(p => !chosen.has(p.id))) : plans;
  const jobs = [];
  for (let i = 0; i < queue.length; i += 10) {   // API cap: 10 plan IDs per request
    const ids = queue.slice(i, i + 10).map(p => p.id).join(',');
    if (docs.length) {
      jobs.push(acaProxy_('aca_provider_coverage', { planids: ids, providers: docs.map(d => d.npi).join(','), year: year })
        .then(r => {
          const rows = (r.data && (r.data.coverage || r.data.plans || r.data)) || [];
          (Array.isArray(rows) ? rows : []).forEach(row => {
            const p = byId[row.plan_id || row.planid || row.id];
            if (p) p._docCov[row.npi || row.provider_npi] = _covIsYes_(row.coverage != null ? row.coverage : row.covered);
          });
          paint(false);
        }).catch(e => console.error('provider coverage:', e)));
    }
    if (meds.length) {
      jobs.push(acaProxy_('aca_drug_coverage', { planids: ids, drugs: meds.map(m => m.rxcui).join(','), year: year })
        .then(r => {
          const rows = (r.data && (r.data.coverage || r.data)) || [];
          (Array.isArray(rows) ? rows : []).forEach(row => {
            const p = byId[row.plan_id || row.planid || row.id];
            if (p) p._medCov[row.rxcui] = _covIsYes_(row.coverage != null ? row.coverage : row.covered);
          });
          paint(false);
        }).catch(e => console.error('drug coverage:', e)));
    }
  }
  try { await qbCovDeadline_(jobs); } catch (e) { console.error('coverage check:', e); }
  window._qbAcaCovBusy = false;
  if (res) res.innerHTML = prev;
  qbAcaRefreshOptionLabels_();
  paint(true);
  qbAcaOptionCardsPaint_();
}

// Coverage answers arrive after the card is already on screen; without this
// the card keeps showing whatever it knew when it was drawn.
function qbAcaOptionCardsPaint_() {
  for (let i = 0; i < QB_MAX_OPTIONS; i++) {
    if ((window._qbAcaSel || {})[i]) qbAcaOptionView_(i);
  }
}

function qbAcaRefreshOptionLabels_() {
  const plans = window._qbAcaPlans || [];
  const docs = window._qbAcaDocs || [], meds = window._qbAcaMeds || [];
  const line = document.getElementById('qb-line') ? document.getElementById('qb-line').value : '';
  if (line !== 'Health — Individual') return;
  const opts = '<option value="">&mdash; pick a plan &mdash;</option>'
    + plans.map(p => {
      let marks = '';
      if (docs.length) {
        const n = docs.filter(d => p._docCov && p._docCov[d.npi]).length;
        marks += ' [' + (n === docs.length ? '\u2713' : n + '/' + docs.length) + ' drs]';
      }
      if (meds.length) {
        const n = meds.filter(m => p._medCov && p._medCov[m.rxcui]).length;
        marks += ' [' + (n === meds.length ? '\u2713' : n + '/' + meds.length) + ' meds]';
      }
      return `<option value="${escWeb(p.id)}">${escWeb(p.metal)}: ${escWeb((p.issuer ? p.issuer + ' \u2014 ' : '') + p.name)} ($${Number(p.net).toFixed(2)}/mo)${marks}</option>`;
    }).join('');
  for (let i = 0; i < QB_MAX_OPTIONS; i++) {
    const sel = document.getElementById('qb-aca-' + i);
    if (sel) { const cur = sel.value; sel.innerHTML = opts; sel.value = cur; }
  }
}

async function qbAcaIchraVerdict_(income, county, people, hraMonthly) {
  try {
    const c = window._qbContact || {};
    const resp = await acaProxy_('aca_ichra', { payload: JSON.stringify({
      household: { income: income, people: people.filter(m => m.applying !== false).map(m => ({
        age: m.age, aptc_eligible: true, gender: m.gender === 'F' ? 'Female' : 'Male',
        uses_tobacco: !!m.uses_tobacco, relationship: m.relationship })) },
      place: { countyfips: county.split('|')[0], state: county.split('|')[1], zipcode: c.zip || '' },
      hra_monthly: hraMonthly,
    }) });
    if (resp.status !== 'ok' || !resp.data) return;
    const d = resp.data;
    const affordable = d.affordable != null ? d.affordable : (d.is_affordable != null ? d.is_affordable : null);
    if (affordable === null) return;
    const res = document.getElementById('qb-aca-result');
    res.innerHTML = '<span style="font-weight:700;color:' + (affordable ? 'var(--danger)' : 'var(--success)') + ';">'
      + (affordable
        ? '&#128683; Official verdict: the ICHRA offer IS affordable \u2014 this household is NOT eligible for tax credits. Quote full prices.'
        : '&#9989; Official verdict: the ICHRA offer is NOT affordable \u2014 they may decline it and keep the tax credit.')
      + '</span><br>' + res.innerHTML;
  } catch (e) { console.error('ichra verdict:', e); }
}

const METAL_STYLE = {
  Bronze:       { bg: 'rgba(205,127,50,0.14)',  fg: '#b06a2a' },
  Silver:       { bg: 'rgba(148,155,164,0.18)', fg: '#6b7280' },
  Gold:         { bg: 'rgba(212,175,55,0.16)',  fg: '#a8862c' },
  Platinum:     { bg: 'rgba(120,130,140,0.18)', fg: '#4b5563' },
  Catastrophic: { bg: 'rgba(100,116,139,0.14)', fg: '#64748b' },
};

let _qbAcaMetalFilter = 'All';
let _qbAcaSort = 'net';

function qbAcaBrowserControls_() {
  const metals = ['All', ...new Set((window._qbAcaPlans || []).map(p => p.metal).filter(Boolean))];
  return `<div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center;margin-bottom:8px;">
    ${metals.map(m => `<button type="button" onclick="_qbAcaMetalFilter='${m}';qbAcaRenderBrowser_()"
      style="border:1px solid ${_qbAcaMetalFilter === m ? 'var(--accent,#1d3557)' : 'var(--border)'};background:${_qbAcaMetalFilter === m ? 'var(--accent,#1d3557)' : 'var(--surface-1)'};color:${_qbAcaMetalFilter === m ? '#fff' : 'var(--text-primary)'};border-radius:999px;padding:4px 12px;font-size:11.5px;font-weight:600;cursor:pointer;">${m}</button>`).join('')}
    <span style="margin-left:auto;font-size:12px;color:var(--text-muted);">Sort:
      <select onchange="_qbAcaSort=this.value;qbAcaRenderBrowser_()" style="width:auto;display:inline-block;font-size:12px;">
        <option value="net"${_qbAcaSort === 'net' ? ' selected' : ''}>Lowest cost to client</option>
        <option value="deductible"${_qbAcaSort === 'deductible' ? ' selected' : ''}>Lowest deductible</option>
        <option value="rating"${_qbAcaSort === 'rating' ? ' selected' : ''}>Highest rated</option>
      </select></span>
  </div>`;
}

// ── Cost-Sharing Reductions (CSR) ───────────────────────────────────────────
// healthcare.gov already prices deductibles/MOOP for the household's CSR
// variant. Our job: say so, and stop a client from silently forfeiting it.
function acaCsrActive_() {
  const c = window._qbAcaCsr;
  return (c && !/none/i.test(String(c))) ? String(c) : null;
}
function acaCsrPct_(csr) {
  const m = /(\d{2})\s*%/.exec(String(csr || ''));
  if (m) return m[1];
  if (/zero cost/i.test(csr || '')) return 'ZERO';
  if (/limited cost/i.test(csr || '')) return 'LIMITED';
  return null;
}
// Zero/Limited (AI/AN) variants ride any metal; the AV tiers are Silver-only.
function acaCsrAppliesTo_(metal, csr) {
  const pct = acaCsrPct_(csr || acaCsrActive_());
  if (!pct) return false;
  return (pct === 'ZERO' || pct === 'LIMITED') ? true : metal === 'Silver';
}
function acaCsrLabel_(csr) {
  const pct = acaCsrPct_(csr || acaCsrActive_());
  if (!pct) return '';
  if (pct === 'ZERO') return 'Zero cost sharing';
  if (pct === 'LIMITED') return 'Limited cost sharing';
  return '\u2728 Extra savings \u00b7 ' + pct + '% plan';
}
const ACA_CSR_TIP = 'Cost-sharing reduction: because of this household\u2019s income, the plan\u2019s deductible, copays and out-of-pocket maximum are already lowered \u2014 at no extra premium. Estimate only; the Marketplace confirms it at enrollment.';
function acaCsrBadge_(metal, csr) {
  if (!acaCsrAppliesTo_(metal, csr)) return '';
  return `<span title="${escWeb(ACA_CSR_TIP)}" style="cursor:help;background:rgba(21,128,61,.12);color:#15803d;font-size:10px;font-weight:800;border-radius:6px;padding:2px 8px;white-space:nowrap;">${escWeb(acaCsrLabel_(csr))}</span>`;
}
// Corner medal for cost-sharing plans: the % is the headline number
function acaCsrMedal_(metal, csr) {
  if (!acaCsrAppliesTo_(metal, csr)) return '';
  const pct = acaCsrPct_(csr || acaCsrActive_());
  const big = (pct === 'ZERO' || pct === 'LIMITED') ? '$0' : pct + '%';
  const sub = (pct === 'ZERO') ? 'no cost' : (pct === 'LIMITED') ? 'limited' : 'covered';
  return `<div title="${escWeb(ACA_CSR_TIP)}" style="cursor:help;flex-shrink:0;
      width:46px;height:46px;border-radius:50%;display:flex;flex-direction:column;align-items:center;justify-content:center;
      background:radial-gradient(circle at 32% 28%, #34d399 0%, #15803d 72%);color:#fff;
      border:2.5px solid var(--surface-1);box-shadow:0 4px 12px rgba(21,128,61,.42);">
      <span style="font-size:14px;font-weight:900;line-height:1;letter-spacing:-.4px;">${big}</span>
      <span style="font-size:7.5px;font-weight:700;text-transform:uppercase;letter-spacing:.4px;opacity:.92;">${sub}</span>
    </div>`;
}
// Small flag beside the Silver filter so the tier is obvious before filtering
function acaCsrFacetFlag_(metal) {
  if (!acaCsrAppliesTo_(metal)) return '';
  const pct = acaCsrPct_(acaCsrActive_());
  const txt = (pct === 'ZERO' || pct === 'LIMITED') ? '\u2728' : '\u2728 ' + pct + '%';
  return `<span title="${escWeb(ACA_CSR_TIP)}" style="cursor:help;background:linear-gradient(120deg,#15803d,#34d399);color:#fff;font-size:9px;font-weight:800;border-radius:999px;padding:1px 6px;white-space:nowrap;">${txt}</span>`;
}

function acaCsrBanner_() {
  const bars = [];
  const bar = (tone, html) => `<div class="pk-bar ${tone}">${html}</div>`;

  // Medicaid/CHIP outranks everything — no credit, no CSR, different door
  if (window._qbAcaMedicaid) {
    bars.push(bar('warn',
      '&#9888;&#65039; <strong>This household may qualify for Medicaid/CHIP.</strong> Their income is below the Marketplace subsidy floor, so <strong>no tax credit and no cost-sharing help apply</strong> to the plans below \u2014 check the Medicaid door before quoting these prices.'));
  } else if (window._qbAcaAptc != null && window._qbAcaAptc > 0) {
    bars.push(bar('ok',
      '\u{1F31F} <strong>Estimated tax credit $' + Number(window._qbAcaAptc).toFixed(0) + '/mo</strong> \u2014 already taken off every price below.'));
  } else if (window._qbAcaAptc != null) {
    bars.push(bar('muted',
      'No premium tax credit at this income \u2014 prices below are full price.'));
  }

  const miss = window._qbAcaUnmatched || [];
  if (miss.length) {
    bars.push(bar('warn', '&#9888;&#65039; <strong>' + miss.length + ' plan'
      + (miss.length === 1 ? '' : 's') + ' from the previous quote could not be matched</strong> to this year\u2019s list ('
      + miss.map(m => escWeb(m.name)).join(', ')
      + '). They stayed on the quote as typed \u2014 re-pick them here if you want live pricing.'));
  }

  const csr = acaCsrActive_();
  if (csr) {
    const pct = acaCsrPct_(csr);
    const silverOnly = !(pct === 'ZERO' || pct === 'LIMITED');
    bars.push(bar('ok',
      '<strong>' + escWeb(acaCsrLabel_(csr)) + '</strong> \u2014 this household qualifies for cost-sharing help'
      + (silverOnly
        ? ', which only applies to <strong>Silver</strong> plans. Silver deductibles and out-of-pocket maximums below are already reduced; leaving Silver gives that up.'
        : '. Deductibles and out-of-pocket costs below are already reduced.')));
  }
  return bars.join('');
}

// Agent corrects the income mid-quote \u2192 teach the intake record too
async function qbAcaSyncIncomeToIntake_(income) {
  const c = window._qbContact;
  if (!c || income == null || isNaN(income)) return;
  // the client record is the source of truth; the intake keeps its own copy
  await qbSaveClientProfile_({ household_income: income, household_members: qbReadHouseholdRows_() });
  try {
    const { data: sess } = await supabaseClient.from('intake_sessions')
      .select('id,responses').eq('contact_id', c.id).eq('status', 'completed')
      .order('created_at', { ascending: false }).limit(5);
    const row = (sess || []).find(x => x.responses && ('aca_income' in x.responses));
    if (!row || String(row.responses.aca_income) === String(income)) return;
    const resp = Object.assign({}, row.responses, { aca_income: String(income) });
    const { data: ok } = await supabaseClient.from('intake_sessions')
      .update({ responses: resp }).eq('id', row.id).select('id');
    const note = document.getElementById('qb-aca-intake-note');
    if (ok && ok.length && note) {
      note.style.display = 'block';
      note.style.color = '#0d9488';
      note.innerHTML = '\u2713 Saved to this client\u2019s record \u2014 household income $'
        + Number(income).toLocaleString() + ' (their intake was updated too).';
    }
  } catch (e) { console.error('qbAcaSyncIncomeToIntake_:', e); }
}


function qbAcaCostFact_(label, ind, fam) {
  if (ind == null && fam == null) return '';
  const famQuote = !!window._qbAcaFamilyQuote;
  const main = ind != null ? ind : fam;
  return `<span style="display:inline-block;">${label} <strong>$${Number(main).toLocaleString()}</strong>` +
    (famQuote && ind != null ? '<span style="font-size:10px;color:var(--text-muted);"> individual</span>' : '') +
    (famQuote && fam != null && ind != null ? `<br><span style="font-size:10.5px;color:var(--text-muted);">$${Number(fam).toLocaleString()} family</span>` : '') +
    '</span>';
}

// The same rows render in two places. Repaint whichever one the link is in:
// slot is the option number on a card, and null inside the picker.
function qbCovExpand_(key, open, slot) {
  window._qbCovExp = window._qbCovExp || {};
  window._qbCovExp[key] = open;
  if (document.getElementById('qb-aca-picker')) renderPickerBody_();
  if (slot !== null && slot !== undefined && slot !== '') qbAcaOptionView_(Number(slot));
  return false;
}

function qbAcaCovLines_(p, slot) {
  const docs = window._qbAcaDocs || [], meds = window._qbAcaMeds || [];
  if (!docs.length && !meds.length) return '';
  const busy = !!window._qbAcaCovBusy;
  const SHOWN = 3;                       // before the row offers "+N more"
  window._qbCovExp = window._qbCovExp || {};

  // Three different states, three different words: the plan answered, the
  // plan was asked and said nothing, or nobody has asked yet.
  const pill = (known, ok, label, asked) => {
    const tone = known ? (ok ? 'ok' : 'bad') : 'unk';
    const mark = known ? (ok ? '\u2713' : '\u2717') : (busy ? '\u23f3' : '?');
    const suffix = known ? ''
      : (busy ? ' <span style="opacity:.7;">checking\u2026</span>'
             : (asked ? ' <span style="opacity:.7;">(not reported)</span>'
                      : ' <span style="opacity:.7;">(not checked yet)</span>'));
    return `<span class="pk-pill ${tone}">${mark} ${label}${suffix}</span>`;
  };

  const row = (icon, kind, list, cover, keyOf, labelOf) => {
    if (!list.length) return '';
    const expKey = p.id + '|' + kind;
    const open = !!window._qbCovExp[expKey];
    const show = open ? list : list.slice(0, SHOWN);
    const hidden = list.length - show.length;
    return `<div style="display:flex;align-items:flex-start;gap:6px;flex-wrap:wrap;margin-top:4px;">
      <span style="font-size:11px;line-height:18px;flex-shrink:0;" title="${kind === 'doc' ? 'Providers &amp; facilities' : 'Medications'}">${icon}</span>
      ${show.map(x => {
        const k = keyOf(x);
        const known = cover(p) && k in cover(p);
        return pill(known, known && cover(p)[k], escWeb(labelOf(x)), !!cover(p));
      }).join(' ')}
      ${hidden > 0 ? `<a href="#" onclick="event.stopPropagation();return qbCovExpand_('${escWeb(expKey)}', true, '${slot === undefined || slot === null ? '' : slot}');"
          style="font-size:11px;font-weight:700;color:var(--accent,#1d3557);text-decoration:none;line-height:18px;">+${hidden} more</a>` : ''}
      ${open && list.length > SHOWN ? `<a href="#" onclick="event.stopPropagation();return qbCovExpand_('${escWeb(expKey)}', false, '${slot === undefined || slot === null ? '' : slot}');"
          style="font-size:11px;color:var(--text-muted);text-decoration:none;line-height:18px;">less</a>` : ''}
    </div>`;
  };

  return row('\u{1FA7A}', 'doc', docs, pp => pp._docCov, d => d.npi, d => d.name.split(' \u00b7 ')[0])
       + row('\u{1F48A}', 'med', meds, pp => pp._medCov, m => m.rxcui, m => m.name);
}

// On an option card this is supporting detail, not the headline \u2014 it opens
// on request and, closed, still says how the plan did.
function qbAcaCovGroupToggle_(i) {
  window._qbCovGrpOpen = window._qbCovGrpOpen || {};
  window._qbCovGrpOpen[i] = !window._qbCovGrpOpen[i];
  qbAcaOptionView_(i);
}

function qbAcaCovSummary_(p) {
  const busy = !!window._qbAcaCovBusy;
  const bits = [];
  let tone = 'var(--text-success)';
  const part = (list, cov, keyOf, icon, okWord) => {
    if (!list.length) return;
    const known = cov ? list.filter(x => keyOf(x) in cov) : [];
    if (!known.length) {
      tone = 'var(--text-muted)';
      bits.push(icon + ' ' + list.length + (busy ? ' \u00b7 checking\u2026' : (cov ? ' \u00b7 no answer' : ' \u00b7 not checked yet')));
      return;
    }
    const ok = known.filter(x => cov[keyOf(x)]).length;
    if (ok < list.length && tone === 'var(--text-success)') tone = 'var(--text-warning)';
    bits.push(icon + ' ' + ok + ' of ' + list.length + ' ' + okWord);
  };
  part(window._qbAcaDocs || [], p._docCov, d => d.npi, '\u{1FA7A}', 'in network');
  part(window._qbAcaMeds || [], p._medCov, m => m.rxcui, '\u{1F48A}', 'covered');
  return { text: bits.join(' \u00b7 '), tone: tone };
}

function qbAcaCovGroup_(p, i) {
  const docs = window._qbAcaDocs || [], meds = window._qbAcaMeds || [];
  if (!docs.length && !meds.length) return '';
  window._qbCovGrpOpen = window._qbCovGrpOpen || {};
  const open = !!window._qbCovGrpOpen[i];
  const sum = qbAcaCovSummary_(p);
  return `<div style="margin-top:8px;border-top:1px solid var(--border);padding-top:6px;">
    <button type="button" onclick="qbAcaCovGroupToggle_(${i})"
      style="width:100%;text-align:left;background:none;border:none;cursor:pointer;padding:0;display:flex;align-items:center;gap:8px;">
      <span style="font-size:11px;font-weight:700;color:var(--text-muted);">${open ? '\u25BE' : '\u25B8'} Providers/Facilities and Medications</span>
      <span style="flex:1;min-width:0;font-size:11px;color:${sum.tone};overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${sum.text}</span>
    </button>
    ${open ? qbAcaCovLines_(p, i) : ''}
  </div>`;
}

function qbAcaAddedSlot_(planId) {
  for (let i = 0; i < QB_MAX_OPTIONS; i++) {
    const sel = document.getElementById('qb-aca-' + i);
    if (sel && sel.value === planId) return i;
  }
  return -1;
}

function qbAcaRenderBrowser_() {
  const box = document.getElementById('qb-aca-browser');
  if (!box) return;
  const plans = window._qbAcaPlans || [];
  if (!plans.length) { box.style.display = 'none'; return; }
  const added = [];
  for (let i = 0; i < QB_MAX_OPTIONS; i++) {
    const sel = document.getElementById('qb-aca-' + i);
    if (sel && sel.value) { const p = plans.find(x => x.id === sel.value); if (p) added.push({ i, p }); }
  }
  box.style.display = 'block';
  box.innerHTML = `
    <div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap;font-size:12px;color:var(--text-muted);">
      <span><strong style="color:var(--text-primary);">${plans.length} plans</strong> loaded \u00b7 ${added.length
        ? added.length + ' on the quote: ' + added.map(a => escWeb(a.p.name.slice(0, 26))).join(' \u00b7 ')
        : 'none picked yet'}</span>
      <a href="#" onclick="openAcaPicker_();return false;" style="color:var(--accent,#1d3557);font-weight:700;text-decoration:none;">\u{1F5D6} Reopen picker</a>
    </div>`;
  if (document.getElementById('qb-aca-picker')) renderPickerBody_();
}

const _qbPk = { carriers: new Set(), metals: new Set(), types: new Set(), hsa: false, docsAll: false, medsAll: false, maxNet: null, sort: 'net', cmp: new Set() };

async function openAcaPicker_() {
  if (!(window._qbAcaPlans || []).length) {
    const inc = document.getElementById('qb-aca-income');
    const cty = document.getElementById('qb-aca-county');
    if (inc && inc.value && cty && cty.value) {
      showToast('Getting this year\u2019s plans first\u2026');
      await qbAcaGetPlans_();          // this opens the picker itself when it lands
      return;
    }
    showToast('Run \u201cFind plans & subsidy\u201d first \u2014 opening the ACA tool.');
    qbWorkbenchOpen_(true, 'aca');
    return;
  }
  qbWorkbenchOpen_(false);           // the picker IS the screen now
  _qbPk.carriers.clear(); _qbPk.metals.clear(); _qbPk.types.clear(); _qbPk.cmp.clear();
  _qbPk.hsa = false; _qbPk.docsAll = false; _qbPk.medsAll = false; _qbPk.maxNet = null; _qbPk.sort = 'net';
  let ov = document.getElementById('qb-aca-picker');
  if (!ov) {
    ov = document.createElement('div');
    ov.id = 'qb-aca-picker';
    ov.style.cssText = 'position:fixed;inset:0;z-index:99990;background:var(--surface-0);display:flex;flex-direction:column;';
    document.body.appendChild(ov);
  }
  ov.style.display = 'flex';
  renderPickerBody_();
}

function closeAcaPicker_() {
  const ov = document.getElementById('qb-aca-picker');
  if (ov) ov.remove();
  const dr = document.getElementById('qb-plan-detail');
  if (dr) dr.remove();
  const cm = document.getElementById('qb-aca-compare');
  if (cm) cm.remove();
  qbAcaRenderBrowser_();
  qbOptAutoFold_();
  qbGroupOptions_();
}

function pkToggle_(set, val) { if (_qbPk[set].has(val)) _qbPk[set].delete(val); else _qbPk[set].add(val); renderPickerBody_(); }

function pkCovAll_(p, kind) {
  const chips = kind === 'doc' ? (window._qbAcaDocs || []) : (window._qbAcaMeds || []);
  const cov = kind === 'doc' ? p._docCov : p._medCov;
  if (!chips.length || !cov) return false;
  return chips.every(c => cov[kind === 'doc' ? c.npi : c.rxcui]);
}

function pkFiltered_() {
  let plans = (window._qbAcaPlans || []).slice();
  if (_qbPk.carriers.size) plans = plans.filter(p => _qbPk.carriers.has(p.issuer || ''));
  if (_qbPk.metals.size) plans = plans.filter(p => _qbPk.metals.has(p.metal || ''));
  if (_qbPk.types.size) plans = plans.filter(p => _qbPk.types.has(p.type || ''));
  if (_qbPk.hsa) plans = plans.filter(p => p.hsa);
  if (_qbPk.docsAll) plans = plans.filter(p => pkCovAll_(p, 'doc'));
  if (_qbPk.medsAll) plans = plans.filter(p => pkCovAll_(p, 'med'));
  if (_qbPk.maxNet != null) plans = plans.filter(p => (p.net || 0) <= _qbPk.maxNet);
  if (_qbPk.sort === 'net') plans.sort((a, b) => (a.net || 0) - (b.net || 0));
  else if (_qbPk.sort === 'premium') plans.sort((a, b) => (a.premium || 0) - (b.premium || 0));
  else if (_qbPk.sort === 'deductible') plans.sort((a, b) => (a.deductible ?? 9e9) - (b.deductible ?? 9e9));
  else if (_qbPk.sort === 'moop') plans.sort((a, b) => (a.moop ?? 9e9) - (b.moop ?? 9e9));
  else if (_qbPk.sort === 'rating') plans.sort((a, b) => (b.rating || 0) - (a.rating || 0));
  return plans;
}

function pkFacet_(title, set, values) {
  const all = window._qbAcaPlans || [];
  return `<div style="margin-bottom:14px;">
    <div style="font-size:11px;font-weight:800;text-transform:uppercase;letter-spacing:.5px;color:var(--text-muted);margin-bottom:6px;">${title}</div>
    ${values.map(v => {
      const n = all.filter(p => (set === 'carriers' ? p.issuer : set === 'metals' ? p.metal : p.type) === v).length;
      return `<label style="display:flex;gap:7px;align-items:center;font-size:12.5px;padding:2px 0;cursor:pointer;">
        <input type="checkbox" ${_qbPk[set].has(v) ? 'checked' : ''} onchange="pkToggle_('${set}','${escWeb(v)}')" style="width:14px;height:14px;" />
        <span style="flex:1;">${escWeb(v)}${set === 'metals' ? ' ' + acaCsrFacetFlag_(v) : ''}</span><span style="color:var(--text-muted);font-size:11px;">${n}</span>
      </label>`;
    }).join('')}
  </div>`;
}

function renderPickerBody_() {
  const ov = document.getElementById('qb-aca-picker');
  if (!ov) return;
  const all = window._qbAcaPlans || [];
  const plans = pkFiltered_();
  const c = window._qbContact || {};
  const carriers = [...new Set(all.map(p => p.issuer).filter(Boolean))].sort();
  const metals = [...new Set(all.map(p => p.metal).filter(Boolean))];
  const types = [...new Set(all.map(p => p.type).filter(Boolean))].sort();
  const docs = window._qbAcaDocs || [], meds = window._qbAcaMeds || [];
  const added = [];
  for (let i = 0; i < QB_MAX_OPTIONS; i++) {
    const sel = document.getElementById('qb-aca-' + i);
    if (sel && sel.value) { const p = all.find(x => x.id === sel.value); if (p) added.push({ i, p }); }
  }

  ov.innerHTML = `
    <div style="display:flex;align-items:center;gap:14px;padding:14px 20px;background:var(--surface-1);border-bottom:1px solid var(--border);">
      <div style="font-size:17px;font-weight:800;">\u{1F5D6} Plan Picker</div>
      <div style="font-size:13px;color:var(--text-muted);">${escWeb(c.name || '')} \u00b7 ${plans.length} of ${all.length} plans</div>
      <button class="btn btn-primary btn-sm" style="margin-left:auto;" onclick="closeAcaPicker_()">\u2713 Done \u2014 back to quote</button>
    </div>
    ${acaCsrBanner_()}
    ${pkBasisPanel_()}
    <div style="flex:1;display:flex;min-height:0;">
      <div style="width:230px;flex-shrink:0;overflow-y:auto;padding:16px;border-right:1px solid var(--border);background:var(--surface-1);">
        ${pkFacet_('Insurance company', 'carriers', carriers)}
        ${pkFacet_('Plan level', 'metals', metals)}
        ${pkFacet_('Network type', 'types', types)}
        <div style="margin-bottom:14px;">
          <div style="font-size:11px;font-weight:800;text-transform:uppercase;letter-spacing:.5px;color:var(--text-muted);margin-bottom:6px;">More</div>
          <label style="display:flex;gap:7px;align-items:center;font-size:12.5px;padding:2px 0;cursor:pointer;">
            <input type="checkbox" ${_qbPk.hsa ? 'checked' : ''} onchange="_qbPk.hsa=this.checked;renderPickerBody_()" style="width:14px;height:14px;" /> HSA-eligible only</label>
          ${docs.length ? `<label style="display:flex;gap:7px;align-items:center;font-size:12.5px;padding:2px 0;cursor:pointer;">
            <input type="checkbox" ${_qbPk.docsAll ? 'checked' : ''} onchange="_qbPk.docsAll=this.checked;renderPickerBody_()" style="width:14px;height:14px;" /> Covers ALL their doctors</label>` : ''}
          ${meds.length ? `<label style="display:flex;gap:7px;align-items:center;font-size:12.5px;padding:2px 0;cursor:pointer;">
            <input type="checkbox" ${_qbPk.medsAll ? 'checked' : ''} onchange="_qbPk.medsAll=this.checked;renderPickerBody_()" style="width:14px;height:14px;" /> Covers ALL their medications</label>` : ''}
          <div style="font-size:12.5px;margin-top:6px;">Client cost under
            $<input type="number" value="${_qbPk.maxNet != null ? _qbPk.maxNet : ''}" style="width:70px;font-size:12px;"
              onchange="_qbPk.maxNet=this.value===''?null:parseFloat(this.value);renderPickerBody_()" />/mo</div>
        </div>
        <button class="btn btn-outline btn-sm" style="width:100%;" onclick="openAcaPicker_()">Reset filters</button>
      </div>
      <div style="flex:1;display:flex;flex-direction:column;min-width:0;">
        <div style="display:flex;align-items:center;gap:10px;padding:10px 20px;border-bottom:1px solid var(--border);font-size:12.5px;">
          Sort by
          <select onchange="_qbPk.sort=this.value;renderPickerBody_()" style="width:auto;font-size:12.5px;">
            <option value="net"${_qbPk.sort === 'net' ? ' selected' : ''}>Lowest cost to client</option>
            <option value="premium"${_qbPk.sort === 'premium' ? ' selected' : ''}>Lowest full premium</option>
            <option value="deductible"${_qbPk.sort === 'deductible' ? ' selected' : ''}>Lowest deductible</option>
            <option value="moop"${_qbPk.sort === 'moop' ? ' selected' : ''}>Lowest max out-of-pocket</option>
            <option value="rating"${_qbPk.sort === 'rating' ? ' selected' : ''}>Highest star rating</option>
          </select>
          ${_qbPk.cmp.size ? `<button class="btn ${_qbPk.cmp.size >= 2 ? 'btn-primary' : 'btn-outline'} btn-sm" ${_qbPk.cmp.size >= 2 ? '' : 'disabled'} onclick="openAcaCompare_()">⚖️ Compare (${_qbPk.cmp.size})</button>` : ''}
          <span style="color:var(--text-muted);margin-left:auto;">${added.length}/${QB_MAX_OPTIONS} on the quote</span>
        </div>
        <div style="flex:1;overflow-y:auto;padding:18px 26px 14px;display:flex;flex-direction:column;gap:14px;">
          ${plans.length ? plans.map(p => pkCard_(p)).join('') : '<div style="color:var(--text-muted);padding:30px;text-align:center;">No plans match these filters \u2014 loosen something.</div>'}
        </div>
        <div class="pk-tray" style="padding:10px 20px;display:flex;gap:10px;align-items:center;flex-wrap:wrap;">
          <span class="pk-tray-label">On the quote${added.length ? ' \u00b7 ' + added.length : ''}</span>
          ${added.length ? added.map(a => `<div class="pk-tray-item">
            <span class="num">${qbOptionNo_(a.i)}</span>
            <div class="who">
              <div class="carrier">${escWeb(a.p.issuer || '')}</div>
              <div class="pname" title="${escWeb(a.p.name)}">${escWeb(a.p.name)}</div>
            </div>
            <div class="price">$${Number(a.p.net).toFixed(0)}<span style="font-size:9.5px;font-weight:600;color:var(--text-muted);">/mo</span></div>
            <button class="rm" title="Remove from the quote" onclick="qbAcaAddPlan_('${escWeb(a.p.id)}')">\u2715</button>
          </div>`).join('')
          : '<span style="font-size:12px;color:var(--text-muted);">nothing yet \u2014 click \u201cAdd\u201d on the plans that fit.</span>'}
          <button class="btn btn-primary btn-sm" style="margin-left:auto;" onclick="closeAcaPicker_()">\u2713 Create Quote</button>
        </div>
      </div>
    </div>`;
}

const ACA_TYPE_TIPS = {
  HMO: 'HMO — Health Maintenance Organization. You pick a primary doctor in the plan’s network and need referrals to see specialists. No coverage outside the network except true emergencies. Usually the lowest premiums.',
  PPO: 'PPO — Preferred Provider Organization. See any doctor without a referral, in or out of network (staying in network costs less). The most flexibility, usually higher premiums.',
  EPO: 'EPO — Exclusive Provider Organization. No referrals needed, but you must stay in the plan’s network except emergencies. A middle ground between HMO and PPO.',
  POS: 'POS — Point of Service. You pick a primary doctor and need referrals like an HMO, but you can go out of network at a higher cost, like a PPO.',
  Indemnity: 'Indemnity — the plan pays a set share of each service and you can use any provider. Rare on the Marketplace.',
};
const ACA_HSA_TIP = 'HSA-eligible — this high-deductible plan lets you open a Health Savings Account: money goes in tax-free, grows tax-free, and comes out tax-free for qualified medical costs.';
const ACA_METAL_TIPS = {
  Bronze: 'Bronze — the plan pays about 60% of covered costs on average; you pay the rest. Lowest premiums, highest out-of-pocket. Good if you rarely use care.',
  Silver: 'Silver — the plan pays about 70% of covered costs on average. Only Silver plans qualify for extra cost-sharing reduction (CSR) savings at lower incomes.',
  Gold: 'Gold — the plan pays about 80% of covered costs on average. Higher premiums, lower costs when you actually use care.',
  Platinum: 'Platinum — the plan pays about 90% of covered costs on average. Highest premiums, lowest out-of-pocket.',
  Catastrophic: 'Catastrophic — a bare-bones safety net with a very high deductible. Only for people under 30 or with a hardship exemption; tax credits can’t be used on it.',
};
function acaTip_(map, key) {
  const t = map === 'hsa' ? ACA_HSA_TIP : (map === 'metal' ? ACA_METAL_TIPS[key] : ACA_TYPE_TIPS[String(key || '').toUpperCase()]);
  return t ? ` title="${escWeb(t)}" ` : ' ';
}

function pkCmpToggle_(id, cb) {
  if (cb.checked) {
    if (_qbPk.cmp.size >= 5) { cb.checked = false; showToast('Compare up to 5 plans at a time.'); return; }
    _qbPk.cmp.add(id);
  } else _qbPk.cmp.delete(id);
  renderPickerBody_();
}

async function qbAcaDetail_(planId) {
  window._qbAcaDetailCache = window._qbAcaDetailCache || {};
  if (window._qbAcaDetailCache[planId]) return window._qbAcaDetailCache[planId];
  const resp = await acaProxy_('aca_plan_detail', { id: planId, year: window._qbAcaYear || new Date().getFullYear() });
  if (resp.status !== 'ok') throw new Error(resp.message || 'detail fetch failed');
  const d = (resp.data && (resp.data.plan || resp.data)) || {};
  window._qbAcaDetailCache[planId] = d;
  return d;
}

function acaCsText_(b) {
  const cs = (b.cost_sharings || [])[0] || {};
  if (cs.display_string) return cs.display_string;
  const bits = [];
  if (cs.copay_amount != null && cs.copay_amount > 0) bits.push('$' + cs.copay_amount + ' copay');
  if (cs.coinsurance_rate != null && cs.coinsurance_rate > 0) bits.push(Math.round(cs.coinsurance_rate * 100) + '% coinsurance');
  if (cs.copay_amount === 0 && !cs.coinsurance_rate) bits.push('No charge');
  return bits.join(' + ') || '';
}

function closeAcaCompare_() {
  const el = document.getElementById('qb-aca-compare');
  if (el) el.remove();
  if (document.getElementById('qb-aca-picker')) renderPickerBody_();
}

async function openAcaCompare_() {
  const plans = [..._qbPk.cmp].map(id => (window._qbAcaPlans || []).find(p => p.id === id)).filter(Boolean);
  if (plans.length < 2) { showToast('Tick ⚖️ Compare on at least 2 plans first.'); return; }
  let ov = document.getElementById('qb-aca-compare');
  if (!ov) {
    ov = document.createElement('div');
    ov.id = 'qb-aca-compare';
    ov.style.cssText = 'position:fixed;inset:0;z-index:99996;background:var(--surface-0);display:flex;flex-direction:column;';
    document.body.appendChild(ov);
  }
  ov.innerHTML = `<div style="padding:40px;text-align:center;color:var(--text-muted);">Pulling the official records for ${plans.length} plans…</div>`;
  const details = {};
  await Promise.all(plans.map(async p => { try { details[p.id] = await qbAcaDetail_(p.id); } catch (e) { details[p.id] = null; } }));
  window._qbCmpPlans = plans; window._qbCmpDetails = details;
  renderAcaCompare_();
}

function renderAcaCompare_() {
  const ov = document.getElementById('qb-aca-compare');
  const plans = window._qbCmpPlans || [], details = window._qbCmpDetails || {};
  if (!ov || !plans.length) return;
  const docs = window._qbAcaDocs || [], meds = window._qbAcaMeds || [];
  const famQ = !!window._qbAcaFamilyQuote;
  const LBL = { benefits_url: '\u{1F4C4} SBC', brochure_url: '\u{1F4D8} Brochure', formulary_url: '\u{1F48A} Drug list', network_url: '\u{1FA7A} Directory' };
  const money = v => v != null ? '$' + Number(v).toLocaleString() : '—';
  const thL = 'position:sticky;left:0;background:var(--surface-1);z-index:2;text-align:left;font-size:11.5px;font-weight:700;color:var(--text-muted);padding:7px 12px;border-bottom:0.5px solid var(--border);min-width:170px;max-width:190px;';
  const td = 'padding:7px 12px;border-bottom:0.5px solid var(--border);font-size:12.5px;vertical-align:top;min-width:190px;';
  const row = (label, cellFn) => `<tr><th style="${thL}">${label}</th>${plans.map(p => `<td style="${td}">${cellFn(p)}</td>`).join('')}</tr>`;

  // union of benefit names, in first-plan order then extras
  const benefitNames = [];
  plans.forEach(p => ((details[p.id] || {}).benefits || []).forEach(b => { if (b.name && !benefitNames.includes(b.name)) benefitNames.push(b.name); }));
  const benefitOf = (p, name) => (((details[p.id] || {}).benefits) || []).find(b => b.name === name);

  ov.innerHTML = `
    <div style="display:flex;align-items:center;gap:14px;padding:14px 20px;background:var(--surface-1);border-bottom:1px solid var(--border);">
      <div style="font-size:17px;font-weight:800;">⚖️ Side-by-side — ${plans.length} plans</div>
      <button class="btn btn-outline btn-sm" style="margin-left:auto;" onclick="closeAcaCompare_()">← Back to all plans</button>
      <button class="btn btn-primary btn-sm" onclick="closeAcaCompare_();closeAcaPicker_()">✓ Done — back to quote</button>
    </div>
    <div style="flex:1;overflow:auto;">
      <table style="border-collapse:collapse;min-width:100%;">
        <thead><tr>
          <th style="${thL}border-bottom:1px solid var(--border);"></th>
          ${plans.map(p => {
            const ms = METAL_STYLE[p.metal] || { bg: 'var(--surface-2)', fg: 'var(--text-muted)' };
            const credit = (p.premium != null && p.net != null && p.premium > p.net) ? p.premium - p.net : 0;
            const slot = qbAcaAddedSlot_(p.id);
            return `<td style="${td}border-bottom:1px solid var(--border);background:var(--surface-1);">
              <span${acaTip_('metal', p.metal)}style="cursor:help;background:${ms.bg};color:${ms.fg};font-size:10px;font-weight:800;border-radius:6px;padding:2px 8px;text-transform:uppercase;">${escWeb(p.metal || '')}</span>
              ${acaCsrBadge_(p.metal)}
              ${p.type ? `<span${acaTip_('type', p.type)}style="cursor:help;font-size:10px;color:var(--text-muted);border:1px solid var(--border);border-radius:6px;padding:2px 6px;">${escWeb(p.type)}</span>` : ''}
              <div style="font-size:11px;font-weight:700;text-transform:uppercase;color:var(--text-muted);margin-top:5px;">${escWeb(p.issuer || '')}</div>
              <div style="font-size:13px;font-weight:600;margin:2px 0 6px;">${escWeb(p.name)}</div>
              <div style="font-size:21px;font-weight:800;color:var(--accent,#1d3557);">$${Number(p.net).toFixed(2)}<span style="font-size:10px;font-weight:500;color:var(--text-muted);"> /mo</span></div>
              ${credit ? `<div style="font-size:10.5px;color:var(--text-muted);">full $${Number(p.premium).toFixed(0)} − <span style="color:var(--success);">$${credit.toFixed(0)} credit</span></div>` : ''}
              <button class="btn ${slot >= 0 ? 'btn-outline' : 'btn-primary'} btn-sm" style="margin-top:6px;width:100%;${slot >= 0 ? 'color:var(--success);border-color:var(--success);' : ''}"
                onclick="qbAcaAddPlan_('${escWeb(p.id)}');renderAcaCompare_()">${slot >= 0 ? '✓ Option ' + qbOptionNo_(slot) + ' — remove' : '＋ Add to quote'}</button>
            </td>`;
          }).join('')}
        </tr></thead>
        <tbody>
          ${row('Deductible' + (famQ ? ' (per person)' : ''), p => `<strong>${money(p.deductible)}</strong>`)}
          ${famQ ? row('Deductible (family)', p => money(p.deductible_family)) : ''}
          ${row('Max out-of-pocket' + (famQ ? ' (per person)' : ''), p => `<strong>${money(p.moop)}</strong>`)}
          ${famQ ? row('Max out-of-pocket (family)', p => money(p.moop_family)) : ''}
          ${row('HSA-eligible', p => p.hsa ? '<span style="color:#0d9488;font-weight:700;">✓ Yes</span>' : '—')}
          ${row('Star rating', p => p.rating ? '⭐ ' + p.rating + ' of 5' : '—')}
          ${docs.map(d => row('\u{1FA7A} ' + escWeb(d.name.split(' · ')[0]), p => {
            const known = p._docCov && d.npi in p._docCov;
            return known ? (p._docCov[d.npi] ? '<span style="color:var(--success);font-weight:700;">✓ In network</span>' : '<span style="color:var(--danger);">✗ Not found</span>') : '<span style="color:var(--text-muted);">?</span>';
          })).join('')}
          ${meds.map(m => row('\u{1F48A} ' + escWeb(m.name), p => {
            const known = p._medCov && m.rxcui in p._medCov;
            return known ? (p._medCov[m.rxcui] ? '<span style="color:var(--success);font-weight:700;">✓ Covered</span>' : '<span style="color:var(--danger);">✗ Not covered</span>') : '<span style="color:var(--text-muted);">?</span>';
          })).join('')}
          ${row('Official documents', p => {
            const d = details[p.id];
            if (!d) return '<span style="color:var(--text-muted);">unavailable</span>';
            const links = Object.keys(LBL).filter(k => d[k]).map(k =>
              `<a href="${escWeb(d[k])}" target="_blank" rel="noopener" style="font-size:11px;display:inline-block;border:1px solid var(--border);border-radius:999px;padding:2px 8px;text-decoration:none;margin:1px 2px 1px 0;">${LBL[k]} ↗</a>`).join('');
            return links || '<span style="color:var(--text-muted);">none published</span>';
          })}
          ${benefitNames.map(name => row(escWeb(name), p => {
            const b = benefitOf(p, name);
            if (!b) return '<span style="color:var(--text-muted);">—</span>';
            return b.covered
              ? '<span style="color:var(--success);font-weight:700;">✓</span> <span style="color:var(--text-secondary);font-size:12px;">' + escWeb(acaCsText_(b)) + '</span>'
              : '<span style="color:var(--danger);">✗ Not covered</span>';
          })).join('')}
        </tbody>
      </table>
    </div>`;
}

async function openPlanDetail_(planId) {
  const p = (window._qbAcaPlans || []).find(x => x.id === planId);
  let dr = document.getElementById('qb-plan-detail');
  if (!dr) {
    dr = document.createElement('div');
    dr.id = 'qb-plan-detail';
    dr.style.cssText = 'position:fixed;top:0;right:0;bottom:0;width:min(560px,92vw);z-index:99995;background:var(--surface-1,#fff);border-left:1px solid var(--border);box-shadow:-12px 0 40px rgba(15,23,42,.18);display:flex;flex-direction:column;';
    document.body.appendChild(dr);
  }
  dr.style.display = 'flex';
  dr.innerHTML = `<div style="padding:16px 20px;border-bottom:1px solid var(--border);display:flex;align-items:center;gap:10px;">
      <div style="font-weight:800;font-size:15px;flex:1;min-width:0;">${escWeb(p ? p.name : 'Plan details')}</div>
      <button class="btn btn-outline btn-sm" onclick="document.getElementById('qb-plan-detail').style.display='none'">\u2715 Close</button>
    </div>
    <div style="padding:24px;color:var(--text-muted);font-size:13px;">Loading the official plan record\u2026</div>`;
  try {
    const d = await qbAcaDetail_(planId);
    const LINK_LABELS = {
      benefits_url: '\u{1F4C4} Summary of Benefits & Coverage (SBC)',
      brochure_url: '\u{1F4D8} Plan brochure',
      formulary_url: '\u{1F48A} Drug formulary',
      network_url: '\u{1FA7A} Provider directory',
    };
    const links = Object.keys(LINK_LABELS)
      .filter(k => d[k])
      .map(k => `<a class="btn btn-outline btn-sm" style="text-decoration:none;" href="${escWeb(d[k])}" target="_blank" rel="noopener">${LINK_LABELS[k]} \u2197</a>`)
      .join(' ');
    const csText = b => {
      const cs = (b.cost_sharings || [])[0] || {};
      if (cs.display_string) return cs.display_string;
      const bits = [];
      if (cs.copay_amount != null && cs.copay_amount > 0) bits.push('$' + cs.copay_amount + ' copay');
      if (cs.coinsurance_rate != null && cs.coinsurance_rate > 0) bits.push(Math.round(cs.coinsurance_rate * 100) + '% coinsurance');
      if (cs.copay_amount === 0 && !cs.coinsurance_rate) bits.push('No charge');
      return bits.join(' + ') || '';
    };
    const benefits = (d.benefits || []).map(b => `
      <tr>
        <td style="padding:5px 8px;border-bottom:0.5px solid var(--border);font-size:12.5px;">${escWeb(b.name || '')}</td>
        <td style="padding:5px 8px;border-bottom:0.5px solid var(--border);text-align:center;">${b.covered ? '<span style="color:var(--success);font-weight:700;">\u2713</span>' : '<span style="color:var(--danger);">\u2717</span>'}</td>
        <td style="padding:5px 8px;border-bottom:0.5px solid var(--border);font-size:12px;color:var(--text-secondary);">${escWeb(csText(b))}</td>
      </tr>`).join('');
    const head = p ? `
      <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:6px;">
        <span${acaTip_('metal', p.metal)}style="cursor:help;background:${(METAL_STYLE[p.metal] || {}).bg || 'var(--surface-2)'};color:${(METAL_STYLE[p.metal] || {}).fg || 'inherit'};font-size:10px;font-weight:800;border-radius:6px;padding:2px 8px;text-transform:uppercase;">${escWeb(p.metal || '')}</span>
        ${acaCsrBadge_(p.metal)}
        ${p.type ? `<span${acaTip_('type', p.type)}style="cursor:help;font-size:10px;color:var(--text-muted);border:1px solid var(--border);border-radius:6px;padding:2px 6px;">${escWeb(p.type)}</span>` : ''}
        <span style="font-size:12px;color:var(--text-muted);">${escWeb(p.issuer || '')}</span>
        <span style="margin-left:auto;font-size:18px;font-weight:800;color:var(--accent,#1d3557);">$${Number(p.net).toFixed(2)}/mo</span>
      </div>
      <div style="display:flex;gap:14px;font-size:12px;color:var(--text-secondary);flex-wrap:wrap;margin-bottom:10px;">
        ${qbAcaCostFact_('Deductible', p.deductible, p.deductible_family)}
        ${qbAcaCostFact_('Max OOP', p.moop, p.moop_family)}
        ${p.rating ? `<span>\u2b50 ${p.rating} of 5</span>` : ''}
      </div>` : '';
    dr.querySelector('div:last-child').outerHTML = `
      <div style="flex:1;overflow-y:auto;padding:16px 20px;">
        ${head}
        ${links ? `<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px;">${links}</div>` : '<div style="font-size:12px;color:var(--text-muted);margin-bottom:14px;">No official documents published for this plan.</div>'}
        ${benefits ? `<div style="font-size:11px;font-weight:800;text-transform:uppercase;letter-spacing:.5px;color:var(--text-muted);margin-bottom:6px;">What it covers</div>
          <table style="width:100%;border-collapse:collapse;">
            <thead><tr style="text-align:left;font-size:10px;text-transform:uppercase;color:var(--text-muted);">
              <th style="padding:4px 8px;">Benefit</th><th style="padding:4px 8px;">Covered</th><th style="padding:4px 8px;">You pay</th></tr></thead>
            <tbody>${benefits}</tbody></table>` : '<div style="font-size:12px;color:var(--text-muted);">Benefit details not published \u2014 use the SBC link above.</div>'}
        <div style="margin-top:14px;">
          <button class="btn btn-primary" style="width:100%;" onclick="qbAcaAddPlan_('${escWeb(planId)}');document.getElementById('qb-plan-detail').style.display='none';">\uff0b Add this plan to the quote</button>
        </div>
      </div>`;
  } catch (e) {
    dr.querySelector('div:last-child').innerHTML = '<span style="color:var(--danger);">Could not load plan details: ' + escWeb(e.message || e) + '</span>';
  }
}

function pkCard_(p) {
  const ms = METAL_STYLE[p.metal] || { bg: 'var(--surface-2)', fg: 'var(--text-muted)' };
  const credit = (p.premium != null && p.net != null && p.premium > p.net) ? p.premium - p.net : 0;
  const slot = qbAcaAddedSlot_(p.id);
  return `<div onclick="openPlanDetail_('${escWeb(p.id)}')" title="Click for full plan details"
    class="pk-card${slot >= 0 ? ' is-selected' : ''}"
    style="cursor:pointer;display:flex;gap:16px;align-items:stretch;border-radius:12px;padding:14px 16px;transition:box-shadow .15s ease;"
    onmouseover="this.style.boxShadow='0 6px 20px rgba(0,0,0,.18)';"
    onmouseout="this.style.boxShadow='none';">
    <div style="flex:1;min-width:0;">
      <div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap;">
        <span${acaTip_('metal', p.metal)}style="cursor:help;background:${ms.bg};color:${ms.fg};font-size:10px;font-weight:800;letter-spacing:.5px;border-radius:6px;padding:2px 8px;text-transform:uppercase;">${escWeb(p.metal || 'Plan')}</span>
        ${acaCsrBadge_(p.metal)}
        ${p.type ? `<span${acaTip_('type', p.type)}style="cursor:help;font-size:10px;color:var(--text-muted);border:1px solid var(--border);border-radius:6px;padding:2px 6px;">${escWeb(p.type)}</span>` : ''}
        ${p.hsa ? `<span${acaTip_('hsa')}style="cursor:help;font-size:10px;color:#0d9488;border:1px solid #0d9488;border-radius:6px;padding:2px 6px;">HSA</span>` : ''}
        ${p.rating ? `<span style="font-size:11px;color:#b3903a;">\u2b50 ${p.rating}</span>` : ''}
        <span style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.5px;color:var(--text-muted);">${escWeb(p.issuer || '')}</span>
      </div>
      <div style="font-size:14px;font-weight:600;margin:4px 0 6px;">${slot >= 0 ? `<span class="pk-sel-badge">\u2713 Selected \u00b7 Option ${qbOptionNo_(slot)}</span>` : ''}${escWeb(p.name)}</div>
      <div style="display:flex;gap:14px;font-size:12px;color:var(--text-secondary);flex-wrap:wrap;">
        ${qbAcaCostFact_('Deductible', p.deductible, p.deductible_family)}
        ${qbAcaCostFact_('Max out-of-pocket', p.moop, p.moop_family)}
      </div>
      ${qbAcaCovLines_(p)}
      <div style="display:flex;gap:10px;align-items:center;margin-top:8px;">
        <label onclick="event.stopPropagation();" style="display:flex;gap:5px;align-items:center;font-size:11px;color:var(--text-muted);cursor:pointer;">
          <input type="checkbox" ${_qbPk.cmp.has(p.id) ? 'checked' : ''} onclick="event.stopPropagation();"
            onchange="pkCmpToggle_('${escWeb(p.id)}', this)" style="width:13px;height:13px;" /> \u2696\ufe0f Compare</label>
        <button type="button" class="btn btn-outline btn-sm" onclick="event.stopPropagation();openPlanDetail_('${escWeb(p.id)}')">Details</button>
      </div>
    </div>
    <div style="width:170px;flex-shrink:0;display:flex;flex-direction:column;align-items:flex-end;justify-content:flex-start;gap:4px;border-left:1px solid var(--border);padding-left:16px;">
      <div style="display:flex;width:100%;align-items:center;gap:8px;margin-bottom:4px;">
        ${acaCsrMedal_(p.metal)}
        <button type="button" class="btn ${slot >= 0 ? 'btn-outline' : 'btn-primary'} btn-sm" style="margin-left:auto;${slot >= 0 ? 'color:var(--success);border-color:var(--success);' : ''}"
          onclick="event.stopPropagation();qbAcaAddPlan_('${escWeb(p.id)}')">${slot >= 0 ? '\u2713 Option ' + qbOptionNo_(slot) : '\uff0b Add'}</button>
      </div>
      <div style="font-size:24px;font-weight:800;color:var(--accent,#1d3557);line-height:1;">$${Number(p.net).toFixed(2)}</div>
      <div style="font-size:10.5px;color:var(--text-muted);">/mo to client</div>
      ${credit ? `<div style="font-size:10.5px;color:var(--text-muted);text-align:right;">full $${Number(p.premium).toFixed(0)} \u2212 <span style="color:var(--success);">$${credit.toFixed(0)} credit</span></div>` : ''}

    </div>
  </div>`;
}


function qbAcaAddPlan_(planId) {
  const existing = qbAcaAddedSlot_(planId);
  if (existing >= 0) {
    // remove from the quote
    const sel = document.getElementById('qb-aca-' + existing);
    sel.value = '';
    qbApplyAcaPlan_(existing);
    ['qb-name-', 'qb-prem-', 'qb-bul-', 'qb-note-'].forEach(pref => {
      const el = document.getElementById(pref + existing); if (el) el.value = '';
    });
    const rec = document.getElementById('qb-rec-' + existing); if (rec) rec.checked = false;
    qbTidyOptions_();
    qbAcaRenderBrowser_();
    if (document.getElementById('qb-aca-picker')) renderPickerBody_();
    return;
  }
  let slot = -1;
  for (let i = 0; i < QB_MAX_OPTIONS; i++) {
    if (!qbOptionFilled_(i)) { slot = i; break; }
  }
  if (slot === -1) { showToast('All ' + QB_MAX_OPTIONS + ' option slots are full \u2014 remove one first.'); return; }
  const wrap = document.getElementById('qb-opt-wrap-' + slot);
  if (wrap) wrap.style.display = 'block';
  const sel = document.getElementById('qb-aca-' + slot);
  if (sel) { sel.value = planId; qbApplyAcaPlan_(slot); }
  qbRenumberOptions_();
  qbSectionSummary_();
  showToast('Added as Option ' + qbOptionNo_(slot) + '.');
  qbAcaRenderBrowser_();
  if (document.getElementById('qb-aca-picker')) renderPickerBody_();
}

// Is this option one the Marketplace could ever have priced? A saved option
// says where it came from; failing that its coverage type does; failing both,
// a metal level in the name is the giveaway.
function qbSlotIsAca_(i, meta, name) {
  if (meta && meta.src) return meta.src === 'aca';
  const line = (document.getElementById('qb-optline-' + i) || {}).value || '';
  if (line) return line === 'Health — Individual';
  return /\((Bronze|Silver|Gold|Platinum|Catastrophic)\)\s*$/i.test(name || '');
}

function qbAcaRelinkOptions_() {
  const plans = window._qbAcaPlans || [];
  window._qbAcaUnmatched = [];
  if (!plans.length) return 0;
  const rq = window._qbRequoteOpt || {};
  window._qbAcaSel = window._qbAcaSel || {};
  let linked = 0;
  for (let i = 0; i < QB_MAX_OPTIONS; i++) {
    const sel = document.getElementById('qb-aca-' + i);
    const nameEl = document.getElementById('qb-name-' + i);
    if (!sel || !nameEl || sel.value) continue;        // already linked
    const nm = (nameEl.value || '').trim();
    if (!nm) continue;
    let hit = null;
    const meta = rq[i] && rq[i].plan_meta;
    if (meta && meta.plan_id) hit = plans.find(p => p.id === meta.plan_id);
    if (!hit) {
      const bare = nm.replace(/\s*\((Bronze|Silver|Gold|Platinum|Catastrophic)\)\s*$/i, '').trim().toLowerCase();
      hit = plans.find(p => String(p.name || '').trim().toLowerCase() === bare);
    }
    if (hit) {
      sel.value = hit.id;
      window._qbAcaSel[i] = hit;
      qbAcaApptWarn_(i, hit);
      qbAcaOptionView_(i);      // rewrites name/premium from the plan
      linked++;
    } else if (qbSlotIsAca_(i, meta, nm)) {
      // looked like a Marketplace plan but isn't in this year's list
      window._qbAcaUnmatched.push({ slot: i, name: nm });
    }
  }
  return linked;
}

async function qbAcaGetPlans_() {
  const c = window._qbContact;
  const res = document.getElementById('qb-aca-result');
  const income = parseFloat(document.getElementById('qb-aca-income').value);
  const county = document.getElementById('qb-aca-county').value;
  if (!income || !county) { showToast('Enter household income and pick the county.'); return; }
  const people = [...document.querySelectorAll('#qb-aca-members > div')].map(d => ({
    relationship: d.querySelector('.aca-rel').value,
    age: parseInt(d.querySelector('.aca-age').value),
    gender: d.querySelector('.aca-gen').value,
    uses_tobacco: d.querySelector('.aca-tob').checked,
    applying: d.querySelector('.aca-app') ? d.querySelector('.aca-app').checked : true,
    has_mec: d.querySelector('.aca-mec') ? d.querySelector('.aca-mec').checked : false,
  })).filter(m => !isNaN(m.age));
  if (!people.some(m => m.applying)) { showToast('At least one household member must be marked Applying.'); return; }
  if (!people.length) { showToast('Add at least the client with an age.'); return; }
  res.textContent = 'Asking healthcare.gov…';
  try {
    const data = await acaProxy_('aca_quote', {
      payload: JSON.stringify({
        zipcode: c.zip, countyfips: county.split('|')[0], state: county.split('|')[1],
        income: income, people: people,
      })
    });
    if (data.status !== 'ok') { res.innerHTML = '<span style="color:var(--danger);">' + escWeb(data.message || 'Marketplace error.') + '</span>'; return; }
    window._qbAcaPlans = data.plans || [];
    window._qbAcaYear = data.year;
    window._qbAcaFamilyQuote = (data.applicant_count != null ? data.applicant_count : people.filter(m => m.applying).length) > 1;
    window._qbAcaCsr = data.csr || null;
    if (!c.state && county.split('|')[1]) {
      const st2 = county.split('|')[1];
      supabaseClient.from('contacts').update({ state: st2 }).eq('id', c.id)
        .then(() => { c.state = st2; }, () => {});
    }
    window._qbAcaMedicaid = !!data.medicaid_chip;
    window._qbAcaAptc = (data.aptc != null) ? data.aptc : null;
    qbAcaSyncIncomeToIntake_(income);
    // Snapshot the inputs behind these numbers — saved onto the quote for the client's "based on" panel
    const countySel2 = document.getElementById('qb-aca-county');
    window._qbAcaInputs = {
      income: income, zip: c.zip || null,
      county: countySel2.options[countySel2.selectedIndex] ? countySel2.options[countySel2.selectedIndex].text : null,
      aptc: data.aptc != null ? data.aptc : null, csr: data.csr || null,
      coverage_start: (document.getElementById('qb-aca-start') || {}).value || null,
      doctors: (window._qbAcaDocs || []).map(d => d.name),
      medications: (window._qbAcaMeds || []).map(m => m.name),
      household: people.map(m => ({ relationship: m.relationship, age: m.age, applying: !!m.applying })),
      applicant_count: data.applicant_count != null ? data.applicant_count : people.filter(m => m.applying).length,
      household_count: data.household_count != null ? data.household_count : people.length,
    };
    let subsidy = data.aptc != null && data.aptc > 0
      ? '<span style="color:var(--success);font-weight:700;">Estimated tax credit: $' + Number(data.aptc).toFixed(0) + '/mo</span>'
      : 'No tax credit at this income';
    if (data.medicaid_chip) subsidy = '<span style="color:var(--text-warning);font-weight:700;">&#9888; This household may qualify for Medicaid/CHIP \u2014 check that door before quoting marketplace plans.</span> ' + subsidy;
    if (data.applicant_count != null && data.household_count != null && data.applicant_count < data.household_count)
      subsidy += ' <span style="color:var(--text-muted);">(pricing ' + data.applicant_count + ' of ' + data.household_count + ' household members)</span>';
    const ichraSel = document.getElementById('qb-aca-ichra');
    if (ichraSel && ichraSel.value === 'yes') {
      const amt = parseFloat(document.getElementById('qb-aca-ichra-amt').value) || 0;
      subsidy = '<span style="color:var(--danger);font-weight:700;">&#9888; ICHRA/HRA offer on file' + (amt ? ' ($' + amt + '/mo)' : '') + ': if that offer meets federal affordability rules, tax credits do NOT apply \u2014 verify before presenting net prices.</span><br>' + subsidy;
      qbAcaIchraVerdict_(income, county, people, amt);
    }
    res.innerHTML = subsidy
      + (data.csr && !/none/i.test(String(data.csr)) ? ' &middot; extra Silver savings (CSR: ' + escWeb(String(data.csr)) + ')' : '')
      + ' &middot; ' + window._qbAcaPlans.length + ' plans (' + data.year + '). Prices shown are AFTER the credit.';
    const opts = '<option value="">&mdash; pick a plan &mdash;</option>'
      + window._qbAcaPlans.map(p =>
        `<option value="${escWeb(p.id)}">${escWeb(p.metal)}: ${escWeb((p.issuer ? p.issuer + ' — ' : '') + p.name)} ($${Number(p.net).toFixed(2)}/mo)</option>`).join('');
    for (let i = 0; i < QB_MAX_OPTIONS; i++) {
      const sel = document.getElementById('qb-aca-' + i);
      if (sel) sel.innerHTML = opts;
    }
    qbAcaRelinkOptions_();     // plans already on the quote show as chosen
    qbAutoCardPaint_();
    _qbAcaMetalFilter = 'All';
    qbAcaRenderBrowser_();
    openAcaPicker_();          // straight into the picker — no second click
    qbAcaCheckCoverage_();     // marks stream in as the checks land
  } catch (e) {
    res.innerHTML = '<span style="color:var(--danger);">Marketplace relay unreachable — is the API key set up?</span>';
  }
}

// Fuzzy carrier-name match: "Blue Cross and Blue Shield of Montana" should hit "BCBS MT"
function qbCarrierMatch_(issuer, names) {
  const norm = s => String(s || '').toLowerCase()
    .replace(/blue[\s\/\-\.]*cross[\s\/\-\.]*(and|&)?[\s\/\-\.]*blue[\s\/\-\.]*shield/g, 'bcbs')
    .replace(/\bmontana\b/g, 'mt').replace(/\barizona\b/g, 'az').replace(/\btexas\b/g, 'tx')
    .replace(/\b(health plans?|insurance( company)?|of|the)\b/g, '')
    .replace(/[^a-z0-9]/g, '');
  const A = norm(issuer);
  return (names || []).some(n => { const B = norm(n); return A && B && (A.includes(B) || B.includes(A)); });
}

function qbAcaApptWarn_(i, plan) {
  const warn = document.getElementById('qb-aca-warn-' + i);
  if (!warn) return;
  if (!plan) { warn.style.display = 'none'; warn.innerHTML = ''; return; }
  const notes = [];

  // 1. Can we actually write this carrier?
  const agentOk = qbCarrierMatch_(plan.issuer, (window._qbCarriers || []).map(c => c.name));
  const agencyOk = agentOk || qbCarrierMatch_(plan.issuer, window._qbAgencyCarrierNames || []);
  if (!agentOk) {
    notes.push(agencyOk
      ? { tone: 'warn',
          html: '&#9888;&#65039; You\u2019re not contracted with <strong>' + escWeb(plan.issuer || 'this carrier')
            + '</strong>. Your agency offers it \u2014 check your appointment before enrolling the client (My Profile \u2192 My Carrier Appointments).' }
      : { tone: 'bad',
          html: '&#9888;&#65039; <strong>' + escWeb(plan.issuer || 'This carrier')
            + '</strong> isn\u2019t on your agency\u2019s carrier list \u2014 you likely can\u2019t enroll the client in this plan. Confirm with your agency before presenting it.' });
  }

  // 2. Cost-sharing help left on the table
  const csr = acaCsrActive_();
  if (csr) {
    if (acaCsrAppliesTo_(plan.metal, csr)) {
      notes.push({ tone: 'ok',
        html: '\u2728 <strong>' + escWeb(acaCsrLabel_(csr).replace('\u2728 ', '')) + '</strong> \u2014 this plan\u2019s deductible and out-of-pocket maximum are already reduced for this household.' });
    } else {
      notes.push({ tone: 'warn',
        html: '&#9888;&#65039; This household qualifies for <strong>' + escWeb(acaCsrLabel_(csr).replace('\u2728 ', ''))
          + '</strong>, which only applies to <strong>Silver</strong> plans. Choosing ' + escWeb(plan.metal || 'this plan')
          + ' gives up that reduced deductible and out-of-pocket maximum \u2014 make sure the client is choosing it on purpose.' });
    }
  }

  if (!notes.length) { warn.style.display = 'none'; warn.innerHTML = ''; return; }
  warn.style.display = 'block';
  warn.style.background = 'transparent'; warn.style.border = 'none'; warn.style.padding = '0';
  warn.innerHTML = notes.map(n => `<div class="pk-note ${n.tone}">${n.html}</div>`).join('');
}

// An ACA option is a record, not a form: everything but the agent's own note
// comes from healthcare.gov, so we show it read-only. Two editable copies of
// the same fact is how a quote ends up disagreeing with itself.
function qbAcaOptionView_(i) {
  const card = document.getElementById('qb-aca-card-' + i);
  const manual = document.getElementById('qb-manual-' + i);
  const carprod = document.getElementById('qb-carprod-' + i);
  const acaWrap = document.getElementById('qb-aca-wrap-' + i);
  const p = (window._qbAcaSel || {})[i];
  if (!card) return;

  if (!p) {                                    // manual entry as before
    card.style.display = 'none'; card.innerHTML = '';
    if (manual) manual.style.display = '';
    if (carprod) carprod.style.display = '';
    if (acaWrap) acaWrap.querySelectorAll('label,select').forEach(el => el.style.display = '');
    return;
  }

  // the plan is the single source of truth — rewrite the hidden inputs from it
  const nameEl = document.getElementById('qb-name-' + i);
  const premEl = document.getElementById('qb-prem-' + i);
  if (nameEl) nameEl.value = p.name + (p.metal ? ' (' + p.metal + ')' : '');
  if (premEl) premEl.value = Number(p.net).toFixed(2);

  if (manual) manual.style.display = 'none';
  if (carprod) carprod.style.display = 'none';
  if (acaWrap) acaWrap.querySelectorAll('label,select').forEach(el => el.style.display = 'none');

  const ms = METAL_STYLE[p.metal] || { bg: 'var(--surface-2)', fg: 'var(--text-muted)' };
  const credit = (p.premium != null && p.net != null && p.premium > p.net) ? p.premium - p.net : 0;
  const money = v => v != null ? '$' + Number(v).toLocaleString() : '\u2014';
  const free = Number(p.net) === 0;

  card.style.display = 'block';
  card.innerHTML = `
    <div class="pk-card is-selected" style="border-radius:12px;padding:12px 14px;">
      <div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap;">
        <span${acaTip_('metal', p.metal)}style="cursor:help;background:${ms.bg};color:${ms.fg};font-size:10px;font-weight:800;border-radius:6px;padding:2px 8px;text-transform:uppercase;">${escWeb(p.metal || '')}</span>
        ${p.type ? `<span${acaTip_('type', p.type)}style="cursor:help;font-size:10px;color:var(--text-muted);border:1px solid var(--border);border-radius:6px;padding:2px 6px;">${escWeb(p.type)}</span>` : ''}
        ${p.hsa ? `<span${acaTip_('hsa')}style="cursor:help;font-size:10px;color:#0d9488;border:1px solid #0d9488;border-radius:6px;padding:2px 6px;">HSA</span>` : ''}
        ${acaCsrBadge_(p.metal)}
        ${p.rating ? `<span style="font-size:11px;color:#b3903a;">\u2b50 ${p.rating}</span>` : ''}
      </div>
      <div style="font-size:10.5px;font-weight:800;text-transform:uppercase;letter-spacing:.5px;color:var(--text-muted);margin-top:6px;">${escWeb(p.issuer || '')}</div>
      <div style="font-size:14.5px;font-weight:700;margin:1px 0 8px;">${escWeb(p.name)}</div>
      <div style="display:flex;align-items:flex-end;gap:14px;flex-wrap:wrap;">
        <div>
          <div style="font-size:22px;font-weight:800;color:var(--accent,#1d3557);line-height:1;">$${Number(p.net).toFixed(2)}<span style="font-size:10.5px;font-weight:500;color:var(--text-muted);"> /mo to client</span></div>
          ${credit ? `<div style="font-size:11px;color:var(--text-muted);margin-top:2px;">full $${Number(p.premium).toFixed(2)} \u2212 <span style="color:var(--text-success);font-weight:700;">$${credit.toFixed(2)} tax credit</span>${free ? ' \u2014 <strong>fully covered</strong>' : ''}</div>` : ''}
        </div>
        <div style="display:flex;gap:14px;font-size:12px;color:var(--text-secondary);flex-wrap:wrap;margin-left:auto;">
          ${qbAcaCostFact_('Deductible', p.deductible, p.deductible_family)}
          ${qbAcaCostFact_('Max out-of-pocket', p.moop, p.moop_family)}
        </div>
      </div>
      ${qbAcaCovGroup_(p, i)}
      <div style="display:flex;gap:8px;margin-top:10px;flex-wrap:wrap;">
        <button type="button" class="btn btn-outline btn-sm" onclick="openPlanDetail_('${escWeb(p.id)}')">Plan details</button>
        <button type="button" class="btn btn-outline btn-sm" onclick="openAcaPicker_()">\u{1F5D6} Change plan</button>
        <button type="button" class="btn btn-outline btn-sm" style="color:var(--text-danger);border-color:var(--border-danger);margin-left:auto;" onclick="qbAcaAddPlan_('${escWeb(p.id)}')">\u{1F5D1} Remove</button>
      </div>
      <div style="font-size:10.5px;color:var(--text-muted);margin-top:8px;">${p._snapshot
        ? 'Saved from the last quote' + (p._year ? ' (' + escWeb(String(p._year)) + ' plan year)' : '')
          + ' \u2014 open <strong>Available Automated Quoting</strong> above to re-check this year\u2019s price.'
        : 'Plan name, price and benefits come straight from healthcare.gov \u2014 add your own note below.'}</div>
    </div>`;
}

// A saved ACA option is a complete plan record on its own. Rebuild the card
// from it so re-opening a quote looks the same as building one; the live
// lookup replaces this object with fresh pricing the moment it runs.
// The provider/drug answers are already in hand when the quote is saved, so
// they travel with the plan snapshot. No extra lookups now, and none later
// from the client's page \u2014 it just reads what we recorded.
function qbAcaCoverageSnapshot_(p) {
  const docs = window._qbAcaDocs || [], meds = window._qbAcaMeds || [];
  if (!docs.length && !meds.length) return null;
  const dc = p._docCov || null, mc = p._medCov || null;
  const providers = docs.map(d => ({
    npi: String(d.npi), name: String(d.name || '').split(' \u00b7 ')[0],
    covered: dc && (d.npi in dc) ? !!dc[d.npi] : null,
  }));
  const medications = meds.map(m => ({
    rxcui: String(m.rxcui), name: m.name,
    covered: mc && (m.rxcui in mc) ? !!mc[m.rxcui] : null,
  }));
  // nothing was actually answered \u2014 don't record a wall of question marks
  if (!providers.some(x => x.covered !== null) && !medications.some(x => x.covered !== null)) return null;
  return { checked_at: new Date().toISOString(), providers: providers, medications: medications };
}

function qbAcaHydrateOption_(i, o) {
  const m = o.plan_meta || {};
  window._qbAcaSel = window._qbAcaSel || {};
  window._qbAcaSel[i] = {
    id: m.plan_id || '',
    name: String(o.display_name || '').replace(/\s*\((Bronze|Silver|Gold|Platinum|Catastrophic)\)\s*$/i, '').trim(),
    issuer: o.carrier_name || '',
    metal: m.metal || '', type: m.plan_type || '',
    premium: m.full_premium != null ? m.full_premium : o.monthly_premium,
    net: m.net_premium != null ? m.net_premium : o.monthly_premium,
    deductible: m.deductible, deductible_family: m.deductible_family,
    moop: m.moop, moop_family: m.moop_family,
    hsa: !!m.hsa, rating: m.rating || null,
    _snapshot: true, _year: m.year || null, _links: m.links || null,
    _docCov: (m.coverage && m.coverage.providers || []).reduce((a, x) => { if (x.covered !== null) a[x.npi] = x.covered; return a; }, {}),
    _medCov: (m.coverage && m.coverage.medications || []).reduce((a, x) => { if (x.covered !== null) a[x.rxcui] = x.covered; return a; }, {}),
  };
  if (m.family_quote) window._qbAcaFamilyQuote = true;
  if (m.csr && !window._qbAcaCsr) window._qbAcaCsr = m.csr;
  qbAcaApptWarn_(i, window._qbAcaSel[i]);
  qbAcaOptionView_(i);
}

function qbApplyAcaPlan_(i) {
  const plan = (window._qbAcaPlans || []).find(p => p.id === document.getElementById('qb-aca-' + i).value);
  window._qbAcaSel = window._qbAcaSel || {};
  const cp = document.getElementById('qb-carprod-' + i);
  if (!plan) {
    delete window._qbAcaSel[i];
    if (cp) cp.style.display = '';
    qbAcaApptWarn_(i, null);
    qbAcaOptionView_(i);
    return;
  }
  window._qbAcaSel[i] = plan;
  const _ol = document.getElementById('qb-optline-' + i);
  if (_ol && !_ol.value) { _ol.value = 'Health \u2014 Individual'; qbOptLineChanged_(i); }
  // Official Marketplace plan: our carrier/product catalog doesn't apply — hide it, warn on appointments instead
  if (cp) cp.style.display = 'none';
  const carSel = document.getElementById('qb-car-' + i);
  if (carSel && carSel.value) { carSel.value = ''; qbFillProducts_(i); }
  qbAcaApptWarn_(i, plan);
  qbAcaOptionView_(i);
  document.getElementById('qb-name-' + i).value = plan.name + (plan.metal ? ' (' + plan.metal + ')' : '');
  document.getElementById('qb-prem-' + i).value = Number(plan.net).toFixed(2);
  const bullets = [];
  if (plan.metal) bullets.push(plan.metal + ' plan' + (plan.type ? ' · ' + plan.type : ''));
  if (plan.premium != null && plan.net != null && plan.premium > plan.net)
    bullets.push('Full price $' + Number(plan.premium).toFixed(2) + '/mo — your estimated tax credit covers $' + Number(plan.premium - plan.net).toFixed(2));
  const famQ = !!window._qbAcaFamilyQuote;
  if (plan.deductible != null) bullets.push('Deductible: $' + Number(plan.deductible).toLocaleString()
    + (famQ && plan.deductible_family != null ? ' per person / $' + Number(plan.deductible_family).toLocaleString() + ' family' : ''));
  if (plan.moop != null) bullets.push('Yearly max out-of-pocket: $' + Number(plan.moop).toLocaleString()
    + (famQ && plan.moop_family != null ? ' per person / $' + Number(plan.moop_family).toLocaleString() + ' family' : ''));
  if (plan.hsa) bullets.push('HSA-eligible');
  if (plan.rating) bullets.push('Quality rating: ' + plan.rating + ' of 5');
  // Doctors and drugs are NOT bullets any more. They ride along with the plan
  // snapshot (plan_meta.coverage) and the client page renders them as their
  // own block \u2014 a frozen line of text was drifting out of date and ending up
  // contradicting the live answer sitting right above it.
  document.getElementById('qb-bul-' + i).value = bullets.join('\n');
}

// ============================================================
// CMS LANDSCAPE PICKER — official MA / MA-PD / SNP / PDP plans
// with real premiums, filtered to the client's state and county.
// ============================================================
// ============================================================
// MEDICARE ADVANTAGE / PART D \u2014 ZIP-first, like the ACA tool.
// An agent knows a client\u2019s ZIP; nobody thinks in counties. The ZIP
// resolves to the county (or offers a choice when it straddles two), and
// everything else is a query against the CMS landscape data we hold.
// ============================================================

const CMS_KIND_LABEL = {
  MAPD: 'Medicare Advantage with drugs',
  MA: 'Medicare Advantage (no drugs)',
  SNP: 'Special Needs Plan',
  PDP: 'Part D drug plan',
};

// CMS county names and the ZIP lookup\u2019s names don\u2019t agree \u2014 "Gallatin" vs
// "Gallatin County", "Fredericksburg City" vs "Fredericksburg city", parishes,
// boroughs, census areas. Compare on a flattened key instead of the text.
function cmsCountyKey_(name) {
  return String(name || '').toLowerCase()
    .replace(/\bste\.?\b/g, 'sainte')
    .replace(/\bst\.?\b/g, 'saint')
    .replace(/\b(city and borough|census area|municipality|municipio|county|parish|borough)\b/g, '')
    .replace(/[^a-z0-9]/g, '');
}

async function qbCmsInit_() {
  const c = window._qbContact;
  const zipEl = document.getElementById('qb-cms-zip');
  if (!zipEl) return;
  if (!zipEl.value && c && c.zip) zipEl.value = c.zip;

  // plan years we actually hold
  const yearSel = document.getElementById('qb-cms-year');
  if (yearSel && !yearSel.options.length) {
    const { data: yrs } = await supabaseClient.from('cms_plan_summary')
      .select('plan_year').order('plan_year', { ascending: false });
    yearSel.innerHTML = (yrs || []).map(y => `<option value="${y.plan_year}">${y.plan_year}</option>`).join('')
      || '<option value="">no plan data loaded</option>';
    window._qbCmsYear = parseInt(yearSel.value) || null;
  }
  qbCmsEligibility_();
  if (zipEl.value && !(document.getElementById('qb-cms-county') || {}).options?.length) await qbCmsZipChanged_(true);
}

function qbCmsYearChanged_() {
  window._qbCmsYear = parseInt((document.getElementById('qb-cms-year') || {}).value) || null;
  qbCmsCounties_();
}

// ZIP \u2192 county, and the ZIP is the CRM\u2019s key so it goes back on the contact
async function qbCmsZipChanged_(quiet) {
  const zipEl = document.getElementById('qb-cms-zip');
  const zip = String((zipEl && zipEl.value) || '').trim();
  if (!/^\d{5}$/.test(zip)) { if (!quiet) showToast('Enter a 5-digit ZIP code.'); return; }
  const c = window._qbContact;
  if (c && zip !== c.zip) {
    const st = zipToState_(zip);
    const patch = st ? { zip: zip, state: st } : { zip: zip };
    try {
      await supabaseClient.from('contacts').update(patch).eq('id', c.id);
      Object.assign(c, patch);
      const cc = contacts.find(x => x.id === c.id); if (cc) Object.assign(cc, patch);
    } catch (e) { console.error('cms zip->contact:', e); }
  }
  await qbCmsCounties_();
  qbCmsEligibility_();
}

async function qbCmsCounties_() {
  const zip = String((document.getElementById('qb-cms-zip') || {}).value || '').trim();
  const sel = document.getElementById('qb-cms-county');
  const status = document.getElementById('qb-cms-status');
  if (!sel || !/^\d{5}$/.test(zip)) return;
  const year = window._qbCmsYear || parseInt((document.getElementById('qb-cms-year') || {}).value) || null;
  if (!year) { if (status) status.innerHTML = '<span style="color:var(--text-warning);">No CMS plan data loaded yet.</span>'; return; }

  sel.innerHTML = '<option value="">\u2026</option>';
  if (status) status.textContent = 'Looking up that ZIP\u2026';

  let hits = [];
  try {
    const d = await acaProxy_('aca_counties', { zip: zip });
    hits = (d && d.counties) || [];
  } catch (e) { console.error('zip->county:', e); }

  const st = (hits[0] && hits[0].state) || zipToState_(zip) || (window._qbContact || {}).state;
  window._qbCmsState = st ? String(st).toUpperCase() : null;
  if (!window._qbCmsState) {
    sel.innerHTML = '<option value="">\u2014 unknown ZIP \u2014</option>';
    if (status) status.innerHTML = '<span style="color:var(--text-warning);">Couldn\u2019t place that ZIP.</span>';
    return;
  }

  // the counties WE hold for that state and year decide the wording
  const { data: rows } = await supabaseClient.from('cms_counties')
    .select('county').eq('state', window._qbCmsState).eq('plan_year', year).order('county');
  const held = (rows || []).map(r => r.county);
  if (!held.length) {
    const { count: pdp } = await supabaseClient.from('cms_plans')
      .select('id', { count: 'exact', head: true })
      .eq('state', window._qbCmsState).eq('plan_year', year).eq('category', 'PDP');
    sel.innerHTML = '<option value="">\u2014 none \u2014</option>';
    if (pdp) {
      const kindSel = document.getElementById('qb-cms-kind');
      if (kindSel) kindSel.value = 'PDP';
      if (status) status.innerHTML = '<strong>' + escWeb(window._qbCmsState)
        + ' has no Medicare Advantage plans in ' + year + '</strong> \u2014 only standalone Part D, which is priced '
        + 'statewide. Switched to <strong>Part D drug plan only</strong> (' + pdp + ' plans).';
    } else if (status) {
      status.innerHTML = '<span style="color:var(--text-warning);">No ' + year + ' plan data for '
        + escWeb(window._qbCmsState) + ' yet.</span>';
    }
    return;
  }

  const wanted = hits.map(h => cmsCountyKey_(h.name));
  const matched = held.filter(h => wanted.includes(cmsCountyKey_(h)));
  const list = matched.length ? matched : held;
  sel.innerHTML = list.map(x => `<option value="${escWeb(x)}">${escWeb(x)}</option>`).join('');
  if (!matched.length && hits.length) {
    sel.innerHTML = '<option value="">\u2014 pick their county \u2014</option>' + sel.innerHTML;
  }

  if (status) {
    status.innerHTML = matched.length === 1
      ? '\u{1F4CD} ' + escWeb(matched[0]) + ' County, ' + escWeb(window._qbCmsState) + ' \u00b7 plan year <strong>' + year + '</strong>'
      : (matched.length > 1
        ? '\u{1F4CD} That ZIP covers <strong>' + matched.length + ' counties</strong> \u2014 pick the right one; plans differ between them.'
        : '\u{1F4CD} Couldn\u2019t match that ZIP to a county we hold \u2014 choose it from the list.');
  }
}

function qbCmsCountyChanged_() { qbCmsEligibility_(); }

// What would stop this agent selling this, said plainly and up front.
function qbCmsEligibility_() {
  const box = document.getElementById('qb-cms-elig');
  if (!box) return;
  const me = (window.allAgents || []).find(a => a.id === (window.currentAgent || {}).id) || window.currentAgent || {};
  const st = window._qbCmsState;
  const bars = [];
  const bar = (tone, html) => bars.push('<div class="pk-bar ' + tone + '" style="margin-bottom:5px;">' + html + '</div>');

  const lic = String(me.licensed_states || '').toUpperCase();
  if (st && lic && !lic.split(/[^A-Z]+/).includes(st)) {
    bar('warn', '&#9888;&#65039; You aren\u2019t showing a license in <strong>' + escWeb(st)
      + '</strong>. You can quote these plans, but you can\u2019t write them until that\u2019s in place.');
  }
  const yr = new Date().getFullYear();
  if (Number(me.ahip_certified_year || 0) < yr) {
    bar('warn', '&#9888;&#65039; No <strong>AHIP certification on file for ' + yr
      + '</strong> \u2014 carriers require it before you can enrol anyone in Medicare Advantage or Part D.');
  }
  if (!window._qbCmsSoaOk) {
    bar('warn', '&#9888;&#65039; No <strong>Scope of Appointment</strong> on file for this client. CMS requires one '
      + 'before you discuss Medicare Advantage or Part D \u2014 send it from their contact card first.');
  }
  box.innerHTML = bars.join('');
}

// Has this client signed a scope of appointment we can point to?
async function qbCmsCheckSoa_() {
  const c = window._qbContact;
  window._qbCmsSoaOk = false;
  if (!c) return;
  try {
    const { data } = await supabaseClient.from('soa_records')
      .select('id,signed_at').eq('contact_id', c.id).not('signed_at', 'is', null)
      .order('signed_at', { ascending: false }).limit(1);
    window._qbCmsSoaOk = !!(data && data.length);
  } catch (e) { window._qbCmsSoaOk = true; }   // never block on a lookup failure
  qbCmsEligibility_();
}

async function qbLoadCmsPlans_() {
  await qbCmsInit_();
  qbCmsCheckSoa_();
}

async function qbCmsGetPlans_() {
  const year = window._qbCmsYear || parseInt((document.getElementById('qb-cms-year') || {}).value) || null;
  const kind = (document.getElementById('qb-cms-kind') || {}).value || 'MAPD';
  const county = (document.getElementById('qb-cms-county') || {}).value || '';
  const st = window._qbCmsState;
  const status = document.getElementById('qb-cms-status');
  if (!year || !st) { showToast('Enter their ZIP code first.'); return; }
  if (kind !== 'PDP' && !county) { showToast('Pick their county.'); return; }

  if (status) status.textContent = 'Getting ' + year + ' plans\u2026';
  let q = supabaseClient.from('cms_plans').select('*').eq('state', st).eq('plan_year', year);
  if (kind === 'PDP') q = q.eq('category', 'PDP');
  else {
    q = q.eq('county', county);
    if (kind === 'SNP') q = q.eq('category', 'SNP');
    else if (kind === 'MA') q = q.eq('category', 'MA');
    else q = q.in('category', ['MA-PD', 'MA']);
  }
  const { data: plans, error } = await q.order('consolidated_premium', { nullsFirst: false }).limit(600);
  if (error) { showToast('Could not load plans: ' + error.message); return; }

  window._qbCmsPlans = (plans || []).map(p => Object.assign({}, p, {
    _premium: (kind === 'PDP' ? p.part_d_premium
      : (p.consolidated_premium != null ? p.consolidated_premium : p.part_c_premium)),
  }));
  window._qbCmsKind = kind;
  window._qbCmsCounty = county;
  if (status) {
    status.innerHTML = '\u{1F4CD} ' + escWeb(kind === 'PDP' ? st : county + ' County, ' + st)
      + ' \u00b7 <strong style="color:var(--text-success);">' + window._qbCmsPlans.length + ' plans</strong> \u00b7 '
      + escWeb(CMS_KIND_LABEL[kind]) + ' \u00b7 ' + year;
  }
  if (!window._qbCmsPlans.length) { showToast('No plans of that kind in this county.'); return; }
  qbCmsRelinkOptions_();
  openCmsPicker_();
  qbCmsDrugCheck_();
}

// Every Medicare plan points at a formulary; the client\u2019s prescriptions are
// already on file. Two indexed queries answer \u201cis my drug covered, and on
// what tier\u201d for every plan on screen \u2014 no API, no waiting.
async function qbCmsDrugCheck_() {
  const plans = window._qbCmsPlans || [];
  if (!plans.length) return;
  if (!(window._qbCmsMeds || []).length) {
    const lists = await qbLoadClientLists_();
    window._qbCmsMeds = (lists.medications || []).filter(m => m.rxcui)
      .map(m => ({ rxcui: String(m.rxcui), name: m.name, days_supply: qbMedDays_(m), quantity: m.quantity, doses_per_day: m.doses_per_day }));
  }
  const meds = window._qbCmsMeds || [];
  if (!meds.length) return;

  if (window._qbPartDCap === undefined) {
    try {
      const { data: cfg } = await supabaseClient.from('plan_year_config')
        .select('part_d_oop_cap').eq('plan_year', window._qbCmsYear || new Date().getFullYear()).maybeSingle();
      window._qbPartDCap = (cfg && Number(cfg.part_d_oop_cap)) || null;
    } catch (e) { window._qbPartDCap = null; }
  }

  window._qbCmsDrugBusy = true;
  qbCmsOptionCardsPaint_();
  try {
    const keys = plans.map(p => p.contract_id + '|' + p.plan_id + '|' + String(p.segment_id || '0').padStart(3, '0'));
    const { data: links } = await supabaseClient.from('pdp_plan_formulary')
      .select('contract_id,plan_id,segment_id,formulary_id')
      .in('contract_id', [...new Set(plans.map(p => p.contract_id))]);
    const byKey = {};
    (links || []).forEach(l => { byKey[l.contract_id + '|' + l.plan_id + '|' + l.segment_id] = l.formulary_id; });

    const fids = [...new Set(keys.map(k => byKey[k]).filter(Boolean))];
    const rx = meds.map(m => m.rxcui);
    const cover = {};
    for (let i = 0; i < fids.length; i += 40) {
      const { data: rows } = await supabaseClient.from('pdp_formulary')
        .select('formulary_id,rxcui,tier,prior_auth,step_therapy,quantity_limit')
        .in('formulary_id', fids.slice(i, i + 40)).in('rxcui', rx);
      (rows || []).forEach(r => { cover[r.formulary_id + '|' + r.rxcui] = r; });
    }

    plans.forEach((p, i) => {
      const fid = byKey[keys[i]];
      p._formularyId = fid || null;
      if (!fid) { p._drugCov = null; return; }
      const out = {};
      meds.forEach(m => { out[m.rxcui] = cover[fid + '|' + m.rxcui] || false; });
      p._drugCov = out;
    });

    // what each plan charges per fill, by tier \u2014 so the card can say what a
    // year actually costs rather than just what the premium is
    const { data: tiers } = await supabaseClient.from('pdp_tier_cost')
      .select('contract_id,plan_id,segment_id,tier,days_supply,cost_type,amount')
      .in('contract_id', [...new Set(plans.map(p => p.contract_id))]);
    const priceOf = {};
    (tiers || []).forEach(t => {
      priceOf[t.contract_id + '|' + t.plan_id + '|' + t.segment_id + '|' + t.tier + '|' + t.days_supply] = t;
    });

    plans.forEach((p, i) => {
      p._estYear = null; p._estCoins = false; p._estMissing = 0;
      if (!p._drugCov) return;
      let monthly = 0;
      p._estSupply = null;
      meds.forEach(m => {
        const hit = p._drugCov[m.rxcui];
        if (!hit) { p._estMissing++; return; }
        const days = qbMedDays_(m);
        const at = d => priceOf[keys[i].split('|').slice(0, 3).join('|') + '|' + hit.tier + '|' + d];
        // Plans price a 90-day fill in its own right; only fall back to the
        // 30-day copay when they have not published one for this supply.
        let t = at(days), per = days;
        if (!t && days !== 30) { t = at(30); per = 30; }
        if (!t) return;
        if (t.cost_type === 2) { p._estCoins = true; return; }   // a share of a price we don't hold
        // Refills a year, as people actually collect them: monthly, every
        // other month, quarterly. Not 365/days, which would put a phantom
        // extra fill on every monthly prescription.
        const fills = { 30: 12, 60: 6, 90: 4 }[per] || 12;
        monthly += ((Number(t.amount) || 0) * fills) / 12;
        if (days !== 30) p._estSupply = true;
      });
      const prem = Number(cmsPremium_(p)) || 0;
      p._estMonthly = monthly;

      // Once they reach the year's out-of-pocket limit, covered drugs cost
      // them nothing more \u2014 so the drug half of the estimate stops there.
      // With no figure on file we apply no cap rather than inventing one.
      const cap = window._qbPartDCap;
      let drugYear = monthly * 12;
      p._estCapMonth = null;
      if (cap && monthly > 0 && drugYear > cap) {
        drugYear = cap;
        p._estCapMonth = Math.ceil(cap / monthly);   // the month they get there
      }
      p._estYear = prem * 12 + drugYear;
    });
  } catch (e) {
    console.error('drug check:', e);
  }
  window._qbCmsDrugBusy = false;
  if (document.getElementById('qb-cms-picker')) renderCmsPicker_();
  qbCmsOptionCardsPaint_();
}

function qbCmsOptionCardsPaint_() {
  for (let i = 0; i < QB_MAX_OPTIONS; i++) if ((window._qbCmsSel || {})[i]) qbCmsOptionView_(i);
}

// One line that says how their prescriptions fare on this plan.
function qbCmsDrugLine_(p, expandKey) {
  const meds = window._qbCmsMeds || [];
  if (!meds.length) return '';
  if (p.category === 'MA') {
    return '<div style="margin-top:8px;font-size:11.5px;color:var(--text-warning);">\u{1F48A} No drug coverage on this plan \u2014 they would need a separate Part D plan.</div>';
  }
  if (window._qbCmsDrugBusy && !p._drugCov) {
    return '<div style="margin-top:8px;font-size:11.5px;color:var(--text-muted);">\u{1F48A} checking their prescriptions\u2026</div>';
  }
  if (!p._drugCov) return '';
  const cov = p._drugCov;
  const ok = meds.filter(m => cov[m.rxcui]).length;
  const tone = ok === meds.length ? 'var(--text-success)' : 'var(--text-warning)';
  const pills = meds.map(m => {
    const hit = cov[m.rxcui];
    if (!hit) return '<span class="pk-pill bad">\u2717 ' + escWeb(m.name) + ' <span style="opacity:.75;">not on the list</span></span>';
    const flags = [];
    if (hit.prior_auth) flags.push('prior auth');
    if (hit.step_therapy) flags.push('step therapy');
    if (hit.quantity_limit) flags.push('qty limit');
    const warn = flags.length ? ' <span style="opacity:.75;">' + flags.join(', ') + '</span>' : '';
    return '<span class="pk-pill ' + (flags.length ? 'unk' : 'ok') + '">' + (flags.length ? '\u26a0' : '\u2713')
      + ' ' + escWeb(m.name) + ' <strong>T' + (hit.tier || '?') + '</strong>' + warn + '</span>';
  }).join(' ');
  return `<div style="margin-top:8px;">
    <div style="font-size:11.5px;font-weight:700;color:${tone};">\u{1F48A} ${ok} of ${meds.length} of their prescriptions covered</div>
    <div style="display:flex;gap:5px;flex-wrap:wrap;margin-top:4px;">${pills}</div>
  </div>`;
}

// Re-quoted options carry a plan id; match them to this year\u2019s list so the
// picker shows them as already chosen.
function qbCmsRelinkOptions_() {
  const plans = window._qbCmsPlans || [];
  if (!plans.length) return 0;
  const rq = window._qbRequoteOpt || {};
  window._qbCmsSel = window._qbCmsSel || {};
  let linked = 0;
  for (let i = 0; i < QB_MAX_OPTIONS; i++) {
    const nameEl = document.getElementById('qb-name-' + i);
    if (!nameEl || !nameEl.value.trim() || window._qbCmsSel[i]) continue;
    const meta = rq[i] && rq[i].plan_meta;
    let hit = null;
    if (meta && meta.src === 'cms' && meta.contract_id) {
      hit = plans.find(p => p.contract_id === meta.contract_id && p.plan_id === meta.plan_id
        && String(p.segment_id) === String(meta.segment_id || '0'));
    }
    if (!hit) hit = plans.find(p => p.plan_name.trim().toLowerCase() === nameEl.value.trim().toLowerCase());
    if (hit) { window._qbCmsSel[i] = hit; qbCmsOptionView_(i); linked++; }
  }
  return linked;
}

// ============================================================
// MEDICARE PLAN PICKER \u2014 same shape as the ACA one: full screen, filter
// down, compare a few, add the ones you want to the quote.
// ============================================================

window._qbCmsPk = { carriers: new Set(), types: new Set(), zero: false, stars: 0, sort: 'premium', cmp: new Set() };

// Dollars and cents, every time. “$35.6” is not a price.
function cmsUsd_(v) {
  return v == null ? '—' : '$' + Number(v).toLocaleString('en-US',
    { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function cmsPremium_(p) {
  return p._premium != null ? p._premium
    : (p.consolidated_premium != null ? p.consolidated_premium : p.part_c_premium);
}

function cmsKey_(p) {
  if (!p) return '';
  return [p.contract_id || '', p.plan_id || '', String(p.segment_id || '0')].join('|');
}

function cmsFind_(idOrKey) {
  const plans = window._qbCmsPlans || [];
  return plans.find(p => p.id === idOrKey) || plans.find(p => cmsKey_(p) === idOrKey) || null;
}

function cmsAddedSlot_(idOrKey) {
  const sel = window._qbCmsSel || {};
  const p = cmsFind_(idOrKey);
  const key = p ? cmsKey_(p) : idOrKey;
  for (let i = 0; i < QB_MAX_OPTIONS; i++) {
    if (!sel[i]) continue;
    if (sel[i].id === idOrKey || cmsKey_(sel[i]) === key) return i;
  }
  return -1;
}

// Take a plan off the quote by its slot \u2014 works whether it came from the
// picker or was restored from a saved quote.
function qbCmsRemoveSlot_(i) {
  if (!(window._qbCmsSel || {})[i]) return;
  delete window._qbCmsSel[i];
  ['qb-name-' + i, 'qb-prem-' + i, 'qb-bul-' + i].forEach(id => {
    const el = document.getElementById(id);
    if (el) { const ro = el.readOnly; el.readOnly = false; el.value = ''; el.readOnly = ro; }
  });
  qbCmsOptionView_(i);
  qbTidyOptions_();
  if (document.getElementById('qb-cms-picker')) renderCmsPicker_();
}

function openCmsPicker_() {
  if (!(window._qbCmsPlans || []).length) {
    showToast('Run \u201cFind Medicare plans\u201d first \u2014 opening the Medicare tool.');
    qbWorkbenchOpen_(true, 'cms');
    return;
  }
  qbWorkbenchOpen_(false);           // the picker IS the screen now
  const pk = window._qbCmsPk;
  pk.carriers.clear(); pk.types.clear(); pk.zero = false; pk.stars = 0; pk.cmp.clear();
  let el = document.getElementById('qb-cms-picker');
  if (!el) {
    el = document.createElement('div');
    el.id = 'qb-cms-picker';
    el.style.cssText = 'position:fixed;inset:0;z-index:99990;background:var(--surface-0);display:flex;flex-direction:column;';
    document.body.appendChild(el);
  }
  el.style.display = 'flex';
  renderCmsPicker_();
}

function closeCmsPicker_() {
  const el = document.getElementById('qb-cms-picker');
  if (el) el.style.display = 'none';
  qbAutoCardPaint_();            // the tool list stays current, the bench stays shut
  qbOptAutoFold_();
  qbGroupOptions_();
}

// (the old one-per-filter toggles are gone — cmsPkChip_ handles them all)
function cmsPkSort_(v) { window._qbCmsPk.sort = v; renderCmsPicker_(); }

function cmsPkFiltered_() {
  const pk = window._qbCmsPk;
  let list = (window._qbCmsPlans || []).slice();
  if (pk.carriers.size) list = list.filter(p => pk.carriers.has(p.org_name));
  if (pk.types.size) list = list.filter(p => pk.types.has(p.plan_type));
  if (pk.zero) list = list.filter(p => Number(cmsPremium_(p) || 0) === 0);
  if (pk.stars) list = list.filter(p => parseFloat(p.star_rating || 0) >= pk.stars);
  const num = v => (v == null ? Infinity : Number(v));
  if (pk.sort === 'year') list.sort((a, b) => (a._estYear == null ? Infinity : a._estYear) - (b._estYear == null ? Infinity : b._estYear));
  else if (pk.sort === 'premium') list.sort((a, b) => num(cmsPremium_(a)) - num(cmsPremium_(b)));
  else if (pk.sort === 'moop') list.sort((a, b) => num(a.moop) - num(b.moop));
  else if (pk.sort === 'stars') list.sort((a, b) => parseFloat(b.star_rating || 0) - parseFloat(a.star_rating || 0));
  else list.sort((a, b) => String(a.org_name).localeCompare(String(b.org_name)));
  return list;
}

function cmsCardHtml_(p) {
  if (p.category === 'PDP') return pdpCardHtml_(p);
  const slot = cmsAddedSlot_(p.id);
  const prem = cmsPremium_(p);
  const money = cmsUsd_;
  const stars = p.star_rating ? '\u2b50 ' + p.star_rating : '';
  return `<div class="pk-card ${slot >= 0 ? 'is-selected' : ''}"
      style="border-radius:12px;padding:12px 14px;cursor:pointer;display:flex;flex-direction:column;height:100%;"
      onclick="openCmsDetail_('${escWeb(p.id)}')">
      ${slot >= 0 ? `<div class="pk-sel-badge">\u2713 OPTION ${qbOptionNo_(slot)}</div>` : ''}
      <div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap;">
        <span style="font-size:10px;font-weight:800;border-radius:6px;padding:2px 8px;background:var(--surface-2);color:var(--text-secondary);text-transform:uppercase;">${escWeb(p.plan_type || p.category)}</span>
        ${p.category === 'MA' ? '<span style="font-size:10px;color:var(--text-warning);border:1px solid var(--border-warning);border-radius:6px;padding:2px 6px;">no drug coverage</span>' : ''}
        ${p.snp_type ? `<span style="font-size:10px;color:#7c3aed;border:1px solid #7c3aed;border-radius:6px;padding:2px 6px;">SNP \u00b7 ${escWeb(p.snp_type)}</span>` : ''}
        ${stars ? `<span style="font-size:11px;color:#b3903a;">${stars}</span>` : ''}
        <label style="margin-left:auto;display:flex;align-items:center;gap:5px;font-size:11px;color:var(--text-muted);cursor:pointer;" onclick="event.stopPropagation();">
          <input type="checkbox" ${window._qbCmsPk.cmp.has(cmsKey_(p)) ? 'checked' : ''} onclick="event.stopPropagation();"
            onchange="cmsCmpToggle_('${escWeb(cmsKey_(p))}', this)" style="width:13px;height:13px;" /> \u2696\ufe0f Compare</label>
      </div>
      <div style="font-size:10.5px;font-weight:800;text-transform:uppercase;letter-spacing:.5px;color:var(--text-muted);margin-top:6px;">${escWeb(p.org_name || '')}</div>
      <div style="font-size:14.5px;font-weight:700;margin:1px 0 8px;">${escWeb(p.plan_name)}</div>
      <div style="display:flex;align-items:flex-end;gap:14px;flex-wrap:wrap;">
        <div>
          <div style="font-size:22px;font-weight:800;color:var(--accent,#1d3557);line-height:1;">$${prem != null ? Number(prem).toFixed(2) : '?'}<span style="font-size:10.5px;font-weight:500;color:var(--text-muted);"> /mo plan premium</span></div>
          <div style="font-size:10.5px;color:var(--text-muted);margin-top:2px;">plus their Part B premium</div>
        </div>
        <div style="display:flex;gap:14px;font-size:12px;color:var(--text-secondary);flex-wrap:wrap;margin-left:auto;">
          ${p.moop != null ? `<div><div style="font-size:10px;color:var(--text-muted);">Max out-of-pocket</div><div style="font-weight:700;">${money(p.moop)}</div></div>` : ''}
          ${p.category !== 'MA' ? `<div><div style="font-size:10px;color:var(--text-muted);">Drug deductible</div><div style="font-weight:700;">${money(p.drug_deductible)}</div></div>` : ''}
        </div>
      </div>
      ${qbCmsDrugLine_(p)}
      <div style="display:flex;gap:8px;margin-top:auto;padding-top:10px;flex-wrap:wrap;">
        <button type="button" class="btn ${slot >= 0 ? 'btn-outline' : 'btn-primary'} btn-sm"
          onclick="event.stopPropagation();qbCmsAddPlan_('${escWeb(p.id)}')">${slot >= 0 ? '\u2713 Added \u2014 remove' : '+ Add to quote'}</button>
        <button type="button" class="btn btn-outline btn-sm" onclick="event.stopPropagation();openCmsDetail_('${escWeb(p.id)}')">Details</button>
      </div>
    </div>`;
}

// How many plans each filter WOULD leave, judged with that filter's own
// group ignored \u2014 the number an agent expects to see before clicking.
function cmsPkCount_(patch) {
  const pk = window._qbCmsPk;
  const saved = { carriers: new Set(pk.carriers), types: new Set(pk.types), zero: pk.zero, stars: pk.stars };
  Object.assign(pk, patch);
  const n = cmsPkFiltered_().length;
  Object.assign(pk, saved);
  return n;
}

function cmsPkClear_() {
  const pk = window._qbCmsPk;
  pk.carriers.clear(); pk.types.clear(); pk.zero = false; pk.stars = 0;
  renderCmsPicker_();
}

function cmsPkChip_(id) {
  const pk = window._qbCmsPk;
  if (id === 'zero') { pk.zero = !pk.zero; }
  else if (id.indexOf('stars') === 0) { const n = parseFloat(id.slice(5)); pk.stars = pk.stars === n ? 0 : n; }
  else if (id.indexOf('type|') === 0) { const t = id.slice(5); pk.types.has(t) ? pk.types.delete(t) : pk.types.add(t); }
  else if (id.indexOf('carrier|') === 0) { const c = id.slice(8); pk.carriers.has(c) ? pk.carriers.delete(c) : pk.carriers.add(c); }
  renderCmsPicker_();
}

// A drug plan is judged on the drugs. Premium and deductible matter, but the
// first question is always "is my prescription on it, and on what tier".
function pdpCardHtml_(p) {
  const slot = cmsAddedSlot_(p.id);
  const money = cmsUsd_;
  const meds = window._qbCmsMeds || [];
  const cov = p._drugCov;
  const covered = cov ? meds.filter(m => cov[m.rxcui]).length : null;
  const flagged = cov ? meds.filter(m => cov[m.rxcui] && (cov[m.rxcui].prior_auth || cov[m.rxcui].step_therapy)).length : 0;
  const tone = covered === null ? 'var(--text-muted)'
    : (covered === meds.length && !flagged ? 'var(--text-success)' : 'var(--text-warning)');

  return `<div class="pk-card ${slot >= 0 ? 'is-selected' : ''}"
      style="border-radius:12px;padding:12px 14px;cursor:pointer;display:flex;flex-direction:column;height:100%;"
      onclick="openCmsDetail_('${escWeb(p.id)}')">
      ${slot >= 0 ? `<div class="pk-sel-badge">\u2713 OPTION ${qbOptionNo_(slot)}</div>` : ''}
      <div style="font-size:10.5px;font-weight:800;text-transform:uppercase;letter-spacing:.5px;color:var(--text-muted);">${escWeb(p.org_name || '')}</div>
      <div style="font-size:14.5px;font-weight:700;margin:1px 0 8px;">${escWeb(p.plan_name)}</div>

      ${meds.length ? `<div style="border:1px solid var(--border);border-radius:9px;padding:8px 10px;background:var(--surface-2);">
        <div style="font-size:12px;font-weight:700;color:${tone};">\u{1F48A} ${
          covered === null ? (window._qbCmsDrugBusy ? 'checking their prescriptions\u2026' : 'not checked yet')
          : covered + ' of ' + meds.length + ' of their prescriptions covered'
            + (flagged ? ' \u00b7 ' + flagged + ' with conditions' : '')}</div>
        ${cov ? `<div style="display:flex;gap:5px;flex-wrap:wrap;margin-top:5px;">
          ${meds.map(m => {
            const hit = cov[m.rxcui];
            if (!hit) return '<span class="pk-pill bad">\u2717 ' + escWeb(m.name) + '</span>';
            const notes = [];
            if (hit.prior_auth) notes.push('prior auth');
            if (hit.step_therapy) notes.push('step therapy');
            return '<span class="pk-pill ' + (notes.length ? 'unk' : 'ok') + '">' + (notes.length ? '\u26a0' : '\u2713')
              + ' ' + escWeb(m.name) + ' <strong>T' + (hit.tier || '?') + '</strong>'
              + (notes.length ? ' <span style="opacity:.75;">' + notes.join(', ') + '</span>' : '') + '</span>';
          }).join(' ')}
        </div>` : ''}
      </div>` : `<div style="font-size:11.5px;color:var(--text-muted);">No prescriptions on file \u2014 add them to their intake and this compares drug lists too.</div>`}

      ${p._estYear != null ? `<div style="margin-top:9px;padding:7px 10px;border-radius:9px;background:var(--bg-info);border:1px solid var(--border-info);">
        <div style="font-size:10px;font-weight:800;letter-spacing:.5px;text-transform:uppercase;color:var(--text-info);">Estimated cost for the year</div>
        <div style="font-size:17px;font-weight:800;color:var(--text-info);">${p._estCoins || p._estMissing ? 'from ' : ''}${money(p._estYear)}</div>
        <div style="font-size:10.5px;color:var(--text-info);opacity:.85;line-height:1.45;">
          premium ${money(cmsPremium_(p))}/mo${p._estMonthly ? ' + ' + money(p._estMonthly) + '/mo in copays' : ' \u00b7 their drugs cost nothing per fill'}${
            p._estSupply ? ' \u00b7 priced on the refill sizes they actually get' : ''}${
            p._estMissing ? ' \u00b7 <strong>' + p._estMissing + ' drug' + (p._estMissing === 1 ? '' : 's') + ' not on this list</strong>, so not counted' : ''}${
            p._estCoins ? ' \u00b7 <strong>one or more priced as a % of the drug\u2019s cost</strong>, which we cannot total' : ''}${
            Number(p.drug_deductible) ? ' \u00b7 before the ' + money(p.drug_deductible) + ' deductible' : ''}${
            p._estCapMonth ? ' \u00b7 <strong>reaches the yearly out-of-pocket limit around month ' + p._estCapMonth
              + '</strong>, so covered drugs cost nothing after that' : ''}</div>
        ${!window._qbPartDCap ? `<div style="font-size:10px;color:var(--text-warning);margin-top:3px;">
          No Part D out-of-pocket limit on file for this year \u2014 a heavy drug list will read higher than it really is.
          Set it in Admin \u2192 plan year config.</div>` : ''}
      </div>` : ''}

      <div style="display:flex;align-items:flex-end;gap:14px;flex-wrap:wrap;margin-top:10px;">
        <div>
          <div style="font-size:22px;font-weight:800;color:var(--accent,#1d3557);line-height:1;">${money(p.part_d_premium)}<span style="font-size:10.5px;font-weight:500;color:var(--text-muted);"> /mo</span></div>
          <div style="font-size:10.5px;color:var(--text-muted);margin-top:2px;">plan premium</div>
        </div>
        <div style="margin-left:auto;text-align:right;">
          <div style="font-size:10px;color:var(--text-muted);">Yearly drug deductible</div>
          <div style="font-size:13px;font-weight:700;">${money(p.drug_deductible)}</div>
        </div>
      </div>

      <div style="display:flex;gap:8px;margin-top:auto;padding-top:10px;flex-wrap:wrap;">
        <button type="button" class="btn ${slot >= 0 ? 'btn-outline' : 'btn-primary'} btn-sm"
          onclick="event.stopPropagation();qbCmsAddPlan_('${escWeb(p.id)}')">${slot >= 0 ? '\u2713 Added \u2014 remove' : '+ Add to quote'}</button>
        <button type="button" class="btn btn-outline btn-sm" onclick="event.stopPropagation();openCmsDetail_('${escWeb(p.id)}')">Details</button>
        <label style="margin-left:auto;display:flex;align-items:center;gap:5px;font-size:11px;color:var(--text-muted);cursor:pointer;" onclick="event.stopPropagation();">
          <input type="checkbox" ${window._qbCmsPk.cmp.has(cmsKey_(p)) ? 'checked' : ''} onclick="event.stopPropagation();"
            onchange="cmsCmpToggle_('${escWeb(cmsKey_(p))}', this)" style="width:13px;height:13px;" /> \u2696\ufe0f Compare</label>
      </div>
    </div>`;
}

function renderCmsPicker_() {
  const el = document.getElementById('qb-cms-picker');
  if (!el) return;
  if (!window._planYearAmts) { planYearAmts_().then(renderCmsPicker_); return; }
  if (!window._qbListsFilled && !(window._qbAcaMeds || []).length) {
    qbAcaFillListsFromClient_().then(renderCmsPicker_); return;
  }
  const all = window._qbCmsPlans || [];
  const list = cmsPkFiltered_();
  const pk = window._qbCmsPk;
  const carriers = [...new Set(all.map(p => p.org_name).filter(Boolean))].sort();
  const types = [...new Set(all.map(p => p.plan_type).filter(Boolean))].sort();

  const counts = { zero: cmsPkCount_({ zero: true }) };
  [4, 4.5].forEach(n => counts['stars' + n] = cmsPkCount_({ stars: n }));
  types.forEach(t => counts['type|' + t] = cmsPkCount_({ types: new Set([t]) }));
  carriers.forEach(c => counts['carrier|' + c] = cmsPkCount_({ carriers: new Set([c]) }));

  const chip = (id, label, n, on) => `<button type="button" class="fx-chip${on ? ' on' : ''}${!n && !on ? ' dead' : ''}"
      ${!n && !on ? 'disabled' : ''} onclick="cmsPkChip_('${escWeb(id)}')">${escWeb(label)} <span class="n">${n}</span></button>`;

  const active = [];
  if (pk.zero) active.push('$0 premium');
  if (pk.stars) active.push('\u2b50 ' + pk.stars + '+');
  if (pk.types.size) active.push([...pk.types].join(', '));
  if (pk.carriers.size) active.push([...pk.carriers].join(', '));
  const chosen = [];
  for (let i = 0; i < QB_MAX_OPTIONS; i++) if ((window._qbCmsSel || {})[i]) chosen.push({ i: i, p: window._qbCmsSel[i] });
  const isPdp = window._qbCmsKind === 'PDP';
  const kind = CMS_KIND_LABEL[window._qbCmsKind || 'MAPD'];
  const where = isPdp ? (window._qbCmsState + ' \u00b7 priced statewide') : (window._qbCmsCounty + ' County, ' + window._qbCmsState);

  el.innerHTML = `
    <div style="padding:12px 18px;border-bottom:1px solid var(--border);display:flex;align-items:center;gap:12px;flex-wrap:wrap;">
      <div style="font-weight:800;font-size:15px;">\u{1F3DB}\uFE0F ${escWeb(kind)}</div>
      <div style="font-size:12px;color:var(--text-muted);">${escWeb(where)} \u00b7 ${window._qbCmsYear || ''} \u00b7 showing ${list.length} of ${all.length}</div>
      ${window._qbCmsPk.cmp.size ? `<button class="btn ${window._qbCmsPk.cmp.size >= 2 ? 'btn-primary' : 'btn-outline'} btn-sm"
        style="margin-left:auto;" ${window._qbCmsPk.cmp.size >= 2 ? '' : 'disabled'} onclick="openCmsCompare_()">\u2696\ufe0f Compare (${window._qbCmsPk.cmp.size})</button>` : ''}
      <button class="btn btn-outline btn-sm" style="${window._qbCmsPk.cmp.size ? '' : 'margin-left:auto;'}" onclick="closeCmsPicker_()">\u2715 Done</button>
    </div>

    <div style="padding:8px 18px 10px;border-bottom:1px solid var(--border);">
      <div class="fx-row">
        <span class="fx-label">Premium</span>
        ${chip('zero', '$0 premium', counts.zero, pk.zero)}
        <span class="fx-label" style="margin-left:14px;">Rating</span>
        ${[4, 4.5].map(n => chip('stars' + n, '\u2b50 ' + n + '+', counts['stars' + n], pk.stars === n)).join('')}
      </div>
      ${types.length > 1 ? `<div class="fx-row">
        <span class="fx-label">Plan type</span>
        ${types.map(t => chip('type|' + t, t, counts['type|' + t], pk.types.has(t))).join('')}
      </div>` : ''}
      ${carriers.length > 1 ? `<div class="fx-row">
        <span class="fx-label">Carrier</span>
        ${carriers.map(c => chip('carrier|' + c, c, counts['carrier|' + c], pk.carriers.has(c))).join('')}
      </div>` : ''}
      <div class="fx-row" style="border-top:1px solid var(--border);margin-top:4px;padding-top:8px;">
        <span class="fx-summary">
          <span class="what">${list.length} of ${all.length} plans</span>
          ${active.length ? '\u00b7 ' + active.map(x => escWeb(x)).join(' \u00b7 ') : '\u00b7 no filters on'}
          ${active.length ? '<button class="fx-clear" onclick="cmsPkClear_()">\u2715 Clear all</button>' : ''}
        </span>
        <label style="margin-left:auto;display:flex;align-items:center;gap:6px;font-size:11.5px;color:var(--text-muted);">
          Sort
          <select onchange="cmsPkSort_(this.value)" style="width:auto;">
            <option value="premium"${pk.sort === 'premium' ? ' selected' : ''}>Lowest premium</option>
        <option value="year"${pk.sort === 'year' ? ' selected' : ''}>Lowest cost for the year</option>
            <option value="moop"${pk.sort === 'moop' ? ' selected' : ''}>Lowest max out-of-pocket</option>
            <option value="stars"${pk.sort === 'stars' ? ' selected' : ''}>Best star rating</option>
            <option value="carrier"${pk.sort === 'carrier' ? ' selected' : ''}>Carrier A\u2013Z</option>
          </select>
        </label>
      </div>
    </div>

    <div id="qb-med-basis" data-kind="${isPdp ? 'PDP' : 'MAPD'}" style="background:var(--surface-1);border-bottom:1px solid var(--border);">${qbMedBasisHtml_(isPdp ? 'PDP' : 'MAPD')}</div>

    <div style="flex:1;overflow:auto;padding:14px 18px;">
      ${medFactsHtml_(isPdp ? 'Part D (PDP)' : 'Medicare Advantage')}
      ${list.length
        ? `<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(330px,1fr));gap:12px;">${list.map(cmsCardHtml_).join('')}</div>`
        : '<div style="color:var(--text-muted);font-size:13px;padding:20px 0;">Nothing matches those filters.</div>'}
    </div>

    ${chosen.length ? `<div class="pk-tray" style="padding:10px 20px;display:flex;gap:10px;align-items:center;flex-wrap:wrap;">
      <span class="pk-tray-label">On the quote \u00b7 ${chosen.length}</span>
      ${chosen.map(x => `<div class="pk-tray-item">
        <span class="num">${qbOptionNo_(x.i)}</span>
        <span class="who">
          <span class="carrier">${escWeb(x.p.org_name || '')}</span>
          <span class="pname">${escWeb(x.p.plan_name)}</span>
        </span>
        <span class="price">$${cmsPremium_(x.p) != null ? Number(cmsPremium_(x.p)).toFixed(2) : '?'}</span>
        <button class="rm" onclick="qbCmsRemoveSlot_(${x.i})" title="Take off the quote">\u2715</button>
      </div>`).join('')}
      <button class="btn btn-primary btn-sm" style="margin-left:auto;" onclick="closeCmsPicker_()">Done \u2014 back to the quote</button>
    </div>` : ''}`;
}

function cmsCmpToggle_(key, cb) {
  const pk = window._qbCmsPk;
  if (cb.checked) {
    if (pk.cmp.size >= 4) { cb.checked = false; showToast('Compare up to 4 plans at a time.'); return; }
    pk.cmp.add(key);
  } else pk.cmp.delete(key);
  renderCmsPicker_();
}

function cmsCmpClear_() { window._qbCmsPk.cmp.clear(); renderCmsPicker_(); }

// Four plans, one screen, the rows an agent actually reads out loud.
function openCmsCompare_() {
  const plans = [...window._qbCmsPk.cmp].map(k => cmsFind_(k)).filter(Boolean);
  if (plans.length < 2) { showToast('Tick \u2696\ufe0f Compare on at least 2 plans first.'); return; }
  let ov = document.getElementById('qb-cms-compare');
  if (!ov) {
    ov = document.createElement('div');
    ov.id = 'qb-cms-compare';
    ov.style.cssText = 'position:fixed;inset:0;z-index:99996;background:var(--surface-0);display:flex;flex-direction:column;';
    document.body.appendChild(ov);
  }
  const money = cmsUsd_;
  const meds = window._qbCmsMeds || [];
  const th = 'position:sticky;left:0;background:var(--surface-0);z-index:2;text-align:left;font-size:11.5px;font-weight:700;color:var(--text-muted);padding:9px 12px;border-bottom:1px solid var(--border);min-width:150px;';
  const td = 'padding:9px 12px;border-bottom:1px solid var(--border);font-size:12.5px;vertical-align:top;min-width:190px;';
  const row = (label, fn) => `<tr><th style="${th}">${label}</th>${plans.map(p => `<td style="${td}">${fn(p)}</td>`).join('')}</tr>`;
  const drugCell = (p, m) => {
    if (p.category === 'MA') return '<span style="color:var(--text-warning);">no drug coverage</span>';
    if (!p._drugCov) return '<span style="color:var(--text-muted);">not checked</span>';
    const hit = p._drugCov[m.rxcui];
    if (!hit) return '<span style="color:var(--text-danger);font-weight:600;">\u2717 not on the list</span>';
    const notes = [];
    if (hit.prior_auth) notes.push('prior auth');
    if (hit.step_therapy) notes.push('step therapy');
    if (hit.quantity_limit) notes.push('qty limit');
    return '<span style="color:var(--text-success);font-weight:700;">\u2713 Tier ' + (hit.tier || '?') + '</span>'
      + (notes.length ? '<div style="font-size:11px;color:var(--text-warning);">' + escWeb(notes.join(', ')) + '</div>' : '');
  };

  ov.innerHTML = `
    <div style="padding:12px 18px;border-bottom:1px solid var(--border);display:flex;align-items:center;gap:12px;flex-wrap:wrap;">
      <div style="font-weight:800;font-size:15px;">\u2696\ufe0f Comparing ${plans.length} Medicare plans</div>
      <button class="btn btn-outline btn-sm" style="margin-left:auto;" onclick="cmsCmpClear_();document.getElementById('qb-cms-compare').style.display='none';">Clear picks</button>
      <button class="btn btn-outline btn-sm" onclick="document.getElementById('qb-cms-compare').style.display='none'">\u2715 Back</button>
    </div>
    <div style="flex:1;overflow:auto;padding:14px 18px;">
      <table style="border-collapse:collapse;width:100%;">
        <thead><tr><th style="${th}"></th>
          ${plans.map(p => `<td style="${td}border-bottom:1.5px solid var(--border);">
            <div style="font-size:10px;font-weight:800;text-transform:uppercase;letter-spacing:.5px;color:var(--text-muted);">${escWeb(p.org_name || '')}</div>
            <div style="font-size:13px;font-weight:700;margin:2px 0 6px;">${escWeb(p.plan_name)}</div>
            <div style="font-size:20px;font-weight:800;color:var(--accent,#1d3557);">$${cmsPremium_(p) != null ? Number(cmsPremium_(p)).toFixed(2) : '?'}<span style="font-size:10px;font-weight:500;color:var(--text-muted);"> /mo</span></div>
            <button class="btn ${cmsAddedSlot_(cmsKey_(p)) >= 0 ? 'btn-outline' : 'btn-primary'} btn-sm" style="width:100%;margin-top:8px;"
              onclick="qbCmsAddPlan_('${escWeb(cmsKey_(p))}');openCmsCompare_();">${cmsAddedSlot_(cmsKey_(p)) >= 0 ? '\u2713 On the quote' : '+ Add to quote'}</button>
          </td>`).join('')}
        </tr></thead>
        <tbody>
          ${row('Plan type', p => escWeb(p.plan_type || p.category))}
          ${row('Prescription coverage', p => p.category === 'MA'
            ? '<span style="color:var(--text-warning);">not included</span>'
            : '<span style="color:var(--text-success);font-weight:700;">included</span>')}
          ${row('Max out-of-pocket', p => '<strong>' + money(p.moop) + '</strong>')}
          ${row('Drug deductible', p => p.category === 'MA' ? '\u2014' : money(p.drug_deductible))}
          ${row('Star rating', p => p.star_rating ? '\u2b50 ' + escWeb(p.star_rating) + ' of 5' : 'not rated yet')}
          ${plans.some(p => p.snp_type) ? row('Special Needs Plan', p => p.snp_type ? escWeb(p.snp_type) : '\u2014') : ''}
          ${meds.map(m => row('\u{1F48A} ' + escWeb(m.name), p => drugCell(p, m))).join('')}
        </tbody>
      </table>
    </div>`;
  ov.style.display = 'flex';
}

// A read-only look at everything CMS publishes for one plan.
function openCmsDetail_(planId) {
  const p = (window._qbCmsPlans || []).find(x => x.id === planId);
  if (!p) return;
  let dr = document.getElementById('qb-cms-detail');
  if (!dr) {
    dr = document.createElement('div');
    dr.id = 'qb-cms-detail';
    dr.style.cssText = 'position:fixed;top:0;right:0;bottom:0;width:min(520px,92vw);z-index:99995;background:var(--surface-1);border-left:1px solid var(--border);box-shadow:-12px 0 40px rgba(15,23,42,.18);display:flex;flex-direction:column;';
    document.body.appendChild(dr);
  }
  const money = cmsUsd_;
  const row = (l, v) => `<div style="display:flex;justify-content:space-between;gap:10px;padding:7px 0;border-bottom:1px solid var(--border);font-size:13px;">
      <span style="color:var(--text-muted);">${l}</span><span style="font-weight:600;text-align:right;">${v}</span></div>`;
  dr.style.display = 'flex';
  dr.innerHTML = `<div style="padding:16px 20px;border-bottom:1px solid var(--border);display:flex;align-items:center;gap:10px;">
      <div style="font-weight:800;font-size:15px;flex:1;min-width:0;">${escWeb(p.plan_name)}</div>
      <button class="btn btn-outline btn-sm" onclick="document.getElementById('qb-cms-detail').style.display='none'">\u2715 Close</button>
    </div>
    <div style="padding:16px 20px;overflow:auto;">
      <div style="font-size:11px;font-weight:800;text-transform:uppercase;letter-spacing:.5px;color:var(--text-muted);">${escWeb(p.org_name || '')}</div>
      ${row('Plan type', escWeb(p.plan_type || p.category))}
      ${row('Monthly plan premium', money(cmsPremium_(p)))}
      ${p.part_c_premium != null ? row('Part C portion', money(p.part_c_premium)) : ''}
      ${p.part_d_premium != null ? row('Part D portion', money(p.part_d_premium)) : ''}
      ${row('Max out-of-pocket (in network)', money(p.moop))}
      ${p.category !== 'MA' ? row('Yearly drug deductible', money(p.drug_deductible)) : ''}
      ${row('CMS star rating', p.star_rating ? '\u2b50 ' + escWeb(p.star_rating) + ' of 5' : 'not rated yet')}
      ${p.snp_type ? row('Special Needs Plan', escWeb(p.snp_type)) : ''}
      ${row('Contract / plan', escWeb(p.contract_id + '-' + p.plan_id + (String(p.segment_id) !== '0' ? '-' + p.segment_id : '')))}
      ${row('Service area', escWeb((p.county && p.county !== 'All Counties' ? p.county + ' County, ' : '') + p.state))}
      <div style="font-size:11px;color:var(--text-muted);margin-top:12px;line-height:1.5;">
        Doctor networks and drug lists aren\u2019t part of this data \u2014 check them on the carrier\u2019s own directory
        before enrolling.
      </div>
      <button class="btn btn-primary btn-sm" style="width:100%;margin-top:14px;" onclick="qbCmsAddPlan_('${escWeb(cmsKey_(p))}');document.getElementById('qb-cms-detail').style.display='none';">
        ${cmsAddedSlot_(p.id) >= 0 ? '\u2713 Added \u2014 remove from quote' : '+ Add this plan to the quote'}</button>
    </div>`;
}

// The drug answers travel with the plan, in the same shape the ACA options use,
// so the client\u2019s page renders them without knowing which tool produced them.
function qbCmsCoverageSnapshot_(p) {
  const meds = window._qbCmsMeds || [];
  if (!meds.length || !p._drugCov) return null;
  const medications = meds.map(m => {
    const hit = p._drugCov[m.rxcui];
    return {
      rxcui: String(m.rxcui), name: m.name, covered: !!hit,
      tier: hit ? hit.tier : null,
      prior_auth: hit ? !!hit.prior_auth : false,
      step_therapy: hit ? !!hit.step_therapy : false,
      quantity_limit: hit ? !!hit.quantity_limit : false,
    };
  });
  return { checked_at: new Date().toISOString(), providers: [], medications: medications };
}

// A saved Medicare option is a complete plan record on its own \u2014 rebuild the
// card from it so re-opening a quote looks like building one.
function qbCmsHydrateOption_(i, o) {
  const m = o.plan_meta || {};
  window._qbCmsSel = window._qbCmsSel || {};
  window._qbCmsSel[i] = {
    id: 'saved-' + i,
    plan_name: o.display_name, org_name: m.org_name || o.carrier_name || '',
    plan_type: m.plan_type || '', category: m.category || 'MA-PD',
    snp_type: m.snp_type || null, star_rating: m.rating || null,
    _premium: m.premium != null ? m.premium : o.monthly_premium,
    part_c_premium: m.part_c_premium, part_d_premium: m.part_d_premium,
    moop: m.moop, drug_deductible: m.drug_deductible,
    contract_id: m.contract_id, plan_id: m.plan_id, segment_id: m.segment_id,
    state: m.state, county: m.county, plan_year: m.year,
    _snapshot: true,
    _formularyId: m.formulary_id || null,
    _drugCov: (m.coverage && m.coverage.medications || []).reduce((a, x) => {
      a[x.rxcui] = x.covered ? { tier: x.tier, prior_auth: x.prior_auth, step_therapy: x.step_therapy, quantity_limit: x.quantity_limit } : false;
      return a;
    }, {}),
  };
  if (!(window._qbCmsMeds || []).length && m.coverage && (m.coverage.medications || []).length) {
    window._qbCmsMeds = m.coverage.medications.map(x => ({ rxcui: String(x.rxcui), name: x.name }));
  }
  qbCmsOptionView_(i);
}

// Add or remove a plan from the quote\u2019s options.
function qbCmsAddPlan_(planId) {
  window._qbCmsSel = window._qbCmsSel || {};
  const at = cmsAddedSlot_(planId);
  if (at >= 0) { qbCmsRemoveSlot_(at); return; }      // already on the quote
  const p = cmsFind_(planId);
  if (!p) return;
  // first free slot
  let slot = -1;
  for (let i = 0; i < QB_MAX_OPTIONS; i++) {
    const w = document.getElementById('qb-opt-wrap-' + i);
    const nm = document.getElementById('qb-name-' + i);
    if (!w || !nm) continue;
    const empty = !nm.value.trim() && !(window._qbCmsSel || {})[i] && !(window._qbAcaSel || {})[i];
    if (w.style.display !== 'none' && empty) { slot = i; break; }
  }
  if (slot < 0) {
    qbRevealOption_();
    for (let i = 0; i < QB_MAX_OPTIONS; i++) {
      const w = document.getElementById('qb-opt-wrap-' + i);
      const nm = document.getElementById('qb-name-' + i);
      if (w && w.style.display !== 'none' && nm && !nm.value.trim()) { slot = i; break; }
    }
  }
  if (slot < 0) { showToast('All ' + QB_MAX_OPTIONS + ' options are full \u2014 remove one first.'); return; }

  const _w = document.getElementById('qb-opt-wrap-' + slot);
  if (_w) _w.style.display = 'block';
  qbRenumberOptions_();
  window._qbCmsSel[slot] = p;
  const ol = document.getElementById('qb-optline-' + slot);
  if (ol && !ol.value) {
    ol.value = window._qbCmsKind === 'PDP' ? 'Part D (PDP)' : 'Medicare Advantage';
    qbOptLineChanged_(slot);
  }
  qbCmsOptionView_(slot);
  renderCmsPicker_();
  qbSectionSummary_();
  showToast('Added as option ' + qbOptionNo_(slot) + '.');
}

// The option card \u2014 a record, not a form, exactly like the ACA one.
function qbCmsOptionView_(i) {
  const card = document.getElementById('qb-cms-card-' + i);
  const manual = document.getElementById('qb-manual-' + i);
  const carprod = document.getElementById('qb-carprod-' + i);
  const cmsWrap = document.getElementById('qb-cms-wrap-' + i);
  const p = (window._qbCmsSel || {})[i];
  if (!card) return;

  if (!p) {
    card.style.display = 'none'; card.innerHTML = '';
    if (manual) manual.style.display = '';
    if (carprod) carprod.style.display = '';
    if (cmsWrap) cmsWrap.style.display = '';
    return;
  }

  const prem = cmsPremium_(p);
  const nameEl = document.getElementById('qb-name-' + i);
  const premEl = document.getElementById('qb-prem-' + i);
  if (nameEl) nameEl.value = p.plan_name;
  if (premEl && prem != null) premEl.value = Number(prem).toFixed(2);
  if (manual) manual.style.display = 'none';
  if (carprod) carprod.style.display = 'none';
  if (cmsWrap) cmsWrap.style.display = 'none';

  const money = cmsUsd_;
  card.style.display = 'block';
  card.innerHTML = `
    <div class="pk-card is-selected" style="border-radius:12px;padding:12px 14px;">
      <div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap;">
        <span style="font-size:10px;font-weight:800;border-radius:6px;padding:2px 8px;background:var(--surface-2);color:var(--text-secondary);text-transform:uppercase;">${escWeb(p.plan_type || p.category)}</span>
        ${p.category === 'MA' ? '<span style="font-size:10px;color:var(--text-warning);border:1px solid var(--border-warning);border-radius:6px;padding:2px 6px;">no drug coverage</span>' : ''}
        ${p.snp_type ? `<span style="font-size:10px;color:#7c3aed;border:1px solid #7c3aed;border-radius:6px;padding:2px 6px;">SNP</span>` : ''}
        ${p.star_rating ? `<span style="font-size:11px;color:#b3903a;">\u2b50 ${escWeb(p.star_rating)}</span>` : ''}
      </div>
      <div style="font-size:10.5px;font-weight:800;text-transform:uppercase;letter-spacing:.5px;color:var(--text-muted);margin-top:6px;">${escWeb(p.org_name || '')}</div>
      <div style="font-size:14.5px;font-weight:700;margin:1px 0 8px;">${escWeb(p.plan_name)}</div>
      <div style="display:flex;align-items:flex-end;gap:14px;flex-wrap:wrap;">
        <div>
          <div style="font-size:22px;font-weight:800;color:var(--accent,#1d3557);line-height:1;">$${prem != null ? Number(prem).toFixed(2) : '?'}<span style="font-size:10.5px;font-weight:500;color:var(--text-muted);"> /mo</span></div>
          <div style="font-size:10.5px;color:var(--text-muted);margin-top:2px;">plus their Part B premium</div>
        </div>
        <div style="display:flex;gap:14px;font-size:12px;color:var(--text-secondary);flex-wrap:wrap;margin-left:auto;">
          ${p.moop != null ? `<div><div style="font-size:10px;color:var(--text-muted);">Max out-of-pocket</div><div style="font-weight:700;">${money(p.moop)}</div></div>` : ''}
          ${p.category !== 'MA' ? `<div><div style="font-size:10px;color:var(--text-muted);">Drug deductible</div><div style="font-weight:700;">${money(p.drug_deductible)}</div></div>` : ''}
        </div>
      </div>
      ${qbCmsDrugLine_(p)}
      <div style="display:flex;gap:8px;margin-top:10px;flex-wrap:wrap;">
        <button type="button" class="btn btn-outline btn-sm" onclick="openCmsDetail_('${escWeb(p.id)}')">Plan details</button>
        <button type="button" class="btn btn-outline btn-sm" onclick="openCmsPicker_()">\u{1F5D6} Change plan</button>
        <button type="button" class="btn btn-outline btn-sm" style="color:var(--text-danger);border-color:var(--border-danger);margin-left:auto;" onclick="qbCmsAddPlan_('${escWeb(p.id)}')">\u{1F5D1} Remove</button>
      </div>
      <div style="font-size:10.5px;color:var(--text-muted);margin-top:8px;">Plan name, premium and limits come straight from the official CMS landscape data \u2014 add your own note below.</div>
    </div>`;
}

function qbApplyCmsPlan_(i) {
  const plan = (window._qbCmsPlans || []).find(p => p.id === document.getElementById('qb-cms-' + i).value);
  window._qbCmsSel = window._qbCmsSel || {};
  if (!plan) { delete window._qbCmsSel[i]; return; }
  window._qbCmsSel[i] = plan;
  const line = document.getElementById('qb-line').value;
  document.getElementById('qb-name-' + i).value = plan.plan_name;
  const prem = line === 'Part D (PDP)' ? plan.part_d_premium : (plan.consolidated_premium != null ? plan.consolidated_premium : plan.part_c_premium);
  if (prem != null) document.getElementById('qb-prem-' + i).value = Number(prem).toFixed(2);
  // Factual, CMS-sourced bullets (objective plan data, not marketing copy)
  const bullets = [];
  if (plan.plan_type) bullets.push('Plan type: ' + plan.plan_type);
  if (plan.moop != null) bullets.push('Yearly in-network max out-of-pocket: $' + Number(plan.moop).toLocaleString());
  if (plan.category !== 'MA') bullets.push(plan.drug_deductible != null ? 'Drug deductible: $' + Number(plan.drug_deductible).toFixed(0) : 'Includes drug coverage');
  if (plan.star_rating) bullets.push('CMS star rating: ' + plan.star_rating + ' of 5');
  if (plan.snp_type) bullets.push('Special Needs Plan: ' + plan.snp_type);
  const bul = document.getElementById('qb-bul-' + i);
  bul.readOnly = false;
  bul.value = bullets.join('\n');
  bul.readOnly = true; // stays locked: factual CMS data only
}

// ============================================================
// RATE CHARTS — enter a carrier's Medigap grid once (typed or
// pasted straight from Excel); the quote builder rates from it.
// ============================================================
async function openRateCharts(productId) {
  const prod = (window._allCarrierProducts_full || window._qbProds || []).find(p => p.id === productId)
    || (await supabaseClient.from('carrier_products').select('*').eq('id', productId).single()).data;
  if (!prod) { showToast('Product not found.'); return; }
  window._rcProduct = prod;
  const { data: charts } = await supabaseClient.from('rate_charts')
    .select('*').eq('product_id', productId).order('state').order('created_at', { ascending: false });
  window._rcCharts = charts || [];
  let rowCounts = {};
  if (charts && charts.length) {
    const { data: rr } = await supabaseClient.from('rate_rows')
      .select('chart_id').in('chart_id', charts.map(c => c.id));
    (rr || []).forEach(r => { rowCounts[r.chart_id] = (rowCounts[r.chart_id] || 0) + 1; });
  }
  const rows = (charts && charts.length) ? charts.map(ch => `
    <div style="display:flex;justify-content:space-between;align-items:center;gap:10px;padding:7px 0;border-bottom:0.5px solid var(--border);${ch.is_active ? '' : 'opacity:.5;'}">
      <div style="flex:1;min-width:0;font-size:13px;">
        <strong>${escWeb(ch.state)}</strong>${ch.zip_prefixes ? ' <span style="font-size:11px;color:var(--text-muted);">(zips ' + escWeb(ch.zip_prefixes) + ')</span>' : ''}
        <span style="font-size:11px;color:var(--text-muted);">&middot; ${escWeb(ch.rating_method)}${ch.effective_date ? ' &middot; eff. ' + ch.effective_date : ''} &middot; ${rowCounts[ch.id] || 0} rates${ch.household_discount_pct ? ' &middot; HH disc ' + ch.household_discount_pct + '%' : ''}${ch.is_active ? '' : ' &middot; inactive'}</span>
      </div>
      <button class="btn btn-outline btn-sm" onclick="openRateChartModal('${productId}','${ch.id}')">Edit</button>
    </div>`).join('')
    : '<div style="font-size:13px;color:var(--text-muted);font-style:italic;">No rate charts yet — add one and the quote builder starts rating this product automatically.</div>';
  showModal('Rate Charts — ' + escWeb(prod.name), `
    <div style="display:flex;justify-content:flex-end;margin-bottom:8px;"><button class="btn btn-primary btn-sm" onclick="openRateChartModal('${productId}', null)">+ Add Rate Chart</button></div>
    ${rows}`, null, { hideConfirm: true });
}

function parseRateGrid_(text, hasGender, hasTobacco) {
  const combos = hasGender && hasTobacco ? [['M', false], ['M', true], ['F', false], ['F', true]]
    : hasGender ? [['M', false], ['F', false]]
    : hasTobacco ? [['U', false], ['U', true]]
    : [['U', false]];
  const out = [];
  for (const raw of text.split(/\n/)) {
    const line = raw.trim();
    if (!line) continue;
    const cells = line.split(/[\t;,]+|\s{2,}/).map(c => c.trim()).filter(c => c !== '');
    if (cells.length < 2) continue;
    const ageCell = cells[0].replace(/\s/g, '').toLowerCase();
    let m, aMin, aMax;
    if ((m = ageCell.match(/^(\d{1,3})[-\u2013](\d{1,3})$/))) { aMin = +m[1]; aMax = +m[2]; }
    else if ((m = ageCell.match(/^(\d{1,3})\+$/))) { aMin = +m[1]; aMax = 120; }
    else if (/^(under65|<65|u65)$/.test(ageCell)) { aMin = 0; aMax = 64; }
    else if ((m = ageCell.match(/^(\d{1,3})$/))) { aMin = aMax = +m[1]; }
    else continue; // header or junk line
    if (aMin > 120 || aMax > 121) continue;
    const rates = cells.slice(1).map(c => parseFloat(c.replace(/[$,]/g, ''))).filter(n => !isNaN(n) && n > 0);
    if (rates.length < combos.length) continue;
    combos.forEach((cb, i) => out.push({ age_min: aMin, age_max: aMax, gender: cb[0], tobacco: cb[1], monthly_rate: rates[i] }));
  }
  return out;
}

function rcPreview_() {
  const hasGender = document.getElementById('rc-gen').checked;
  const hasTobacco = document.getElementById('rc-tob').checked;
  const rows = parseRateGrid_(document.getElementById('rc-grid').value, hasGender, hasTobacco);
  const pv = document.getElementById('rc-preview');
  if (!rows.length) {
    pv.innerHTML = '<div style="font-size:12px;color:var(--danger);margin-top:8px;">Nothing recognized yet — each line should start with an age (65, 65-69, or 80+) followed by the rate column(s).</div>';
    return;
  }
  const ages = [...new Set(rows.map(r => r.age_min + (r.age_max !== r.age_min ? '-' + r.age_max : '')))];
  const sample = rows.slice(0, 8).map(r =>
    `<tr><td style="padding:2px 8px;">${r.age_min}${r.age_max !== r.age_min ? '-' + r.age_max : ''}</td><td style="padding:2px 8px;">${r.gender}</td><td style="padding:2px 8px;">${r.tobacco ? 'Tobacco' : 'Non-tob'}</td><td style="padding:2px 8px;">$${r.monthly_rate.toFixed(2)}</td></tr>`).join('');
  pv.innerHTML = `<div style="font-size:12px;color:var(--success);margin-top:8px;font-weight:600;">&#10003; Recognized ${rows.length} rates across ${ages.length} age band${ages.length === 1 ? '' : 's'}.</div>
    <table style="font-size:11px;border-collapse:collapse;margin-top:4px;color:var(--text-muted);"><tr><th style="text-align:left;padding:2px 8px;">Age</th><th style="text-align:left;padding:2px 8px;">Gender</th><th style="text-align:left;padding:2px 8px;">Tobacco</th><th style="text-align:left;padding:2px 8px;">Monthly</th></tr>${sample}</table>
    ${rows.length > 8 ? '<div style="font-size:11px;color:var(--text-muted);">&hellip;and ' + (rows.length - 8) + ' more</div>' : ''}`;
  window._rcParsed = rows;
}

function openRateChartModal(productId, chartId) {
  const ch = chartId ? (window._rcCharts || []).find(x => x.id === chartId) : null;
  showModal(ch ? 'Edit Rate Chart — ' + ch.state : 'Add Rate Chart', `
    <div style="padding:16px 20px;">
      <div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:0 14px;">
        <div><label>State *</label><input type="text" id="rc-state" maxlength="2" value="${ch ? escWeb(ch.state) : 'MT'}" style="text-transform:uppercase;" /></div>
        <div><label>Rating method</label>
          <select id="rc-method">
            <option value="attained-age" ${!ch || ch.rating_method === 'attained-age' ? 'selected' : ''}>Attained-age</option>
            <option value="issue-age" ${ch && ch.rating_method === 'issue-age' ? 'selected' : ''}>Issue-age</option>
            <option value="community" ${ch && ch.rating_method === 'community' ? 'selected' : ''}>Community-rated</option>
          </select></div>
        <div><label>Effective date</label><input type="date" id="rc-eff" value="${ch && ch.effective_date ? ch.effective_date : ''}" /></div>
        <div><label>Household discount % (optional)</label><input type="number" step="0.1" id="rc-hh" value="${ch && ch.household_discount_pct ? ch.household_discount_pct : ''}" /></div>
        <div><label>Zip prefixes (optional, 3-digit, comma-sep)</label><input type="text" id="rc-zips" value="${ch ? escWeb(ch.zip_prefixes || '') : ''}" placeholder="e.g. 597,598 — blank = whole state" /></div>
      </div>
      <div style="display:flex;gap:16px;margin-top:12px;font-size:13px;">
        <label style="display:flex;gap:6px;align-items:center;font-weight:400;margin:0;"><input type="checkbox" id="rc-gen" style="width:auto;" checked onchange="rcPreview_()" /> Separate male / female columns</label>
        <label style="display:flex;gap:6px;align-items:center;font-weight:400;margin:0;"><input type="checkbox" id="rc-tob" style="width:auto;" onchange="rcPreview_()" /> Separate tobacco columns</label>
      </div>
      <label style="margin-top:12px;">Paste the rate grid from the carrier's sheet (Excel paste works — one line per age)</label>
      <div style="font-size:11px;color:var(--text-muted);margin-bottom:4px;">Column order per line: Age, then ${'{'}M non-tob, M tob, F non-tob, F tob{'}'} / {'{'}M, F{'}'} / {'{'}non-tob, tob{'}'} / single rate — matching the checkboxes above. Ages: 65 &middot; 65-69 &middot; 80+ &middot; under65.</div>
      <textarea id="rc-grid" rows="9" style="width:100%;box-sizing:border-box;font-family:monospace;font-size:12px;" placeholder="65   128.40   147.66&#10;66   131.20   150.88&#10;67-69   135.75   156.11" oninput="rcPreview_()"></textarea>
      <div id="rc-preview">${ch ? '<div style="font-size:12px;color:var(--text-muted);margin-top:8px;">Existing rates stay unless you paste a new grid — pasting REPLACES all rates for this chart.</div>' : ''}</div>
      <label style="margin-top:10px;">Notes</label><input type="text" id="rc-notes" value="${ch ? escWeb(ch.notes || '') : ''}" />
      ${ch ? `<label style="display:flex;gap:8px;align-items:center;margin-top:12px;font-weight:400;"><input type="checkbox" id="rc-active" style="width:auto;" ${ch.is_active ? 'checked' : ''}/> Active</label>` : ''}
    </div>
  `, async () => {
    const state = document.getElementById('rc-state').value.trim().toUpperCase();
    if (!/^[A-Z]{2}$/.test(state)) { showToast('State must be the 2-letter code.'); return false; }
    const meta = {
      product_id: productId,
      state,
      rating_method: document.getElementById('rc-method').value,
      effective_date: document.getElementById('rc-eff').value || null,
      household_discount_pct: parseFloat(document.getElementById('rc-hh').value) || null,
      zip_prefixes: document.getElementById('rc-zips').value.trim() || null,
      notes: document.getElementById('rc-notes').value.trim() || null,
    };
    if (ch) meta.is_active = document.getElementById('rc-active').checked;
    const gridText = document.getElementById('rc-grid').value.trim();
    let parsed = null;
    if (gridText) {
      parsed = parseRateGrid_(gridText, document.getElementById('rc-gen').checked, document.getElementById('rc-tob').checked);
      if (!parsed.length) { showToast('The pasted grid could not be read — check the preview.'); return false; }
    } else if (!ch) {
      showToast('Paste the rate grid — a chart with no rates cannot quote.'); return false;
    }
    let chartRow = ch;
    if (ch) {
      const { error } = await supabaseClient.from('rate_charts').update(meta).eq('id', ch.id);
      if (error) { showToast('Error: ' + error.message); return false; }
    } else {
      const { data: ins, error } = await supabaseClient.from('rate_charts').insert(meta).select().single();
      if (error) { showToast('Error: ' + error.message); return false; }
      chartRow = ins;
    }
    if (parsed) {
      const { error: eDel } = await supabaseClient.from('rate_rows').delete().eq('chart_id', chartRow.id);
      if (eDel) { showToast('Error: ' + eDel.message); return false; }
      const { error: eIns } = await supabaseClient.from('rate_rows')
        .insert(parsed.map(r => Object.assign({ chart_id: chartRow.id }, r)));
      if (eIns) { showToast('Error: ' + eIns.message); return false; }
    }
    showToast(ch ? 'Rate chart updated.' : 'Rate chart added — quoting is now automatic for this product.');
    openRateCharts(productId);
    return false;
  }, { confirmLabel: ch ? 'Save Chart' : 'Add Chart', wide: true });
}

// ============================================================
// CMS LANDSCAPE IMPORT — the annual fall ritual, in one modal.
// Reads the (large) official CSV in chunks in the browser,
// keeps only the chosen states, and loads them for quoting.
// ============================================================
const CMS_COLS = {
  year: 'contract year', category: 'contract category type',
  state: 'state territory abbreviation', county: 'county name',
  contract: 'contract id', plan: 'plan id', segment: 'segment id',
  org: 'organization marketing name', name: 'plan name', type: 'plan type',
  snp: 'snp type', sanctioned: 'sanctioned plan',
  partc: 'part c premium', partd: 'part d total premium',
  consolidated: 'monthly consolidated premium (part c + d)',
  deductible: 'annual part d deductible amount',
  moop: 'in-network maximum out-of-pocket (moop) amount',
  star: 'overall star rating',
};

function cmsRow_(cells, idx, st) {
  const star = (cells[idx.star] || '').trim();
  const snp = (cells[idx.snp] || '').trim();
  return {
    plan_year: parseInt(cells[idx.year]) || null,
    category: (cells[idx.category] || '').trim(),
    state: st,
    county: (cells[idx.county] || '').trim(),
    contract_id: (cells[idx.contract] || '').trim(),
    plan_id: (cells[idx.plan] || '').trim(),
    segment_id: (cells[idx.segment] || '0').trim() || '0',
    org_name: (cells[idx.org] || '').trim() || null,
    plan_name: (cells[idx.name] || '').trim(),
    plan_type: (cells[idx.type] || '').trim() || null,
    snp_type: /not applicable|^$/i.test(snp) ? null : snp,
    part_c_premium: cmsMoney_(cells[idx.partc]),
    part_d_premium: cmsMoney_(cells[idx.partd]),
    consolidated_premium: cmsMoney_(cells[idx.consolidated]),
    drug_deductible: cmsMoney_(cells[idx.deductible]),
    moop: cmsMoney_(cells[idx.moop]),
    star_rating: /not applicable|plan too new|^$/i.test(star) ? null : star,
  };
}

function cmsMoney_(v) {
  v = String(v == null ? '' : v).replace(/[$,\s]/g, '');
  if (!v || /not applicable|n\/a/i.test(v)) return null;
  const n = parseFloat(v);
  return isNaN(n) ? null : Math.round(n * 100) / 100;
}

function cmsSplitLine_(line) {
  // CSV split honoring quoted fields
  const out = [];
  let cur = '', inQ = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (ch === '"') { inQ = !inQ; continue; }
    if (ch === ',' && !inQ) { out.push(cur); cur = ''; continue; }
    cur += ch;
  }
  out.push(cur);
  return out;
}

// Ask the automatic loader to look at cms.gov right now rather than waiting
// for Monday. It does nothing if the file on offer is the one we already have.
async function cmsCheckNow_() {
  showToast('Asking CMS for the current file\u2026');
  try {
    const { data, error } = await supabaseClient.functions.invoke('cms-landscape-sync', { body: { mode: 'stage' } });
    if (error) throw error;
    if (data && data.status === 'skipped') showToast('Already on the newest file CMS publishes.');
    else if (data && data.status === 'staged') showToast('New file found \u2014 loading it now (a minute or two).');
    else showToast('Check finished: ' + ((data && data.status) || 'no answer'));
  } catch (e) {
    showToast('Could not reach the loader: ' + (e.message || e));
  }
  setTimeout(renderAdmin, 4000);
}

async function markReviewed_(id) {
  const note = prompt('Anything worth noting about this review? (optional)') || null;
  const { error } = await supabaseClient.from('system_reviews')
    .update({ last_reviewed: new Date().toISOString().slice(0, 10), last_note: note })
    .eq('id', id).select('id');
  if (error) { showToast('Could not save: ' + error.message); return; }
  showToast('Marked reviewed today.');
  renderAdmin();
}

function openCmsImportModal() {
  showModal('Import CMS Landscape File', `
    <p style="font-size:13px;color:var(--text-muted);margin-bottom:10px;">
      Download the current <strong>Landscape file</strong> (zip) from cms.gov &rarr; Prescription Drug Coverage,
      unzip it, and choose the big CSV here.
    </p>
    <label>States to import</label>
    <input type="text" id="cms-states" value="ALL" placeholder="ALL, or e.g. MT, WY, ID" />
    <div style="font-size:11.5px;color:var(--text-muted);margin-top:3px;">
      <strong>ALL</strong> loads every state and territory &mdash; that is the whole country, so give it a few
      minutes and leave this window open. Otherwise list 2-letter codes separated by commas.
    </div>
    <label>Landscape CSV file</label>
    <input type="file" id="cms-file" accept=".csv" />
    <div id="cms-progress" style="font-size:12px;color:var(--text-muted);margin-top:10px;"></div>
  `, async () => {
    const file = document.getElementById('cms-file').files[0];
    const raw = document.getElementById('cms-states').value.trim();
    const allStates = /^all$/i.test(raw) || raw === '';
    const states = raw.split(',').map(x => x.trim().toUpperCase()).filter(x => /^[A-Z]{2}$/.test(x));
    if (!file) { showToast('Choose the landscape CSV file.'); return false; }
    if (!allStates && !states.length) { showToast('List at least one state, or type ALL.'); return false; }
    const prog = document.getElementById('cms-progress');
    const label = allStates ? 'every state' : states.join(', ');
    const t0 = Date.now();
    prog.textContent = 'Reading file\u2026';

    // A national file is far too big to hold in memory and post at the end,
    // so rows go to the database as they're parsed. The old year's rows are
    // cleared once, on the first flush.
    let wiped = false, loaded = 0, failed = null;
    const flush = async (rows, year) => {
      if (!rows.length || failed) return;
      if (!wiped) {
        let del = supabaseClient.from('cms_plans').delete().eq('plan_year', year);
        if (!allStates) del = del.in('state', states);
        const { error } = await del;
        if (error) { failed = error.message; return; }
        wiped = true;
      }
      for (let i = 0; i < rows.length; i += 1000) {
        const { error } = await supabaseClient.from('cms_plans').insert(rows.slice(i, i + 1000));
        if (error) { failed = error.message; return; }
        loaded += Math.min(1000, rows.length - i);
      }
      const secs = Math.round((Date.now() - t0) / 1000);
      prog.textContent = 'Loaded ' + loaded.toLocaleString() + ' plans so far \u2014 ' + secs + 's elapsed\u2026';
    };

    // Stream the file in chunks; carry partial lines between chunks
    const CHUNK = 4 * 1024 * 1024;
    let offset = 0, carry = '', header = null, idx = null, kept = [], seen = 0, year = null;
    while (offset < file.size) {
      const text = await file.slice(offset, offset + CHUNK).text();
      offset += CHUNK;
      const lines = (carry + text).split(/\r?\n/);
      carry = lines.pop();
      for (const line of lines) {
        if (!header) {
          header = cmsSplitLine_(line.replace(/^\uFEFF/, '')).map(h => h.trim().toLowerCase());
          idx = {};
          for (const k in CMS_COLS) idx[k] = header.indexOf(CMS_COLS[k]);
          if (idx.state === -1 || idx.name === -1 || idx.contract === -1) {
            prog.innerHTML = '<span style="color:var(--danger);">This does not look like a CMS landscape file (columns not recognized).</span>';
            return false;
          }
          continue;
        }
        seen++;
        const cells = cmsSplitLine_(line);
        const st = (cells[idx.state] || '').trim();
        if (!allStates && !states.includes(st)) continue;
        if (allStates && !/^[A-Z]{2}$/.test(st)) continue;
        if (idx.sanctioned !== -1 && (cells[idx.sanctioned] || '').trim() === 'Yes') continue;
        const star = (cells[idx.star] || '').trim();
        year = parseInt(cells[idx.year]) || year;
        kept.push(cmsRow_(cells, idx, st));
      }
      await flush(kept.filter(k => k.plan_year && k.plan_name && k.contract_id), year);
      kept = [];
      if (failed) { prog.innerHTML = '<span style="color:var(--danger);">Import stopped: ' + escWeb(failed) + '</span>'; return false; }
      prog.textContent = 'Scanned ' + seen.toLocaleString() + ' rows \u00b7 loaded ' + loaded.toLocaleString() + ' plans for ' + label + '\u2026';
    }
    // whatever the final partial chunk left behind
    if (carry.trim() && header) {
      const cells = cmsSplitLine_(carry);
      const st = (cells[idx.state] || '').trim();
      if ((allStates ? /^[A-Z]{2}$/.test(st) : states.includes(st)) && cells[idx.contract]) {
        kept.push(cmsRow_(cells, idx, st));
      }
    }
    await flush(kept.filter(k => k.plan_year && k.plan_name && k.contract_id), year);
    if (failed) { prog.innerHTML = '<span style="color:var(--danger);">Import stopped: ' + escWeb(failed) + '</span>'; return false; }
    if (!loaded) { prog.innerHTML = '<span style="color:var(--danger);">No plans found for ' + escWeb(label) + '.</span>'; return false; }

    showToast('Imported ' + loaded.toLocaleString() + ' plans for ' + label + ' (' + year + ').');
    renderAdmin();
  }, { confirmLabel: 'Import' });
}

// ============================================================
// PRODUCT MODAL SMARTS — standardized Medigap picker + CMS hints
// ============================================================
function cpProductLineChanged_() {
  const line = document.getElementById('cp-line').value;
  const isMedigap = line === 'Medicare Supplement';
  const mg = document.getElementById('cp-mg-wrap');
  const hint = document.getElementById('cp-cms-hint');
  const codeWrap = document.getElementById('cp-code-wrap');
  if (mg) mg.style.display = isMedigap ? 'block' : 'none';
  // The standardized-plan dropdown sets the code itself — hide the manual field for Medigap
  if (codeWrap) codeWrap.style.display = isMedigap ? 'none' : 'block';
  if (hint) hint.style.display = (line === 'Medicare Advantage' || line === 'Part D (PDP)') ? 'block' : 'none';
}

function cpApplyMedigap_() {
  const code = document.getElementById('cp-mg').value;
  const plan = MEDIGAP_PLANS.find(p => p[0] === code);
  if (!plan) return;
  const label = code.startsWith('HD')
    ? 'Medicare Supplement High-Deductible Plan ' + code.slice(2)
    : 'Medicare Supplement Plan ' + code;
  document.getElementById('cp-name').value = label;
  document.getElementById('cp-code').value = code.startsWith('HD') ? 'HD Plan ' + code.slice(2) : 'Plan ' + code;
  document.getElementById('cp-bullets').value = plan[2].join('\n');
}
